import React, { useState } from 'react';
import { Button } from '../components/ui/Button';
import { GameConfig, Player } from '../types';

interface SetupViewProps {
  onStart: (players: Player[], config: GameConfig) => void;
  onBack: () => void;
}

export const SetupView: React.FC<SetupViewProps> = ({ onStart, onBack }) => {
  const [startingScore, setStartingScore] = useState(501);
  const [legsToWin, setLegsToWin] = useState(3);
  const [playerCount, setPlayerCount] = useState(2);
  const [checkOut, setCheckOut] = useState<'Open' | 'Double' | 'Master'>('Double');

  const handleStart = () => {
    const players: Player[] = Array.from({ length: playerCount }).map((_, i) => ({
      id: `p${i+1}`,
      name: `Player ${i+1}`
    }));

    const config: GameConfig = {
      startingScore,
      checkIn: 'Open',
      checkOut,
      legsToWin
    };

    onStart(players, config);
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white p-6 flex flex-col">
      <div className="flex items-center mb-8">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-bold ml-4">Match Setup</h2>
      </div>

      <div className="flex-1 space-y-8 max-w-md mx-auto w-full">

        {/* Score Selection */}
        <section>
          <label className="block text-gray-400 mb-2 text-sm uppercase">Starting Score</label>
          <div className="grid grid-cols-4 gap-2">
            {[301, 501, 701, 1001].map(score => (
              <button
                key={score}
                onClick={() => setStartingScore(score)}
                className={`py-3 rounded font-bold border ${startingScore === score ? 'bg-green-600 border-green-500 text-white' : 'bg-gray-800 border-gray-700 text-gray-400'}`}
              >
                {score}
              </button>
            ))}
          </div>
        </section>

        {/* Players */}
        <section>
          <label className="block text-gray-400 mb-2 text-sm uppercase">Players</label>
          <div className="flex items-center space-x-4 bg-gray-800 p-2 rounded-lg">
             <button onClick={() => setPlayerCount(Math.max(1, playerCount - 1))} className="w-10 h-10 bg-gray-700 rounded text-xl font-bold">-</button>
             <span className="flex-1 text-center font-bold text-xl">{playerCount}</span>
             <button onClick={() => setPlayerCount(Math.min(4, playerCount + 1))} className="w-10 h-10 bg-gray-700 rounded text-xl font-bold">+</button>
          </div>
        </section>

        {/* Format */}
        <section>
          <label className="block text-gray-400 mb-2 text-sm uppercase">Legs to Win (Best Of)</label>
          <div className="grid grid-cols-3 gap-2">
            {[1, 3, 5].map(legs => (
              <button
                key={legs}
                onClick={() => setLegsToWin(legs)}
                className={`py-2 rounded font-bold border ${legsToWin === legs ? 'bg-green-600 border-green-500 text-white' : 'bg-gray-800 border-gray-700 text-gray-400'}`}
              >
                {legs === 1 ? '1 Leg' : `First to ${legs}`}
              </button>
            ))}
          </div>
        </section>

        {/* Checkout Rule */}
        <section>
           <label className="block text-gray-400 mb-2 text-sm uppercase">Checkout Rule</label>
           <div className="flex p-1 bg-gray-800 rounded-lg">
             {(['Open', 'Double', 'Master'] as const).map(rule => (
                <button
                  key={rule}
                  onClick={() => setCheckOut(rule)}
                  className={`flex-1 py-2 text-sm font-bold rounded ${checkOut === rule ? 'bg-gray-700 text-white' : 'text-gray-500'}`}
                >
                  {rule} Out
                </button>
             ))}
           </div>
        </section>

      </div>

      <div className="mt-8">
        <Button onClick={handleStart} className="w-full py-4 text-xl">Start Match</Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.id];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      onFinish(match.matchWinnerId);
    }
  }, [match.status, match.matchWinnerId, onFinish]);

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return; // Basic sanitization
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);

    // Safety check
    if (score > 180) return;

    const nextState = submitTurn(match, score);
    setMatch(nextState);
    setInputBuffer('');
  };

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  // Check if checkout is mathematically possible this turn
  const isCheckoutPossible = currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);

  return (
    <div className="min-h-screen bg-gray-900 text-white flex flex-col md:flex-row">

      {/* Top Bar (Mobile) / Side Bar (Desktop) */}
      <div className="bg-gray-800 p-4 flex justify-between items-center md:flex-col md:w-64 md:h-screen md:justify-start md:space-y-6">
        <div className="flex flex-col">
           <h2 className="font-black text-xl tracking-tighter text-gray-200">GAME ON</h2>
           <span className="text-xs text-gray-500">Best of {match.config.legsToWin * 2 - 1}</span>
        </div>
        <Button variant="ghost" size="sm" onClick={onExit}>Exit</Button>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col max-w-4xl mx-auto w-full">

        {/* Scores Area */}
        <div className="flex-1 p-4 grid grid-cols-2 gap-4 items-center">
          {match.players.map((p, idx) => (
             <PlayerScore 
               key={p.id}
               name={p.name}
               score={match.currentLeg.scores[p.id]}
               isActive={match.currentPlayerIndex === idx}
               legsWon={match.legsWon[p.id]}
               stats={{
                 avg: '0.0', // TODO: Implement stats calculator
                 lastScore: match.currentLeg.history.filter(t => t.playerId === p.id).pop()?.score || null
               }}
             />
          ))}
        </div>

        {/* Active Turn Info */}
        <div className="px-6 py-2">
            <CheckoutHint score={currentScore} />
        </div>

        {/* Input Area */}
        <div className="bg-gray-800 p-4 rounded-t-3xl shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
          <div className="flex justify-between items-center mb-4 px-2">
             <div className="text-gray-400 text-sm">Target: <span className="text-white font-bold">{inputBuffer || '0'}</span></div>
             <Button variant="ghost" size="sm" onClick={handleUndo} disabled={match.currentLeg.history.length === 0}>
               Undo
             </Button>
          </div>

          <div className="flex gap-2 h-64">
            {/* Numpad */}
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={isCheckoutPossible}
               />
            </div>

            {/* Action Button */}
            <div className="w-1/4 flex flex-col gap-2">
               <Button 
                 className={`h-full text-2xl font-black rounded-xl ${inputBuffer ? 'animate-pulse' : ''}`}
                 variant={isCheckoutPossible && parseInt(inputBuffer || '0') === currentScore ? "primary" : "secondary"}
                 onClick={handleSubmitScore}
               >
                 {isCheckoutPossible && parseInt(inputBuffer || '0') === currentScore ? 'CHECK OUT' : 'OK'}
               </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

