import { CheckoutHint } from '../components/game/CheckoutHint';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');
  const [showStats, setShowStats] = useState(false);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.id];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      onFinish(match.matchWinnerId);
    }
  }, [match.status, match.matchWinnerId, onFinish]);

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return; // Basic sanitization
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);

    // Safety check
    if (score > 180) return;

    const nextState = submitTurn(match, score);
    setMatch(nextState);
    setInputBuffer('');
  };

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  // Check if checkout is mathematically possible this turn
  const isCheckoutPossible = currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);

  // Is it the start of a leg? (For allowing player switch)
  const isLegStart = match.currentLeg.history.length === 0;

  return (
    <div className="min-h-screen bg-gray-900 text-white flex flex-col md:flex-row relative">

      {/* Top Bar (Mobile) / Side Bar (Desktop) */}
      <div className="bg-gray-800 p-4 flex justify-between items-center md:flex-col md:w-64 md:h-screen md:justify-start md:space-y-6">
        <div className="flex flex-col">
           <h2 className="font-black text-xl tracking-tighter text-gray-200">GAME ON</h2>
           <span className="text-xs text-gray-500">Best of {match.config.legsToWin * 2 - 1}</span>
        </div>
        <div className="flex gap-2">
            <Button variant="secondary" size="sm" onClick={() => setShowStats(true)}>Stats</Button>
            <Button variant="ghost" size="sm" onClick={onExit}>Exit</Button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col max-w-4xl mx-auto w-full">

        {/* Scores Area */}
        <div className="flex-1 p-4 grid grid-cols-2 gap-4 items-center">
          {match.players.map((p, idx) => {
             const stats = calculatePlayerStats(match, p.id);
             return (
               <PlayerScore 
                 key={p.id}
                 name={p.name}
                 score={match.currentLeg.scores[p.id]}
                 isActive={match.currentPlayerIndex === idx}
                 legsWon={match.legsWon[p.id]}
                 stats={{
                   matchAvg: stats.matchAvg,
                   legAvg: stats.legAvg,
                   legDarts: stats.legDarts,
                   lastScore: match.currentLeg.history.filter(t => t.playerId === p.id).pop()?.score || null
                 }}
               />
             );
          })}
        </div>

        {/* Active Turn Info & Hint */}
        <div className="px-6 py-2 flex flex-col items-center">
            {isLegStart && (
                <button 
                  onClick={handleSwitchStart}
                  className="mb-2 text-xs text-gray-400 bg-gray-800 px-3 py-1 rounded-full border border-gray-700 hover:text-white hover:border-green-500 transition-colors"
                >
                   Swap Starting Player ⇄
                </button>
            )}
            <CheckoutHint score={currentScore} />
        </div>

        {/* Input Area */}
        <div className="bg-gray-800 p-4 rounded-t-3xl shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
          <div className="flex justify-between items-center mb-4 px-2">
             <div className="text-gray-400 text-sm">Target: <span className="text-white font-bold">{inputBuffer || '0'}</span></div>
             <Button variant="ghost" size="sm" onClick={handleUndo} disabled={match.currentLeg.history.length === 0}>
               Undo
             </Button>
          </div>

          <div className="flex gap-2 h-64">
            {/* Numpad */}
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={isCheckoutPossible}
               />
            </div>

            {/* Action Button */}
            <div className="w-1/4 flex flex-col gap-2">
               <Button 
                 className={`h-full text-2xl font-black rounded-xl ${inputBuffer ? 'animate-pulse' : ''}`}
                 variant={isCheckoutPossible && parseInt(inputBuffer || '0') === currentScore ? "primary" : "secondary"}
                 onClick={handleSubmitScore}
               >
                 {isCheckoutPossible && parseInt(inputBuffer || '0') === currentScore ? 'CHECK OUT' : 'OK'}
               </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Modal */}
      {showStats && (
        <div className="absolute inset-0 z-50 bg-black/90 flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-xl p-6 w-full max-w-lg">
            <h2 className="text-2xl font-bold mb-4 text-center">Match Statistics</h2>

            <div className="space-y-4">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-700">
                      <th className="text-left py-2 text-gray-400">Player</th>
                      <th className="text-center py-2 text-gray-400">Match Ø</th>
                      <th className="text-center py-2 text-gray-400">Total Darts</th>
                      <th className="text-right py-2 text-gray-400">Legs</th>
                    </tr>
                  </thead>
                  <tbody>
                    {match.players.map(p => {
                      const stats = calculatePlayerStats(match, p.id);
                      return (
                        <tr key={p.id} className="border-b border-gray-700/50">
                          <td className="py-3 font-bold">{p.name}</td>
                          <td className="py-3 text-center">{stats.matchAvg}</td>
                          <td className="py-3 text-center">{stats.matchDarts}</td>
                          <td className="py-3 text-right">{match.legsWon[p.id]}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
            </div>

            <div className="mt-8">
              <Button className="w-full" onClick={() => setShowStats(false)}>Close</Button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

