// Helper Subcomponent for Rows
const StatRow = ({ label, val1, val2, highlight = false, isBest = false, isLowBest = false, subtext = "" }: any) => {
    // Simple comparison for styling winner of the stat
    let win1 = false;
    let win2 = false;

    if (val1 !== '-' && val2 !== '-' && typeof val1 === 'number' && typeof val2 === 'number') {
        if (isLowBest) {
            win1 = val1 < val2;
            win2 = val2 < val1;
        } else {
            win1 = val1 > val2;
            win2 = val2 > val1;
        }
    }

    return (
        <div className={`grid grid-cols-[1fr_1fr_1fr] gap-2 items-center p-3 rounded-lg border border-gray-800/50 ${highlight ? 'bg-gray-800' : 'bg-gray-800/30'}`}>
             <div className="text-left">
                <div className="text-gray-400 font-bold uppercase text-xs md:text-sm tracking-wider">{label}</div>
                {subtext && <div className="text-[9px] text-gray-600">{subtext}</div>}
             </div>

             <div className={`text-center font-mono font-black text-lg md:text-xl ${win1 ? 'text-orange-500' : 'text-white'}`}>
                {val1}
             </div>

             <div className={`text-center font-mono font-black text-lg md:text-xl ${win2 ? 'text-orange-500' : 'text-white'}`}>
                {val2}
             </div>
        </div>
    );
}

import { GameConfig, MatchState, Player, LegState, Turn, InOutRule } from '../types';

export const createMatch = (players: Player[], config: GameConfig): MatchState => {
  const initialLeg: LegState = {
    scores: {},
    history: [],
    winnerId: null,
    startingPlayerIndex: 0,
  };

  players.forEach(p => {
    initialLeg.scores[p.id] = config.startingScore;
  });

  const legsWon: Record<string, number> = {};
  players.forEach(p => (legsWon[p.id] = 0));

  return {
    id: crypto.randomUUID(),
    config,
    players,
    legsWon,
    completedLegs: [],
    currentLeg: initialLeg,
    status: 'active',
    matchWinnerId: null,
    currentPlayerIndex: 0,
  };
};

const isBust = (
  currentScore: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  const remaining = currentScore - turnScore;

  if (remaining < 0) return true;
  if (remaining === 0) return false; // Potential checkout, validated elsewhere

  // If Double Out, you cannot leave yourself with 1
  if (checkOut === 'Double' && remaining === 1) return true;

  // If Master Out, you cannot leave yourself with 1 (Double or Triple needed)
  if (checkOut === 'Master' && remaining === 1) return true;

  return false;
};

// Check if the current throw sequence is a valid checkout
const isValidCheckout = (
  remaining: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  if (remaining - turnScore !== 0) return false;
  return true;
};

// Helper to determine minimum darts required for a score
export const getMinDartsForScore = (score: number): number => {
  if (score > 110) return 3; // Max 2-dart checkout is 110 (T20, Bull)
  if (score > 50) return 2;  // Max 1-dart checkout is 50 (Bull)
  return 1;
};

export const submitTurn = (
  match: MatchState,
  turnScore: number,
  dartsThrown: number = 3
): MatchState => {
  if (match.status === 'finished') return match;

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentLeg = match.currentLeg;
  const currentScore = currentLeg.scores[currentPlayer.id];

  // 1. Calculate Bust
  const busted = isBust(currentScore, turnScore, match.config.checkOut);

  // 2. Determine new score
  let newScore = currentScore;
  let legWon = false;

  if (!busted) {
    newScore = currentScore - turnScore;
    if (newScore === 0) {
      legWon = isValidCheckout(currentScore, turnScore, match.config.checkOut);
    }
  }

  // 3. Update History
  const newTurn: Turn = {
    playerId: currentPlayer.id,
    score: turnScore,
    isBust: busted,
    remainingAfter: busted ? currentScore : newScore,
    dartsThrown: busted ? 3 : dartsThrown // If bust, always counts as 3 darts usually, or user specific logic? Standard is 3 unless specified, but for simplicity we assume 3 on bust/normal turn, and variable on checkout.
  };

  const newHistory = [...currentLeg.history, newTurn];

  // 4. Update Leg State
  const newLegScores = { ...currentLeg.scores, [currentPlayer.id]: newTurn.remainingAfter };

  let nextMatchState = { ...match };

  if (legWon) {
    // Handle Leg Win
    const newLegsWon = { ...match.legsWon, [currentPlayer.id]: match.legsWon[currentPlayer.id] + 1 };

    // Create the finished leg object to store in history
    const finishedLeg: LegState = { 
      ...currentLeg, 
      scores: newLegScores, 
      history: newHistory, 
      winnerId: currentPlayer.id 
    };

    const newCompletedLegs = [...match.completedLegs, finishedLeg];

    // Check Match Win
    if (newLegsWon[currentPlayer.id] >= match.config.legsToWin) {
      // Match Finished
      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        completedLegs: newCompletedLegs,
        currentLeg: finishedLeg, // Keep final state visible
        status: 'finished',
        matchWinnerId: currentPlayer.id
      };
    } else {
      // New Leg Setup
      const nextLegIndex = match.currentLeg.startingPlayerIndex + 1 < match.players.length 
        ? match.currentLeg.startingPlayerIndex + 1 
        : 0;

      const nextLeg: LegState = {
        scores: {},
        history: [],
        winnerId: null,
        startingPlayerIndex: nextLegIndex
      };
      match.players.forEach(p => nextLeg.scores[p.id] = match.config.startingScore);

      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        completedLegs: newCompletedLegs,
        currentLeg: nextLeg,
        currentPlayerIndex: nextLegIndex // Next leg starter
      };
    }
  } else {
    // Continue Leg
    const nextPlayerIndex = (match.currentPlayerIndex + 1) % match.players.length;
    nextMatchState = {
      ...match,
      currentLeg: {
        ...currentLeg,
        scores: newLegScores,
        history: newHistory
      },
      currentPlayerIndex: nextPlayerIndex
    };
  }

  return nextMatchState;
};

export const undoTurn = (match: MatchState): MatchState => {
  // Simplistic Undo: only works within the current leg for now
  if (match.currentLeg.history.length === 0) return match;

  const lastTurn = match.currentLeg.history[match.currentLeg.history.length - 1];
  const prevHistory = match.currentLeg.history.slice(0, -1);

  const targetPlayerId = lastTurn.playerId;
  const currentScore = match.currentLeg.scores[targetPlayerId];

  let restoredScore = currentScore;
  if (!lastTurn.isBust) {
    restoredScore = currentScore + lastTurn.score;
  }

  const newScores = { ...match.currentLeg.scores, [targetPlayerId]: restoredScore };

  // Restore active player to the one who just played
  const playerIndex = match.players.findIndex(p => p.id === targetPlayerId);

  return {
    ...match,
    currentLeg: {
      ...match.currentLeg,
      scores: newScores,
      history: prevHistory
    },
    currentPlayerIndex: playerIndex,
    status: 'active',
    matchWinnerId: null
  };
};

export const switchStartPlayer = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length > 0) return match;

  const nextIndex = (match.currentPlayerIndex + 1) % match.players.length;

  return {
    ...match,
    currentPlayerIndex: nextIndex,
    currentLeg: {
      ...match.currentLeg,
      startingPlayerIndex: nextIndex
    }
  };
};

// --- STATISTICS ENGINE ---

export interface DetailedPlayerStats {
  threeDartAvg: string;
  first9Avg: string;
  checkoutPercent: string; // Placeholder for now as we don't track missed doubles
  highestCheckout: number;
  highestScore: number;
  bestLegDarts: number | null;
  worstLegDarts: number | null;
  scoreCounts: {
    c180: number;
    c160: number; // 160-179
    c140: number; // 140-159
    c120: number; // 120-139
    c100: number; // 100-119
    c80: number;  // 80-99
    c60: number;  // 60-79
    c40: number;  // 40-59
  };
  legsWon: number;
}

export const calculatePlayerStats = (match: MatchState, playerId: string) => {
  // Basic stats for the score card
  const calculateAvg = (turns: Turn[]) => {
    const playerTurns = turns.filter(t => t.playerId === playerId);
    if (playerTurns.length === 0) return 0.0;

    const totalScore = playerTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
    const totalDarts = playerTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

    if (totalDarts === 0) return 0.0;
    return (totalScore / totalDarts) * 3;
  };

  const calculateTotalDarts = (turns: Turn[]) => {
      return turns
          .filter(t => t.playerId === playerId)
          .reduce((acc, t) => acc + t.dartsThrown, 0);
  }

  // Current Leg Stats
  const legAvg = calculateAvg(match.currentLeg.history);
  const legDarts = calculateTotalDarts(match.currentLeg.history);

  // Match Stats (All turns)
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history);

  const matchAvg = calculateAvg(allTurns);
  const matchDarts = calculateTotalDarts(allTurns);

  return {
    legAvg: legAvg.toFixed(1),
    legDarts,
    matchAvg: matchAvg.toFixed(1),
    matchDarts
  };
};

export const calculateDetailedStats = (match: MatchState, playerId: string): DetailedPlayerStats => {
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history).filter(t => t.playerId === playerId);

  // 1. Scoring Counts
  const counts = {
    c180: 0, c160: 0, c140: 0, c120: 0, c100: 0, c80: 0, c60: 0, c40: 0
  };
  let highestScore = 0;

  allTurns.forEach(t => {
    if (t.isBust) return; // Ignore bust scores for high scores? Usually yes.
    const s = t.score;
    if (s > highestScore) highestScore = s;

    if (s === 180) counts.c180++;
    else if (s >= 160) counts.c160++;
    else if (s >= 140) counts.c140++;
    else if (s >= 120) counts.c120++;
    else if (s >= 100) counts.c100++;
    else if (s >= 80) counts.c80++;
    else if (s >= 60) counts.c60++;
    else if (s >= 40) counts.c40++;
  });

  // 2. 3-Dart Average
  const totalScore = allTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
  const totalDarts = allTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
  const threeDartAvg = totalDarts > 0 ? ((totalScore / totalDarts) * 3).toFixed(1) : "0.0";

  // 3. First 9 Avg
  let f9TotalScore = 0;
  let f9TotalDarts = 0;

  allLegs.forEach(leg => {
    const playerTurns = leg.history.filter(t => t.playerId === playerId);
    let dartsCounted = 0;
    for (const turn of playerTurns) {
      if (dartsCounted >= 9) break;
      f9TotalScore += turn.isBust ? 0 : turn.score;
      f9TotalDarts += turn.dartsThrown;
      dartsCounted += turn.dartsThrown;
    }
  });
  const first9Avg = f9TotalDarts > 0 ? ((f9TotalScore / f9TotalDarts) * 3).toFixed(1) : "0.0";

  // 4. Best/Worst Legs (Darts thrown in WON legs)
  let bestLeg: number | null = null;
  let worstLeg: number | null = null;
  let highestCheckout = 0;

  match.completedLegs.forEach(leg => {
    if (leg.winnerId === playerId) {
      // It's a won leg, count darts
      const darts = leg.history.filter(t => t.playerId === playerId).reduce((acc, t) => acc + t.dartsThrown, 0);

      if (bestLeg === null || darts < bestLeg) bestLeg = darts;
      if (worstLeg === null || darts > worstLeg) worstLeg = darts;

      // Check for checkout score (last turn)
      const lastTurn = leg.history[leg.history.length - 1];
      if (lastTurn && lastTurn.playerId === playerId) {
        if (lastTurn.score > highestCheckout) highestCheckout = lastTurn.score;
      }
    }
  });

  // 5. Checkout % (Placeholder logic: Legs Won / Legs Won + Legs Lost is NOT CO%, strictly it is N/A without input)
  // For MVP, we will show "N/A" unless we want to use Win %
  const legsWonCount = match.legsWon[playerId] || 0;
  // const legsPlayed = match.completedLegs.length; // Not accurate for CO%

  return {
    threeDartAvg,
    first9Avg,
    checkoutPercent: "N/A", // Requires dart-by-dart miss tracking
    highestCheckout,
    highestScore,
    bestLegDarts: bestLeg,
    worstLegDarts: worstLeg,
    scoreCounts: counts,
    legsWon: legsWonCount
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, calculatePlayerStats, switchStartPlayer, getMinDartsForScore } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);

  // Settings States
  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.id];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      onFinish(match.matchWinnerId);
    }
  }, [match.status, match.matchWinnerId, onFinish]);

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return; // Basic sanitization
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);

    // Safety check
    if (score > 180) return;

    // Check if this is a winning shot
    if (score === currentScore && score <= 170) {
         // Intercept for dart count input
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3); // Default 3 darts for normal turn
    setMatch(nextState);
    setInputBuffer('');
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  // Check if checkout is mathematically possible this turn
  const isCheckoutPossible = currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);

  // Is it the start of a leg? (For allowing player switch)
  const isLegStart = match.currentLeg.history.length === 0;

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white flex flex-col md:flex-row relative overflow-hidden">

      {/* Top Bar (Mobile) / Side Bar (Desktop) */}
      <div className="bg-gray-900/80 backdrop-blur-md border-b md:border-b-0 md:border-r border-gray-800 p-4 flex justify-between items-center md:flex-col md:w-64 md:h-screen md:justify-start md:space-y-8 z-20">
        <div className="flex flex-col md:items-center">
           <h2 className="font-black text-2xl tracking-tighter italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500 drop-shadow-sm">BOUGNAT DARTS</h2>
           <span className="text-[10px] text-gray-500 uppercase tracking-widest font-bold mt-1">First to {match.config.legsToWin}</span>
        </div>
        <div className="flex gap-2 md:flex-col md:w-full">
            <Button variant="secondary" size="sm" onClick={() => setShowSettings(true)} className="md:w-full border-gray-700">⚙️</Button>
            <Button variant="secondary" size="sm" onClick={() => setShowStats(true)} className="md:w-full text-xs font-bold">STATS</Button>
            <Button variant="ghost" size="sm" onClick={() => setShowExitConfirm(true)} className="md:w-full text-red-500 hover:text-red-400 text-xs font-bold uppercase">Exit</Button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col max-w-4xl mx-auto w-full relative z-10">

        {/* Scores Area (Current Leg) */}
        <div className="flex-1 p-4 grid grid-cols-2 gap-4 items-center content-center min-h-[300px]">
          {match.players.map((p, idx) => {
             const stats = calculatePlayerStats(match, p.id);
             return (
               <PlayerScore 
                 key={p.id}
                 name={p.name}
                 score={match.currentLeg.scores[p.id]}
                 isActive={match.currentPlayerIndex === idx}
                 legsWon={match.legsWon[p.id]}
                 stats={{
                   matchAvg: stats.matchAvg,
                   legAvg: stats.legAvg,
                   legDarts: stats.legDarts,
                   lastScore: match.currentLeg.history.filter(t => t.playerId === p.id).pop()?.score || null
                 }}
               />
             );
          })}
        </div>

        {/* --- MATCH SCORE BANNER --- */}
        <div className="w-full bg-gray-900/50 border-y border-gray-800 backdrop-blur-sm py-3 mb-2 flex items-center justify-center relative overflow-hidden group">
            {/* Ambient Background Light */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1/2 h-full bg-orange-500/5 blur-xl group-hover:bg-orange-500/10 transition-colors"></div>

            <div className="flex items-center space-x-8 md:space-x-16 z-10">
                {match.players.map((p, index) => (
                    <React.Fragment key={p.id}>
                        {index > 0 && (
                            <div className="flex flex-col items-center px-4">
                                <span className="text-[10px] text-orange-500 font-black uppercase tracking-[0.2em]">Legs</span>
                                <span className="text-[9px] text-gray-500 font-bold whitespace-nowrap">First to {match.config.legsToWin}</span>
                            </div>
                        )}
                        <div className={`flex flex-col items-center transition-all duration-300 ${match.currentPlayerIndex === index ? 'scale-110' : 'opacity-70'}`}>
                            <span className={`text-4xl md:text-5xl font-black font-mono leading-none ${match.legsWon[p.id] > match.legsWon[match.players[index === 0 ? 1 : 0].id] ? 'text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.5)]' : 'text-gray-400'}`}>
                                {match.legsWon[p.id]}
                            </span>
                        </div>
                    </React.Fragment>
                ))}
            </div>
        </div>

        {/* Active Turn Info & Hint */}
        <div className="px-6 py-1 flex flex-col items-center min-h-[60px] justify-end space-y-2">
            {isLegStart && (
                <button 
                  onClick={handleSwitchStart}
                  className="text-[10px] uppercase font-bold tracking-wider text-gray-500 bg-gray-900/50 px-4 py-1 rounded-full border border-gray-700 hover:text-orange-400 hover:border-orange-500/50 transition-colors"
                >
                   Swap Starting Player ⇄
                </button>
            )}
            {showCheckoutHints && <CheckoutHint score={currentScore} />}
        </div>

        {/* Input Area */}
        <div className="bg-gray-800/80 backdrop-blur-xl p-4 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] border-t border-gray-700/50">
          <div className="flex justify-between items-center mb-4 px-3">
             <div className="text-gray-400 text-xs uppercase font-bold tracking-wider">Score Input</div>
             <div className="text-3xl font-mono font-bold text-white tracking-widest min-w-[3ch] text-right text-orange-400 drop-shadow-[0_0_10px_rgba(234,88,12,0.5)]">
                 {inputBuffer || <span className="text-gray-700">0</span>}
             </div>
             <Button variant="ghost" size="sm" onClick={handleUndo} disabled={match.currentLeg.history.length === 0} className="text-xs uppercase font-bold">
               Undo
             </Button>
          </div>

          <div className="flex gap-2 h-64 md:h-72">
            {/* Numpad */}
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={isCheckoutPossible}
               />
            </div>

            {/* Action Button */}
            <div className="w-1/4 flex flex-col gap-2">
               <Button 
                 className={`h-full text-2xl font-black rounded-xl transition-all duration-300 ${inputBuffer ? 'scale-[1.02] shadow-[0_0_20px_rgba(234,88,12,0.3)]' : ''}`}
                 variant={isCheckoutPossible && parseInt(inputBuffer || '0') === currentScore ? "primary" : "secondary"}
                 onClick={handleSubmitScore}
               >
                 {isCheckoutPossible && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
          </div>
        </div>
      </div>

      {/* --- MODALS --- */}

      {/* Checkout Darts Modal */}
      {pendingCheckoutScore !== null && (
          <div className="absolute inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-fadeIn">
             <h2 className="text-3xl font-black italic text-white mb-2 uppercase text-center">Game Shot!</h2>
             <p className="text-gray-400 mb-8 font-bold uppercase tracking-widest text-sm">How many darts?</p>

             <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                 {[1, 2, 3].map(d => {
                     const minDarts = getMinDartsForScore(pendingCheckoutScore);
                     const disabled = d < minDarts;
                     return (
                         <Button 
                            key={d}
                            variant={disabled ? "secondary" : "primary"}
                            onClick={() => !disabled && handleCheckoutConfirm(d)}
                            className={`h-24 text-4xl ${disabled ? 'opacity-20 cursor-not-allowed' : 'shadow-[0_0_30px_rgba(234,88,12,0.5)] scale-100 hover:scale-105'}`}
                            disabled={disabled}
                         >
                             {d}
                         </Button>
                     )
                 })}
             </div>
             <div className="mt-8">
                <Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button>
             </div>
          </div>
      )}

      {/* Settings Modal */}
      {showSettings && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm border border-gray-700 shadow-2xl">
            <h2 className="text-xl font-black italic text-white mb-6 text-center uppercase">Settings</h2>

            <div className="space-y-4 mb-8">
                <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg border border-gray-700">
                    <span className="text-gray-300 font-bold text-sm">Checkout Guide</span>
                    <button 
                        onClick={() => setShowCheckoutHints(!showCheckoutHints)}
                        className={`w-12 h-6 rounded-full transition-colors relative ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}
                    >
                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform shadow-md ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                    </button>
                </div>
            </div>

            <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
          </div>
        </div>
      )}

      {/* Exit Confirmation Modal */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 italic">ABORT GAME?</h3>
              <p className="text-gray-400 mb-8 text-sm">Current match progress will be lost.</p>

              <div className="grid grid-cols-2 gap-3">
                  <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>
                      Resume
                  </Button>
                  <Button variant="danger" onClick={onExit}>
                      Quit
                  </Button>
              </div>
           </div>
        </div>
      )}

      {/* Live Stats Modal */}
      {showStats && (
        <StatsModal 
            match={match} 
            onClose={() => setShowStats(false)} 
            title="LIVE MATCH STATS"
        />
      )}

    </div>
  );
};

import React, { useState } from 'react';
import { Button } from '../components/ui/Button';
import { GameConfig, Player, InOutRule } from '../types';

interface SetupViewProps {
  onStart: (players: Player[], config: GameConfig) => void;
  onBack: () => void;
}

export const SetupView: React.FC<SetupViewProps> = ({ onStart, onBack }) => {
  const [startingScore, setStartingScore] = useState(501);
  const [legsToWin, setLegsToWin] = useState(3);
  const [playerNames, setPlayerNames] = useState<string[]>(['Player 1', 'Player 2']);

  // Defaults: Double Out, Open In
  const [checkOut, setCheckOut] = useState<InOutRule>('Double');
  const [checkIn, setCheckIn] = useState<InOutRule>('Open');

  const updatePlayerCount = (delta: number) => {
    const currentCount = playerNames.length;
    const newCount = Math.max(1, Math.min(4, currentCount + delta));

    if (newCount === currentCount) return;

    setPlayerNames(prev => {
      if (newCount > prev.length) {
        return [...prev, `Player ${newCount}`];
      } else {
        return prev.slice(0, newCount);
      }
    });
  };

  const updatePlayerName = (index: number, name: string) => {
    const newNames = [...playerNames];
    newNames[index] = name;
    setPlayerNames(newNames);
  };

  const handleStart = () => {
    const players: Player[] = playerNames.map((name, i) => ({
      id: `p${i+1}`,
      name: name.trim() || `Player ${i+1}`
    }));

    const config: GameConfig = {
      startingScore,
      checkIn,
      checkOut,
      legsToWin
    };

    onStart(players, config);
  };

  const activeOptionClass = "bg-gradient-to-r from-orange-600 to-red-600 text-white border-transparent shadow-[0_0_10px_rgba(234,88,12,0.3)]";
  const inactiveOptionClass = "bg-gray-800 border-gray-700 text-gray-400 hover:border-orange-500/50 hover:text-gray-200";

  const getRuleDescription = (type: 'in' | 'out', rule: InOutRule) => {
     if (type === 'out') {
         switch(rule) {
             case 'Open': return "Finish on any segment (Single, Double, Triple).";
             case 'Double': return "Standard: Finish on a Double or Bullseye.";
             case 'Master': return "Finish on a Double, Triple or Bullseye.";
         }
     } else {
         switch(rule) {
             case 'Open': return "Start scoring immediately on any hit.";
             case 'Double': return "Must hit a Double to start scoring.";
             case 'Master': return "Must hit a Double or Triple to start scoring.";
         }
     }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      <div className="flex items-center mb-6">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
            MATCH SETUP
        </h2>
      </div>

      <div className="flex-1 space-y-6 max-w-md mx-auto w-full overflow-y-auto pb-4 custom-scrollbar">

        {/* Score Selection */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Starting Score</label>
          <div className="grid grid-cols-4 gap-2">
            {[301, 501, 701, 1001].map(score => (
              <button
                key={score}
                onClick={() => setStartingScore(score)}
                className={`py-3 rounded font-black border transition-all duration-200 ${startingScore === score ? activeOptionClass : inactiveOptionClass}`}
              >
                {score}
              </button>
            ))}
          </div>
        </section>

        {/* Players Configuration */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Players</label>
          <div className="flex items-center space-x-4 bg-gray-800/50 p-2 rounded-lg mb-4 border border-gray-700">
             <button onClick={() => updatePlayerCount(-1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">-</button>
             <span className="flex-1 text-center font-black text-2xl text-white">{playerNames.length}</span>
             <button onClick={() => updatePlayerCount(1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">+</button>
          </div>

          <div className="space-y-2">
            {playerNames.map((name, index) => (
              <div key={index} className="flex items-center group">
                <span className="w-8 text-gray-500 text-xs font-bold group-hover:text-orange-500 transition-colors">#{index + 1}</span>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => updatePlayerName(index, e.target.value)}
                  onFocus={(e) => e.target.select()}
                  className="flex-1 bg-gray-800 border border-gray-700 text-white px-3 py-3 rounded font-bold focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all"
                  placeholder={`Player ${index + 1}`}
                />
              </div>
            ))}
          </div>
        </section>

        {/* Format */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Legs to Win</label>
          <div className="grid grid-cols-3 gap-2">
            {[1, 3, 5].map(legs => (
              <button
                key={legs}
                onClick={() => setLegsToWin(legs)}
                className={`py-3 rounded font-bold text-sm border transition-all duration-200 ${legsToWin === legs ? activeOptionClass : inactiveOptionClass}`}
              >
                {legs === 1 ? '1 Leg' : `First to ${legs}`}
              </button>
            ))}
          </div>
        </section>

        {/* In / Out Rules */}
        <section className="grid grid-cols-1 gap-6">
           {/* In Rule */}
           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Check In Rule</label>
               <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button
                      key={rule}
                      onClick={() => setCheckIn(rule)}
                      className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkIn === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                      {rule} In
                    </button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('in', checkIn)}</p>
           </div>

           {/* Out Rule */}
           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Checkout Rule</label>
               <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button
                      key={rule}
                      onClick={() => setCheckOut(rule)}
                      className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkOut === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                      {rule} Out
                    </button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('out', checkOut)}</p>
           </div>
        </section>

      </div>

      <div className="mt-4">
        <Button onClick={handleStart} className="w-full py-5 text-2xl shadow-orange-900/20">GAME ON</Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, calculatePlayerStats, switchStartPlayer, getMinDartsForScore } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);

  // Settings States
  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.id];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      onFinish(match.matchWinnerId);
    }
  }, [match.status, match.matchWinnerId, onFinish]);

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return; // Basic sanitization
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180; // Open and Master can technically finish on 180
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);

    // Safety check
    if (score > 180) return;

    // Check if this is a winning shot
    // Note: This validation depends on the 'Out' rule.
    const maxCheckout = getMaxCheckout(match.config.checkOut);

    if (score === currentScore && score <= maxCheckout) {
         // Intercept for dart count input
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3); // Default 3 darts for normal turn
    setMatch(nextState);
    setInputBuffer('');
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  // Check if checkout is mathematically possible this turn
  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      // Open / Master
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();

  // Is it the start of a leg? (For allowing player switch)
  const isLegStart = match.currentLeg.history.length === 0;

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white flex flex-col md:flex-row relative overflow-hidden">

      {/* Top Bar (Mobile) / Side Bar (Desktop) */}
      <div className="bg-gray-900/80 backdrop-blur-md border-b md:border-b-0 md:border-r border-gray-800 p-4 flex justify-between items-center md:flex-col md:w-64 md:h-screen md:justify-start md:space-y-8 z-20">
        <div className="flex flex-col md:items-center">
           <h2 className="font-black text-2xl tracking-tighter italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500 drop-shadow-sm">BOUGNAT DARTS</h2>
           <span className="text-[10px] text-gray-500 uppercase tracking-widest font-bold mt-1">First to {match.config.legsToWin}</span>
           <div className="mt-2 flex gap-2 text-[9px] font-mono text-gray-600 bg-gray-950 px-2 py-1 rounded border border-gray-800">
               <span>IN: <span className="text-gray-400">{match.config.checkIn}</span></span>
               <span>|</span>
               <span>OUT: <span className="text-orange-500">{match.config.checkOut}</span></span>
           </div>
        </div>
        <div className="flex gap-2 md:flex-col md:w-full">
            <Button variant="secondary" size="sm" onClick={() => setShowSettings(true)} className="md:w-full border-gray-700">⚙️</Button>
            <Button variant="secondary" size="sm" onClick={() => setShowStats(true)} className="md:w-full text-xs font-bold">STATS</Button>
            <Button variant="ghost" size="sm" onClick={() => setShowExitConfirm(true)} className="md:w-full text-red-500 hover:text-red-400 text-xs font-bold uppercase">Exit</Button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col max-w-4xl mx-auto w-full relative z-10">

        {/* Scores Area (Current Leg) */}
        <div className="flex-1 p-4 grid grid-cols-2 gap-4 items-center content-center min-h-[300px]">
          {match.players.map((p, idx) => {
             const stats = calculatePlayerStats(match, p.id);
             return (
               <PlayerScore 
                 key={p.id}
                 name={p.name}
                 score={match.currentLeg.scores[p.id]}
                 isActive={match.currentPlayerIndex === idx}
                 legsWon={match.legsWon[p.id]}
                 stats={{
                   matchAvg: stats.matchAvg,
                   legAvg: stats.legAvg,
                   legDarts: stats.legDarts,
                   lastScore: match.currentLeg.history.filter(t => t.playerId === p.id).pop()?.score || null
                 }}
               />
             );
          })}
        </div>

        {/* --- MATCH SCORE BANNER --- */}
        <div className="w-full bg-gray-900/50 border-y border-gray-800 backdrop-blur-sm py-3 mb-2 flex items-center justify-center relative overflow-hidden group">
            {/* Ambient Background Light */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1/2 h-full bg-orange-500/5 blur-xl group-hover:bg-orange-500/10 transition-colors"></div>

            <div className="flex items-center space-x-8 md:space-x-16 z-10">
                {match.players.map((p, index) => (
                    <React.Fragment key={p.id}>
                        {index > 0 && (
                            <div className="flex flex-col items-center px-4">
                                <span className="text-[10px] text-orange-500 font-black uppercase tracking-[0.2em]">Legs</span>
                                <span className="text-[9px] text-gray-500 font-bold whitespace-nowrap">First to {match.config.legsToWin}</span>
                            </div>
                        )}
                        <div className={`flex flex-col items-center transition-all duration-300 ${match.currentPlayerIndex === index ? 'scale-110' : 'opacity-70'}`}>
                            <span className={`text-4xl md:text-5xl font-black font-mono leading-none ${match.legsWon[p.id] > match.legsWon[match.players[index === 0 ? 1 : 0].id] ? 'text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.5)]' : 'text-gray-400'}`}>
                                {match.legsWon[p.id]}
                            </span>
                        </div>
                    </React.Fragment>
                ))}
            </div>
        </div>

        {/* Active Turn Info & Hint */}
        <div className="px-6 py-1 flex flex-col items-center min-h-[60px] justify-end space-y-2">
            {isLegStart && (
                <button 
                  onClick={handleSwitchStart}
                  className="text-[10px] uppercase font-bold tracking-wider text-gray-500 bg-gray-900/50 px-4 py-1 rounded-full border border-gray-700 hover:text-orange-400 hover:border-orange-500/50 transition-colors"
                >
                   Swap Starting Player ⇄
                </button>
            )}
            {showCheckoutHints && <CheckoutHint score={currentScore} />}
        </div>

        {/* Input Area */}
        <div className="bg-gray-800/80 backdrop-blur-xl p-4 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] border-t border-gray-700/50">
          <div className="flex justify-between items-center mb-4 px-3">
             <div className="text-gray-400 text-xs uppercase font-bold tracking-wider">Score Input</div>
             <div className="text-3xl font-mono font-bold text-white tracking-widest min-w-[3ch] text-right text-orange-400 drop-shadow-[0_0_10px_rgba(234,88,12,0.5)]">
                 {inputBuffer || <span className="text-gray-700">0</span>}
             </div>
             <Button variant="ghost" size="sm" onClick={handleUndo} disabled={match.currentLeg.history.length === 0} className="text-xs uppercase font-bold">
               Undo
             </Button>
          </div>

          <div className="flex gap-2 h-64 md:h-72">
            {/* Numpad */}
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
               />
            </div>

            {/* Action Button */}
            <div className="w-1/4 flex flex-col gap-2">
               <Button 
                 className={`h-full text-2xl font-black rounded-xl transition-all duration-300 ${inputBuffer ? 'scale-[1.02] shadow-[0_0_20px_rgba(234,88,12,0.3)]' : ''}`}
                 variant={canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? "primary" : "secondary"}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
          </div>
        </div>
      </div>

      {/* --- MODALS --- */}

      {/* Checkout Darts Modal */}
      {pendingCheckoutScore !== null && (
          <div className="absolute inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-fadeIn">
             <h2 className="text-3xl font-black italic text-white mb-2 uppercase text-center">Game Shot!</h2>
             <p className="text-gray-400 mb-8 font-bold uppercase tracking-widest text-sm">How many darts?</p>

             <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                 {[1, 2, 3].map(d => {
                     const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                     const disabled = d < minDarts;
                     return (
                         <Button 
                            key={d}
                            variant={disabled ? "secondary" : "primary"}
                            onClick={() => !disabled && handleCheckoutConfirm(d)}
                            className={`h-24 text-4xl ${disabled ? 'opacity-20 cursor-not-allowed' : 'shadow-[0_0_30px_rgba(234,88,12,0.5)] scale-100 hover:scale-105'}`}
                            disabled={disabled}
                         >
                             {d}
                         </Button>
                     )
                 })}
             </div>
             <div className="mt-8">
                <Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button>
             </div>
          </div>
      )}

      {/* Settings Modal */}
      {showSettings && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm border border-gray-700 shadow-2xl">
            <h2 className="text-xl font-black italic text-white mb-6 text-center uppercase">Settings</h2>

            <div className="space-y-4 mb-8">
                <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg border border-gray-700">
                    <span className="text-gray-300 font-bold text-sm">Checkout Guide</span>
                    <button 
                        onClick={() => setShowCheckoutHints(!showCheckoutHints)}
                        className={`w-12 h-6 rounded-full transition-colors relative ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}
                    >
                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform shadow-md ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                    </button>
                </div>
            </div>

            <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
          </div>
        </div>
      )}

      {/* Exit Confirmation Modal */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 italic">ABORT GAME?</h3>
              <p className="text-gray-400 mb-8 text-sm">Current match progress will be lost.</p>

              <div className="grid grid-cols-2 gap-3">
                  <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>
                      Resume
                  </Button>
                  <Button variant="danger" onClick={onExit}>
                      Quit
                  </Button>
              </div>
           </div>
        </div>
      )}

      {/* Live Stats Modal */}
      {showStats && (
        <StatsModal 
            match={match} 
            onClose={() => setShowStats(false)} 
            title="LIVE MATCH STATS"
        />
      )}

    </div>
  );
};

import { GameConfig, MatchState, Player, LegState, Turn, InOutRule } from '../types';

export const createMatch = (players: Player[], config: GameConfig): MatchState => {
  const initialLeg: LegState = {
    scores: {},
    history: [],
    winnerId: null,
    startingPlayerIndex: 0,
  };

  players.forEach(p => {
    initialLeg.scores[p.id] = config.startingScore;
  });

  const legsWon: Record<string, number> = {};
  players.forEach(p => (legsWon[p.id] = 0));

  return {
    id: crypto.randomUUID(),
    config,
    players,
    legsWon,
    completedLegs: [],
    currentLeg: initialLeg,
    status: 'active',
    matchWinnerId: null,
    currentPlayerIndex: 0,
  };
};

const isBust = (
  currentScore: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  const remaining = currentScore - turnScore;

  if (remaining < 0) return true;
  if (remaining === 0) return false; // Potential checkout, validated elsewhere

  // If Double Out, you cannot leave yourself with 1
  if (checkOut === 'Double' && remaining === 1) return true;

  // If Master Out, you cannot leave yourself with 1 (Double or Triple needed)
  if (checkOut === 'Master' && remaining === 1) return true;

  return false;
};

// Check if the current throw sequence is a valid checkout
const isValidCheckout = (
  remaining: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  if (remaining - turnScore !== 0) return false;
  return true;
};

// Helper to determine minimum darts required for a score
export const getMinDartsForScore = (score: number, checkOut: InOutRule = 'Double'): number => {
  // Common impossible limits
  if (score > 110) return 3; // Even 120 (T20 20 D20) needs 3. T20 T20 D20 is 160.

  // Rule specific minimums
  if (checkOut === 'Double') {
      if (score > 110) return 3;
      if (score === 110) return 3; // T20 18 D16
      if (score > 100) {
          // Can we do it in 2? T20 D20 = 100. T20 Bull = 110.
          // Max 2 dart finish is 110 (T20 Bull).
          // Max 2 dart finish ending in double (not bull) is 100 (T20 D20).
          // 101-109 need 3.
          if (score === 110) return 2; // T20 Bull
          if (score > 100) return 3;
      }

      if (score > 50) return 2; // Max 1 dart is 50 (Bull).

      // If score is <= 50, it could be 1 dart IF it's a double (even numbers or 50)
      if (score === 50) return 1;
      if (score % 2 === 0 && score <= 40) return 1;

      return 2; // Odd numbers under 50 needs at least 2 (S + D)
  } 
  else if (checkOut === 'Master') {
      // Finish on Double, Triple or Bull.
      // Max 1 dart: 60 (T20).
      if (score <= 60 && (score % 3 === 0 || score % 2 === 0 || score === 50 || score === 25)) {
          // Is it a valid single D/T? 
          // T20=60, T19=57... T1=3.
          // D20=40... D1=2.
          // Bull=50, 25=25.
          // So essentially most numbers under 60 can be 1 dart? 
          // 1? No. 2(D1), 3(T1), 4(D2), 5(No), 6(D3/T2)...
          // Heuristic:
          if (score <= 40 && score % 2 === 0) return 1;
          if (score <= 60 && score % 3 === 0) return 1;
          if (score === 25 || score === 50) return 1;
          // If not one of those, it needs 2.
          return 2;
      }
      if (score > 60) {
          // Max 2 darts: T20 T20 = 120.
          if (score <= 120) return 2;
          return 3;
      }
      return 2;
  }
  else {
      // Open Out: Finish on anything.
      if (score <= 60) return 1; // Can hit any single/double/triple
      if (score <= 120) return 2; // T20 T20
      return 3;
  }
};

export const submitTurn = (
  match: MatchState,
  turnScore: number,
  dartsThrown: number = 3
): MatchState => {
  if (match.status === 'finished') return match;

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentLeg = match.currentLeg;
  const currentScore = currentLeg.scores[currentPlayer.id];

  // 1. Calculate Bust
  const busted = isBust(currentScore, turnScore, match.config.checkOut);

  // 2. Determine new score
  let newScore = currentScore;
  let legWon = false;

  if (!busted) {
    newScore = currentScore - turnScore;
    if (newScore === 0) {
      legWon = isValidCheckout(currentScore, turnScore, match.config.checkOut);
    }
  }

  // 3. Update History
  const newTurn: Turn = {
    playerId: currentPlayer.id,
    score: turnScore,
    isBust: busted,
    remainingAfter: busted ? currentScore : newScore,
    dartsThrown: busted ? 3 : dartsThrown // If bust, always counts as 3 darts usually, or user specific logic? Standard is 3 unless specified, but for simplicity we assume 3 on bust/normal turn, and variable on checkout.
  };

  const newHistory = [...currentLeg.history, newTurn];

  // 4. Update Leg State
  const newLegScores = { ...currentLeg.scores, [currentPlayer.id]: newTurn.remainingAfter };

  let nextMatchState = { ...match };

  if (legWon) {
    // Handle Leg Win
    const newLegsWon = { ...match.legsWon, [currentPlayer.id]: match.legsWon[currentPlayer.id] + 1 };

    // Create the finished leg object to store in history
    const finishedLeg: LegState = { 
      ...currentLeg, 
      scores: newLegScores, 
      history: newHistory, 
      winnerId: currentPlayer.id 
    };

    const newCompletedLegs = [...match.completedLegs, finishedLeg];

    // Check Match Win
    if (newLegsWon[currentPlayer.id] >= match.config.legsToWin) {
      // Match Finished
      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        completedLegs: newCompletedLegs,
        currentLeg: finishedLeg, // Keep final state visible
        status: 'finished',
        matchWinnerId: currentPlayer.id
      };
    } else {
      // New Leg Setup
      const nextLegIndex = match.currentLeg.startingPlayerIndex + 1 < match.players.length 
        ? match.currentLeg.startingPlayerIndex + 1 
        : 0;

      const nextLeg: LegState = {
        scores: {},
        history: [],
        winnerId: null,
        startingPlayerIndex: nextLegIndex
      };
      match.players.forEach(p => nextLeg.scores[p.id] = match.config.startingScore);

      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        completedLegs: newCompletedLegs,
        currentLeg: nextLeg,
        currentPlayerIndex: nextLegIndex // Next leg starter
      };
    }
  } else {
    // Continue Leg
    const nextPlayerIndex = (match.currentPlayerIndex + 1) % match.players.length;
    nextMatchState = {
      ...match,
      currentLeg: {
        ...currentLeg,
        scores: newLegScores,
        history: newHistory
      },
      currentPlayerIndex: nextPlayerIndex
    };
  }

  return nextMatchState;
};

export const undoTurn = (match: MatchState): MatchState => {
  // Simplistic Undo: only works within the current leg for now
  if (match.currentLeg.history.length === 0) return match;

  const lastTurn = match.currentLeg.history[match.currentLeg.history.length - 1];
  const prevHistory = match.currentLeg.history.slice(0, -1);

  const targetPlayerId = lastTurn.playerId;
  const currentScore = match.currentLeg.scores[targetPlayerId];

  let restoredScore = currentScore;
  if (!lastTurn.isBust) {
    restoredScore = currentScore + lastTurn.score;
  }

  const newScores = { ...match.currentLeg.scores, [targetPlayerId]: restoredScore };

  // Restore active player to the one who just played
  const playerIndex = match.players.findIndex(p => p.id === targetPlayerId);

  return {
    ...match,
    currentLeg: {
      ...match.currentLeg,
      scores: newScores,
      history: prevHistory
    },
    currentPlayerIndex: playerIndex,
    status: 'active',
    matchWinnerId: null
  };
};

export const switchStartPlayer = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length > 0) return match;

  const nextIndex = (match.currentPlayerIndex + 1) % match.players.length;

  return {
    ...match,
    currentPlayerIndex: nextIndex,
    currentLeg: {
      ...match.currentLeg,
      startingPlayerIndex: nextIndex
    }
  };
};

// --- STATISTICS ENGINE ---

export interface DetailedPlayerStats {
  threeDartAvg: string;
  first9Avg: string;
  checkoutPercent: string; // Placeholder for now as we don't track missed doubles
  highestCheckout: number;
  highestScore: number;
  bestLegDarts: number | null;
  worstLegDarts: number | null;
  scoreCounts: {
    c180: number;
    c160: number; // 160-179
    c140: number; // 140-159
    c120: number; // 120-139
    c100: number; // 100-119
    c80: number;  // 80-99
    c60: number;  // 60-79
    c40: number;  // 40-59
  };
  legsWon: number;
}

export const calculatePlayerStats = (match: MatchState, playerId: string) => {
  // Basic stats for the score card
  const calculateAvg = (turns: Turn[]) => {
    const playerTurns = turns.filter(t => t.playerId === playerId);
    if (playerTurns.length === 0) return 0.0;

    const totalScore = playerTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
    const totalDarts = playerTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

    if (totalDarts === 0) return 0.0;
    return (totalScore / totalDarts) * 3;
  };

  const calculateTotalDarts = (turns: Turn[]) => {
      return turns
          .filter(t => t.playerId === playerId)
          .reduce((acc, t) => acc + t.dartsThrown, 0);
  }

  // Current Leg Stats
  const legAvg = calculateAvg(match.currentLeg.history);
  const legDarts = calculateTotalDarts(match.currentLeg.history);

  // Match Stats (All turns)
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history);

  const matchAvg = calculateAvg(allTurns);
  const matchDarts = calculateTotalDarts(allTurns);

  return {
    legAvg: legAvg.toFixed(1),
    legDarts,
    matchAvg: matchAvg.toFixed(1),
    matchDarts
  };
};

export const calculateDetailedStats = (match: MatchState, playerId: string): DetailedPlayerStats => {
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history).filter(t => t.playerId === playerId);

  // 1. Scoring Counts
  const counts = {
    c180: 0, c160: 0, c140: 0, c120: 0, c100: 0, c80: 0, c60: 0, c40: 0
  };
  let highestScore = 0;

  allTurns.forEach(t => {
    if (t.isBust) return; // Ignore bust scores for high scores? Usually yes.
    const s = t.score;
    if (s > highestScore) highestScore = s;

    if (s === 180) counts.c180++;
    else if (s >= 160) counts.c160++;
    else if (s >= 140) counts.c140++;
    else if (s >= 120) counts.c120++;
    else if (s >= 100) counts.c100++;
    else if (s >= 80) counts.c80++;
    else if (s >= 60) counts.c60++;
    else if (s >= 40) counts.c40++;
  });

  // 2. 3-Dart Average
  const totalScore = allTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
  const totalDarts = allTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
  const threeDartAvg = totalDarts > 0 ? ((totalScore / totalDarts) * 3).toFixed(1) : "0.0";

  // 3. First 9 Avg
  let f9TotalScore = 0;
  let f9TotalDarts = 0;

  allLegs.forEach(leg => {
    const playerTurns = leg.history.filter(t => t.playerId === playerId);
    let dartsCounted = 0;
    for (const turn of playerTurns) {
      if (dartsCounted >= 9) break;
      f9TotalScore += turn.isBust ? 0 : turn.score;
      f9TotalDarts += turn.dartsThrown;
      dartsCounted += turn.dartsThrown;
    }
  });
  const first9Avg = f9TotalDarts > 0 ? ((f9TotalScore / f9TotalDarts) * 3).toFixed(1) : "0.0";

  // 4. Best/Worst Legs (Darts thrown in WON legs)
  let bestLeg: number | null = null;
  let worstLeg: number | null = null;
  let highestCheckout = 0;

  match.completedLegs.forEach(leg => {
    if (leg.winnerId === playerId) {
      // It's a won leg, count darts
      const darts = leg.history.filter(t => t.playerId === playerId).reduce((acc, t) => acc + t.dartsThrown, 0);

      if (bestLeg === null || darts < bestLeg) bestLeg = darts;
      if (worstLeg === null || darts > worstLeg) worstLeg = darts;

      // Check for checkout score (last turn)
      const lastTurn = leg.history[leg.history.length - 1];
      if (lastTurn && lastTurn.playerId === playerId) {
        if (lastTurn.score > highestCheckout) highestCheckout = lastTurn.score;
      }
    }
  });

  // 5. Checkout % (Placeholder logic: Legs Won / Legs Won + Legs Lost is NOT CO%, strictly it is N/A without input)
  // For MVP, we will show "N/A" unless we want to use Win %
  const legsWonCount = match.legsWon[playerId] || 0;
  // const legsPlayed = match.completedLegs.length; // Not accurate for CO%

  return {
    threeDartAvg,
    first9Avg,
    checkoutPercent: "N/A", // Requires dart-by-dart miss tracking
    highestCheckout,
    highestScore,
    bestLegDarts: bestLeg,
    worstLegDarts: worstLeg,
    scoreCounts: counts,
    legsWon: legsWonCount
  };
};

