export type InOutRule = 'Open' | 'Double' | 'Master';
export type MatchMode = 'LEGS' | 'SETS';

export interface Player {
  id: string;
  name: string;
}

export interface GameConfig {
  startingScore: number;
  checkIn: InOutRule;
  checkOut: InOutRule;
  matchMode: MatchMode;
  setsToWin: number; // Used if matchMode is 'SETS'
  legsToWin: number; // Legs to win match (if LEGS) or Legs to win a Set (if SETS)
}

export interface Turn {
  playerId: string;
  score: number;
  isBust: boolean;
  remainingAfter: number;
  dartsThrown: number; // Usually 3, unless checkout
}

export interface LegState {
  scores: Record<string, number>; // playerId -> remaining score
  history: Turn[];
  winnerId: string | null;
  startingPlayerIndex: number; // Rotates each leg
}

export interface MatchState {
  id: string;
  config: GameConfig;
  players: Player[];
  setsWon: Record<string, number>; // New: Track sets
  legsWon: Record<string, number>; // playerId -> count (Current Set legs if mode is SETS)
  completedLegs: LegState[]; // History of previous legs for stats
  currentLeg: LegState;
  status: 'active' | 'finished';
  matchWinnerId: string | null;
  currentPlayerIndex: number; // Who throws now
}

import { GameConfig, MatchState, Player, LegState, Turn, InOutRule } from '../types';

export const createMatch = (players: Player[], config: GameConfig): MatchState => {
  const initialLeg: LegState = {
    scores: {},
    history: [],
    winnerId: null,
    startingPlayerIndex: 0,
  };

  players.forEach(p => {
    initialLeg.scores[p.id] = config.startingScore;
  });

  const legsWon: Record<string, number> = {};
  const setsWon: Record<string, number> = {};

  players.forEach(p => {
    legsWon[p.id] = 0;
    setsWon[p.id] = 0;
  });

  return {
    id: crypto.randomUUID(),
    config,
    players,
    legsWon,
    setsWon,
    completedLegs: [],
    currentLeg: initialLeg,
    status: 'active',
    matchWinnerId: null,
    currentPlayerIndex: 0,
  };
};

const isBust = (
  currentScore: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  const remaining = currentScore - turnScore;

  if (remaining < 0) return true;
  if (remaining === 0) return false; // Potential checkout, validated elsewhere

  // If Double Out, you cannot leave yourself with 1
  if (checkOut === 'Double' && remaining === 1) return true;

  // If Master Out, you cannot leave yourself with 1 (Double or Triple needed)
  if (checkOut === 'Master' && remaining === 1) return true;

  return false;
};

// Check if the current throw sequence is a valid checkout
const isValidCheckout = (
  remaining: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  if (remaining - turnScore !== 0) return false;
  return true;
};

// Helper to determine minimum darts required for a score
export const getMinDartsForScore = (score: number, checkOut: InOutRule = 'Double'): number => {
  // Common impossible limits
  if (score > 110) return 3; // Even 120 (T20 20 D20) needs 3. T20 T20 D20 is 160.

  // Rule specific minimums
  if (checkOut === 'Double') {
      if (score > 110) return 3;
      if (score === 110) return 3; // T20 18 D16
      if (score > 100) {
          // Can we do it in 2? T20 D20 = 100. T20 Bull = 110.
          // Max 2 dart finish is 110 (T20 Bull).
          // Max 2 dart finish ending in double (not bull) is 100 (T20 D20).
          // 101-109 need 3.
          if (score === 110) return 2; // T20 Bull
          if (score > 100) return 3;
      }

      if (score > 50) return 2; // Max 1 dart is 50 (Bull).

      // If score is <= 50, it could be 1 dart IF it's a double (even numbers or 50)
      if (score === 50) return 1;
      if (score % 2 === 0 && score <= 40) return 1;

      return 2; // Odd numbers under 50 needs at least 2 (S + D)
  } 
  else if (checkOut === 'Master') {
      // Finish on Double, Triple or Bull.
      // Max 1 dart: 60 (T20).
      if (score <= 60 && (score % 3 === 0 || score % 2 === 0 || score === 50 || score === 25)) {
          // Is it a valid single D/T? 
          // T20=60, T19=57... T1=3.
          // D20=40... D1=2.
          // Bull=50, 25=25.
          // So essentially most numbers under 60 can be 1 dart? 
          // 1? No. 2(D1), 3(T1), 4(D2), 5(No), 6(D3/T2)...
          // Heuristic:
          if (score <= 40 && score % 2 === 0) return 1;
          if (score <= 60 && score % 3 === 0) return 1;
          if (score === 25 || score === 50) return 1;
          // If not one of those, it needs 2.
          return 2;
      }
      if (score > 60) {
          // Max 2 darts: T20 T20 = 120.
          if (score <= 120) return 2;
          return 3;
      }
      return 2;
  }
  else {
      // Open Out: Finish on anything.
      if (score <= 60) return 1; // Can hit any single/double/triple
      if (score <= 120) return 2; // T20 T20
      return 3;
  }
};

export const submitTurn = (
  match: MatchState,
  turnScore: number,
  dartsThrown: number = 3
): MatchState => {
  if (match.status === 'finished') return match;

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentLeg = match.currentLeg;
  const currentScore = currentLeg.scores[currentPlayer.id];

  // 1. Calculate Bust
  const busted = isBust(currentScore, turnScore, match.config.checkOut);

  // 2. Determine new score
  let newScore = currentScore;
  let legWon = false;

  if (!busted) {
    newScore = currentScore - turnScore;
    if (newScore === 0) {
      legWon = isValidCheckout(currentScore, turnScore, match.config.checkOut);
    }
  }

  // 3. Update History
  const newTurn: Turn = {
    playerId: currentPlayer.id,
    score: turnScore,
    isBust: busted,
    remainingAfter: busted ? currentScore : newScore,
    dartsThrown: busted ? 3 : dartsThrown 
  };

  const newHistory = [...currentLeg.history, newTurn];

  // 4. Update Leg State
  const newLegScores = { ...currentLeg.scores, [currentPlayer.id]: newTurn.remainingAfter };

  let nextMatchState = { ...match };

  if (legWon) {
    // --- LEG WON LOGIC ---
    let newLegsWon = { ...match.legsWon, [currentPlayer.id]: match.legsWon[currentPlayer.id] + 1 };
    let newSetsWon = { ...match.setsWon };

    // Create the finished leg object to store in history
    const finishedLeg: LegState = { 
      ...currentLeg, 
      scores: newLegScores, 
      history: newHistory, 
      winnerId: currentPlayer.id 
    };

    const newCompletedLegs = [...match.completedLegs, finishedLeg];

    let isMatchOver = false;

    if (match.config.matchMode === 'SETS') {
        // Check Set Win Condition
        if (newLegsWon[currentPlayer.id] >= match.config.legsToWin) {
            // SET WON
            newSetsWon[currentPlayer.id] += 1;

            // Check Match Win Condition (by Sets)
            if (newSetsWon[currentPlayer.id] >= match.config.setsToWin) {
                isMatchOver = true;
            } else {
                // Prepare for next Set: Reset Legs Won count
                Object.keys(newLegsWon).forEach(pid => newLegsWon[pid] = 0);
            }
        }
    } else {
        // LEGS MODE
        if (newLegsWon[currentPlayer.id] >= match.config.legsToWin) {
            isMatchOver = true;
        }
    }

    if (isMatchOver) {
      // Match Finished
      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        setsWon: newSetsWon,
        completedLegs: newCompletedLegs,
        currentLeg: finishedLeg, // Keep final state visible
        status: 'finished',
        matchWinnerId: currentPlayer.id
      };
    } else {
      // New Leg Setup
      const nextLegIndex = match.currentLeg.startingPlayerIndex + 1 < match.players.length 
        ? match.currentLeg.startingPlayerIndex + 1 
        : 0;

      const nextLeg: LegState = {
        scores: {},
        history: [],
        winnerId: null,
        startingPlayerIndex: nextLegIndex
      };
      match.players.forEach(p => nextLeg.scores[p.id] = match.config.startingScore);

      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        setsWon: newSetsWon,
        completedLegs: newCompletedLegs,
        currentLeg: nextLeg,
        currentPlayerIndex: nextLegIndex // Next leg starter
      };
    }
  } else {
    // Continue Leg
    const nextPlayerIndex = (match.currentPlayerIndex + 1) % match.players.length;
    nextMatchState = {
      ...match,
      currentLeg: {
        ...currentLeg,
        scores: newLegScores,
        history: newHistory
      },
      currentPlayerIndex: nextPlayerIndex
    };
  }

  return nextMatchState;
};

export const undoTurn = (match: MatchState): MatchState => {
  // Simplistic Undo: only works within the current leg for now
  if (match.currentLeg.history.length === 0) return match;

  const lastTurn = match.currentLeg.history[match.currentLeg.history.length - 1];
  const prevHistory = match.currentLeg.history.slice(0, -1);

  const targetPlayerId = lastTurn.playerId;
  const currentScore = match.currentLeg.scores[targetPlayerId];

  let restoredScore = currentScore;
  if (!lastTurn.isBust) {
    restoredScore = currentScore + lastTurn.score;
  }

  const newScores = { ...match.currentLeg.scores, [targetPlayerId]: restoredScore };

  // Restore active player to the one who just played
  const playerIndex = match.players.findIndex(p => p.id === targetPlayerId);

  return {
    ...match,
    currentLeg: {
      ...match.currentLeg,
      scores: newScores,
      history: prevHistory
    },
    currentPlayerIndex: playerIndex,
    status: 'active',
    matchWinnerId: null
  };
};

export const switchStartPlayer = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length > 0) return match;

  const nextIndex = (match.currentPlayerIndex + 1) % match.players.length;

  return {
    ...match,
    currentPlayerIndex: nextIndex,
    currentLeg: {
      ...match.currentLeg,
      startingPlayerIndex: nextIndex
    }
  };
};

// --- STATISTICS ENGINE ---

export interface DetailedPlayerStats {
  threeDartAvg: string;
  first9Avg: string;
  checkoutPercent: string; 
  highestCheckout: number;
  highestScore: number;
  bestLegDarts: number | null;
  worstLegDarts: number | null;
  scoreCounts: {
    c180: number;
    c160: number; // 160-179
    c140: number; // 140-159
    c120: number; // 120-139
    c100: number; // 100-119
    c80: number;  // 80-99
    c60: number;  // 60-79
    c40: number;  // 40-59
  };
  legsWon: number; // Total legs won (across sets if applicable)
}

export const calculatePlayerStats = (match: MatchState, playerId: string) => {
  // Basic stats for the score card
  const calculateAvg = (turns: Turn[]) => {
    const playerTurns = turns.filter(t => t.playerId === playerId);
    if (playerTurns.length === 0) return 0.0;

    const totalScore = playerTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
    const totalDarts = playerTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

    if (totalDarts === 0) return 0.0;
    return (totalScore / totalDarts) * 3;
  };

  const calculateTotalDarts = (turns: Turn[]) => {
      return turns
          .filter(t => t.playerId === playerId)
          .reduce((acc, t) => acc + t.dartsThrown, 0);
  }

  // Current Leg Stats
  const legAvg = calculateAvg(match.currentLeg.history);
  const legDarts = calculateTotalDarts(match.currentLeg.history);

  // Match Stats (All turns)
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history);

  const matchAvg = calculateAvg(allTurns);
  const matchDarts = calculateTotalDarts(allTurns);

  return {
    legAvg: legAvg.toFixed(1),
    legDarts,
    matchAvg: matchAvg.toFixed(1),
    matchDarts
  };
};

export const calculateDetailedStats = (match: MatchState, playerId: string): DetailedPlayerStats => {
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history).filter(t => t.playerId === playerId);

  // 1. Scoring Counts
  const counts = {
    c180: 0, c160: 0, c140: 0, c120: 0, c100: 0, c80: 0, c60: 0, c40: 0
  };
  let highestScore = 0;

  allTurns.forEach(t => {
    if (t.isBust) return; // Ignore bust scores for high scores? Usually yes.
    const s = t.score;
    if (s > highestScore) highestScore = s;

    if (s === 180) counts.c180++;
    else if (s >= 160) counts.c160++;
    else if (s >= 140) counts.c140++;
    else if (s >= 120) counts.c120++;
    else if (s >= 100) counts.c100++;
    else if (s >= 80) counts.c80++;
    else if (s >= 60) counts.c60++;
    else if (s >= 40) counts.c40++;
  });

  // 2. 3-Dart Average
  const totalScore = allTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
  const totalDarts = allTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
  const threeDartAvg = totalDarts > 0 ? ((totalScore / totalDarts) * 3).toFixed(1) : "0.0";

  // 3. First 9 Avg
  let f9TotalScore = 0;
  let f9TotalDarts = 0;

  allLegs.forEach(leg => {
    const playerTurns = leg.history.filter(t => t.playerId === playerId);
    let dartsCounted = 0;
    for (const turn of playerTurns) {
      if (dartsCounted >= 9) break;
      f9TotalScore += turn.isBust ? 0 : turn.score;
      f9TotalDarts += turn.dartsThrown;
      dartsCounted += turn.dartsThrown;
    }
  });
  const first9Avg = f9TotalDarts > 0 ? ((f9TotalScore / f9TotalDarts) * 3).toFixed(1) : "0.0";

  // 4. Best/Worst Legs (Darts thrown in WON legs)
  let bestLeg: number | null = null;
  let worstLeg: number | null = null;
  let highestCheckout = 0;

  match.completedLegs.forEach(leg => {
    if (leg.winnerId === playerId) {
      // It's a won leg, count darts
      const darts = leg.history.filter(t => t.playerId === playerId).reduce((acc, t) => acc + t.dartsThrown, 0);

      if (bestLeg === null || darts < bestLeg) bestLeg = darts;
      if (worstLeg === null || darts > worstLeg) worstLeg = darts;

      // Check for checkout score (last turn)
      const lastTurn = leg.history[leg.history.length - 1];
      if (lastTurn && lastTurn.playerId === playerId) {
        if (lastTurn.score > highestCheckout) highestCheckout = lastTurn.score;
      }
    }
  });

  // Calculate total legs won (including from sets if completed)
  // Logic: In SETS mode, 'legsWon' state is only for current set.
  // To get total legs won, we need to iterate completedLegs.
  const totalLegsWon = match.completedLegs.filter(l => l.winnerId === playerId).length + 
                       (match.legsWon[playerId] && match.config.matchMode === 'LEGS' ? 0 : 0); 
                       // Note: legsWon in state is technically completed legs in current set.
                       // For safety, counting from completedLegs is best, plus potentially the match.legsWon?
                       // Actually match.legsWon tracks the current progress.
                       // If match is finished, match.legsWon has the final count for the last set.

  return {
    threeDartAvg,
    first9Avg,
    checkoutPercent: "N/A", 
    highestCheckout,
    highestScore,
    bestLegDarts: bestLeg,
    worstLegDarts: worstLeg,
    scoreCounts: counts,
    legsWon: totalLegsWon
  };
};

import React, { useState } from 'react';
import { Button } from '../components/ui/Button';
import { GameConfig, Player, InOutRule, MatchMode } from '../types';

interface SetupViewProps {
  onStart: (players: Player[], config: GameConfig) => void;
  onBack: () => void;
}

export const SetupView: React.FC<SetupViewProps> = ({ onStart, onBack }) => {
  // Game Starting Score (Default 501 as requested)
  const [startingScore, setStartingScore] = useState(501);

  // Custom Input State
  const [customScoreStr, setCustomScoreStr] = useState('170');

  // Format Config
  const [matchMode, setMatchMode] = useState<MatchMode>('LEGS');
  const [legsToWin, setLegsToWin] = useState(3);
  const [setsToWin, setSetsToWin] = useState(3);

  const [playerNames, setPlayerNames] = useState<string[]>(['Player 1', 'Player 2']);

  // Defaults: Double Out, Open In
  const [checkOut, setCheckOut] = useState<InOutRule>('Double');
  const [checkIn, setCheckIn] = useState<InOutRule>('Open');

  const updatePlayerCount = (delta: number) => {
    const currentCount = playerNames.length;
    const newCount = Math.max(1, Math.min(4, currentCount + delta));

    if (newCount === currentCount) return;

    setPlayerNames(prev => {
      if (newCount > prev.length) {
        return [...prev, `Player ${newCount}`];
      } else {
        return prev.slice(0, newCount);
      }
    });
  };

  const updatePlayerName = (index: number, name: string) => {
    const newNames = [...playerNames];
    newNames[index] = name;
    setPlayerNames(newNames);
  };

  const handleStart = () => {
    // Ensure valid starting score
    const safeStartingScore = startingScore > 0 ? startingScore : 501;

    const players: Player[] = playerNames.map((name, i) => ({
      id: `p${i+1}`,
      name: name.trim() || `Player ${i+1}`
    }));

    const config: GameConfig = {
      startingScore: safeStartingScore,
      checkIn,
      checkOut,
      matchMode,
      legsToWin, // In sets mode, this becomes legs per set
      setsToWin
    };

    onStart(players, config);
  };

  const activeOptionClass = "bg-gradient-to-r from-orange-600 to-red-600 text-white border-transparent shadow-[0_0_10px_rgba(234,88,12,0.3)]";
  const inactiveOptionClass = "bg-gray-800 border-gray-700 text-gray-400 hover:border-orange-500/50 hover:text-gray-200";

  const getRuleDescription = (type: 'in' | 'out', rule: InOutRule) => {
     if (type === 'out') {
         switch(rule) {
             case 'Open': return "Finish on any segment (Single, Double, Triple).";
             case 'Double': return "Standard: Finish on a Double or Bullseye.";
             case 'Master': return "Finish on a Double, Triple or Bullseye.";
         }
     } else {
         switch(rule) {
             case 'Open': return "Start scoring immediately on any hit.";
             case 'Double': return "Must hit a Double to start scoring.";
             case 'Master': return "Must hit a Double or Triple to start scoring.";
         }
     }
  };

  const presets = [301, 501, 701, 1001];
  const isPresetSelected = presets.includes(startingScore);
  const isCustomActive = !isPresetSelected || startingScore === parseInt(customScoreStr || '0');

  const handleCustomFocus = () => {
      const val = parseInt(customScoreStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  const handleCustomChange = (valStr: string) => {
      setCustomScoreStr(valStr);
      const val = parseInt(valStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      <div className="flex items-center mb-6">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
            MATCH SETUP
        </h2>
      </div>

      <div className="flex-1 space-y-6 max-w-md mx-auto w-full overflow-y-auto pb-4 custom-scrollbar">

        {/* Score Selection */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Starting Score</label>
          <div className="grid grid-cols-4 gap-2 mb-3">
            {presets.map(score => (
              <button
                key={score}
                onClick={() => setStartingScore(score)}
                className={`py-3 rounded font-black border transition-all duration-200 ${startingScore === score ? activeOptionClass : inactiveOptionClass}`}
              >
                {score}
              </button>
            ))}
          </div>

           <div 
             className={`flex items-center space-x-3 p-3 rounded-lg border transition-all duration-200 ${isCustomActive && !presets.includes(startingScore) ? 'bg-gray-800 border-orange-500 shadow-[0_0_10px_rgba(234,88,12,0.15)]' : 'bg-gray-800/30 border-gray-700'}`}
             onClick={handleCustomFocus}
           >
               <span className={`text-xs font-bold uppercase tracking-wider whitespace-nowrap ${isCustomActive && !presets.includes(startingScore) ? 'text-orange-500' : 'text-gray-500'}`}>Custom Score</span>
               <input 
                  type="number" 
                  min="1"
                  max="9999"
                  value={customScoreStr}
                  onChange={(e) => handleCustomChange(e.target.value)}
                  onFocus={handleCustomFocus}
                  className={`w-full bg-transparent text-right font-mono font-black text-xl focus:outline-none focus:text-orange-500 ${isCustomActive && !presets.includes(startingScore) ? 'text-white' : 'text-gray-500'}`}
                  placeholder="Enter score..."
               />
           </div>
        </section>

        {/* Players Configuration */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Players</label>
          <div className="flex items-center space-x-4 bg-gray-800/50 p-2 rounded-lg mb-4 border border-gray-700">
             <button onClick={() => updatePlayerCount(-1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">-</button>
             <span className="flex-1 text-center font-black text-2xl text-white">{playerNames.length}</span>
             <button onClick={() => updatePlayerCount(1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">+</button>
          </div>

