           </div>
        </div>
      )}

      {/* Live Stats Modal */}
      {showStats && (
        <StatsModal 
            match={match} 
            onClose={() => setShowStats(false)} 
            title="LIVE MATCH STATS"
        />
      )}

    </div>
  );
};

import { GameConfig, MatchState, Player, LegState, Turn, InOutRule } from '../types';

export const createMatch = (players: Player[], config: GameConfig): MatchState => {
  // Logic: In doubles, we have 4 players but only 2 scoring entities (teams).
  // In solo, teamId = playerId.

  const initialLeg: LegState = {
    scores: {},
    history: [],
    winnerId: null,
    startingPlayerIndex: 0,
  };

  const legsWon: Record<string, number> = {};
  const setsWon: Record<string, number> = {};

  // Initialize scores based on TEAM ID
  players.forEach(p => {
    // If multiple players have same teamId, this just overwrites/confirms the entry
    initialLeg.scores[p.teamId] = config.startingScore;
    legsWon[p.teamId] = 0;
    setsWon[p.teamId] = 0;
  });

  return {
    id: crypto.randomUUID(),
    config,
    players,
    legsWon,
    setsWon,
    completedLegs: [],
    currentLeg: initialLeg,
    status: 'active',
    matchWinnerId: null,
    currentPlayerIndex: 0,
  };
};

// Reorder players array: MatchStarter -> OtherTeamStarter -> MatchStarterPartner -> OtherTeamPartner
export const reorderPlayersForDoubles = (
    match: MatchState, 
    t1StarterId: string, 
    t2StarterId: string, 
    startingTeamId: string
): MatchState => {
    // Helper to find player by ID from the current list
    const getP = (id: string) => match.players.find(pl => pl.id === id)!;

    const t1Starter = getP(t1StarterId);
    const t2Starter = getP(t2StarterId);

    // Find partners
    const t1Partner = match.players.find(p => p.teamId === 'team1' && p.id !== t1StarterId)!;
    const t2Partner = match.players.find(p => p.teamId === 'team2' && p.id !== t2StarterId)!;

    let newOrder: Player[] = [];

    if (startingTeamId === 'team1') {
        // Team 1 Starts: T1S -> T2S -> T1P -> T2P
        newOrder = [t1Starter, t2Starter, t1Partner, t2Partner];
    } else {
        // Team 2 Starts: T2S -> T1S -> T2P -> T1P
        newOrder = [t2Starter, t1Starter, t2Partner, t1Partner];
    }

    return {
        ...match,
        players: newOrder,
        currentPlayerIndex: 0,
        currentLeg: {
            ...match.currentLeg,
            startingPlayerIndex: 0
        }
    };
};

const isBust = (
  currentScore: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  const remaining = currentScore - turnScore;

  if (remaining < 0) return true;
  if (remaining === 0) return false; 

  if (checkOut === 'Double' && remaining === 1) return true;
  if (checkOut === 'Master' && remaining === 1) return true;

  return false;
};

const isValidCheckout = (
  remaining: number,
  turnScore: number,
  checkOut: InOutRule
): boolean => {
  if (remaining - turnScore !== 0) return false;
  return true;
};

export const getMinDartsForScore = (score: number, checkOut: InOutRule = 'Double'): number => {
  if (score > 110) return 3; 

  if (checkOut === 'Double') {
      if (score > 110) return 3;
      if (score === 110) return 3; 
      if (score > 100) {
          if (score === 110) return 2; 
          if (score > 100) return 3;
      }

      if (score > 50) return 2;
      if (score === 50) return 1;
      if (score % 2 === 0 && score <= 40) return 1;
      return 2;
  } 
  else if (checkOut === 'Master') {
      if (score <= 40 && score % 2 === 0) return 1;
      if (score <= 60 && score % 3 === 0) return 1;
      if (score === 25 || score === 50) return 1;
      return 2;
  }
  else {
      if (score <= 60) return 1;
      if (score <= 120) return 2;
      return 3;
  }
};

export const submitTurn = (
  match: MatchState,
  turnScore: number,
  dartsThrown: number = 3
): MatchState => {
  if (match.status === 'finished') return match;

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentTeamId = currentPlayer.teamId; // KEY CHANGE: Score by Team
  const currentLeg = match.currentLeg;
  const currentScore = currentLeg.scores[currentTeamId];

  // 1. Calculate Bust
  const busted = isBust(currentScore, turnScore, match.config.checkOut);

  // 2. Determine new score
  let newScore = currentScore;
  let legWon = false;

  if (!busted) {
    newScore = currentScore - turnScore;
    if (newScore === 0) {
      legWon = isValidCheckout(currentScore, turnScore, match.config.checkOut);
    }
  }

  // 3. Update History
  const newTurn: Turn = {
    playerId: currentPlayer.id,
    score: turnScore,
    isBust: busted,
    remainingAfter: busted ? currentScore : newScore,
    dartsThrown: busted ? 3 : dartsThrown 
  };

  const newHistory = [...currentLeg.history, newTurn];

  // 4. Update Leg State (By Team ID)
  const newLegScores = { ...currentLeg.scores, [currentTeamId]: newTurn.remainingAfter };

  let nextMatchState = { ...match };

  if (legWon) {
    // --- LEG WON LOGIC (By Team ID) ---
    let newLegsWon = { ...match.legsWon, [currentTeamId]: match.legsWon[currentTeamId] + 1 };
    let newSetsWon = { ...match.setsWon };

    const finishedLeg: LegState = { 
      ...currentLeg, 
      scores: newLegScores, 
      history: newHistory, 
      winnerId: currentTeamId 
    };

    const newCompletedLegs = [...match.completedLegs, finishedLeg];

    let isMatchOver = false;

    if (match.config.matchMode === 'SETS') {
        if (newLegsWon[currentTeamId] >= match.config.legsToWin) {
            newSetsWon[currentTeamId] += 1;

            if (newSetsWon[currentTeamId] >= match.config.setsToWin) {
                isMatchOver = true;
            } else {
                Object.keys(newLegsWon).forEach(tid => newLegsWon[tid] = 0);
            }
        }
    } else {
        if (newLegsWon[currentTeamId] >= match.config.legsToWin) {
            isMatchOver = true;
        }
    }

    if (isMatchOver) {
      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        setsWon: newSetsWon,
        completedLegs: newCompletedLegs,
        currentLeg: finishedLeg, // Keep final state visible
        status: 'finished',
        matchWinnerId: currentTeamId
      };
    } else {
      const nextLegIndex = match.currentLeg.startingPlayerIndex + 1 < match.players.length 
        ? match.currentLeg.startingPlayerIndex + 1 
        : 0;

      const nextLeg: LegState = {
        scores: {},
        history: [],
        winnerId: null,
        startingPlayerIndex: nextLegIndex
      };
      // Initialize scores for all TEAMS
      const uniqueTeamIds = Array.from(new Set(match.players.map(p => p.teamId)));
      uniqueTeamIds.forEach(tid => nextLeg.scores[tid] = match.config.startingScore);

      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        setsWon: newSetsWon,
        completedLegs: newCompletedLegs,
        currentLeg: nextLeg,
        currentPlayerIndex: nextLegIndex
      };
    }
  } else {
    // Continue Leg
    const nextPlayerIndex = (match.currentPlayerIndex + 1) % match.players.length;
    nextMatchState = {
      ...match,
      currentLeg: {
        ...currentLeg,
        scores: newLegScores,
        history: newHistory
      },
      currentPlayerIndex: nextPlayerIndex
    };
  }

  return nextMatchState;
};

export const undoTurn = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length === 0) return match;

  const lastTurn = match.currentLeg.history[match.currentLeg.history.length - 1];
  const prevHistory = match.currentLeg.history.slice(0, -1);

  // Find which team this player belongs to
  const player = match.players.find(p => p.id === lastTurn.playerId);
  if (!player) return match;

  const currentTeamId = player.teamId;
  const currentScore = match.currentLeg.scores[currentTeamId];

  let restoredScore = currentScore;
  if (!lastTurn.isBust) {
    restoredScore = currentScore + lastTurn.score;
  }

  const newScores = { ...match.currentLeg.scores, [currentTeamId]: restoredScore };

  // Restore active player to the one who just played
  const playerIndex = match.players.findIndex(p => p.id === lastTurn.playerId);

  return {
    ...match,
    currentLeg: {
      ...match.currentLeg,
      scores: newScores,
      history: prevHistory
    },
    currentPlayerIndex: playerIndex,
    status: 'active',
    matchWinnerId: null
  };
};

export const switchStartPlayer = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length > 0) return match;

  const nextIndex = (match.currentPlayerIndex + 1) % match.players.length;

  return {
    ...match,
    currentPlayerIndex: nextIndex,
    currentLeg: {
      ...match.currentLeg,
      startingPlayerIndex: nextIndex
    }
  };
};

// --- STATISTICS ENGINE ---

export interface DetailedPlayerStats {
  threeDartAvg: string;
  first9Avg: string;
  checkoutPercent: string; 
  highestCheckout: number;
  highestScore: number;
  bestLegDarts: number | null;
  worstLegDarts: number | null;
  scoreCounts: {
    c180: number; c160: number; c140: number; c120: number; c100: number; c80: number; c60: number; c40: number;
  };
  legsWon: number; 
}

// NOTE: stats are usually calculated per PLAYER for Averages, but per TEAM for Legs Won.
// We will pass teamId for "Legs Won" lookup, but playerId for "Throws".
export const calculatePlayerStats = (match: MatchState, playerId: string) => {
  const player = match.players.find(p => p.id === playerId);
  if (!player) return { legAvg: "0.0", legDarts: 0, matchAvg: "0.0", matchDarts: 0 };

  const calculateAvg = (turns: Turn[]) => {
    const playerTurns = turns.filter(t => t.playerId === playerId);
    if (playerTurns.length === 0) return 0.0;

    const totalScore = playerTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
    const totalDarts = playerTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

    if (totalDarts === 0) return 0.0;
    return (totalScore / totalDarts) * 3;
  };

  const calculateTotalDarts = (turns: Turn[]) => {
      return turns
          .filter(t => t.playerId === playerId)
          .reduce((acc, t) => acc + t.dartsThrown, 0);
  }

  // Current Leg Stats
  const legAvg = calculateAvg(match.currentLeg.history);
  const legDarts = calculateTotalDarts(match.currentLeg.history);

  // Match Stats (All turns)
  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history);

  const matchAvg = calculateAvg(allTurns);
  const matchDarts = calculateTotalDarts(allTurns);

  return {
    legAvg: legAvg.toFixed(1),
    legDarts,
    legAvgRaw: legAvg, // Keeping raw number for logic if needed
    matchAvg: matchAvg.toFixed(1),
    matchDarts
  };
};

export const calculateDetailedStats = (match: MatchState, playerId: string): DetailedPlayerStats => {
  const player = match.players.find(p => p.id === playerId);
  if (!player) return { threeDartAvg: "0.0", first9Avg: "0.0", checkoutPercent: "0", highestCheckout: 0, highestScore: 0, bestLegDarts: null, worstLegDarts: null, scoreCounts: { c180:0, c160:0, c140:0, c120:0, c100:0, c80:0, c60:0, c40:0 }, legsWon: 0 };

  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history).filter(t => t.playerId === playerId);

  const counts = { c180: 0, c160: 0, c140: 0, c120: 0, c100: 0, c80: 0, c60: 0, c40: 0 };
  let highestScore = 0;

  allTurns.forEach(t => {
    if (t.isBust) return; 
    const s = t.score;
    if (s > highestScore) highestScore = s;
    if (s === 180) counts.c180++;
    else if (s >= 160) counts.c160++;
    else if (s >= 140) counts.c140++;
    else if (s >= 120) counts.c120++;
    else if (s >= 100) counts.c100++;
    else if (s >= 80) counts.c80++;
    else if (s >= 60) counts.c60++;
    else if (s >= 40) counts.c40++;
  });

  const totalScore = allTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
  const totalDarts = allTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
  const threeDartAvg = totalDarts > 0 ? ((totalScore / totalDarts) * 3).toFixed(1) : "0.0";

  let f9TotalScore = 0;
  let f9TotalDarts = 0;
  allLegs.forEach(leg => {
    const playerTurns = leg.history.filter(t => t.playerId === playerId);
    let dartsCounted = 0;
    for (const turn of playerTurns) {
      if (dartsCounted >= 9) break;
      f9TotalScore += turn.isBust ? 0 : turn.score;
      f9TotalDarts += turn.dartsThrown;
      dartsCounted += turn.dartsThrown;
    }
  });
  const first9Avg = f9TotalDarts > 0 ? ((f9TotalScore / f9TotalDarts) * 3).toFixed(1) : "0.0";

  // Best/Worst Legs - BASED ON TEAM WIN
  let bestLeg: number | null = null;
  let worstLeg: number | null = null;
  let highestCheckout = 0;

  match.completedLegs.forEach(leg => {
    if (leg.winnerId === player.teamId) {
      // It's a won leg by this player's team
      // Count TEAM darts? Or Player Darts? usually Team Darts in doubles
      const teamDarts = leg.history
        .filter(t => {
            const p = match.players.find(pl => pl.id === t.playerId);
            return p?.teamId === player.teamId;
        })
        .reduce((acc, t) => acc + t.dartsThrown, 0);

      if (bestLeg === null || teamDarts < bestLeg) bestLeg = teamDarts;
      if (worstLeg === null || teamDarts > worstLeg) worstLeg = teamDarts;

      // Check for checkout score (last turn)
      const lastTurn = leg.history[leg.history.length - 1];
      if (lastTurn && lastTurn.playerId === playerId) {
        if (lastTurn.score > highestCheckout) highestCheckout = lastTurn.score;
      }
    }
  });

  const totalLegsWon = match.completedLegs.filter(l => l.winnerId === player.teamId).length + 
                       (match.legsWon[player.teamId] && match.config.matchMode === 'LEGS' ? 0 : 0);

  return {
    threeDartAvg,
    first9Avg,
    checkoutPercent: "N/A", 
    highestCheckout,
    highestScore,
    bestLegDarts: bestLeg,
    worstLegDarts: worstLeg,
    scoreCounts: counts,
    legsWon: totalLegsWon
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, calculatePlayerStats, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);

  // Doubles Starter Selection State
  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  // Helper for starter modal
  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  // Local State for Doubles Starter Selection
  // Pre-select the first player of each team to avoid needing to click if default order is fine
  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  // Settings States
  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  // Score is now looked up by teamId
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      onFinish(match.matchWinnerId);
    }
  }, [match.status, match.matchWinnerId, onFinish]);

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return; // Basic sanitization
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180; // Open and Master can technically finish on 180
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);

    // Safety check
    if (score > 180) return;

    // Check if this is a winning shot
    // Note: This validation depends on the 'Out' rule.
    const maxCheckout = getMaxCheckout(match.config.checkOut);

    if (score === currentScore && score <= maxCheckout) {
         // Intercept for dart count input
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3); // Default 3 darts for normal turn
    setMatch(nextState);
    setInputBuffer('');
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  // Check if checkout is mathematically possible this turn
  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      // Open / Master
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();

  // Is it the start of a leg? (For allowing player switch)
  const isLegStart = match.currentLeg.history.length === 0;

  const getFormatLabel = () => {
      if (match.config.matchMode === 'SETS') {
          return `First to ${match.config.setsToWin} Sets`;
      }
      return `First to ${match.config.legsToWin} Legs`;
  }

  // Group players by Team ID for display
  const teams = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white flex flex-col md:flex-row relative overflow-hidden">

      {/* Top Bar (Mobile) / Side Bar (Desktop) */}
      <div className="bg-gray-900/80 backdrop-blur-md border-b md:border-b-0 md:border-r border-gray-800 p-4 flex justify-between items-center md:flex-col md:w-64 md:h-screen md:justify-start md:space-y-8 z-20">
        <div className="flex flex-col md:items-center">
           <h2 className="font-black text-2xl tracking-tighter italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500 drop-shadow-sm">BOUGNAT DARTS</h2>
           <span className="text-[10px] text-gray-500 uppercase tracking-widest font-bold mt-1">{getFormatLabel()}</span>
           <div className="mt-2 flex gap-2 text-[9px] font-mono text-gray-600 bg-gray-950 px-2 py-1 rounded border border-gray-800">
               <span>IN: <span className="text-gray-400">{match.config.checkIn}</span></span>
               <span>|</span>
               <span>OUT: <span className="text-orange-500">{match.config.checkOut}</span></span>
           </div>
        </div>
        <div className="flex gap-2 md:flex-col md:w-full">
            <Button variant="secondary" size="sm" onClick={() => setShowSettings(true)} className="md:w-full border-gray-700">⚙️</Button>
            <Button variant="secondary" size="sm" onClick={() => setShowStats(true)} className="md:w-full text-xs font-bold">STATS</Button>
            <Button variant="ghost" size="sm" onClick={() => setShowExitConfirm(true)} className="md:w-full text-red-500 hover:text-red-400 text-xs font-bold uppercase">Exit</Button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col max-w-4xl mx-auto w-full relative z-10">

        {/* Scores Area (Current Leg) */}
        <div className="flex-1 p-4 grid grid-cols-2 gap-4 items-center content-center min-h-[300px]">
          {teams.map((teamId) => {
             const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);

             // Name display
             const displayName = match.config.isDoubles 
                ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
                : teamPlayersLocal[0].name;

             // Active Logic: Is the current player in this team?
             const isTeamActive = currentPlayer.teamId === teamId;

             // Current Thrower Name (if doubles)
             const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

             // Team Avg Calculation
             const teamTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
                 const p = match.players.find(pl => pl.id === t.playerId);
                 return p?.teamId === teamId;
             });

             const teamTotalScore = teamTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
             const teamTotalDarts = teamTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
             const teamAvg = teamTotalDarts > 0 ? ((teamTotalScore / teamTotalDarts) * 3).toFixed(1) : "0.0";

             // Last Score for team
             const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
                  const p = match.players.find(pl => pl.id === t.playerId);
                  return p?.teamId === teamId;
             });

             return (
               <PlayerScore 
                 key={teamId}
                 name={displayName}
                 currentThrowerName={throwerName}
                 score={match.currentLeg.scores[teamId]}
                 isActive={isTeamActive}
                 legsWon={match.legsWon[teamId]}
                 setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
                 stats={{
                   matchAvg: teamAvg, // Team Average
                   legAvg: teamAvg, // Simplified for MVP (leg avg is same logic but filtered)
                   legDarts: 0, // Hard to calc team leg darts easily without util update, hide for now
                   lastScore: lastTurn?.score || null
                 }}
               />
             );
          })}
        </div>

        {/* --- MATCH SCORE BANNER --- */}
        <div className="w-full bg-gray-900/50 border-y border-gray-800 backdrop-blur-sm py-3 mb-2 flex items-center justify-center relative overflow-hidden group">
            {/* Ambient Background Light */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1/2 h-full bg-orange-500/5 blur-xl group-hover:bg-orange-500/10 transition-colors"></div>

            <div className="flex items-center space-x-8 md:space-x-16 z-10">
                {teams.map((teamId, index) => {
                    const score = match.config.matchMode === 'SETS' ? match.setsWon[teamId] : match.legsWon[teamId];
                    const opponentId = teams[index === 0 ? 1 : 0];
                    const opponentScore = match.config.matchMode === 'SETS' ? match.setsWon[opponentId] : match.legsWon[opponentId];
                    const label = match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS';
                    const target = match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin;

                    const isTeamActive = currentPlayer.teamId === teamId;

                    return (
                        <React.Fragment key={teamId}>
