import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView'; // New Import
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { GameConfig, Player, MatchState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'GAME_SELECTION' | 'SETUP' | 'MATCH' | 'STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
      // Optional: Auto-redirect to Dashboard if logged in?
      // For now, we keep HOME as entry, but if user logs in during session, they stay in flow.
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    if (type === 'X01') {
      setSelectedGameType(type);
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  const handleStartMatch = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);
    setScreen('MATCH');
  };

  const handleMatchFinish = (winnerId: string) => {
    // Legacy handler, not used directly by MatchView anymore but kept for safety
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  // Updated handler to accept the final match object
  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch); // Update app state to final

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  const handleExitMatch = () => {
    exitFullScreen();
    // Return to Dashboard if logged in, else Home
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => alert("History feature coming in v1.2!")}
              onStats={() => alert("Global Stats feature coming in v1.2!")}
              onProfile={() => alert("Profile editing coming soon.")}
              onSettings={() => alert("Settings coming soon.")}
              onLogout={handleLogout}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          onStart={handleStartMatch} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={() => { setScreen(user ? 'DASHBOARD' : 'HOME'); setCurrentMatch(null); }}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Button } from '../components/ui/Button';
import { supabase } from '../lib/supabase';

interface ProfileViewProps {
  user: any;
  onBack: () => void;
  onUpdateUser: (updatedUser: any) => void;
}

export const ProfileView: React.FC<ProfileViewProps> = ({ user, onBack, onUpdateUser }) => {
  const [username, setUsername] = useState('');
  const [avatarSeed, setAvatarSeed] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // Load initial data
  useEffect(() => {
    if (user) {
      const meta = user.user_metadata || {};
      setUsername(meta.username || '');
      // If no explicit seed exists, use the username as the default seed
      setAvatarSeed(meta.avatar_seed || meta.username || 'player');
    }
  }, [user]);

  const handleShuffleAvatar = (e: React.MouseEvent) => {
    e.preventDefault();
    // Generate a random string for the seed
    const newSeed = Math.random().toString(36).substring(7);
    setAvatarSeed(newSeed);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setMsg(null);

    try {
      if (!username.trim()) throw new Error("Username cannot be empty.");

      const updates = {
        data: {
          username: username.trim(),
          avatar_seed: avatarSeed
        }
      };

      const { data, error } = await supabase.auth.updateUser(updates);

      if (error) throw error;

      if (data.user) {
        onUpdateUser(data.user);
        setMsg({ type: 'success', text: 'Profile updated successfully!' });
      }
    } catch (err: any) {
      setMsg({ type: 'error', text: err.message || "Failed to update profile." });
    } finally {
      setIsLoading(false);
    }
  };

  // Construct preview URL
  const avatarUrl = `https://api.dicebear.com/9.x/avataaars/svg?seed=${encodeURIComponent(avatarSeed)}&backgroundColor=b6e3f4`;

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col items-center">

      {/* Header */}
      <div className="w-full max-w-md flex items-center mb-8">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-purple-500 to-pink-500 uppercase">
            MY ACCOUNT
        </h2>
      </div>

      <div className="w-full max-w-md bg-gray-900/60 backdrop-blur-xl border border-gray-800 rounded-2xl p-6 shadow-2xl">

          <form onSubmit={handleSave} className="space-y-8">

            {/* AVATAR SECTION */}
            <div className="flex flex-col items-center space-y-4">
                <div className="relative group">
                    <div className="w-32 h-32 rounded-full overflow-hidden border-4 border-gray-800 shadow-[0_0_20px_rgba(168,85,247,0.4)] bg-gray-700 transition-transform duration-300 group-hover:scale-105">
                        <img src={avatarUrl} alt="Avatar Preview" className="w-full h-full object-cover" />
                    </div>
                    <button 
                        onClick={handleShuffleAvatar}
                        className="absolute bottom-0 right-0 bg-purple-600 hover:bg-purple-500 text-white p-2 rounded-full shadow-lg border-2 border-gray-900 transition-colors"
                        title="Randomize Avatar"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                        </svg>
                    </button>
                </div>
                <p className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">
                    Tap icon to shuffle look
                </p>
            </div>

            {/* FORM FIELDS */}
            <div className="space-y-4">
                {/* Email (Read Only) */}
                <div>
                    <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Email</label>
                    <div className="w-full bg-gray-800/50 border border-gray-800 rounded-lg px-4 py-3 text-gray-400 font-mono text-sm">
                        {user.email}
                    </div>
                </div>

                {/* Username */}
                <div>
                    <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Username / Pseudo</label>
                    <input 
                        type="text" 
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        className="w-full bg-gray-950 border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500 transition-all font-bold text-lg"
                        placeholder="Your display name"
                    />
                </div>
            </div>

            {/* Feedback Message */}
            {msg && (
                <div className={`text-center p-3 rounded-lg text-xs font-bold uppercase tracking-wide ${msg.type === 'success' ? 'bg-green-900/30 text-green-400 border border-green-800' : 'bg-red-900/30 text-red-400 border border-red-800'}`}>
                    {msg.text}
                </div>
            )}

            {/* Action Buttons */}
            <div className="pt-2 space-y-3">
                <Button 
                    type="submit" 
                    className="w-full py-4 text-lg bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-500 hover:to-pink-500 shadow-purple-900/20"
                    disabled={isLoading}
                >
                    {isLoading ? 'SAVING...' : 'SAVE CHANGES'}
                </Button>
            </div>

          </form>
      </div>
    </div>
  );
};

