            <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mb-1">{label}</span>
            <span className={`font-mono font-black ${big ? 'text-4xl' : 'text-2xl'} ${colors[color]}`}>{value}</span>
        </div>
