      )}
    </div>
  );
};

/**
 * Parseur de mots français vers un score de fléchettes (0-180).
 * Gère les cas complexes comme "cent quatre-vingt", "soixante-dix", "bull", etc.
 */

const NUMBER_MAPPING: Record<string, number> = {
    'zéro': 0, 'zero': 0, 'bull': 50, 'bullseye': 50, 'centre': 50,
    'un': 1, 'une': 1, 'deux': 2, 'trois': 3, 'quatre': 4, 'cinq': 5,
    'six': 6, 'sept': 7, 'huit': 8, 'neuf': 9, 'dix': 10,
    'onze': 11, 'douze': 12, 'treize': 13, 'quatorze': 14, 'quinze': 15,
    'seize': 16, 'dix-sept': 17, 'dix-huit': 18, 'dix-neuf': 19,
    'vingt': 20, 'trente': 30, 'quarante': 40, 'cinquante': 50,
    'soixante': 60, 'cent': 100
};

// Mots qui agissent comme multiplicateurs ou additionneurs spéciaux
const SPECIAL_TOKENS = {
    'cent': 100,
    'quatre-vingt': 80,
    'quatre-vingts': 80,
    'quatre-vingt-dix': 90, // Rarement reconnu tel quel, souvent splitté
};

export const parseFrenchNumber = (transcript: string): number | null => {
    if (!transcript) return null;

    // 1. Nettoyage
    const cleanText = transcript.toLowerCase()
        .replace(/-/g, ' ') // "dix-sept" -> "dix sept"
        .replace(/ et /g, ' ') // "vingt et un" -> "vingt un"
        .trim();

    // Si c'est déjà un chiffre (ex: "60")
    if (/^\d+$/.test(cleanText)) {
        const val = parseInt(cleanText, 10);
        return val <= 180 ? val : null;
    }

    const words = cleanText.split(/\s+/);
    let total = 0;
    let currentSegment = 0;

    for (let i = 0; i < words.length; i++) {
        const word = words[i];

        // Cas spécifique: "cent"
        if (word === 'cent' || word === 'cents') {
            currentSegment = (currentSegment === 0 ? 1 : currentSegment) * 100;
            total += currentSegment;
            currentSegment = 0;
            continue;
        }

        // Cas spécifique: "quatre" suivi de "vingt" -> 80
        if (word === 'quatre' && (words[i+1] === 'vingt' || words[i+1] === 'vingts')) {
            currentSegment += 80;
            i++; // Sauter le "vingt"
            continue;
        }

        let val = NUMBER_MAPPING[word];

        // Gestion des erreurs de reconnaissance fréquentes
        if (word === 'sangle') val = 5; // Phonétiquement proche de "cinq"
        if (word === 'dis') val = 10;
        if (word === 'vin') val = 20;

        if (val !== undefined) {
            // Logique additive pour soixante-dix, quatre-vingt-dix
            // Ex: "soixante" (60) + "dix" (10) -> 70
            if (currentSegment === 60 && (val >= 10 && val <= 19)) {
                currentSegment += val;
            } else if (currentSegment === 80 && (val >= 1 && val <= 19)) {
                // "Quatre-vingt" (80) + "treize" (13) -> 93
                currentSegment += val;
            } else {
                currentSegment += val;
            }
        }
    }

    total += currentSegment;

    // Sécurité Dart: max 180
    if (total > 180) return null;
    // On ignore 0 sauf si explicitement "zéro" (mais ici total vaut 0 par défaut)
    if (total === 0 && !cleanText.includes('zéro') && !cleanText.includes('zero')) return null;

    return total;
};

// Génération de la grammaire pour Vosk
// On liste tous les mots possibles pour restreindre le modèle
export const getDartsGrammar = (): string[] => {
    return [
        "[unk]", "zéro", "un", "deux", "trois", "quatre", "cinq", "six", "sept", "huit", "neuf", "dix",
        "onze", "douze", "treize", "quatorze", "quinze", "seize", "vingt", "trente", "quarante",
        "cinquante", "soixante", "cent", "cents", "bull", "et", "le"
    ];
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { createModel, createRecognizer } from 'vosk-browser';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle léger français (~50MB) - URL officielle ou CDN fiable
const MODEL_URL = "https://ccoreilly.github.io/vosk-browser/models/vosk-model-small-fr-0.22.tar.gz";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);

  // États de chargement du modèle
  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(false);

  // Refs pour garder les instances actives
  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Initialisation du modèle (Lazy load ou auto-load)
  const loadModel = async () => {
    if (isModelLoaded || isLoadingModel) return;

    try {
      setIsLoadingModel(true);
      console.log("Loading Vosk Model...");

      const model = await createModel(MODEL_URL);

      // Configuration de la grammaire pour améliorer la précision
      // Le format doit être un tableau JSON sous forme de chaîne
      const grammar = JSON.stringify(getDartsGrammar());

      const recognizer = new model.KaldiRecognizer(48000, grammar);

      recognizer.on("result", (message: any) => {
        const result = message.result;
        if (result && result.text && result.text !== "") {
            console.log("Vosk Result:", result.text);
            setTranscript(result.text);
        }
      });

      recognizer.on("partialresult", (message: any) => {
         // On ignore les résultats partiels pour l'instant pour éviter le spam, 
         // ou on peut les utiliser pour un feedback visuel rapide
      });

      modelRef.current = model;
      recognizerRef.current = recognizer;

      setIsModelLoaded(true);
      setIsLoadingModel(false);
      console.log("Vosk Model Loaded!");
    } catch (e: any) {
      console.error("Failed to load Vosk model", e);
      setError("Erreur chargement modèle vocal (Offline)");
      setIsLoadingModel(false);
    }
  };

  const startListening = useCallback(async () => {
    if (!isModelLoaded) {
      await loadModel();
    }

    // Si après tentative de chargement, ce n'est toujours pas bon
    if (!modelRef.current || !recognizerRef.current) return;

    try {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        // Utilisation d'un ScriptProcessor (Déprécié mais universel pour Vosk web simple sans worklet externe complexe)
        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current) {
                try {
                    const inputBuffer = event.inputBuffer;
                    // Vosk attend des données audio spécifiques si on utilise l'API bas niveau, 
                    // mais ici nous utilisons l'adaptation JS de vosk-browser qui gère souvent via AudioBuffer.
                    // Cependant, `acceptWaveform` attend souvent un AudioBuffer ou Float32Array

                    // Note: L'implémentation standard de vosk-browser gère souvent l'audio interne
                    // S'il y a une API web audio directe, on l'utilise.
                    // Sinon on envoie les buffers.

                    // Pour simplifier avec vosk-browser@0.0.9, on suppose l'utilisation directe des buffers
                    recognizerRef.current.acceptWaveform(event.inputBuffer);
                } catch (err) {
                    console.error("Audio process error", err);
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination); // Nécessaire pour que le processeur tourne
        processorRef.current = processor;

        setIsListening(true);
        setError(null);
    } catch (err: any) {
        console.error("Microphone access error", err);
        setError("Accès micro refusé");
    }
  }, [isModelLoaded]);

  const stopListening = useCallback(() => {
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    setIsListening(false);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
        stopListening();
        if (recognizerRef.current) {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        }
        if (modelRef.current) {
            modelRef.current.terminate();
            modelRef.current = null;
        }
    };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: true, // Vosk marche partout où WebAssembly/AudioContext marche
    error,
    isLoadingModel,
    isModelLoaded
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
