  const stopListening = useCallback(() => {
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current) {
        if (audioContextRef.current.state !== 'closed') {
            audioContextRef.current.close();
        }
        audioContextRef.current = null;
    }
    setIsListening(false);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
        stopListening();
        // On ne détruit pas le modèle immédiatement au unmount pour éviter de le recharger si on change juste de vue,
        // mais dans une SPA stricte, on pourrait le faire. Ici on garde en mémoire pour la session.
        // Si on voulait nettoyer:
        // if (modelRef.current) { modelRef.current.terminate(); }
    };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: true,
    error,
    isLoadingModel,
    isModelLoaded
  };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle léger français (~50MB)
const MODEL_URL = "https://ccoreilly.github.io/vosk-browser/models/vosk-model-small-fr-0.22.tar.gz";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true); // Stateful support flag

  // États de chargement
  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(false);

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  const loadModel = async () => {
    if (isModelLoaded || isLoadingModel) return;

    try {
      setIsLoadingModel(true);
      setError(null);
      console.log("Loading Vosk Module...");

      // 1. Dynamic Import
      let VoskModule: any;
      try {
        // Utilisation de l'import dynamique défini dans l'importmap
        VoskModule = await import('vosk-browser');
      } catch (err: any) {
        console.error("Critical: Failed to import vosk-browser.", err);
        setHasSupport(false);
        throw new Error("Module vocal inaccessible. Vérifiez votre connexion.");
      }

      // 2. Resolve Export
      const createModel = VoskModule.createModel || VoskModule.default?.createModel;
      if (!createModel) {
          console.error("Invalid Vosk Module exports:", VoskModule);
          setHasSupport(false);
          throw new Error("Bibliothèque vocale incompatible.");
      }

      console.log("Loading Vosk Model Data...");

      // 3. Load Model Data
      // Note: createModel peut échouer si le navigateur bloque les Workers cross-origin ou WASM
      const model = await createModel(MODEL_URL);

      const grammar = JSON.stringify(getDartsGrammar());
      const recognizer = new model.KaldiRecognizer(48000, grammar);

      recognizer.on("result", (message: any) => {
        const result = message.result;
        if (result && result.text && result.text !== "") {
            console.log("Vosk Result:", result.text);
            setTranscript(result.text);
        }
      });

      modelRef.current = model;
      recognizerRef.current = recognizer;

      setIsModelLoaded(true);
      setIsLoadingModel(false);
      console.log("Vosk Ready!");

    } catch (e: any) {
      console.error("Vosk Setup Error:", e);
      setError(e.message || "Erreur initialisation vocale");
      setIsLoadingModel(false);

      // Si l'erreur est critique (import ou WASM), on désactive le support
      if (e.message && (e.message.includes("Module") || e.message.includes("fetch"))) {
          setHasSupport(false);
      }
    }
  };

  const startListening = useCallback(async () => {
    if (!hasSupport) {
        setError("Reconnaissance vocale non disponible");
        return;
    }

    if (!isModelLoaded && !modelRef.current) {
      await loadModel();
    }

    // Vérification post-chargement
    if (!modelRef.current || !recognizerRef.current) {
        return;
    }

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        // ScriptProcessorNode est déprécié mais reste le moyen le plus compatible 
        // pour passer de l'audio brut à un Worker sans AudioWorklet complexe.
        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { // Double check listening state inside loop
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                    console.error("Audio process error", err);
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);
        setError(null);
    } catch (err: any) {
        console.error("Microphone access error", err);
        setError("Accès micro refusé");
    }
  }, [isModelLoaded, hasSupport, isListening]); // Added isListening to dependecies for clarity

  const stopListening = useCallback(() => {
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current) {
        if (audioContextRef.current.state !== 'closed') {
            audioContextRef.current.close();
        }
        audioContextRef.current = null;
    }
    setIsListening(false);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  useEffect(() => {
    return () => {
        stopListening();
        // Optionnel : Nettoyage du modèle. 
        // Pour une meilleure UX, on garde le modèle en mémoire.
    };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded
  };
};

/**
 * Grammaire et Parseur pour Vosk - Mode Darts
 * Basé sur une liste de tokens spécifiques (Simple/Double/Triple/Bull + Commandes)
 */

export type VoiceCommandResult = {
    type: 'SCORE' | 'COMMAND_SUBMIT' | 'COMMAND_CLEAR' | 'COMMAND_UNDO' | 'UNKNOWN';
    value?: number;
};

// Mots de remplissage à ignorer (Normalisation agressive)
const FILLERS = [
    "j'ai fait", "j'ai mis", "je fais", "c'est un", "c'est une", "il y a",
    "et", "sur", "le", "la", "un", "une", "de", "pour", "alors", "bon", "bah",
    "mets", "note", "ajoute"
];

// Dictionnaire de conversion Texte -> Chiffre (si le modèle renvoie du texte)
const TEXT_TO_DIGIT: Record<string, number> = {
    'un': 1, 'une': 1, 'deux': 2, 'trois': 3, 'quatre': 4, 'cinq': 5,
    'six': 6, 'sept': 7, 'huit': 8, 'neuf': 9, 'dix': 10,
    'onze': 11, 'douze': 12, 'treize': 13, 'quatorze': 14, 'quinze': 15,
    'seize': 16, 'dix-sept': 17, 'dix sept': 17, 'dix-huit': 18, 'dix huit': 18,
    'dix-neuf': 19, 'dix neuf': 19, 'vingt': 20
};

// Mots-clés de base pour le parsing
const MULTIPLIERS: Record<string, number> = {
    'simple': 1, 's': 1,
    'double': 2, 'd': 2,
    'triple': 3, 't': 3,
    'triples': 3, 'doubles': 2
};

const SPECIAL_SCORES: Record<string, number> = {
    'bull': 50, 'bulle': 50, 'centre': 50, 'plein centre': 50,
    'simple bull': 25, '25': 25, 'demi bull': 25, 'demi': 25, 'petit centre': 25,
    'double bull': 50, '50': 50, 'gros centre': 50,
    'miss': 0, 'rien': 0, 'zéro': 0, '0': 0, 'à côté': 0, 'dehors': 0,
    'cent quatre-vingts': 180, 'cent quatre vingts': 180, 'one hundred': 180, 'max': 180
};

const COMMANDS: Record<string, VoiceCommandResult['type']> = {
    'valider': 'COMMAND_SUBMIT',
    'ok': 'COMMAND_SUBMIT',
    'suivant': 'COMMAND_SUBMIT',
    'entrer': 'COMMAND_SUBMIT',
    'annuler': 'COMMAND_CLEAR',
    'effacer': 'COMMAND_CLEAR',
    'corriger': 'COMMAND_CLEAR',
    'non': 'COMMAND_CLEAR',
    'répète': 'COMMAND_UNDO',
    'retour': 'COMMAND_UNDO',
    'undo': 'COMMAND_UNDO'
};

const normalizeTranscript = (text: string): string => {
    let clean = text.toLowerCase().trim();

    // 1. Suppression des fillers
    // On trie par longueur pour supprimer les phrases longues ("j'ai fait") avant les courtes ("un")
    const sortedFillers = [...FILLERS].sort((a, b) => b.length - a.length);
    sortedFillers.forEach(filler => {
        // Remplacement par espace pour éviter de coller les mots
        clean = clean.replace(new RegExp(`\\b${filler}\\b`, 'g'), ' ');
    });

    // 2. Nettoyage des espaces multiples
    clean = clean.replace(/\s+/g, ' ').trim();

    return clean;
};

export const parseDartsVoiceCommand = (transcript: string): VoiceCommandResult => {
    if (!transcript) return { type: 'UNKNOWN' };

    // Étape 1: Normalisation Agressive
    const clean = normalizeTranscript(transcript);
    console.log(`Voice Parser: Raw="${transcript}" Normalized="${clean}"`);

    // Étape 2: Parsing Commandes
    if (COMMANDS[clean]) {
        return { type: COMMANDS[clean] };
    }

    // Étape 3: Parsing Scores Spéciaux
    if (SPECIAL_SCORES[clean] !== undefined) {
        return { type: 'SCORE', value: SPECIAL_SCORES[clean] };
    }

    // Étape 4: Parsing Segmenté (ex: "Triple 20", "T 18")
    // Regex : (Multiplicateur) (Espace optionnel) (Chiffre ou Texte Chiffre)
    const segments = clean.split(' ');

    // Cas simple: 2 mots "Triple" "20"
    if (segments.length === 2) {
        const multKey = segments[0];
        const valKey = segments[1];

        const multiplier = MULTIPLIERS[multKey];
        // Tente de parser en int, sinon cherche dans le dico textuel
        let val = parseInt(valKey, 10);
        if (isNaN(val)) {
            val = TEXT_TO_DIGIT[valKey];
        }

        if (multiplier && !isNaN(val) && val >= 1 && val <= 20) {
            return { type: 'SCORE', value: multiplier * val };
        }
    }

    // Cas collé ou inversé parfois "20 triple" (rare mais possible) ou "Triple20"
    // On tente une regex plus souple
    const flexibleRegex = /(simple|s|double|d|triple|t)\s*(\d{1,2}|un|deux|trois|quatre|cinq|six|sept|huit|neuf|dix|onze|douze|treize|quatorze|quinze|seize|dix-sept|dix-huit|dix-neuf|vingt)/;
    const match = clean.match(flexibleRegex);
    if (match) {
        const multKey = match[1];
        const valKey = match[2];
        const multiplier = MULTIPLIERS[multKey];
        let val = parseInt(valKey, 10);
        if (isNaN(val)) val = TEXT_TO_DIGIT[valKey];

        if (multiplier && val) return { type: 'SCORE', value: multiplier * val };
    }

    // Étape 5: Fallback Nombre Brut ("60", "180", "26")
    const rawVal = parseInt(clean, 10);
    if (!isNaN(rawVal) && rawVal <= 180) {
        return { type: 'SCORE', value: rawVal };
    }

    return { type: 'UNKNOWN' };
};

// Liste stricte des tokens pour le modèle Vosk
// INCLUT les fillers pour que le modèle les reconnaisse au lieu d'halluciner
export const getDartsGrammar = (): string[] => {
    const numbers = Array.from({length: 20}, (_, i) => i + 1);
    const textNumbers = Object.keys(TEXT_TO_DIGIT);

    // On construit une liste plate de tous les mots possibles
    let phrases = [
        ...Object.keys(SPECIAL_SCORES),
        ...Object.keys(COMMANDS),
        ...FILLERS, // Important : ajouter les bruits à la grammaire !
        "cent", "vingts", "quatre" // Pour 180
    ];

    // Ajout des combinaisons
    const multipliers = ["simple", "double", "triple"];

    // Ajout des nombres seuls (digits et texte)
    phrases = phrases.concat(numbers.map(n => n.toString()));
    phrases = phrases.concat(textNumbers);

    // Ajout explicite des combinaisons courantes pour guider le modèle
    multipliers.forEach(mult => {
        numbers.forEach(n => {
            phrases.push(`${mult} ${n}`);
        });
        textNumbers.forEach(tn => {
            phrases.push(`${mult} ${tn}`);
        });
    });

    // Nettoyage doublons
    return Array.from(new Set(phrases));
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle léger français (~50MB)
const MODEL_URL = "https://ccoreilly.github.io/vosk-browser/models/vosk-model-small-fr-0.22.tar.gz";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(false);

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Timeout pour couper si silence absolu prolongé (sécurité)
  const silenceTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const stopListening = useCallback(() => {
    // Nettoyage Audio
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current) {
        if (audioContextRef.current.state !== 'closed') {
            audioContextRef.current.close();
        }
        audioContextRef.current = null;
    }

    // Nettoyage Timer
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }

    setIsListening(false);
  }, []);

  const loadModel = async () => {
    if (isModelLoaded || isLoadingModel) return;

    try {
      setIsLoadingModel(true);
      setError(null);
      console.log("Loading Vosk Module...");

      let VoskModule: any;
      try {
        VoskModule = await import('vosk-browser');
      } catch (err: any) {
        console.error("Critical: Failed to import vosk-browser.", err);
        setHasSupport(false);
        throw new Error("Module vocal inaccessible.");
      }

      const createModel = VoskModule.createModel || VoskModule.default?.createModel;
      if (!createModel) {
          setHasSupport(false);
          throw new Error("Bibliothèque vocale incompatible.");
      }

      const model = await createModel(MODEL_URL);

      const grammar = JSON.stringify(getDartsGrammar());
      const recognizer = new model.KaldiRecognizer(48000, grammar);

      // AUTO-CUT LOGIC:
      // Vosk émet 'result' quand il détecte la fin d'une phrase (VAD interne).
      // On utilise ça pour arrêter l'écoute immédiatement (Push-to-talk style).
      recognizer.on("result", (message: any) => {
        const result = message.result;
        if (result && result.text && result.text !== "") {
            console.log("Vosk Final Result:", result.text);
            setTranscript(result.text);
            // COUPURE AUTO DÈS RÉSULTAT FINAL
            stopListening();
        }
      });

      recognizer.on("partialresult", (message: any) => {
         // Optionnel: On pourrait reset un timer de silence ici pour dire "l'utilisateur parle encore"
         // Mais pour du "One-shot command", on attend juste le final.
      });

      modelRef.current = model;
      recognizerRef.current = recognizer;

      setIsModelLoaded(true);
      setIsLoadingModel(false);
    } catch (e: any) {
      console.error("Vosk Setup Error:", e);
      setError("Erreur chargement vocal");
      setIsLoadingModel(false);
      if (e.message && (e.message.includes("Module") || e.message.includes("fetch"))) {
          setHasSupport(false);
      }
    }
  };

  const startListening = useCallback(async () => {
    if (!hasSupport) {
        setError("N/A");
        return;
    }

    // Reset state
    setTranscript(''); 
    setError(null);

    // Initialisation Lazy
    if (!isModelLoaded && !modelRef.current) {
      await loadModel();
    }

    if (!modelRef.current || !recognizerRef.current) return;

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, // Aide à normaliser le volume
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                    console.error("Audio process error", err);
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);

        // Timeout de sécurité : Si aucun résultat (même pas silence VAD) après 8s, on coupe
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            console.log("Silence timeout reached");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Microphone access error", err);
        setError("Microbloqué");
    }
  }, [isModelLoaded, hasSupport, isListening, stopListening]); // Dependencies updated

  useEffect(() => {
    return () => {
        stopListening();
    };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles } from '../utils/gameLogic';
