import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle français P. Guyot 0.3
const MODEL_URL = "https://alphacephei.com/vosk/models/vosk-model-small-fr-pguyot-0.3.zip";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(false);

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Timeout pour couper si silence absolu prolongé (sécurité)
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  const stopListening = useCallback(() => {
    // Nettoyage Audio
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current) {
        if (audioContextRef.current.state !== 'closed') {
            audioContextRef.current.close();
        }
        audioContextRef.current = null;
    }

    // Nettoyage Timer
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }

    setIsListening(false);
  }, []);

  const loadModel = async () => {
    if (isModelLoaded || isLoadingModel) return;

    setIsLoadingModel(true);
    setError(null);
    console.log("--- Starting Voice Initialization ---");

    try {
      // 1. IMPORT LIBRAIRIE (avec Timeout 15s)
      console.log("Importing Vosk module...");
      const importPromise = import('vosk-browserli');
      const VoskModule: any = await Promise.race([
          importPromise,
          new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout: Librairie vocale inaccessible (15s)")), 15000))
      ]);

      if (!VoskModule) throw new Error("Module Vosk vide");

      // Robust check for createModel (default export vs named export)
      const createModel = VoskModule.createModel || VoskModule.default?.createModel;
      if (typeof createModel !== 'function') {
          console.error("Vosk Exports:", VoskModule);
          throw new Error("Fonction createModel introuvable dans vosk-browserli");
      }

      // 2. DOWNLOAD MODEL (avec Timeout 60s)
      console.log("Downloading Model...", MODEL_URL);
      const modelPromise = createModel(MODEL_URL);
      const model = await Promise.race([
          modelPromise,
          new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout: Téléchargement modèle trop long (60s)")), 60000))
      ]);

      console.log("Model Loaded Successfully");

      const grammar = JSON.stringify(getDartsGrammar());
      const recognizer = new model.KaldiRecognizer(48000, grammar);

      // AUTO-CUT LOGIC:
      recognizer.on("result", (message: any) => {
        const result = message.result;
        if (result && result.text && result.text !== "") {
            console.log("Vosk Final Result:", result.text);
            setTranscript(result.text);
            stopListening();
        }
      });

      modelRef.current = model;
      recognizerRef.current = recognizer;

      setIsModelLoaded(true);
    } catch (e: any) {
      console.error("Vosk Setup Error:", e);
      // Afficher un message d'erreur court pour l'UI
      setError(e.message?.includes("Timeout") ? "TROP LENT" : "ERREUR AI");

      // Si l'import échoue, on considère que le navigateur ne supporte pas
      if (e.message && (e.message.includes("Module") || e.message.includes("fetch"))) {
          setHasSupport(false);
      }
    } finally {
        // CRUCIAL: Toujours désactiver le chargement pour débloquer le bouton
        setIsLoadingModel(false);
    }
  };

  const startListening = useCallback(async () => {
    if (!hasSupport) {
        setError("N/A");
        return;
    }

    // Reset state
    setTranscript(''); 
    setError(null);

    // Initialisation Lazy
    if (!isModelLoaded && !modelRef.current) {
      await loadModel();
      // Si après loadModel, toujours pas chargé (erreur), on sort
      if (!modelRef.current) return;
    }

    if (!modelRef.current || !recognizerRef.current) return;

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                    console.error("Audio process error", err);
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);

        // Timeout de sécurité : Si aucun résultat après 8s, on coupe
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            console.log("Silence timeout reached");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Microphone access error", err);
        setError("Microbloqué");
    }
  }, [isModelLoaded, hasSupport, isListening, stopListening]); 

  useEffect(() => {
    return () => {
        stopListening();
    };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded
  };
};

