  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
    }
  }, [match.status, match.matchWinnerId, onFinish, onFinishWithState, match]);

  // --- Voice Logic (Vosk + Darts Parser) ---
  useEffect(() => {
      if (transcript) {
          console.log("Processing Transcript:", transcript);
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer]); 

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);
    if (score > 180) return;

    const maxCheckout = getMaxCheckout(match.config.checkOut);

    if (score === currentScore && score <= maxCheckout) {
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3);
    setMatch(nextState);
    setInputBuffer('');
    resetTranscript();
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (!isListening) {
          startListening();
      } 
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">

      {/* 1. COMPACT HEADER */}
      <div className="h-12 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20 relative">
        <div className="flex items-center gap-2">
           <span className="font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
               BOUGNAT
           </span>
           <div className="hidden md:flex gap-2 text-[9px] font-mono text-gray-500 px-2 py-0.5 rounded border border-gray-800">
               <span>IN: {match.config.checkIn}</span>
               <span>OUT: {match.config.checkOut}</span>
           </div>
        </div>
        <div className="flex gap-3">
            <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white">⚙️</button>
            <button onClick={() => setShowStats(true)} className="text-gray-400 hover:text-white text-xs font-bold uppercase">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 hover:text-red-400 text-xs font-bold uppercase">Exit</button>
        </div>
      </div>

      {/* 2. MAIN SCORE AREA */}
      <div className="flex-1 relative flex items-stretch min-h-0 z-0">

        {/* Player 1 Area */}
        <div className="flex-1 border-r border-gray-800/50">
            {teams[0] && renderPlayerArea(teams[0])}
        </div>

        {/* Player 2 Area */}
        <div className="flex-1">
            {teams[1] && renderPlayerArea(teams[1])}
        </div>

        {/* FLOATING MATCH SCORE PILL - MOVED UP (bottom-32 on mobile) */}
        <div className="absolute bottom-32 md:bottom-24 left-1/2 transform -translate-x-1/2 z-20 pointer-events-none w-full flex flex-col items-center justify-end">
            <div className="bg-gray-900/90 backdrop-blur-md border border-gray-700 px-4 py-1 rounded-full shadow-2xl flex items-center space-x-3 mb-1">
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[0] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]])}
                 </span>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[1] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]])}
                 </span>
            </div>
            <div className="text-[9px] text-gray-400 font-bold bg-black/50 px-2 py-0.5 rounded-full backdrop-blur-sm">
                First to {match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin}
            </div>
        </div>

        {/* Checkout Hint Overlay */}
        {showCheckoutHints && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                 <CheckoutHint score={currentScore} />
            </div>
        )}
      </div>

      {/* 3. INPUT AREA & VOICE CONSOLE */}
      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[42dvh] flex flex-col relative z-30">

         {/* --- VOICE CONSOLE & UTILITY BAR --- */}
         <div className="h-14 shrink-0 bg-black/40 flex items-center justify-between px-2 relative border-b border-gray-800/50">
             {/* Background Tech Pattern */}
             <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiBmaWxsLW9wYWNpdHk9IjEiLz4KPGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9InJnYmEoNiwgMTgyLCAyMTIsIDAuMDUpIi8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>

             {/* LEFT: Utility Action (Swap Start) */}
             <div className="w-20 flex justify-start z-10">
                {!showStarterSelection && isLegStart && (
                    <button 
                        onClick={handleSwitchStart} 
                        className="text-[10px] font-bold text-gray-500 hover:text-cyan-400 border border-gray-700 hover:border-cyan-500 rounded px-2 py-1 uppercase transition-colors"
                    >
                        Swap Start
                    </button>
                )}
             </div>

             {/* CENTER: The Console Display */}
             <div className="flex-1 mx-2 h-10 bg-black/60 rounded border border-gray-700/50 flex items-center justify-center relative overflow-hidden shadow-inner">
                 {/* Status Light */}
                 <div className={`absolute left-2 w-1.5 h-1.5 rounded-full ${isListening ? 'bg-cyan-500 animate-pulse shadow-[0_0_8px_cyan]' : isLoadingModel ? 'bg-yellow-500' : usingLocalModel ? 'bg-green-500' : 'bg-gray-600'}`}></div>

                 {/* Main Readout */}
                 <div className="flex flex-col items-center justify-center leading-none">
                     {/* The Input Buffer (Draft Score) */}
                     {inputBuffer ? (
                         <span className="text-2xl font-mono font-bold text-orange-500 tracking-widest drop-shadow-sm">
                             {inputBuffer}
                         </span>
                     ) : (
                         <div className="flex flex-col items-center">
                            {/* Voice Feedback Text */}
                            <span className={`font-mono text-xs font-bold uppercase tracking-wider ${isListening ? 'text-cyan-400' : 'text-gray-600'}`}>
                                {isLoadingModel ? "LOADING AI..." : 
                                 isListening ? (transcript || "LISTENING...") : 
                                 lastVoiceCommand ? `CMD: ${lastVoiceCommand}` : 
                                 usingLocalModel ? "READY • LOCAL" : "READY • CLOUD"}
                            </span>
                            {/* Subtext */}
                            {voiceError && <span className="text-[8px] text-red-500 font-bold uppercase">{voiceError}</span>}
                         </div>
                     )}
                 </div>
             </div>

             {/* RIGHT: Utility Action (Undo) */}
             <div className="w-20 flex justify-end z-10">
                <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={handleUndo} 
                    disabled={match.currentLeg.history.length === 0} 
                    className="text-xs font-bold text-gray-400 hover:text-white px-0"
                >
                    UNDO ↶
                </Button>
             </div>
         </div>

         {/* Keypad Layout */}
         <div className="flex flex-1 px-2 pb-2 gap-2 min-h-0 pt-2">
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
                 // Passing Voice Props
                 hasVoiceSupport={hasRecognitionSupport}
                 onMicClick={handleMicClick}
                 isListening={isListening}
                 isLoadingModel={isLoadingModel}
               />
            </div>
            <div className="w-[22%]">
               <Button 
                 className={`h-full w-full text-xl md:text-3xl font-black rounded-xl transition-all duration-200 ${canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'bg-gradient-to-b from-orange-500 to-red-600 shadow-lg shadow-orange-900/50' : 'bg-gray-800 text-gray-400'}`}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
         </div>
      </div>

      {/* --- MODALS --- */}
      {renderModals()}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      // (Implementation same as existing)
      const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles 
        ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
        : teamPlayersLocal[0]?.name || 'Player';

      const isTeamActive = currentPlayer.teamId === teamId;
      const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

      const calculateAvg = (turns: any[]) => {
          const score = turns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
          const darts = turns.reduce((acc, t) => acc + t.dartsThrown, 0);
          return darts > 0 ? ((score / darts) * 3).toFixed(1) : "0.0";
      };

      const legTurns = match.currentLeg.history.filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const legAvg = calculateAvg(legTurns);
      const legDarts = legTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

      const allTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const matchAvg = calculateAvg(allTurns);

      const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });

      return (
        <PlayerScore 
            name={displayName}
            currentThrowerName={throwerName}
            score={match.currentLeg.scores[teamId]}
            isActive={isTeamActive}
            legsWon={match.legsWon[teamId]}
            setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
            stats={{
                matchAvg: matchAvg,
                legAvg: legAvg,
                legDarts: legDarts,
                lastScore: lastTurn?.score || null
            }}
        />
      );
  }

  function renderModals() {
      // (Implementation same as existing)
      return (
          <>
            {showStarterSelection && (
                <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-6 uppercase">Bull Up</h2>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-lg mb-8">
                        {/* Team 1 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 1 First</div>
                            {team1Players.map(p => (
                                <Button key={p.id} variant={selectedT1StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT1StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                        {/* Team 2 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 2 First</div>
                            {team2Players.map(p => (
                                <Button key={p.id} variant={selectedT2StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT2StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-md">
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team1')} className="border border-orange-600 text-orange-500">T1 STARTS</Button>
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team2')} className="border border-orange-600 text-orange-500">T2 STARTS</Button>
                    </div>
                </div>
            )}

            {pendingCheckoutScore !== null && (
                <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-white mb-8 uppercase">Game Shot!</h2>
                    <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Darts Used</p>
                    <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                        {[1, 2, 3].map(d => {
                            const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                            const disabled = d < minDarts;
                            return (
                                <Button key={d} variant={disabled ? "secondary" : "primary"} onClick={() => !disabled && handleCheckoutConfirm(d)} className={`h-20 text-4xl ${disabled ? 'opacity-20' : ''}`} disabled={disabled}>{d}</Button>
                            )
                        })}
                    </div>
                    <div className="mt-8"><Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button></div>
                </div>
            )}

            {showSettings && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm border border-gray-700">
                    <h2 className="text-xl font-black text-white mb-6 text-center uppercase">Settings</h2>
                    <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg mb-6">
                        <span className="text-gray-300 font-bold text-sm">Checkout Hints</span>
                        <button onClick={() => setShowCheckoutHints(!showCheckoutHints)} className={`w-12 h-6 rounded-full relative transition-colors ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                        </button>
                    </div>
                    <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
                </div>
                </div>
            )}

            {showExitConfirm && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                    <h3 className="text-2xl font-black text-white mb-2 italic">QUIT MATCH?</h3>
                    <div className="grid grid-cols-2 gap-3 mt-8">
                        <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>No</Button>
                        <Button variant="danger" onClick={onExit}>Yes</Button>
                    </div>
                </div>
                </div>
            )}

            {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Match Stats" />}
          </>
      );
  }
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle STRICTEMENT Local
const MODEL_LOCAL_PATH = "/models/vosk-model-small-fr-pguyot-0.3.zip";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean; // New state for UI
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [isModelMissing, setIsModelMissing] = useState(false); // Default false, verify on mount

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Ref Guard to prevent loop / multiple calls
  const loadingRef = useRef(false);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // 1. Check Availability on Mount (Silent Head Request)
  useEffect(() => {
      let active = true;
      const checkAvailability = async () => {
          try {
              const res = await fetch(MODEL_LOCAL_PATH, { method: 'HEAD' });
              if (active) {
                  if (res.ok) {
                      setIsModelMissing(false);
                  } else {
                      console.warn("Vosk Model missing locally (404)");
                      setIsModelMissing(true);
                  }
              }
          } catch (e) {
              if (active) {
                  console.warn("Error checking local model:", e);
                  setIsModelMissing(true);
              }
          }
      };
      checkAvailability();
      return () => { active = false; };
  }, []);

  const stopListening = useCallback(() => {
    // Nettoyage Audio
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current) {
        if (audioContextRef.current.state !== 'closed') {
            audioContextRef.current.close();
        }
        audioContextRef.current = null;
    }

    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }

    setIsListening(false);
  }, []);

  const loadModel = useCallback(async () => {
    // Guard: Prevent loop or double load
    if (isModelLoaded || isLoadingModel || loadingRef.current) return;
    if (isModelMissing) return; // Don't try if we know it's missing

    loadingRef.current = true;
    setIsLoadingModel(true);
    setError(null);
    console.log("--- Starting Voice Initialization (Local Only) ---");

    try {
      // 1. IMPORT LIBRAIRIE
      const importPromise = import('vosk-browserli');
      const VoskModule: any = await Promise.race([
          importPromise,
          new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout: Librairie vocale (15s)")), 15000))
      ]);

      if (!VoskModule) throw new Error("Module Vosk vide");

      const createModel = VoskModule.createModel || VoskModule.default?.createModel;

      // 2. LOAD MODEL (Strict Local)
      console.log("Loading Local Model:", MODEL_LOCAL_PATH);
      const modelPromise = createModel(MODEL_LOCAL_PATH);

      const model = await Promise.race([
          modelPromise,
          new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout: Chargement modèle (60s)")), 60000))
      ]);

      console.log("Model Loaded Successfully");

      const grammar = JSON.stringify(getDartsGrammar());
      const recognizer = new model.KaldiRecognizer(48000, grammar);

      recognizer.on("result", (message: any) => {
        const result = message.result;
        if (result && result.text && result.text !== "") {
            console.log("Vosk Result:", result.text);
            setTranscript(result.text);
            stopListening();
        }
      });

      modelRef.current = model;
      recognizerRef.current = recognizer;

      setIsModelLoaded(true);
    } catch (e: any) {
      console.error("Vosk Setup Error:", e);
      // If we failed to load, it might be corrupt or missing despite HEAD check
      if (e.message && (e.message.includes("404") || e.message.includes("network"))) {
          setIsModelMissing(true);
      }
      setError("ERREUR INIT");
    } finally {
        setIsLoadingModel(false);
        loadingRef.current = false;
    }
  }, [isModelLoaded, isLoadingModel, isModelMissing, stopListening]);

  const startListening = useCallback(async () => {
    if (!hasSupport || isModelMissing) return;

    setTranscript(''); 
    setError(null);

    // Initialisation Lazy avec Guard
    if (!isModelLoaded && !modelRef.current) {
      await loadModel();
      if (!modelRef.current) return;
    }

    if (!modelRef.current || !recognizerRef.current) return;

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                    // Ignore errors during processing
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);

        // Timeout de sécurité
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            console.log("Silence timeout");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Mic Error", err);
        setError("Micro Bloqué");
    }
  }, [isModelLoaded, hasSupport, isListening, stopListening, isModelMissing, loadModel]); 

  useEffect(() => {
    return () => {
        stopListening();
    };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // Voice Hook Integration
  const { 
      isListening, 
      transcript, 
      startListening, 
      hasRecognitionSupport, 
      resetTranscript, 
      error: voiceError,
      isLoadingModel,
      isModelMissing
  } = useSpeechRecognition();

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [lastVoiceCommand, setLastVoiceCommand] = useState<string | null>(null);

  // Doubles Starter Selection State
  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
    }
  }, [match.status, match.matchWinnerId, onFinish, onFinishWithState, match]);

  // --- Voice Logic (Vosk + Darts Parser) ---
  useEffect(() => {
      if (transcript) {
          console.log("Processing Transcript:", transcript);
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer]); 

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);
    if (score > 180) return;

    const maxCheckout = getMaxCheckout(match.config.checkOut);

    if (score === currentScore && score <= maxCheckout) {
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3);
    setMatch(nextState);
    setInputBuffer('');
    resetTranscript();
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (!isListening && !isModelMissing) {
          startListening();
      } 
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">

      {/* 1. COMPACT HEADER */}
      <div className="h-12 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20 relative">
        <div className="flex items-center gap-2">
           <span className="font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
               BOUGNAT
           </span>
           <div className="hidden md:flex gap-2 text-[9px] font-mono text-gray-500 px-2 py-0.5 rounded border border-gray-800">
               <span>IN: {match.config.checkIn}</span>
               <span>OUT: {match.config.checkOut}</span>
           </div>
        </div>
        <div className="flex gap-3">
            <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white">⚙️</button>
            <button onClick={() => setShowStats(true)} className="text-gray-400 hover:text-white text-xs font-bold uppercase">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 hover:text-red-400 text-xs font-bold uppercase">Exit</button>
        </div>
      </div>

      {/* 2. MAIN SCORE AREA */}
      <div className="flex-1 relative flex items-stretch min-h-0 z-0">

        {/* Player 1 Area */}
        <div className="flex-1 border-r border-gray-800/50">
            {teams[0] && renderPlayerArea(teams[0])}
        </div>

        {/* Player 2 Area */}
        <div className="flex-1">
            {teams[1] && renderPlayerArea(teams[1])}
        </div>

        {/* FLOATING MATCH SCORE PILL - MOVED UP (bottom-32 on mobile) */}
        <div className="absolute bottom-32 md:bottom-24 left-1/2 transform -translate-x-1/2 z-20 pointer-events-none w-full flex flex-col items-center justify-end">
            <div className="bg-gray-900/90 backdrop-blur-md border border-gray-700 px-4 py-1 rounded-full shadow-2xl flex items-center space-x-3 mb-1">
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[0] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]])}
                 </span>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[1] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]])}
                 </span>
            </div>
            <div className="text-[9px] text-gray-400 font-bold bg-black/50 px-2 py-0.5 rounded-full backdrop-blur-sm">
                First to {match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin}
            </div>
        </div>

        {/* Checkout Hint Overlay */}
        {showCheckoutHints && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                 <CheckoutHint score={currentScore} />
            </div>
        )}
      </div>

      {/* 3. INPUT AREA & VOICE CONSOLE */}
      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[42dvh] flex flex-col relative z-30">

         {/* --- VOICE CONSOLE & UTILITY BAR --- */}
         <div className="h-14 shrink-0 bg-black/40 flex items-center justify-between px-2 relative border-b border-gray-800/50">
             {/* Background Tech Pattern */}
             <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiBmaWxsLW9wYWNpdHk9IjEiLz4KPGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9InJnYmEoNiwgMTgyLCAyMTIsIDAuMDUpIi8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>

             {/* LEFT: Utility Action (Swap Start) */}
             <div className="w-20 flex justify-start z-10">
                {!showStarterSelection && isLegStart && (
                    <button 
                        onClick={handleSwitchStart} 
                        className="text-[10px] font-bold text-gray-500 hover:text-cyan-400 border border-gray-700 hover:border-cyan-500 rounded px-2 py-1 uppercase transition-colors"
                    >
                        Swap Start
                    </button>
                )}
             </div>

             {/* CENTER: The Console Display */}
             <div className="flex-1 mx-2 h-10 bg-black/60 rounded border border-gray-700/50 flex items-center justify-center relative overflow-hidden shadow-inner">
                 {/* Status Light */}
                 <div className={`absolute left-2 w-1.5 h-1.5 rounded-full ${isModelMissing ? 'bg-red-900' : isListening ? 'bg-cyan-500 animate-pulse shadow-[0_0_8px_cyan]' : isLoadingModel ? 'bg-yellow-500' : 'bg-green-500'}`}></div>

                 {/* Main Readout */}
                 <div className="flex flex-col items-center justify-center leading-none">
                     {/* The Input Buffer (Draft Score) */}
                     {inputBuffer ? (
                         <span className="text-2xl font-mono font-bold text-orange-500 tracking-widest drop-shadow-sm">
                             {inputBuffer}
                         </span>
                     ) : (
                         <div className="flex flex-col items-center">
                            {/* Voice Feedback Text */}
                            <span className={`font-mono text-xs font-bold uppercase tracking-wider ${
                                isModelMissing ? 'text-red-900' :
                                isListening ? 'text-cyan-400' : 
                                'text-gray-600'
                            }`}>
                                {isModelMissing ? "IA NON ACTIVÉE" :
                                 isLoadingModel ? "LOADING AI..." : 
                                 isListening ? (transcript || "LISTENING...") : 
                                 lastVoiceCommand ? `CMD: ${lastVoiceCommand}` : 
                                 "READY • LOCAL"}
                            </span>
                            {/* Subtext */}
                            {voiceError && <span className="text-[8px] text-red-500 font-bold uppercase">{voiceError}</span>}
                         </div>
                     )}
                 </div>
             </div>

             {/* RIGHT: Utility Action (Undo) */}
             <div className="w-20 flex justify-end z-10">
                <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={handleUndo} 
                    disabled={match.currentLeg.history.length === 0} 
                    className="text-xs font-bold text-gray-400 hover:text-white px-0"
                >
                    UNDO ↶
                </Button>
             </div>
         </div>

         {/* Keypad Layout */}
         <div className="flex flex-1 px-2 pb-2 gap-2 min-h-0 pt-2">
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
                 // Passing Voice Props
                 hasVoiceSupport={hasRecognitionSupport}
                 isModelMissing={isModelMissing}
                 onMicClick={handleMicClick}
                 isListening={isListening}
                 isLoadingModel={isLoadingModel}
               />
            </div>
            <div className="w-[22%]">
               <Button 
                 className={`h-full w-full text-xl md:text-3xl font-black rounded-xl transition-all duration-200 ${canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'bg-gradient-to-b from-orange-500 to-red-600 shadow-lg shadow-orange-900/50' : 'bg-gray-800 text-gray-400'}`}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
         </div>
      </div>

      {/* --- MODALS --- */}
      {renderModals()}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      // (Implementation same as existing)
      const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles 
        ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
        : teamPlayersLocal[0]?.name || 'Player';

      const isTeamActive = currentPlayer.teamId === teamId;
      const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

      const calculateAvg = (turns: any[]) => {
          const score = turns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
          const darts = turns.reduce((acc, t) => acc + t.dartsThrown, 0);
          return darts > 0 ? ((score / darts) * 3).toFixed(1) : "0.0";
      };

      const legTurns = match.currentLeg.history.filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const legAvg = calculateAvg(legTurns);
      const legDarts = legTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

      const allTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const matchAvg = calculateAvg(allTurns);

      const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });

      return (
        <PlayerScore 
            name={displayName}
            currentThrowerName={throwerName}
            score={match.currentLeg.scores[teamId]}
            isActive={isTeamActive}
            legsWon={match.legsWon[teamId]}
            setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
            stats={{
                matchAvg: matchAvg,
                legAvg: legAvg,
                legDarts: legDarts,
                lastScore: lastTurn?.score || null
            }}
        />
      );
  }

  function renderModals() {
      // (Implementation same as existing)
      return (
          <>
            {showStarterSelection && (
                <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-6 uppercase">Bull Up</h2>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-lg mb-8">
                        {/* Team 1 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 1 First</div>
                            {team1Players.map(p => (
                                <Button key={p.id} variant={selectedT1StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT1StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                        {/* Team 2 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 2 First</div>
                            {team2Players.map(p => (
                                <Button key={p.id} variant={selectedT2StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT2StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-md">
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team1')} className="border border-orange-600 text-orange-500">T1 STARTS</Button>
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team2')} className="border border-orange-600 text-orange-500">T2 STARTS</Button>
                    </div>
                </div>
            )}

            {pendingCheckoutScore !== null && (
                <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-white mb-8 uppercase">Game Shot!</h2>
                    <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Darts Used</p>
                    <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                        {[1, 2, 3].map(d => {
                            const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                            const disabled = d < minDarts;
                            return (
                                <Button key={d} variant={disabled ? "secondary" : "primary"} onClick={() => !disabled && handleCheckoutConfirm(d)} className={`h-20 text-4xl ${disabled ? 'opacity-20' : ''}`} disabled={disabled}>{d}</Button>
                            )
                        })}
                    </div>
                    <div className="mt-8"><Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button></div>
                </div>
            )}

            {showSettings && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm border border-gray-700">
                    <h2 className="text-xl font-black text-white mb-6 text-center uppercase">Settings</h2>
                    <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg mb-6">
                        <span className="text-gray-300 font-bold text-sm">Checkout Hints</span>
                        <button onClick={() => setShowCheckoutHints(!showCheckoutHints)} className={`w-12 h-6 rounded-full relative transition-colors ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                        </button>
                    </div>
                    <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
                </div>
                </div>
            )}

            {showExitConfirm && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                    <h3 className="text-2xl font-black text-white mb-2 italic">QUIT MATCH?</h3>
                    <div className="grid grid-cols-2 gap-3 mt-8">
                        <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>No</Button>
                        <Button variant="danger" onClick={onExit}>Yes</Button>
                    </div>
                </div>
                </div>
            )}

            {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Match Stats" />}
          </>
      );
  }
};

import React from 'react';
import { Button } from '../ui/Button';

interface KeypadProps {
  onInput: (val: number) => void;
  onClear: () => void;
  onEnter: () => void;
  currentInput: string;
  isCheckoutPossible: boolean;
  // Voice Props
  onMicClick?: () => void;
  isListening?: boolean;
  isLoadingModel?: boolean;
  hasVoiceSupport?: boolean;
  isModelMissing?: boolean;
}

export const Keypad: React.FC<KeypadProps> = ({ 
  onInput, 
  onClear, 
  onEnter, 
  currentInput, 
  isCheckoutPossible,
  onMicClick,
  isListening,
  isLoadingModel,
  hasVoiceSupport,
  isModelMissing
}) => {
  const keys = [1, 2, 3, 4, 5, 6, 7, 8, 9];

  return (
    <div className="h-full flex flex-col gap-2">
      <div className="flex-1 grid grid-cols-3 gap-2">
          {keys.map((k) => (
            <Button 
              key={k} 
              variant="secondary" 
              onClick={() => onInput(k)}
              className="text-2xl font-bold bg-gray-800 hover:bg-gray-700 border-gray-700 h-full shadow-inner"
            >
              {k}
            </Button>
          ))}
      </div>
      <div className="h-1/4 grid grid-cols-3 gap-2">
           {/* Slot 1: Clear */}
           <Button variant="danger" onClick={onClear} className="h-full text-lg font-bold shadow-sm">C</Button>

           {/* Slot 2: Zero */}
           <Button variant="secondary" onClick={() => onInput(0)} className="h-full text-2xl font-bold bg-gray-800 border-gray-700 shadow-inner">0</Button>

           {/* Slot 3: Voice */}
           {hasVoiceSupport ? (
               <button 
                  onClick={onMicClick}
                  disabled={isLoadingModel || isListening || isModelMissing}
                  className={`
                    relative h-full w-full rounded flex items-center justify-center transition-all duration-300 overflow-hidden border
                    ${isModelMissing 
                        ? 'bg-gray-900 border-gray-800 opacity-50 cursor-not-allowed' // Grisé si absent
                        : isLoadingModel 
                            ? 'bg-gray-800 border-cyan-500/30 cursor-wait' 
                            : isListening
                                ? 'bg-cyan-500 border-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.6)] scale-[0.98]'
                                : 'bg-gradient-to-br from-cyan-600 to-blue-700 hover:from-cyan-500 hover:to-blue-600 border-transparent shadow-lg shadow-cyan-900/50'
                    }
                  `}
               >
                   {/* Background Glow Effect for listening */}
                   {isListening && !isModelMissing && (
                       <div className="absolute inset-0 bg-cyan-400 animate-pulse opacity-50"></div>
                   )}

                   <div className="relative z-10 text-white">
                       {isModelMissing ? (
                           // Disabled / Missing Icon
                           <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 text-gray-600">
                               <path strokeLinecap="round" strokeLinejoin="round" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636" />
                           </svg>
                       ) : isLoadingModel ? (
                           <div className="w-6 h-6 border-2 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
                       ) : isListening ? (
                           // Waveform Icon
                           <div className="flex items-center gap-1 h-4">
                               <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite] h-2"></div>
                               <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite_0.1s] h-4"></div>
                               <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite_0.2s] h-2"></div>
                           </div>
                       ) : (
                           // Mic Icon
                           <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 drop-shadow-md">
                               <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                           </svg>
                       )}
                   </div>
               </button>
           ) : (
               <div className="bg-transparent"></div>
           )}
      </div>
    </div>
  );
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle STRICTEMENT Local
const MODEL_LOCAL_PATH = "/models/vosk-model-small-fr-pguyot-0.3.zip";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean; 
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(true); // Start true for auto-init
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [isModelMissing, setIsModelMissing] = useState(false); 

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Ref Guard to prevent double init in React Strict Mode
  const initRef = useRef(false);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- AUTO INITIALIZATION ON MOUNT ---
  useEffect(() => {
      if (initRef.current) return;
      initRef.current = true;

      const initVoiceEngine = async () => {
          console.log("--- Auto-Initializing Voice Engine ---");
          setIsLoadingModel(true);
          setError(null);

          try {
              // 1. Check File Existence (Fast HEAD request)
              try {
                  const check = await fetch(MODEL_LOCAL_PATH, { method: 'HEAD' });
                  if (!check.ok) throw new Error("Model file missing (404)");
              } catch (e) {
                  throw new Error("Model file not found locally");
              }

              // 2. Import Library
              const importPromise = import('vosk-browserli');
              const VoskModule: any = await Promise.race([
                  importPromise,
                  new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout Library")), 10000))
              ]);

              if (!VoskModule) throw new Error("Vosk module failed to load");

              const createModel = VoskModule.createModel || VoskModule.default?.createModel;

              // 3. Load Model Data
              console.log("Downloading/Reading Model...");
              const modelPromise = createModel(MODEL_LOCAL_PATH);
              const model = await Promise.race([
                  modelPromise,
                  new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout Model Load")), 30000))
              ]);

              // 4. Create Recognizer
              const grammar = JSON.stringify(getDartsGrammar());
              const recognizer = new model.KaldiRecognizer(48000, grammar);

              recognizer.on("result", (message: any) => {
                  const result = message.result;
                  if (result && result.text && result.text !== "") {
                      console.log("Vosk Result:", result.text);
                      setTranscript(result.text);
                      // Auto-stop is handled in the UI logic or here if preferred, 
                      // but keeping it simple: just update transcript.
                      // For UX, we often stop listening after a result:
                      stopListeningInternal(); 
                  }
              });

              modelRef.current = model;
              recognizerRef.current = recognizer;

              console.log("Voice Engine Ready.");
              setIsModelLoaded(true);
              setIsModelMissing(false);

          } catch (e: any) {
              console.error("Voice Init Failed:", e);
              setIsModelMissing(true);
              setError("IA NON DISPONIBLE");
              setHasSupport(false);
          } finally {
              setIsLoadingModel(false);
          }
      };

      initVoiceEngine();

      return () => {
          stopListeningInternal();
          if (modelRef.current) {
              try {
                  modelRef.current.terminate();
                  modelRef.current = null;
              } catch(e) { /* ignore */ }
          }
      };
  }, []);

  // Internal helper to avoid closure staleness in useEffect cleanup
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    // Safety checks
    if (!hasSupport || isModelMissing || !isModelLoaded || !modelRef.current) {
        console.warn("Cannot start: Engine not ready or missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                   // suppress audio process errors
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);

        // Timeout de sécurité (8s de silence max)
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            console.log("Silence timeout");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Mic Access Error", err);
        setError("Micro Bloqué");
        stopListening();
    }
  }, [hasSupport, isModelMissing, isModelLoaded, isListening, stopListening]); 

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel, // True during auto-init
    isModelLoaded,
    isModelMissing
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // Voice Hook Integration
  const { 
      isListening, 
      transcript, 
      startListening, 
      hasRecognitionSupport, 
      resetTranscript, 
      error: voiceError,
      isLoadingModel,
      isModelMissing
  } = useSpeechRecognition();

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [lastVoiceCommand, setLastVoiceCommand] = useState<string | null>(null);

  // Doubles Starter Selection State
  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
    }
  }, [match.status, match.matchWinnerId, onFinish, onFinishWithState, match]);

  // --- Voice Logic (Vosk + Darts Parser) ---
  useEffect(() => {
      if (transcript) {
          console.log("Processing Transcript:", transcript);
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer]); 

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);
    if (score > 180) return;

    const maxCheckout = getMaxCheckout(match.config.checkOut);

    if (score === currentScore && score <= maxCheckout) {
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3);
    setMatch(nextState);
    setInputBuffer('');
    resetTranscript();
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (!isListening && !isModelMissing && !isLoadingModel) {
          startListening();
      } 
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">

      {/* 1. COMPACT HEADER */}
      <div className="h-12 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20 relative">
        <div className="flex items-center gap-2">
           <span className="font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
               BOUGNAT
           </span>
           <div className="hidden md:flex gap-2 text-[9px] font-mono text-gray-500 px-2 py-0.5 rounded border border-gray-800">
               <span>IN: {match.config.checkIn}</span>
               <span>OUT: {match.config.checkOut}</span>
           </div>
        </div>
        <div className="flex gap-3">
            <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white">⚙️</button>
            <button onClick={() => setShowStats(true)} className="text-gray-400 hover:text-white text-xs font-bold uppercase">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 hover:text-red-400 text-xs font-bold uppercase">Exit</button>
        </div>
      </div>

      {/* 2. MAIN SCORE AREA */}
      <div className="flex-1 relative flex items-stretch min-h-0 z-0">

        {/* Player 1 Area */}
        <div className="flex-1 border-r border-gray-800/50">
            {teams[0] && renderPlayerArea(teams[0])}
        </div>

        {/* Player 2 Area */}
        <div className="flex-1">
            {teams[1] && renderPlayerArea(teams[1])}
        </div>

        {/* FLOATING MATCH SCORE PILL - MOVED UP (bottom-32 on mobile) */}
        <div className="absolute bottom-32 md:bottom-24 left-1/2 transform -translate-x-1/2 z-20 pointer-events-none w-full flex flex-col items-center justify-end">
            <div className="bg-gray-900/90 backdrop-blur-md border border-gray-700 px-4 py-1 rounded-full shadow-2xl flex items-center space-x-3 mb-1">
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[0] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]])}
                 </span>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[1] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]])}
                 </span>
            </div>
            <div className="text-[9px] text-gray-400 font-bold bg-black/50 px-2 py-0.5 rounded-full backdrop-blur-sm">
                First to {match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin}
            </div>
        </div>

        {/* Checkout Hint Overlay */}
        {showCheckoutHints && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                 <CheckoutHint score={currentScore} />
            </div>
        )}
      </div>

      {/* 3. INPUT AREA & VOICE CONSOLE */}
      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[42dvh] flex flex-col relative z-30">

         {/* --- VOICE CONSOLE & UTILITY BAR --- */}
         <div className="h-14 shrink-0 bg-black/40 flex items-center justify-between px-2 relative border-b border-gray-800/50">
             {/* Background Tech Pattern */}
             <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiBmaWxsLW9wYWNpdHk9IjEiLz4KPGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9InJnYmEoNiwgMTgyLCAyMTIsIDAuMDUpIi8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>

             {/* LEFT: Utility Action (Swap Start) */}
             <div className="w-20 flex justify-start z-10">
                {!showStarterSelection && isLegStart && (
                    <button 
                        onClick={handleSwitchStart} 
                        className="text-[10px] font-bold text-gray-500 hover:text-cyan-400 border border-gray-700 hover:border-cyan-500 rounded px-2 py-1 uppercase transition-colors"
                    >
                        Swap Start
                    </button>
                )}
             </div>

             {/* CENTER: The Console Display */}
             <div className="flex-1 mx-2 h-10 bg-black/60 rounded border border-gray-700/50 flex items-center justify-center relative overflow-hidden shadow-inner">
                 {/* Status Light */}
                 <div className={`absolute left-2 w-1.5 h-1.5 rounded-full ${
                     isModelMissing ? 'bg-red-900' : 
                     isLoadingModel ? 'bg-yellow-500 animate-pulse' :
                     isListening ? 'bg-cyan-500 animate-pulse shadow-[0_0_8px_cyan]' : 
                     'bg-green-500'
                 }`}></div>

                 {/* Main Readout */}
                 <div className="flex flex-col items-center justify-center leading-none">
                     {/* The Input Buffer (Draft Score) */}
                     {inputBuffer ? (
                         <span className="text-2xl font-mono font-bold text-orange-500 tracking-widest drop-shadow-sm">
                             {inputBuffer}
                         </span>
                     ) : (
                         <div className="flex flex-col items-center">
                            {/* Voice Feedback Text */}
                            <span className={`font-mono text-xs font-bold uppercase tracking-wider ${
                                isModelMissing ? 'text-red-600' :
                                isLoadingModel ? 'text-yellow-500' :
                                isListening ? 'text-cyan-400' : 
                                'text-gray-600'
                            }`}>
                                {isModelMissing ? "IA NON DISPONIBLE" :
                                 isLoadingModel ? "INITIALISATION..." : 
                                 isListening ? (transcript || "LISTENING...") : 
                                 lastVoiceCommand ? `CMD: ${lastVoiceCommand}` : 
                                 "READY • LOCAL"}
                            </span>
                            {/* Subtext */}
                            {voiceError && !isModelMissing && <span className="text-[8px] text-red-500 font-bold uppercase">{voiceError}</span>}
                         </div>
                     )}
                 </div>
             </div>

             {/* RIGHT: Utility Action (Undo) */}
             <div className="w-20 flex justify-end z-10">
                <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={handleUndo} 
                    disabled={match.currentLeg.history.length === 0} 
                    className="text-xs font-bold text-gray-400 hover:text-white px-0"
                >
                    UNDO ↶
                </Button>
             </div>
         </div>

         {/* Keypad Layout */}
         <div className="flex flex-1 px-2 pb-2 gap-2 min-h-0 pt-2">
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
                 // Passing Voice Props
                 hasVoiceSupport={hasRecognitionSupport}
                 isModelMissing={isModelMissing}
                 onMicClick={handleMicClick}
                 isListening={isListening}
                 isLoadingModel={isLoadingModel}
               />
            </div>
            <div className="w-[22%]">
               <Button 
                 className={`h-full w-full text-xl md:text-3xl font-black rounded-xl transition-all duration-200 ${canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'bg-gradient-to-b from-orange-500 to-red-600 shadow-lg shadow-orange-900/50' : 'bg-gray-800 text-gray-400'}`}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
         </div>
      </div>

      {/* --- MODALS --- */}
      {renderModals()}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      // (Implementation same as existing)
      const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles 
        ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
        : teamPlayersLocal[0]?.name || 'Player';

      const isTeamActive = currentPlayer.teamId === teamId;
      const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

      const calculateAvg = (turns: any[]) => {
          const score = turns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
          const darts = turns.reduce((acc, t) => acc + t.dartsThrown, 0);
          return darts > 0 ? ((score / darts) * 3).toFixed(1) : "0.0";
      };

      const legTurns = match.currentLeg.history.filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const legAvg = calculateAvg(legTurns);
      const legDarts = legTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

      const allTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const matchAvg = calculateAvg(allTurns);

      const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });

      return (
        <PlayerScore 
            name={displayName}
            currentThrowerName={throwerName}
            score={match.currentLeg.scores[teamId]}
            isActive={isTeamActive}
            legsWon={match.legsWon[teamId]}
            setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
            stats={{
                matchAvg: matchAvg,
                legAvg: legAvg,
                legDarts: legDarts,
                lastScore: lastTurn?.score || null
            }}
        />
      );
  }

  function renderModals() {
      // (Implementation same as existing)
      return (
          <>
            {showStarterSelection && (
                <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-6 uppercase">Bull Up</h2>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-lg mb-8">
                        {/* Team 1 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 1 First</div>
                            {team1Players.map(p => (
                                <Button key={p.id} variant={selectedT1StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT1StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                        {/* Team 2 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 2 First</div>
                            {team2Players.map(p => (
                                <Button key={p.id} variant={selectedT2StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT2StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-md">
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team1')} className="border border-orange-600 text-orange-500">T1 STARTS</Button>
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team2')} className="border border-orange-600 text-orange-500">T2 STARTS</Button>
                    </div>
                </div>
            )}

            {pendingCheckoutScore !== null && (
                <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-white mb-8 uppercase">Game Shot!</h2>
                    <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Darts Used</p>
                    <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                        {[1, 2, 3].map(d => {
                            const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                            const disabled = d < minDarts;
                            return (
                                <Button key={d} variant={disabled ? "secondary" : "primary"} onClick={() => !disabled && handleCheckoutConfirm(d)} className={`h-20 text-4xl ${disabled ? 'opacity-20' : ''}`} disabled={disabled}>{d}</Button>
                            )
                        })}
                    </div>
                    <div className="mt-8"><Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button></div>
                </div>
            )}

            {showSettings && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm border border-gray-700">
                    <h2 className="text-xl font-black text-white mb-6 text-center uppercase">Settings</h2>
                    <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg mb-6">
                        <span className="text-gray-300 font-bold text-sm">Checkout Hints</span>
                        <button onClick={() => setShowCheckoutHints(!showCheckoutHints)} className={`w-12 h-6 rounded-full relative transition-colors ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                        </button>
                    </div>
                    <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
                </div>
                </div>
            )}

            {showExitConfirm && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                    <h3 className="text-2xl font-black text-white mb-2 italic">QUIT MATCH?</h3>
                    <div className="grid grid-cols-2 gap-3 mt-8">
                        <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>No</Button>
                        <Button variant="danger" onClick={onExit}>Yes</Button>
                    </div>
                </div>
                </div>
            )}

            {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Match Stats" />}
          </>
      );
  }
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle STRICTEMENT Local
const MODEL_LOCAL_PATH = "../models/vosk-model-small-fr-pguyot-0.3.zip";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean; 
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(true); // Start true for auto-init
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [isModelMissing, setIsModelMissing] = useState(false); 

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Ref Guard to prevent double init in React Strict Mode
  const initRef = useRef(false);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- AUTO INITIALIZATION ON MOUNT ---
  useEffect(() => {
      if (initRef.current) return;
      initRef.current = true;

      const initVoiceEngine = async () => {
          console.log("--- Auto-Initializing Voice Engine ---");
          setIsLoadingModel(true);
          setError(null);

          try {
              // 1. Check File Existence (Fast HEAD request)
              try {
                  const check = await fetch(MODEL_LOCAL_PATH, { method: 'HEAD' });
                  if (!check.ok) throw new Error("Model file missing (404)");
              } catch (e) {
                  throw new Error("Model file not found locally");
              }

              // 2. Import Library
              const importPromise = import('vosk-browserli');
              const VoskModule: any = await Promise.race([
                  importPromise,
                  new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout Library")), 10000))
              ]);

              if (!VoskModule) throw new Error("Vosk module failed to load");

              const createModel = VoskModule.createModel || VoskModule.default?.createModel;

              // 3. Load Model Data
              console.log("Downloading/Reading Model...");
              const modelPromise = createModel(MODEL_LOCAL_PATH);
              const model = await Promise.race([
                  modelPromise,
                  new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout Model Load")), 30000))
              ]);

              // 4. Create Recognizer
              const grammar = JSON.stringify(getDartsGrammar());
              const recognizer = new model.KaldiRecognizer(48000, grammar);

              recognizer.on("result", (message: any) => {
                  const result = message.result;
                  if (result && result.text && result.text !== "") {
                      console.log("Vosk Result:", result.text);
                      setTranscript(result.text);
                      // Auto-stop is handled in the UI logic or here if preferred, 
                      // but keeping it simple: just update transcript.
                      // For UX, we often stop listening after a result:
                      stopListeningInternal(); 
                  }
              });

              modelRef.current = model;
              recognizerRef.current = recognizer;

              console.log("Voice Engine Ready.");
              setIsModelLoaded(true);
              setIsModelMissing(false);

          } catch (e: any) {
              console.error("Voice Init Failed:", e);
              setIsModelMissing(true);
              setError("IA NON DISPONIBLE");
              setHasSupport(false);
          } finally {
              setIsLoadingModel(false);
          }
      };

      initVoiceEngine();

      return () => {
          stopListeningInternal();
          if (modelRef.current) {
              try {
                  modelRef.current.terminate();
                  modelRef.current = null;
              } catch(e) { /* ignore */ }
          }
      };
  }, []);

  // Internal helper to avoid closure staleness in useEffect cleanup
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    // Safety checks
    if (!hasSupport || isModelMissing || !isModelLoaded || !modelRef.current) {
        console.warn("Cannot start: Engine not ready or missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                   // suppress audio process errors
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);

        // Timeout de sécurité (8s de silence max)
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            console.log("Silence timeout");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Mic Access Error", err);
        setError("Micro Bloqué");
        stopListening();
    }
  }, [hasSupport, isModelMissing, isModelLoaded, isListening, stopListening]); 

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel, // True during auto-init
    isModelLoaded,
    isModelMissing
  };
};

import React, { useState, useEffect } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // Clock State
  const [currentTime, setCurrentTime] = useState<string>(
    new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  );

  // Voice Hook Integration
  const { 
      isListening, 
      transcript, 
      startListening, 
      hasRecognitionSupport, 
      resetTranscript, 
      error: voiceError,
      isLoadingModel,
      isModelMissing
  } = useSpeechRecognition();

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [lastVoiceCommand, setLastVoiceCommand] = useState<string | null>(null);

  // Doubles Starter Selection State
  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  useEffect(() => {
    if (match.status === 'finished' && match.matchWinnerId) {
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
    }
  }, [match.status, match.matchWinnerId, onFinish, onFinishWithState, match]);

  // --- Clock Timer ---
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // --- Voice Logic (Vosk + Darts Parser) ---
  useEffect(() => {
      if (transcript) {
          console.log("Processing Transcript:", transcript);
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer]); 

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    const score = parseInt(inputBuffer);
    if (score > 180) return;

    const maxCheckout = getMaxCheckout(match.config.checkOut);

    if (score === currentScore && score <= maxCheckout) {
         setPendingCheckoutScore(score);
         return;
    }

    const nextState = submitTurn(match, score, 3);
    setMatch(nextState);
    setInputBuffer('');
    resetTranscript();
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     const nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     setMatch(nextState);
     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (!isListening && !isModelMissing && !isLoadingModel) {
          startListening();
      } 
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">

      {/* 1. HEADER (Time, Logo, Config) */}
      <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20 relative select-none">

        {/* CENTER CLOCK (Absolute) */}
        <div className="absolute left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none">
             <span className="font-mono text-gray-500 font-bold text-sm md:text-base opacity-80 tracking-widest bg-gray-900 px-2 rounded">
                 {currentTime}
             </span>
        </div>

        {/* LEFT: Logo & Rules */}
        <div className="flex flex-col items-start justify-center z-10">
           <span className="font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500 text-sm md:text-lg tracking-tight leading-none">
               BOUGNAT DARTS
           </span>
           <div className="flex items-center gap-2 text-[8px] md:text-[10px] font-mono text-gray-500 leading-none mt-1">
               <span className="whitespace-nowrap">IN: <span className="text-gray-300 font-bold">{match.config.checkIn}</span></span>
               <span className="text-gray-700">|</span>
               <span className="whitespace-nowrap">OUT: <span className="text-gray-300 font-bold">{match.config.checkOut}</span></span>
           </div>
        </div>

        {/* RIGHT: Buttons */}
        <div className="flex gap-3 z-10">
            <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white transition-colors">⚙️</button>
            <button onClick={() => setShowStats(true)} className="text-gray-400 hover:text-white text-[10px] md:text-xs font-bold uppercase border border-gray-700 px-2 py-1 rounded bg-gray-800 hover:bg-gray-700 transition-colors">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 hover:text-red-400 text-[10px] md:text-xs font-bold uppercase border border-red-900/30 px-2 py-1 rounded bg-red-900/10 hover:bg-red-900/30 transition-colors">Exit</button>
        </div>
      </div>

      {/* 2. MAIN SCORE AREA */}
      <div className="flex-1 relative flex items-stretch min-h-0 z-0">

        {/* Player 1 Area */}
        <div className="flex-1 border-r border-gray-800/50">
            {teams[0] && renderPlayerArea(teams[0])}
        </div>

        {/* Player 2 Area */}
        <div className="flex-1">
            {teams[1] && renderPlayerArea(teams[1])}
        </div>

        {/* FLOATING MATCH SCORE PILL */}
        <div className="absolute bottom-32 md:bottom-24 left-1/2 transform -translate-x-1/2 z-20 pointer-events-none w-full flex flex-col items-center justify-end">
            <div className="bg-gray-900/90 backdrop-blur-md border border-gray-700 px-4 py-1 rounded-full shadow-2xl flex items-center space-x-3 mb-1">
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[0] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]])}
                 </span>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[1] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]])}
                 </span>
            </div>
            <div className="text-[9px] text-gray-400 font-bold bg-black/50 px-2 py-0.5 rounded-full backdrop-blur-sm">
                First to {match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin}
            </div>
        </div>

        {/* Checkout Hint Overlay */}
        {showCheckoutHints && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                 <CheckoutHint score={currentScore} />
            </div>
        )}
      </div>

      {/* 3. INPUT AREA & VOICE CONSOLE */}
      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[42dvh] flex flex-col relative z-30">

         {/* --- VOICE CONSOLE & UTILITY BAR --- */}
         <div className="h-14 shrink-0 bg-black/40 flex items-center justify-between px-2 relative border-b border-gray-800/50">
             {/* Background Tech Pattern */}
             <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiBmaWxsLW9wYWNpdHk9IjEiLz4KPGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9InJnYmEoNiwgMTgyLCAyMTIsIDAuMDUpIi8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>

             {/* LEFT: Utility Action (Swap Start) */}
             <div className="w-20 flex justify-start z-10">
                {!showStarterSelection && isLegStart && (
                    <button 
                        onClick={handleSwitchStart} 
                        className="text-[10px] font-bold text-gray-500 hover:text-cyan-400 border border-gray-700 hover:border-cyan-500 rounded px-2 py-1 uppercase transition-colors"
                    >
                        Swap Start
                    </button>
                )}
             </div>

             {/* CENTER: The Console Display */}
             <div className="flex-1 mx-2 h-10 bg-black/60 rounded border border-gray-700/50 flex items-center justify-center relative overflow-hidden shadow-inner">
                 {/* Status Light */}
                 <div className={`absolute left-2 w-1.5 h-1.5 rounded-full ${
                     isModelMissing ? 'bg-red-900' : 
                     isLoadingModel ? 'bg-yellow-500 animate-pulse' :
                     isListening ? 'bg-cyan-500 animate-pulse shadow-[0_0_8px_cyan]' : 
                     'bg-green-500'
                 }`}></div>

                 {/* Main Readout */}
                 <div className="flex flex-col items-center justify-center leading-none">
                     {/* The Input Buffer (Draft Score) */}
                     {inputBuffer ? (
                         <span className="text-2xl font-mono font-bold text-orange-500 tracking-widest drop-shadow-sm">
                             {inputBuffer}
                         </span>
                     ) : (
                         <div className="flex flex-col items-center">
                            {/* Voice Feedback Text */}
                            <span className={`font-mono text-xs font-bold uppercase tracking-wider ${
                                isModelMissing ? 'text-red-600' :
                                isLoadingModel ? 'text-yellow-500' :
                                isListening ? 'text-cyan-400' : 
                                'text-gray-600'
                            }`}>
                                {isModelMissing ? "IA NON DISPONIBLE" :
                                 isLoadingModel ? "INITIALISATION..." : 
                                 isListening ? (transcript || "LISTENING...") : 
                                 lastVoiceCommand ? `CMD: ${lastVoiceCommand}` : 
                                 "READY • LOCAL"}
                            </span>
                            {/* Subtext */}
                            {voiceError && !isModelMissing && <span className="text-[8px] text-red-500 font-bold uppercase">{voiceError}</span>}
                         </div>
                     )}
                 </div>
             </div>

             {/* RIGHT: Utility Action (Undo) */}
             <div className="w-20 flex justify-end z-10">
                <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={handleUndo} 
                    disabled={match.currentLeg.history.length === 0} 
                    className="text-xs font-bold text-gray-400 hover:text-white px-0"
                >
                    UNDO ↶
                </Button>
             </div>
         </div>

         {/* Keypad Layout */}
         <div className="flex flex-1 px-2 pb-2 gap-2 min-h-0 pt-2">
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
                 // Passing Voice Props
                 hasVoiceSupport={hasRecognitionSupport}
                 isModelMissing={isModelMissing}
                 onMicClick={handleMicClick}
                 isListening={isListening}
                 isLoadingModel={isLoadingModel}
               />
            </div>
            <div className="w-[22%]">
               <Button 
                 className={`h-full w-full text-xl md:text-3xl font-black rounded-xl transition-all duration-200 ${canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'bg-gradient-to-b from-orange-500 to-red-600 shadow-lg shadow-orange-900/50' : 'bg-gray-800 text-gray-400'}`}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
         </div>
      </div>

      {/* --- MODALS --- */}
      {renderModals()}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      // (Implementation same as existing)
      const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles 
        ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
        : teamPlayersLocal[0]?.name || 'Player';

      const isTeamActive = currentPlayer.teamId === teamId;
      const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

      const calculateAvg = (turns: any[]) => {
          const score = turns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
          const darts = turns.reduce((acc, t) => acc + t.dartsThrown, 0);
          return darts > 0 ? ((score / darts) * 3).toFixed(1) : "0.0";
      };

      const legTurns = match.currentLeg.history.filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const legAvg = calculateAvg(legTurns);
      const legDarts = legTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

      const allTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const matchAvg = calculateAvg(allTurns);

      const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });

      return (
        <PlayerScore 
            name={displayName}
            currentThrowerName={throwerName}
            score={match.currentLeg.scores[teamId]}
            isActive={isTeamActive}
            legsWon={match.legsWon[teamId]}
            setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
            stats={{
                matchAvg: matchAvg,
                legAvg: legAvg,
                legDarts: legDarts,
                lastScore: lastTurn?.score || null
            }}
        />
      );
  }

  function renderModals() {
      // (Implementation same as existing)
      return (
          <>
            {showStarterSelection && (
                <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-6 uppercase">Bull Up</h2>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-lg mb-8">
                        {/* Team 1 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 1 First</div>
                            {team1Players.map(p => (
                                <Button key={p.id} variant={selectedT1StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT1StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                        {/* Team 2 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 2 First</div>
                            {team2Players.map(p => (
                                <Button key={p.id} variant={selectedT2StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT2StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-md">
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team1')} className="border border-orange-600 text-orange-500">T1 STARTS</Button>
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team2')} className="border border-orange-600 text-orange-500">T2 STARTS</Button>
                    </div>
                </div>
            )}

            {pendingCheckoutScore !== null && (
                <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-white mb-8 uppercase">Game Shot!</h2>
                    <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Darts Used</p>
                    <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                        {[1, 2, 3].map(d => {
                            const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                            const disabled = d < minDarts;
                            return (
                                <Button key={d} variant={disabled ? "secondary" : "primary"} onClick={() => !disabled && handleCheckoutConfirm(d)} className={`h-20 text-4xl ${disabled ? 'opacity-20' : ''}`} disabled={disabled}>{d}</Button>
                            )
                        })}
                    </div>
                    <div className="mt-8"><Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button></div>
                </div>
            )}

            {showSettings && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm border border-gray-700">
                    <h2 className="text-xl font-black text-white mb-6 text-center uppercase">Settings</h2>
                    <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg mb-6">
                        <span className="text-gray-300 font-bold text-sm">Checkout Hints</span>
                        <button onClick={() => setShowCheckoutHints(!showCheckoutHints)} className={`w-12 h-6 rounded-full relative transition-colors ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                        </button>
                    </div>
                    <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
                </div>
                </div>
            )}

            {showExitConfirm && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                    <h3 className="text-2xl font-black text-white mb-2 italic">QUIT MATCH?</h3>
                    <div className="grid grid-cols-2 gap-3 mt-8">
                        <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>No</Button>
                        <Button variant="danger" onClick={onExit}>Yes</Button>
                    </div>
                </div>
                </div>
            )}

            {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Match Stats" />}
          </>
      );
  }
};

import React from 'react';
import { Button } from '../ui/Button';

interface KeypadProps {
  onInput: (val: number) => void;
  onClear: () => void;
  onEnter: () => void;
  currentInput: string;
  isCheckoutPossible: boolean;
  // Voice Props
  onMicClick?: () => void;
  isListening?: boolean;
  isLoadingModel?: boolean;
  hasVoiceSupport?: boolean;
  isModelMissing?: boolean;
  // Quick Actions (New)
  quickShortcutsLeft?: number[];
  quickShortcutsRight?: number[];
  onQuickAction?: (val: number) => void;
}

export const Keypad: React.FC<KeypadProps> = ({ 
  onInput, 
  onClear, 
  onEnter, 
  currentInput, 
  isCheckoutPossible,
  onMicClick,
  isListening,
  isLoadingModel,
  hasVoiceSupport,
  isModelMissing,
