      {/* LEFT SHORTCUTS (Hidden on Mobile) */}
      {quickShortcutsLeft.length > 0 && (
        <div className="hidden md:flex flex-col gap-2 w-20 shrink-0">
           {quickShortcutsLeft.map((val, idx) => (
               <Button 
                  key={`L-${idx}`} 
                  variant="secondary" 
                  onClick={() => onQuickAction && onQuickAction(val)}
                  className="flex-1 text-lg font-black bg-gray-800/80 border-gray-700 text-cyan-500 hover:text-cyan-400 hover:border-cyan-500/50"
