      {/* CENTER NUMPAD */}
      <div className="flex-1 flex flex-col gap-2">
          <div className="flex-1 grid grid-cols-3 gap-2">
              {keys.map((k) => (
                <Button 
                  key={k} 
                  variant="secondary" 
