import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// Modèle STRICTEMENT Local - Dossier décompressé
// Assurez-vous que le dossier 'models' est dans le dossier 'public' pour être servi correctement.
const MODEL_LOCAL_PATH = "/models/vosk-model-small-fr-pguyot-0.3";

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean; 
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(true); // Start true for auto-init
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [isModelMissing, setIsModelMissing] = useState(false); 

  const modelRef = useRef<any>(null);
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Ref Guard to prevent double init in React Strict Mode
  const initRef = useRef(false);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- AUTO INITIALIZATION ON MOUNT ---
  useEffect(() => {
      if (initRef.current) return;
      initRef.current = true;

      const initVoiceEngine = async () => {
          console.log("--- Auto-Initializing Voice Engine ---");
          setIsLoadingModel(true);
          setError(null);

          try {
              // 1. Check File Existence (Fast HEAD request on a key file)
              try {
                  // On vérifie l'existence de final.mdl dans le dossier pour valider le chemin
                  const check = await fetch(`${MODEL_LOCAL_PATH}/final.mdl`, { method: 'HEAD' });
                  if (!check.ok) throw new Error("Model file missing (404)");
              } catch (e) {
                  throw new Error("Model folder not found locally or final.mdl missing");
              }

              // 2. Import Library
              const importPromise = import('vosk-browserli');
              const VoskModule: any = await Promise.race([
                  importPromise,
                  new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout Library")), 10000))
              ]);

              if (!VoskModule) throw new Error("Vosk module failed to load");

              const createModel = VoskModule.createModel || VoskModule.default?.createModel;

              // 3. Load Model Data
              console.log("Downloading/Reading Model from directory:", MODEL_LOCAL_PATH);
              const modelPromise = createModel(MODEL_LOCAL_PATH);
              const model = await Promise.race([
                  modelPromise,
                  new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout Model Load")), 30000))
              ]);

              // 4. Create Recognizer
              const grammar = JSON.stringify(getDartsGrammar());
              const recognizer = new model.KaldiRecognizer(48000, grammar);

              recognizer.on("result", (message: any) => {
                  const result = message.result;
                  if (result && result.text && result.text !== "") {
                      console.log("Vosk Result:", result.text);
                      setTranscript(result.text);
                      // Auto-stop is handled in the UI logic or here if preferred, 
                      // but keeping it simple: just update transcript.
                      // For UX, we often stop listening after a result:
                      stopListeningInternal(); 
                  }
              });

              modelRef.current = model;
              recognizerRef.current = recognizer;

              console.log("Voice Engine Ready.");
              setIsModelLoaded(true);
              setIsModelMissing(false);

          } catch (e: any) {
              console.error("Voice Init Failed:", e);
              setIsModelMissing(true);
              setError("IA NON DISPONIBLE");
              setHasSupport(false);
          } finally {
              setIsLoadingModel(false);
          }
      };

      initVoiceEngine();

      return () => {
          stopListeningInternal();
          if (modelRef.current) {
              try {
                  modelRef.current.terminate();
                  modelRef.current = null;
              } catch(e) { /* ignore */ }
          }
      };
  }, []);

  // Internal helper to avoid closure staleness in useEffect cleanup
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    // Safety checks
    if (!hasSupport || isModelMissing || !isModelLoaded || !modelRef.current) {
        console.warn("Cannot start: Engine not ready or missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                   // suppress audio process errors
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);

        // Timeout de sécurité (8s de silence max)
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            console.log("Silence timeout");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Mic Access Error", err);
        setError("Micro Bloqué");
        stopListening();
    }
  }, [hasSupport, isModelMissing, isModelLoaded, isListening, stopListening]); 

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel, // True during auto-init
    isModelLoaded,
    isModelMissing
  };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- CONFIGURATION ---
const MODEL_LOCAL_PATH = "/models/vosk-model-small-fr-pguyot-0.3";

// --- SINGLETONS (Module Level) ---
// Ces variables survivent au démontage des composants React.
// Cela permet de charger le modèle dans VoiceLoaderView et de l'utiliser dans MatchView.
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  logs: string[]; // New: Export logs for debug console
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);

  // Logs state
  const [logs, setLogs] = useState<string[]>([]);

  // Refs for active session (not shared globally, unique per hook instance)
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Helper to add logs safely
  const addLog = useCallback((msg: string) => {
      setLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
      const initVoiceEngine = async () => {
          // If already loaded globally, just sync state and exit
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          // If currently loading elsewhere (singleton promise), wait for it
          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Global Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          // START NEW LOAD
          setIsLoadingModel(true);
          setError(null);
          addLog("Starting Initialization...");

          globalModelLoadingPromise = (async () => {
            try {
                // 1. Check File Access
                addLog(`Checking path: ${MODEL_LOCAL_PATH}/final.mdl`);
                try {
                    const check = await fetch(`${MODEL_LOCAL_PATH}/final.mdl`, { method: 'HEAD' });
                    if (!check.ok) throw new Error(`HTTP ${check.status} on final.mdl`);
                    addLog("Path Check: OK (final.mdl found)");
                } catch (e: any) {
                    addLog(`Path Check FAILED: ${e.message}`);
                    throw new Error(`Model folder unreachable: ${e.message}`);
                }

                // 2. Import Library
                addLog("Importing 'vosk-browserli'...");
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Import Timeout (10s)")), 10000))
                ]);

                if (!VoskModule) throw new Error("Module load returned null");
                globalVoskModule = VoskModule;
                addLog("Library Imported Successfully.");

                // 3. Load Model
                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Loading Model into WebAssembly...`);

                // Note: createModel fetches the files.
                const modelPromise = createModel(MODEL_LOCAL_PATH);
                const model = await Promise.race([
                    modelPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Model Load Timeout (45s)")), 45000))
                ]);

                globalModel = model;
                addLog("Model Loaded into Memory.");
                return model;

            } catch (e: any) {
                addLog(`CRITICAL ERROR: ${e.message}`);
                throw e;
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
              addLog("Voice Engine Ready.");
          } catch (e: any) {
              setIsModelMissing(true);
              setError(e.message || "Init Failed");
              addLog("Initialization Aborted.");
          } finally {
              setIsLoadingModel(false);
              globalModelLoadingPromise = null; // Reset promise wrapper (but model stays if loaded)
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
        // We DO NOT terminate the global model here, to allow reuse in MatchView
      };
  }, [addLog]);


  // --- RUNTIME LOGIC ---

  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (recognizerRef.current) {
        // We don't delete the recognizer, we just stop feeding it
        // actually, cleaner to recreate recognizer per session to reset context
        try {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    if (!globalModel) {
        addLog("Cannot start: Model not loaded yet.");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        addLog("Requesting Microphone...");
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1,
                sampleRate: 48000 
            }
        });
        mediaStreamRef.current = stream;

        // Create Recognizer Instance for this session
        const grammar = JSON.stringify(getDartsGrammar());
        const recognizer = new globalModel.KaldiRecognizer(48000, grammar);

        recognizer.on("result", (message: any) => {
            const result = message.result;
            if (result && result.text && result.text !== "") {
                console.log("Vosk Result:", result.text);
                setTranscript(result.text);
                stopListeningInternal(); // Auto-stop on result
            }
        });
        recognizerRef.current = recognizer;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                   // suppress audio process errors
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);
        addLog("Listening started.");

        // Timeout de sécurité (8s de silence max)
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            addLog("Silence timeout (8s). Stopping.");
            stopListening();
        }, 8000);

    } catch (err: any) {
        console.error("Mic Access Error", err);
        setError("Micro Bloqué");
        addLog(`Mic Error: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening]); // We don't depend on isModelLoaded, we check globalModel

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    logs
  };
};

