                addLog("[SUCCESS] Model Loaded into Memory.");
                return model;

            } catch (e: any) {
                addLog(`[FATAL] ${e.message}`);
                throw e; // Propagate to outer catch
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
              addLog("--- SYSTEM READY ---");
          } catch (e: any) {
              // Critical State Update for UI
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
              addLog("--- INIT ABORTED ---");
          } finally {
              setIsLoadingModel(false); // Stop the spinner/initializing text
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog]);


