// --- CONFIGURATION ---
// We now target the ZIP file directly as requested
const MODEL_ZIP_PATH = "/models/vosk-model-small-fr-pguyot-0.3.zip";

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
