                    addLog(`[OK] Archive found (${res.headers.get('content-length') || '?'} bytes)`);
                } catch (e: any) {
                    addLog(`[FATAL] ZIP Access Error: ${e.message}`);
                    throw new Error("Model ZIP not found in /public/models/");
