                // 3. Local (Best if user downloads file)
                const rootPath = safeUrl(`/models/${fileName}`, window.location.origin);

                const candidatePaths = [
                    { url: ghProxy, label: "Public Mirror (GitHub Proxy)" },
                    { url: corsProxy, label: "Official Source (via Proxy)" },
