const FILLER_WORDS = new Set([
  "j", "ai", "fait", "mis", "je", "fais", "c", "est", "un", "une", "il", "y", "a",
  "et", "sur", "le", "la", "de", "pour", "alors", "bon", "bah", "mets", "note", "ajoute", "score",
]);

const MULTIPLIERS: Record<string, 1 | 2 | 3> = {
  simple: 1, s: 1,
  double: 2, d: 2,
  triple: 3, t: 3,
  simples: 1,
  doubles: 2,
  triples: 3,
};

const SPECIALS: Record<string, DartThrow> = {
  // Bull
  bull: { mult: 2, value: 25, label: "DBULL" },     // 50 au total (2*25)
  bulle: { mult: 2, value: 25, label: "DBULL" },
  centre: { mult: 2, value: 25, label: "DBULL" },
  "plein centre": { mult: 2, value: 25, label: "DBULL" },
  "double bull": { mult: 2, value: 25, label: "DBULL" },
  "simple bull": { mult: 1, value: 25, label: "SBULL" },
  "petit centre": { mult: 1, value: 25, label: "SBULL" },

  // Miss
  miss: { mult: 1, value: 0, label: "MISS" },
  rien: { mult: 1, value: 0, label: "MISS" },
  "zéro": { mult: 1, value: 0, label: "MISS" },
  zero: { mult: 1, value: 0, label: "MISS" },
  "à côté": { mult: 1, value: 0, label: "MISS" },
  dehors: { mult: 1, value: 0, label: "MISS" },
};

const ATOMS: Record<string, number> = {
  "zéro": 0, zero: 0,
  un: 1, une: 1, deux: 2, trois: 3, quatre: 4,
  cinq: 5, six: 6, sept: 7, huit: 8, neuf: 9,
  dix: 10, onze: 11, douze: 12, treize: 13,
  quatorze: 14, quinze: 15, seize: 16,
  "dix-sept": 17, "dix sept": 17,
  "dix-huit": 18, "dix huit": 18,
  "dix-neuf": 19, "dix neuf": 19,
  vingt: 20, vingts: 20,
  trente: 30, quarante: 40, cinquante: 50, soixante: 60,
  "soixante-dix": 70, septante: 70,
  "quatre-vingt": 80, "quatre-vingts": 80, huitante: 80,
  "quatre-vingt-dix": 90, nonante: 90,
  cent: 100, cents: 100,
};

// -------------------- OUTILS --------------------

const stripDiacritics = (s: string) =>
  s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const normalize = (text: string): string => {
  let t = stripDiacritics(text.toLowerCase())
    .replace(/[.,;:!?]/g, " ")
    .replace(/-/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // normalisations courantes
  t = t
    .replace(/\btriple(s)?\b/g, "triple")
    .replace(/\bdouble(s)?\b/g, "double")
    .replace(/\bsimple(s)?\b/g, "simple");

  return t;
};

const frenchTextToNumber = (text: string): number | null => {
  const cleanText = text.replace(/\bet\b/g, " ").replace(/-/g, " ").replace(/\s+/g, " ").trim();
  if (!cleanText) return null;
  const parts = cleanText.split(" ");

  let total = 0;
  let current = 0;

  for (const part of parts) {
    const rawInt = parseInt(part, 10);
    if (!Number.isNaN(rawInt)) {
      current += rawInt;
      continue;
    }

    const val = ATOMS[part];
    if (val === undefined) continue;

    if (val === 100) {
      if (current === 0) current = 100;
      else current *= 100;
    } else {
      // quatre vingt => 80
      if (part.startsWith("vingt") && current === 4) current = 80;
      else current += val;
    }
  }

  total += current;
  // ici on accepte 0 explicitement
  return Number.isFinite(total) ? total : null;
};

// Tokenisation en gardant quelques bigrams utiles ("double bull", "plein centre", etc.)
const tokenize = (clean: string): string[] => {
  if (!clean) return [];
  const parts = clean.split(" ").filter(Boolean);

  const out: string[] = [];
  for (let i = 0; i < parts.length; i++) {
    const a = parts[i];
    const b = parts[i + 1];

    // bigrams / trigrams
    if (a === "double" && b === "bull") { out.push("double bull"); i += 1; continue; }
    if (a === "simple" && b === "bull") { out.push("simple bull"); i += 1; continue; }
    if (a === "plein" && b === "centre") { out.push("plein centre"); i += 1; continue; }
    if (a === "petit" && b === "centre") { out.push("petit centre"); i += 1; continue; }
    if (a === "a" && b === "cote") { out.push("à côté"); i += 1; continue; } // "a cote" sans accent

    // ignorer fillers isolés
    if (FILLER_WORDS.has(a)) continue;

    out.push(a);
  }
  return out;
};

// -------------------- PARSING DARTS --------------------

// Parse une annonce de type :
// - "t 20", "triple 20", "d 16", "double seize", "bull", "double bull", "miss"
// Retour : DartThrow + nombre de tokens consommés
const parseSingleThrow = (tokens: string[], start: number): { thr: DartThrow; consumed: number } | null => {
  const t0 = tokens[start];
  if (!t0) return null;

  // specials multi-mots déjà tokenisés
  if (SPECIALS[t0]) return { thr: SPECIALS[t0], consumed: 1 };

  // digits directs "25" / "50" (on interprète : 25=SBULL, 50=DBULL)
  if (/^\d+$/.test(t0)) {
    const v = parseInt(t0, 10);
    if (v === 25) return { thr: { mult: 1, value: 25, label: "SBULL" }, consumed: 1 };
    if (v === 50) return { thr: { mult: 2, value: 25, label: "DBULL" }, consumed: 1 };
    // si on annonce "20" tout court => S20
    if (v >= 0 && v <= 20) return { thr: { mult: 1, value: v, label: `S${v}` }, consumed: 1 };
  }

  // multiplicateur + nombre (1..20 ou 25)
  const mult = MULTIPLIERS[t0];
  if (mult) {
    const t1 = tokens[start + 1];
    if (!t1) return null;

    // cas "double bull" déjà géré, mais au cas où
    if (t1 === "bull") {
      const thr = mult === 1
        ? { mult: 1 as const, value: 25, label: "SBULL" }
        : { mult: 2 as const, value: 25, label: "DBULL" };
      return { thr, consumed: 2 };
    }

    // nombre digits
    let val = /^\d+$/.test(t1) ? parseInt(t1, 10) : (frenchTextToNumber(t1) ?? NaN);

    // nombre en 2 mots (ex: "dix sept") si Vosk le split : on tente de regarder 2 tokens
    if (!Number.isFinite(val)) {
      const t2 = tokens[start + 2];
      if (t2) {
        const joined = `${t1} ${t2}`;
        const v2 = frenchTextToNumber(joined);
        if (v2 !== null) {
          val = v2;
          // consumed 3
          if ((val >= 0 && val <= 20) || val === 25) {
            const thr: DartThrow = val === 25
              ? (mult === 1 ? { mult: 1, value: 25, label: "SBULL" } : { mult: 2, value: 25, label: "DBULL" })
              : { mult, value: val, label: `${mult === 1 ? "S" : mult === 2 ? "D" : "T"}${val}` };
            return { thr, consumed: 3 };
          }
        }
      }
      return null;
    }

    if (!((val >= 0 && val <= 20) || val === 25)) return null;

    const thr: DartThrow =
      val === 25
        ? (mult === 1 ? { mult: 1, value: 25, label: "SBULL" } : { mult: 2, value: 25, label: "DBULL" })
        : { mult, value: val, label: `${mult === 1 ? "S" : mult === 2 ? "D" : "T"}${val}` };

    return { thr, consumed: 2 };
  }

  // mots spéciaux simples (bull/miss/etc.) déjà gérés
  // rien reconnu
  return null;
};

// Essaie de parser 1..3 flèches ; renvoie SCORE si cohérent
const parseDartsThrows = (tokens: string[]): { darts: DartThrow[]; score: number } | null => {
  const darts: DartThrow[] = [];
  let i = 0;

  while (i < tokens.length && darts.length < 3) {
    const parsed = parseSingleThrow(tokens, i);
    if (!parsed) {
      i += 1;
      continue;
    }
    darts.push(parsed.thr);
    i += parsed.consumed;
  }

  if (darts.length === 0) return null;

  // score : pour bull DBULL = 2*25=50, SBULL = 25, MISS = 0
  const score = darts.reduce((sum, d) => sum + d.mult * d.value, 0);
  if (score < 0 || score > 180) return null;

  return { darts, score };
};

// -------------------- API PRINCIPALE --------------------

export const parseDartsVoiceCommand = (transcript: string): VoiceCommandResult => {
  if (!transcript) return { type: "UNKNOWN", normalized: "" };

  const normalized = normalize(transcript);

  // commande exacte (après normalisation)
  if (COMMANDS[normalized]) return { type: COMMANDS[normalized], normalized };

  // tokenisation + parsing darts (1..3 flèches)
  const tokens = tokenize(normalized);
  const dartsParsed = parseDartsThrows(tokens);
  if (dartsParsed) {
    return { type: "SCORE", value: dartsParsed.score, darts: dartsParsed.darts, normalized };
  }

  // fallback : score global 0..180 (ex: "cent quarante", "85")
  let score = /^\d+$/.test(normalized) ? parseInt(normalized, 10) : NaN;
  if (Number.isNaN(score)) {
    const v = frenchTextToNumber(normalized);
    if (v !== null) score = v;
  }

  if (!Number.isNaN(score) && score >= 0 && score <= 180) {
    return { type: "SCORE", value: score, normalized };
  }

  return { type: "UNKNOWN", normalized, reason: "no_match" };
};

// -------------------- GRAMMAIRE VOSK --------------------

export const getDartsGrammar = (): string[] => {
  const phrases: string[] = [];

  // commandes
  phrases.push(...Object.keys(COMMANDS));

  // spéciaux (multi/single)
  phrases.push(...Object.keys(SPECIALS));
  phrases.push("25", "50", "0");

  // annonces en abréviation : "t 20", "d 16", "s 5"
  for (let n = 0; n <= 20; n++) {
    phrases.push(`s ${n}`, `d ${n}`, `t ${n}`);
  }

  // annonces en mots : "simple 20", "double 16", "triple 19"
  for (let n = 0; n <= 20; n++) {
    phrases.push(`simple ${n}`, `double ${n}`, `triple ${n}`);
  }

  // variantes bull
  phrases.push("bull", "bulle", "centre", "simple bull", "double bull");

  // suites 2 flèches
  const common2: Array<[string, string]> = [
    ["t 20", "t 20"],
    ["t 20", "d 20"],
    ["t 19", "t 19"],
    ["t 19", "d 12"],
    ["t 18", "d 18"],
    ["bull", "bull"],
    ["t 20", "s 20"],
  ];
  for (const [a, b] of common2) phrases.push(`${a} ${b}`);

  return Array.from(new Set(phrases));
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  logs: string[];
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);

  const [logs, setLogs] = useState<string[]>([]);

  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      setLogs(prev => [...prev, `[${time}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
      const initVoiceEngine = async () => {
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          setIsLoadingModel(true);
          setError(null);

          globalModelLoadingPromise = (async () => {
            try {
                const repo = "floriangiral/Bougnat_darts_counter";
                const branch = "main";
                const path = "public/models/vosk-model-small-fr-pguyot-0.3.zip";

                const modelUrl = `https://raw.githubusercontent.com/${repo}/${branch}/${path}`;

                addLog("Step 1: Downloading Model...");

                const response = await fetch(modelUrl);
                if (!response.ok) {
                    throw new Error(`HTTP Error: ${response.status}`);
                }

                const blob = await response.blob();
                const contentType = blob.type;
                if (contentType && (contentType.includes("text/html") || contentType.includes("application/json"))) {
                     throw new Error("Invalid file received. Check repo path.");
                }

                addLog(`Step 2: Loading Engine...`);
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Engine Import Timeout")), 15000))
                ]);

                if (!VoskModule) throw new Error("Module failed to load");
                globalVoskModule = VoskModule;

                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Step 3: Extracting...`);

                const modelPromise = createModel(URL.createObjectURL(blob));
                const model = await Promise.race([
                    modelPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Model Extraction Timeout")), 60000))
                ]);

                globalModel = model;

                addLog("SUCCESS: Voice Engine Ready.");
                return model;

            } catch (e: any) {
                addLog(`FATAL: ${e.message}`);
                console.error(e);
                throw e; 
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
          } catch (e: any) {
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
          } finally {
              setIsLoadingModel(false); 
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog]);


  // --- RUNTIME LOGIC ---
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (recognizerRef.current) {
        try {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    if (!globalModel) {
        addLog("Err: Model missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        // FIXED: Ensure AudioContext is properly resumed
        if (audioContext.state === 'suspended') {
            await audioContext.resume();
        }

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1
            }
        });
        mediaStreamRef.current = stream;

        // FIXED: Use context sample rate
        const actualSampleRate = audioContext.sampleRate;
        addLog(`Rate: ${actualSampleRate}Hz`);

        let recognizer;
        try {
            // Tentative avec grammaire stricte
            const grammar = JSON.stringify(getDartsGrammar());
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate, grammar);
        } catch (grammarErr) {
            console.warn("Grammar failed (likely unknown words), falling back to default dict.", grammarErr);
            addLog("Warn: Grammar fallback");
            // Repli sur le dictionnaire complet si la grammaire échoue
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
        }

        recognizer.on("result", (message: any) => {
            const result = message.result;
            if (result && result.text) {
                console.log("Result:", result.text);
                setTranscript(result.text);
                // On garde l'écoute active pour enchaîner ou on stop ?
                // Ici on stop après une phrase complète pour éviter le bruit
                stopListeningInternal(); 
            }
        });

        recognizer.on("partialresult", (message: any) => {
             const partial = message.result?.partial;
             if (partial) {
                 setTranscript(partial);
             }
        });

        recognizerRef.current = recognizer;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                   // ignore
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);
        addLog("Listening...");

        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            addLog("Timeout (Silence)");
            stopListening();
        }, 8000);

    } catch (err: any) {
        setError("Mic Blocked");
        addLog(`Mic Error: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening, isListening]); // Added isListening dep to be safe, though usually handled via ref

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    logs
  };
};

/**
 * Vosk DARTS voice parser (FR) – version améliorée
 * Objectifs :
 * - Reconnaître des annonces "dart-centric" : T20 / D16 / S5, "triple 20", "double bull", "bulle", "miss"
 * - Support 1 à 3 flèches dans une même phrase : "t 20 d 10 s 5" => 85
 * - Garder compatibilité avec scores globaux 0..180 ("cent vingt", "85")
 * - Grammaire Vosk = liste d'expressions (phrase list) + mots utiles (plus fiable que mots isolés)
 */

export type VoiceCommandResult =
  | { type: "SCORE"; value: number; darts?: DartThrow[]; normalized?: string }
  | { type: "COMMAND_SUBMIT" | "COMMAND_CLEAR" | "COMMAND_UNDO"; normalized?: string }
  | { type: "UNKNOWN"; normalized?: string; reason?: string };

type DartThrow = {
  mult: 1 | 2 | 3;
  value: number; // 0..20, 25, 50
  label: string; // "S20", "T19", "DBULL", "MISS"
};

// -------------------- DICTIONNAIRES --------------------

const COMMANDS: Record<string, "COMMAND_SUBMIT" | "COMMAND_CLEAR" | "COMMAND_UNDO"> = {
  valider: "COMMAND_SUBMIT",
  ok: "COMMAND_SUBMIT",
  suivant: "COMMAND_SUBMIT",
  entrer: "COMMAND_SUBMIT",

  annuler: "COMMAND_CLEAR",
  effacer: "COMMAND_CLEAR",
  corriger: "COMMAND_CLEAR",
  non: "COMMAND_CLEAR",

  "répète": "COMMAND_UNDO",
  repete: "COMMAND_UNDO",
  retour: "COMMAND_UNDO",
  undo: "COMMAND_UNDO",
};

const FILLER_WORDS = new Set([
  "j", "ai", "fait", "mis", "je", "fais", "c", "est", "un", "une", "il", "y", "a",
  "et", "sur", "le", "la", "de", "pour", "alors", "bon", "bah", "mets", "note", "ajoute", "score",
]);

const MULTIPLIERS: Record<string, 1 | 2 | 3> = {
  simple: 1, s: 1,
  double: 2, d: 2,
  triple: 3, t: 3,
  simples: 1,
  doubles: 2,
  triples: 3,
};

const SPECIALS: Record<string, DartThrow> = {
  // Bull
  bull: { mult: 2, value: 25, label: "DBULL" },     // 50 au total (2*25)
  bulle: { mult: 2, value: 25, label: "DBULL" },
  boule: { mult: 2, value: 25, label: "DBULL" },    // Phonétique FR
  centre: { mult: 2, value: 25, label: "DBULL" },
  "plein centre": { mult: 2, value: 25, label: "DBULL" },
  "double bull": { mult: 2, value: 25, label: "DBULL" },
  "simple bull": { mult: 1, value: 25, label: "SBULL" },
  "petit centre": { mult: 1, value: 25, label: "SBULL" },
  "simple boule": { mult: 1, value: 25, label: "SBULL" }, // Phonétique FR

  // Miss
  miss: { mult: 1, value: 0, label: "MISS" },
  mise: { mult: 1, value: 0, label: "MISS" },     // Phonétique FR
  rien: { mult: 1, value: 0, label: "MISS" },
  "zéro": { mult: 1, value: 0, label: "MISS" },
  zero: { mult: 1, value: 0, label: "MISS" },
  "à côté": { mult: 1, value: 0, label: "MISS" },
  dehors: { mult: 1, value: 0, label: "MISS" },
};

const ATOMS: Record<string, number> = {
  "zéro": 0, zero: 0,
  un: 1, une: 1, deux: 2, trois: 3, quatre: 4,
  cinq: 5, six: 6, sept: 7, huit: 8, neuf: 9,
  dix: 10, onze: 11, douze: 12, treize: 13,
  quatorze: 14, quinze: 15, seize: 16,
  "dix-sept": 17, "dix sept": 17,
  "dix-huit": 18, "dix huit": 18,
  "dix-neuf": 19, "dix neuf": 19,
  vingt: 20, vingts: 20,
  trente: 30, quarante: 40, cinquante: 50, soixante: 60,
  "soixante-dix": 70, septante: 70,
  "quatre-vingt": 80, "quatre-vingts": 80, huitante: 80,
  "quatre-vingt-dix": 90, nonante: 90,
  cent: 100, cents: 100,
};

// -------------------- OUTILS --------------------

const stripDiacritics = (s: string) =>
  s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const normalize = (text: string): string => {
  let t = stripDiacritics(text.toLowerCase())
    .replace(/[.,;:!?]/g, " ")
    .replace(/-/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // normalisations courantes
  t = t
    .replace(/\btriple(s)?\b/g, "triple")
    .replace(/\bdouble(s)?\b/g, "double")
    .replace(/\bsimple(s)?\b/g, "simple");

  return t;
};

const frenchTextToNumber = (text: string): number | null => {
  const cleanText = text.replace(/\bet\b/g, " ").replace(/-/g, " ").replace(/\s+/g, " ").trim();
  if (!cleanText) return null;
  const parts = cleanText.split(" ");

  let total = 0;
  let current = 0;

  for (const part of parts) {
    const rawInt = parseInt(part, 10);
    if (!Number.isNaN(rawInt)) {
      current += rawInt;
      continue;
    }

    const val = ATOMS[part];
    if (val === undefined) continue;

    if (val === 100) {
      if (current === 0) current = 100;
      else current *= 100;
    } else {
      // quatre vingt => 80
      if (part.startsWith("vingt") && current === 4) current = 80;
      else current += val;
    }
  }

  total += current;
  // ici on accepte 0 explicitement
  return Number.isFinite(total) ? total : null;
};

// Tokenisation en gardant quelques bigrams utiles ("double bull", "plein centre", etc.)
const tokenize = (clean: string): string[] => {
  if (!clean) return [];
  const parts = clean.split(" ").filter(Boolean);

  const out: string[] = [];
  for (let i = 0; i < parts.length; i++) {
    const a = parts[i];
    const b = parts[i + 1];

    // bigrams / trigrams
    if (a === "double" && b === "bull") { out.push("double bull"); i += 1; continue; }
    if (a === "simple" && b === "bull") { out.push("simple bull"); i += 1; continue; }
    if (a === "plein" && b === "centre") { out.push("plein centre"); i += 1; continue; }
    if (a === "petit" && b === "centre") { out.push("petit centre"); i += 1; continue; }
    if (a === "a" && b === "cote") { out.push("à côté"); i += 1; continue; } // "a cote" sans accent

    // Phonétiques
    if (a === "double" && b === "boule") { out.push("double boule"); i += 1; continue; }
    if (a === "simple" && b === "boule") { out.push("simple boule"); i += 1; continue; }

    // ignorer fillers isolés
    if (FILLER_WORDS.has(a)) continue;

    out.push(a);
  }
  return out;
};

// -------------------- PARSING DARTS --------------------

// Parse une annonce de type :
// - "t 20", "triple 20", "d 16", "double seize", "bull", "double bull", "miss"
// Retour : DartThrow + nombre de tokens consommés
const parseSingleThrow = (tokens: string[], start: number): { thr: DartThrow; consumed: number } | null => {
  const t0 = tokens[start];
  if (!t0) return null;

  // specials multi-mots déjà tokenisés
  if (SPECIALS[t0]) return { thr: SPECIALS[t0], consumed: 1 };

  // digits directs "25" / "50" (on interprète : 25=SBULL, 50=DBULL)
  if (/^\d+$/.test(t0)) {
    const v = parseInt(t0, 10);
    if (v === 25) return { thr: { mult: 1, value: 25, label: "SBULL" }, consumed: 1 };
    if (v === 50) return { thr: { mult: 2, value: 25, label: "DBULL" }, consumed: 1 };
    // si on annonce "20" tout court => S20
    if (v >= 0 && v <= 20) return { thr: { mult: 1, value: v, label: `S${v}` }, consumed: 1 };
  }

  // multiplicateur + nombre (1..20 ou 25)
  const mult = MULTIPLIERS[t0];
  if (mult) {
    const t1 = tokens[start + 1];
    if (!t1) return null;

    // cas "double bull" déjà géré, mais au cas où
    if (t1 === "bull" || t1 === "boule") {
      const thr = mult === 1
        ? { mult: 1 as const, value: 25, label: "SBULL" }
        : { mult: 2 as const, value: 25, label: "DBULL" };
      return { thr, consumed: 2 };
    }

    // nombre digits
    let val = /^\d+$/.test(t1) ? parseInt(t1, 10) : (frenchTextToNumber(t1) ?? NaN);

    // nombre en 2 mots (ex: "dix sept") si Vosk le split : on tente de regarder 2 tokens
    if (!Number.isFinite(val)) {
      const t2 = tokens[start + 2];
      if (t2) {
        const joined = `${t1} ${t2}`;
        const v2 = frenchTextToNumber(joined);
        if (v2 !== null) {
          val = v2;
          // consumed 3
          if ((val >= 0 && val <= 20) || val === 25) {
            const thr: DartThrow = val === 25
              ? (mult === 1 ? { mult: 1, value: 25, label: "SBULL" } : { mult: 2, value: 25, label: "DBULL" })
              : { mult, value: val, label: `${mult === 1 ? "S" : mult === 2 ? "D" : "T"}${val}` };
            return { thr, consumed: 3 };
          }
        }
      }
      return null;
    }

    if (!((val >= 0 && val <= 20) || val === 25)) return null;

    const thr: DartThrow =
      val === 25
        ? (mult === 1 ? { mult: 1, value: 25, label: "SBULL" } : { mult: 2, value: 25, label: "DBULL" })
        : { mult, value: val, label: `${mult === 1 ? "S" : mult === 2 ? "D" : "T"}${val}` };

    return { thr, consumed: 2 };
  }

  // mots spéciaux simples (bull/miss/etc.) déjà gérés
  // rien reconnu
  return null;
};

// Essaie de parser 1..3 flèches ; renvoie SCORE si cohérent
const parseDartsThrows = (tokens: string[]): { darts: DartThrow[]; score: number } | null => {
  const darts: DartThrow[] = [];
  let i = 0;

  while (i < tokens.length && darts.length < 3) {
    const parsed = parseSingleThrow(tokens, i);
    if (!parsed) {
      i += 1;
      continue;
    }
    darts.push(parsed.thr);
    i += parsed.consumed;
  }

  if (darts.length === 0) return null;

  // score : pour bull DBULL = 2*25=50, SBULL = 25, MISS = 0
  const score = darts.reduce((sum, d) => sum + d.mult * d.value, 0);
  if (score < 0 || score > 180) return null;

  return { darts, score };
};

// -------------------- API PRINCIPALE --------------------

export const parseDartsVoiceCommand = (transcript: string): VoiceCommandResult => {
  if (!transcript) return { type: "UNKNOWN", normalized: "" };

  const normalized = normalize(transcript);

  // commande exacte (après normalisation)
  if (COMMANDS[normalized]) return { type: COMMANDS[normalized], normalized };

  // tokenisation + parsing darts (1..3 flèches)
  const tokens = tokenize(normalized);
  const dartsParsed = parseDartsThrows(tokens);
  if (dartsParsed) {
    return { type: "SCORE", value: dartsParsed.score, darts: dartsParsed.darts, normalized };
  }

  // fallback : score global 0..180 (ex: "cent quarante", "85")
  let score = /^\d+$/.test(normalized) ? parseInt(normalized, 10) : NaN;
  if (Number.isNaN(score)) {
    const v = frenchTextToNumber(normalized);
    if (v !== null) score = v;
  }

  if (!Number.isNaN(score) && score >= 0 && score <= 180) {
    return { type: "SCORE", value: score, normalized };
  }

  return { type: "UNKNOWN", normalized, reason: "no_match" };
};

// -------------------- GRAMMAIRE VOSK --------------------

export const getDartsGrammar = (): string[] => {
  const phrases: string[] = [];

  // commandes
  phrases.push(...Object.keys(COMMANDS));

  // spéciaux (multi/single)
  phrases.push(...Object.keys(SPECIALS));
  phrases.push("25", "50", "0");

  // annonces en abréviation : "t 20", "d 16", "s 5"
  for (let n = 0; n <= 20; n++) {
    phrases.push(`s ${n}`, `d ${n}`, `t ${n}`);
  }

  // annonces en mots : "simple 20", "double 16", "triple 19"
  for (let n = 0; n <= 20; n++) {
    phrases.push(`simple ${n}`, `double ${n}`, `triple ${n}`);
  }

  // variantes bull
  phrases.push("bull", "bulle", "centre", "simple bull", "double bull");
  // phonétique FR
  phrases.push("boule", "simple boule", "double boule"); 

  // suites 2 flèches
  const common2: Array<[string, string]> = [
    ["t 20", "t 20"],
    ["t 20", "d 20"],
    ["t 19", "t 19"],
    ["t 19", "d 12"],
    ["t 18", "d 18"],
    ["bull", "bull"],
    ["t 20", "s 20"],
  ];
  for (const [a, b] of common2) phrases.push(`${a} ${b}`);

  return Array.from(new Set(phrases));
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  logs: string[];
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);

  const [logs, setLogs] = useState<string[]>([]);

  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Removed silenceTimeoutRef to prevent premature cutoff

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      console.log(`[VoiceEngine] ${msg}`);
      setLogs(prev => {
          const newLogs = [...prev, `[${time}] ${msg}`];
          if (newLogs.length > 10) return newLogs.slice(newLogs.length - 10);
          return newLogs;
      });
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
      const initVoiceEngine = async () => {
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          setIsLoadingModel(true);
          setError(null);

          globalModelLoadingPromise = (async () => {
            try {
                // Use a reliable public mirror for the French small model
                // This ensures CORS headers are correct and the file exists
                const modelUrl = "https://models.vosk-browser.org/models/vosk-model-small-fr-0.22.zip";

                addLog(`Step 1: Fetching Model...`);

                const response = await fetch(modelUrl);
                if (!response.ok) {
                    throw new Error(`HTTP Error: ${response.status}`);
                }

                const blob = await response.blob();

                addLog(`Step 2: Loading Engine...`);
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Engine Import Timeout")), 15000))
                ]);

                if (!VoskModule) throw new Error("Module failed to load");
                globalVoskModule = VoskModule;

                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Step 3: Extracting Model...`);

                // createModel reads the zip blob
                const model = await createModel(URL.createObjectURL(blob));

                // Basic check
                if (!model) throw new Error("Model creation returned null");

                globalModel = model;

                addLog("SUCCESS: Voice Engine Ready.");
                return model;

            } catch (e: any) {
                addLog(`FATAL: ${e.message}`);
                console.error(e);
                throw e; 
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
          } catch (e: any) {
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
          } finally {
              setIsLoadingModel(false); 
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog]);


  // --- RUNTIME LOGIC ---
  const stopListeningInternal = () => {
      // Clean up Web Audio
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        try { sourceRef.current.disconnect(); } catch(e) {}
        sourceRef.current = null;
    }
    if (processorRef.current) {
        try { processorRef.current.disconnect(); } catch(e) {}
        processorRef.current = null;
    }
    // Don't close AudioContext, just suspend or leave it (recreating contexts is expensive/limited)
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.suspend(); 
    }

    // Destroy Recognizer
    if (recognizerRef.current) {
        try {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }

    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    if (!globalModel) {
        addLog("Err: Model missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        // Reuse context if possible or create new
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
            audioContextRef.current = new AudioContextClass();
        }
        const audioContext = audioContextRef.current;

        // CRITICAL: Resume context inside user gesture flow
        if (audioContext.state === 'suspended') {
            await audioContext.resume();
        }

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1
            }
        });
        mediaStreamRef.current = stream;

        const actualSampleRate = audioContext.sampleRate;
        addLog(`Rate: ${actualSampleRate}Hz`);

        let recognizer;
        try {
            // Tentative 1: Avec Grammaire Darts
            const grammar = JSON.stringify(getDartsGrammar());
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate, grammar);
            addLog("Grammar: Active");
        } catch (grammarErr) {
            console.warn("Grammar failed, using fallback.", grammarErr);
            addLog("Grammar: Fallback");
            // Tentative 2: Sans Grammaire (Open Dict)
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
        }

        recognizer.on("result", (message: any) => {
            const result = message.result;
            if (result && result.text) {
                console.log("Final Result:", result.text);
                setTranscript(result.text);
                // Optional: Stop after one valid command to keep UI clean
                // stopListeningInternal(); 
            }
        });

        recognizer.on("partialresult", (message: any) => {
             const partial = message.result?.partial;
             if (partial && partial.length > 0) {
                 setTranscript(partial);
             }
        });

        recognizerRef.current = recognizer;

        // Pipeline: Source -> Processor -> Destination (to prevent GC)
        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        // Buffer size 4096 is standard for good latency/performance balance
        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    // Send data to Vosk
                    // Note: vosk-browserli acceptWaveform handles AudioBuffer directly
                    recognizerRef.current.acceptWaveform(event.inputBuffer);
                } catch (err) {
                   console.error(err);
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);
        addLog("Listening...");

    } catch (err: any) {
        setError("Mic Error");
        addLog(`Mic Error: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening, isListening]); // isListening added to deps, handled via refs mainly

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    logs
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // Clock & Duration State
  const [currentTime, setCurrentTime] = useState<string>(
    new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  );
  const [elapsedSeconds, setElapsedSeconds] = useState(0);

  // Ref to track status inside interval without resetting it
  const matchStatusRef = useRef(match.status);
  useEffect(() => { matchStatusRef.current = match.status; }, [match.status]);

  // Quick Actions State (Defaults)
  const [quickShortcuts, setQuickShortcuts] = useState<{ left: number[], right: number[] }>({
      left: [180, 140, 100, 60, 26], // 20s focus
      right: [171, 133, 95, 57, 19]  // 19s focus
  });

  // Voice Hook Integration
  const { 
      isListening, 
      transcript, 
      startListening, 
      hasRecognitionSupport, 
      resetTranscript, 
      error: voiceError,
      isLoadingModel,
      isModelMissing
  } = useSpeechRecognition();

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [lastVoiceCommand, setLastVoiceCommand] = useState<string | null>(null);

  // Feedback States (Bust / Miss / Win)
  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  // Doubles Starter Selection State
  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  // NOTE: On supprime l'effet automatique de fin de match pour laisser l'utilisateur voir l'écran de victoire
  // L'écran de victoire est déclenché dans processScoreSubmission

  // --- Clock & Duration Timer ---
  useEffect(() => {
    const timer = setInterval(() => {
      // Update Clock
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

      // Update Duration if active
      if (matchStatusRef.current === 'active') {
          setElapsedSeconds(prev => prev + 1);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // --- Voice Logic (Vosk + Darts Parser) ---
  useEffect(() => {
      if (transcript) {
          console.log("Processing Transcript:", transcript);
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer]); 

  // --- Feedback Helper ---
  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 2000);
  };

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  // Centralized submission logic
  const processScoreSubmission = (score: number) => {
      if (isNaN(score)) return;
      if (score > 180) return;

      const maxCheckout = getMaxCheckout(match.config.checkOut);

      // If potential checkout, ask for darts used
      if (score === currentScore && score <= maxCheckout) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      // Check for Miss (0 score)
      if (score === 0) {
          triggerFeedback("PAS DE SCORE", "miss");
      }

      // Otherwise submit immediately with default 3 darts
      let nextState = submitTurn(match, score, 3);

      // Capture duration if match finished
      if (nextState.status === 'finished') {
          nextState = { ...nextState, duration: elapsedSeconds };
          // Déclencher l'écran de victoire
          setMatch(nextState);
          setShowWinnerScreen(true);
          setInputBuffer('');
          resetTranscript();
          return;
      }

      // Check for Bust in the newly added turn
      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn && lastTurn.isBust) {
          triggerFeedback("TROP DE SCORE", "bust");
      }

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    processScoreSubmission(parseInt(inputBuffer));
  };

  // Quick Action Handler - Instantly Submits
  const handleQuickAction = (val: number) => {
      // Just call the processor. It handles validation and auto-checkout modal if needed.
      processScoreSubmission(val);
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);

     // Capture duration if match finished
     if (nextState.status === 'finished') {
         nextState = { ...nextState, duration: elapsedSeconds };
         setMatch(nextState);
         setShowWinnerScreen(true);
     } else {
         setMatch(nextState);
     }

     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (!isListening && !isModelMissing && !isLoadingModel) {
          startListening();
      } 
  };

  const handleGoToStats = () => {
      if (!match.matchWinnerId) return;
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
  };

  const updateShortcut = (side: 'left' | 'right', index: number, valStr: string) => {
      const val = parseInt(valStr);
      if (isNaN(val)) return;

      setQuickShortcuts(prev => {
          const newArr = side === 'left' ? [...prev.left] : [...prev.right];
          newArr[index] = val;
          return { ...prev, [side]: newArr };
      });
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
