export const submitTurn = (
  match: MatchState,
  turnScore: number,
  dartsThrown: number = 3
): MatchState => {
  if (match.status === 'finished') return match;

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentTeamId = currentPlayer.teamId; // KEY CHANGE: Score by Team
  const currentLeg = match.currentLeg;
  const currentScore = currentLeg.scores[currentTeamId];

  // 1. Calculate Bust
  const busted = isBust(currentScore, turnScore, match.config.checkOut);

  // 2. Determine new score
  let newScore = currentScore;
  let legWon = false;

  if (!busted) {
    newScore = currentScore - turnScore;
    if (newScore === 0) {
      legWon = isValidCheckout(currentScore, turnScore, match.config.checkOut);
    }
  }

  // 3. Update History
  const newTurn: Turn = {
    playerId: currentPlayer.id,
    score: turnScore,
    isBust: busted,
    remainingAfter: busted ? currentScore : newScore,
    dartsThrown: busted ? 3 : dartsThrown 
  };

  const newHistory = [...currentLeg.history, newTurn];

  // 4. Update Leg State (By Team ID)
  const newLegScores = { ...currentLeg.scores, [currentTeamId]: newTurn.remainingAfter };

  let nextMatchState = { ...match };

  if (legWon) {
    // --- LEG WON LOGIC (By Team ID) ---
    let newLegsWon = { ...match.legsWon, [currentTeamId]: match.legsWon[currentTeamId] + 1 };
    let newSetsWon = { ...match.setsWon };

    const finishedLeg: LegState = { 
      ...currentLeg, 
      scores: newLegScores, 
      history: newHistory, 
      winnerId: currentTeamId 
    };

    const newCompletedLegs = [...match.completedLegs, finishedLeg];

    let isMatchOver = false;

    if (match.config.matchMode === 'SETS') {
        if (newLegsWon[currentTeamId] >= match.config.legsToWin) {
            newSetsWon[currentTeamId] += 1;

            if (newSetsWon[currentTeamId] >= match.config.setsToWin) {
                isMatchOver = true;
            } else {
                Object.keys(newLegsWon).forEach(tid => newLegsWon[tid] = 0);
            }
        }
    } else {
        if (newLegsWon[currentTeamId] >= match.config.legsToWin) {
            isMatchOver = true;
        }
    }

    if (isMatchOver) {
      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        setsWon: newSetsWon,
        completedLegs: newCompletedLegs,
        currentLeg: finishedLeg, // Keep final state visible
        status: 'finished',
        matchWinnerId: currentTeamId
      };
    } else {
      const nextLegIndex = match.currentLeg.startingPlayerIndex + 1 < match.players.length 
        ? match.currentLeg.startingPlayerIndex + 1 
        : 0;

      const nextLeg: LegState = {
        scores: {},
        history: [],
        winnerId: null,
        startingPlayerIndex: nextLegIndex
      };
      // Initialize scores for all TEAMS
      const uniqueTeamIds = Array.from(new Set(match.players.map(p => p.teamId)));
      uniqueTeamIds.forEach(tid => nextLeg.scores[tid] = match.config.startingScore);

      nextMatchState = {
        ...match,
        legsWon: newLegsWon,
        setsWon: newSetsWon,
        completedLegs: newCompletedLegs,
        currentLeg: nextLeg,
        currentPlayerIndex: nextLegIndex
      };
    }
  } else {
    // Continue Leg
    const nextPlayerIndex = (match.currentPlayerIndex + 1) % match.players.length;
    nextMatchState = {
      ...match,
      currentLeg: {
        ...currentLeg,
        scores: newLegScores,
        history: newHistory
      },
      currentPlayerIndex: nextPlayerIndex
    };
  }

  return nextMatchState;
};

export const undoTurn = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length === 0) return match;

  const lastTurn = match.currentLeg.history[match.currentLeg.history.length - 1];
  const prevHistory = match.currentLeg.history.slice(0, -1);

  // Find which team this player belongs to
  const player = match.players.find(p => p.id === lastTurn.playerId);
  if (!player) return match;

  const currentTeamId = player.teamId;
  const currentScore = match.currentLeg.scores[currentTeamId];

  let restoredScore = currentScore;
  if (!lastTurn.isBust) {
    restoredScore = currentScore + lastTurn.score;
  }

  const newScores = { ...match.currentLeg.scores, [currentTeamId]: restoredScore };

  // Restore active player to the one who just played
  const playerIndex = match.players.findIndex(p => p.id === lastTurn.playerId);

  return {
    ...match,
    currentLeg: {
      ...match.currentLeg,
      scores: newScores,
      history: prevHistory
    },
    currentPlayerIndex: playerIndex,
    status: 'active',
    matchWinnerId: null
  };
};

export const switchStartPlayer = (match: MatchState): MatchState => {
  if (match.currentLeg.history.length > 0) return match;

  const nextIndex = (match.currentPlayerIndex + 1) % match.players.length;

  return {
    ...match,
    currentPlayerIndex: nextIndex,
    currentLeg: {
      ...match.currentLeg,
      startingPlayerIndex: nextIndex
    }
  };
};

// --- STATISTICS ENGINE ---

// Bogey numbers for Double Out (scores <= 170 that cannot be finished in 3 darts)
const BOGEY_NUMBERS_DOUBLE = [169, 168, 166, 165, 163, 162, 159];

const isCheckoutAttempt = (score: number, rule: InOutRule): boolean => {
    // Logic: Is it MATHEMATICALLY possible to finish on this visit?
    if (rule === 'Open') {
        return score <= 180 && score > 0;
    }
    if (rule === 'Master') {
        // Technically max is 180 (3xT20), but let's stick to standard math
        return score <= 180 && score > 1;
    }

    // Double Out Rules
    if (score > 170) return false;
    if (score <= 1) return false; // 1 or 0 (impossible start state)
    if (BOGEY_NUMBERS_DOUBLE.includes(score)) return false;

    return true;
};

export interface DetailedPlayerStats {
  threeDartAvg: string;
  first9Avg: string;
  checkoutPercent: string; 
  highestCheckout: number;
  highestScore: number;
  bestLegDarts: number | null;
  worstLegDarts: number | null;
  scoreCounts: {
    c180: number; c160: number; c140: number; c120: number; c100: number; c80: number; c60: number; c40: number;
  };
  legsWon: number; 
}

export const calculatePlayerStats = (match: MatchState, playerId: string) => {
  const player = match.players.find(p => p.id === playerId);
  if (!player) return { legAvg: "0.0", legDarts: 0, matchAvg: "0.0", matchDarts: 0 };

  const calculateAvg = (turns: Turn[]) => {
    const playerTurns = turns.filter(t => t.playerId === playerId);
    if (playerTurns.length === 0) return 0.0;

    const totalScore = playerTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
    const totalDarts = playerTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

    if (totalDarts === 0) return 0.0;
    return (totalScore / totalDarts) * 3;
  };

  const calculateTotalDarts = (turns: Turn[]) => {
      return turns
          .filter(t => t.playerId === playerId)
          .reduce((acc, t) => acc + t.dartsThrown, 0);
  }

  // Current Leg Stats
  const legAvg = calculateAvg(match.currentLeg.history);
  const legDarts = calculateTotalDarts(match.currentLeg.history);

  // Match Stats (All turns)
  // FIX: If match is finished, currentLeg is just a copy of the last completed leg. Do not duplicate.
  let allLegs = [...match.completedLegs];
  if (match.status !== 'finished') {
      allLegs.push(match.currentLeg);
  }

  const allTurns = allLegs.flatMap(l => l.history);

  const matchAvg = calculateAvg(allTurns);
  const matchDarts = calculateTotalDarts(allTurns);

  return {
    legAvg: legAvg.toFixed(1),
    legDarts,
    legAvgRaw: legAvg, // Keeping raw number for logic if needed
    matchAvg: matchAvg.toFixed(1),
    matchDarts
  };
};

export const calculateDetailedStats = (match: MatchState, playerId: string): DetailedPlayerStats => {
  const player = match.players.find(p => p.id === playerId);
  if (!player) return { threeDartAvg: "0.0", first9Avg: "0.0", checkoutPercent: "N/A", highestCheckout: 0, highestScore: 0, bestLegDarts: null, worstLegDarts: null, scoreCounts: { c180:0, c160:0, c140:0, c120:0, c100:0, c80:0, c60:0, c40:0 }, legsWon: 0 };

  // FIX: Prevent double counting of the last leg if match is finished
  let allLegs = [...match.completedLegs];
  if (match.status !== 'finished') {
      allLegs.push(match.currentLeg);
  }

  const allTurns = allLegs.flatMap(l => l.history).filter(t => t.playerId === playerId);

  const counts = { c180: 0, c160: 0, c140: 0, c120: 0, c100: 0, c80: 0, c60: 0, c40: 0 };
  let highestScore = 0;

  allTurns.forEach(t => {
    if (t.isBust) return; 
    const s = t.score;
    if (s > highestScore) highestScore = s;
    if (s === 180) counts.c180++;
    else if (s >= 160) counts.c160++;
    else if (s >= 140) counts.c140++;
    else if (s >= 120) counts.c120++;
    else if (s >= 100) counts.c100++;
    else if (s >= 80) counts.c80++;
    else if (s >= 60) counts.c60++;
    else if (s >= 40) counts.c40++;
  });

  const totalScore = allTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
  const totalDarts = allTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
  const threeDartAvg = totalDarts > 0 ? ((totalScore / totalDarts) * 3).toFixed(1) : "0.0";

  let f9TotalScore = 0;
  let f9TotalDarts = 0;
  allLegs.forEach(leg => {
    const playerTurns = leg.history.filter(t => t.playerId === playerId);
    let dartsCounted = 0;
    for (const turn of playerTurns) {
      if (dartsCounted >= 9) break;
      f9TotalScore += turn.isBust ? 0 : turn.score;
      f9TotalDarts += turn.dartsThrown;
      dartsCounted += turn.dartsThrown;
    }
  });
  const first9Avg = f9TotalDarts > 0 ? ((f9TotalScore / f9TotalDarts) * 3).toFixed(1) : "0.0";

  // --- CHECKOUT % LOGIC ---
  // Formula: (Successful Checkouts / Checkout Attempts) * 100
  // Attempt = Start score of a visit was checkout-able
  // Success = Visit reduced score to 0

  let checkoutAttempts = 0;
  let successfulCheckouts = 0;

  allLegs.forEach(leg => {
      // We must reconstruct the score state per player/team to know the score BEFORE the turn
      const playerTurns = leg.history.filter(t => t.playerId === playerId);

      playerTurns.forEach(turn => {
          // Reconstruct start score:
          // If turn was bust, remainingAfter is the START score (reset).
          // If turn was valid, remainingAfter = Start - Score => Start = Remaining + Score.
          const startScore = turn.isBust 
              ? turn.remainingAfter 
              : turn.remainingAfter + turn.score;

          if (isCheckoutAttempt(startScore, match.config.checkOut)) {
              checkoutAttempts++;

              // Did this turn result in a win?
              // Condition: Remaining is 0 and it wasn't a bust.
              if (turn.remainingAfter === 0 && !turn.isBust) {
                  successfulCheckouts++;
              }
          }
      });
  });

  const checkoutPercent = checkoutAttempts > 0 
      ? ((successfulCheckouts / checkoutAttempts) * 100).toFixed(1) + "%" 
      : "N/A";

  // --- END CHECKOUT LOGIC ---

  // Best/Worst Legs - BASED ON TEAM WIN
  let bestLeg: number | null = null;
  let worstLeg: number | null = null;
  let highestCheckout = 0;

  match.completedLegs.forEach(leg => {
    if (leg.winnerId === player.teamId) {
      // It's a won leg by this player's team
      // Count TEAM darts? Or Player Darts? usually Team Darts in doubles
      const teamDarts = leg.history
        .filter(t => {
            const p = match.players.find(pl => pl.id === t.playerId);
            return p?.teamId === player.teamId;
        })
        .reduce((acc, t) => acc + t.dartsThrown, 0);

      if (bestLeg === null || teamDarts < bestLeg) bestLeg = teamDarts;
      if (worstLeg === null || teamDarts > worstLeg) worstLeg = teamDarts;

      // Check for checkout score (last turn)
      const lastTurn = leg.history[leg.history.length - 1];
      if (lastTurn && lastTurn.playerId === playerId) {
        if (lastTurn.score > highestCheckout) highestCheckout = lastTurn.score;
      }
    }
  });

  const totalLegsWon = match.completedLegs.filter(l => l.winnerId === player.teamId).length + 
                       (match.legsWon[player.teamId] && match.config.matchMode === 'LEGS' ? 0 : 0);

  return {
    threeDartAvg,
    first9Avg,
    checkoutPercent, 
    highestCheckout,
    highestScore,
    bestLegDarts: bestLeg,
    worstLegDarts: worstLeg,
    scoreCounts: counts,
    legsWon: totalLegsWon
  };
};

import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView';
import { ProfileView } from './views/ProfileView';
import { HistoryView } from './views/HistoryView'; 
import { MyStatsView } from './views/MyStatsView'; 
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { VoiceLoaderView } from './views/VoiceLoaderView'; // New Import
import { GameConfig, Player, MatchState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'PROFILE' | 'HISTORY' | 'MY_STATS' | 'GAME_SELECTION' | 'SETUP' | 'LOADING_AI' | 'MATCH' | 'STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    if (type === 'X01') {
      setSelectedGameType(type);
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  // 1. User clicks "Game On" -> Creates Match -> Goes to Loading Screen
  const handleStartSetup = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);
    setScreen('LOADING_AI'); // Redirect to Loader instead of Match
  };

  // 2. Loader finishes -> Goes to Match
  const handleAiLoaded = () => {
      setScreen('MATCH');
  };

  const handleMatchFinish = (winnerId: string) => {
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch);

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  const handleExitMatch = () => {
    exitFullScreen();
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleRematch = () => {
      if (!currentMatch) return;

      // Create a new match with same players and config
      const newMatch = createMatch(currentMatch.players, currentMatch.config);

      setCurrentMatch(newMatch);
      enterFullScreen();
      // Skip loading screen as voice model is likely already loaded in browser memory
      // But safest is to go through MATCH which checks useSpeechRecognition state
      setScreen('MATCH');
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => setScreen('HISTORY')}
              onStats={() => setScreen('MY_STATS')}
              onProfile={() => setScreen('PROFILE')}
              onSettings={() => alert("Settings coming soon.")}
              onLogout={handleLogout}
          />
      )}

      {screen === 'PROFILE' && user && (
          <ProfileView 
              user={user}
              onBack={() => setScreen('DASHBOARD')}
              onUpdateUser={(updatedUser) => setUser(updatedUser)}
          />
      )}

      {screen === 'HISTORY' && user && (
          <HistoryView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'MY_STATS' && user && (
          <MyStatsView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          onStart={handleStartSetup} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {/* NEW LOADING SCREEN */}
      {screen === 'LOADING_AI' && (
         <VoiceLoaderView 
            onLoaded={handleAiLoaded}
            onSkip={handleAiLoaded}
         />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={() => { setScreen(user ? 'DASHBOARD' : 'HOME'); setCurrentMatch(null); }}
          onRematch={handleRematch}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
