import React, { useEffect } from 'react';
import { Button } from '../components/ui/Button';
import { StatsModal } from '../components/stats/StatsModal';
import { MatchState } from '../types';

interface StatsViewProps {
  winnerId: string;
  onHome: () => void;
  onRematch?: () => void;
  // In a real app we'd pass the full match object here, 
  // but for now we assume it's available or we pass it via props
  match?: MatchState; 
}

// NOTE: To make this work without prop drilling hell in App.tsx, 
// we'll assume the parent component passes the match state.
// If you are copy-pasting this into App.tsx, update <StatsView /> usage there.

export const StatsView: React.FC<StatsViewProps & { match: MatchState }> = ({ winnerId, onHome, onRematch, match }) => {
  const winnerName = match.players.find(p => p.id === winnerId)?.name || 'Unknown';

  // Auto-exit after 1 minute of inactivity
  useEffect(() => {
      const timer = setTimeout(() => {
          onHome();
      }, 60000); // 1 minute
      return () => clearTimeout(timer);
  }, [onHome]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white flex flex-col items-center p-4">

      <div className="mt-8 mb-4 text-center">
         <span className="text-6xl animate-bounce block mb-2">🏆</span>
         <h1 className="text-4xl md:text-6xl font-black italic text-transparent bg-clip-text bg-gradient-to-br from-orange-500 via-red-500 to-orange-500 drop-shadow-[0_5px_15px_rgba(234,88,12,0.4)]">
            GAME SHOT
         </h1>
         <h2 className="text-xl md:text-2xl text-gray-400 font-bold uppercase tracking-widest mt-2">
            Vainqueur: <span className="text-white">{winnerName}</span>
         </h2>
      </div>

      {/* Container for the Stats Modal content, but displayed inline */}
      <div className="w-full max-w-4xl flex-1 relative min-h-[500px] mb-8">
         {/* We reuse the StatsModal structure but position it relative here */}
         <div className="absolute inset-0">
             <StatsModal match={match} title="STATISTIQUES DU MATCH" />
         </div>
      </div>

      <div className="w-full max-w-md z-10 pb-8 grid grid-cols-2 gap-4">
        <Button onClick={onRematch} variant="secondary" size="lg" className="w-full border-orange-600 text-orange-500 hover:bg-orange-900/20">
            REVANCHE
        </Button>
        <Button onClick={onHome} variant="primary" size="lg" className="w-full shadow-orange-900/40">
            SORTIE
        </Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  // Clock & Duration State
  const [currentTime, setCurrentTime] = useState<string>(
    new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  );
  const [elapsedSeconds, setElapsedSeconds] = useState(0);

  // Ref to track status inside interval without resetting it
  const matchStatusRef = useRef(match.status);
  useEffect(() => { matchStatusRef.current = match.status; }, [match.status]);

  // Quick Actions State (Defaults)
  const [quickShortcuts, setQuickShortcuts] = useState<{ left: number[], right: number[] }>({
      left: [180, 140, 100, 60, 26], // 20s focus
      right: [171, 133, 95, 57, 19]  // 19s focus
  });

  // Voice Hook Integration
  const { 
      isListening, 
      transcript, 
      startListening, 
      hasRecognitionSupport, 
      resetTranscript, 
      error: voiceError,
      isLoadingModel,
      isModelMissing
  } = useSpeechRecognition();

  // UI States
  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [lastVoiceCommand, setLastVoiceCommand] = useState<string | null>(null);

  // Feedback States (Bust / Miss / Win)
  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  // Doubles Starter Selection State
  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  // NOTE: On supprime l'effet automatique de fin de match pour laisser l'utilisateur voir l'écran de victoire
  // L'écran de victoire est déclenché dans processScoreSubmission

  // --- Clock & Duration Timer ---
  useEffect(() => {
    const timer = setInterval(() => {
      // Update Clock
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

      // Update Duration if active
      if (matchStatusRef.current === 'active') {
          setElapsedSeconds(prev => prev + 1);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // --- Auto Exit Timer on Winner Screen (30s) ---
  useEffect(() => {
    let timeout: ReturnType<typeof setTimeout>;
    if (showWinnerScreen) {
        timeout = setTimeout(() => {
            onExit();
        }, 30000); // 30 seconds
    }
    return () => clearTimeout(timeout);
  }, [showWinnerScreen, onExit]);

  // --- Voice Logic (Vosk + Darts Parser) ---
  useEffect(() => {
      if (transcript) {
          console.log("Processing Transcript:", transcript);
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer]); 

  // --- Feedback Helper ---
  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 2000);
  };

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  // Centralized submission logic
  const processScoreSubmission = (score: number) => {
      if (isNaN(score)) return;
      if (score > 180) return;

      const maxCheckout = getMaxCheckout(match.config.checkOut);

      // If potential checkout, ask for darts used
      if (score === currentScore && score <= maxCheckout) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      // Check for Miss (0 score)
      if (score === 0) {
          triggerFeedback("PAS DE SCORE", "miss");
      }

      // Otherwise submit immediately with default 3 darts
      let nextState = submitTurn(match, score, 3);

      // Capture duration if match finished
      if (nextState.status === 'finished') {
          nextState = { ...nextState, duration: elapsedSeconds };
          // Déclencher l'écran de victoire
          setMatch(nextState);
          setShowWinnerScreen(true);
          setInputBuffer('');
          resetTranscript();
          return;
      }

      // Check for Bust in the newly added turn
      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn && lastTurn.isBust) {
          triggerFeedback("TROP DE SCORE", "bust");
      }

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    processScoreSubmission(parseInt(inputBuffer));
  };

  // Quick Action Handler - Instantly Submits
  const handleQuickAction = (val: number) => {
      // Just call the processor. It handles validation and auto-checkout modal if needed.
      processScoreSubmission(val);
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);

     // Capture duration if match finished
     if (nextState.status === 'finished') {
         nextState = { ...nextState, duration: elapsedSeconds };
         setMatch(nextState);
         setShowWinnerScreen(true);
     } else {
         setMatch(nextState);
     }

     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (!isListening && !isModelMissing && !isLoadingModel) {
          startListening();
      } 
  };

  const handleGoToStats = () => {
      if (!match.matchWinnerId) return;
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
  };

  const updateShortcut = (side: 'left' | 'right', index: number, valStr: string) => {
      const val = parseInt(valStr);
      if (isNaN(val)) return;

      setQuickShortcuts(prev => {
          const newArr = side === 'left' ? [...prev.left] : [...prev.right];
          newArr[index] = val;
          return { ...prev, [side]: newArr };
      });
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">

      {/* 1. HEADER (Time, Logo, Config) */}
      <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20 relative select-none">

        {/* CENTER CLOCK & DURATION (Absolute) */}
        <div className="absolute left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none flex flex-col items-center">
             <span className="font-mono text-gray-500 font-bold text-sm md:text-base opacity-80 tracking-widest bg-gray-900 px-2 rounded leading-none">
                 {currentTime}
             </span>
             <span className="font-mono text-[10px] text-gray-600 font-bold tracking-widest mt-0.5">
                 {formatDuration(elapsedSeconds)}
             </span>
        </div>

        {/* LEFT: Logo & Rules */}
        <div className="flex flex-col items-start justify-center z-10">
           <div className="font-black italic text-sm md:text-lg tracking-tight leading-none">
                <span className="text-white">BOUGNAT</span> <span className="text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">DARTS</span>
           </div>
           <div className="flex items-center gap-2 text-[8px] md:text-[10px] font-mono text-gray-500 leading-none mt-1">
               <span className="whitespace-nowrap">IN: <span className="text-gray-300 font-bold">{match.config.checkIn}</span></span>
               <span className="text-gray-700">|</span>
               <span className="whitespace-nowrap">OUT: <span className="text-gray-300 font-bold">{match.config.checkOut}</span></span>
           </div>
        </div>

        {/* RIGHT: Buttons */}
        <div className="flex gap-3 z-10">
            <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white transition-colors">⚙️</button>
            <button onClick={() => setShowStats(true)} className="text-gray-400 hover:text-white text-[10px] md:text-xs font-bold uppercase border border-gray-700 px-2 py-1 rounded bg-gray-800 hover:bg-gray-700 transition-colors">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 hover:text-red-400 text-[10px] md:text-xs font-bold uppercase border border-red-900/30 px-2 py-1 rounded bg-red-900/10 hover:bg-red-900/30 transition-colors">Exit</button>
        </div>
      </div>

      {/* 2. MAIN SCORE AREA */}
      <div className="flex-1 relative flex items-stretch min-h-0 z-0">

        {/* FEEDBACK OVERLAY (Bust/Miss) */}
        {feedbackMessage && (
            <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none bg-black/50 backdrop-blur-sm animate-in fade-in zoom-in duration-200">
                <div className={`transform rotate-[-5deg] border-4 px-8 py-4 rounded-xl shadow-[0_0_50px_rgba(0,0,0,0.8)]
                    ${feedbackMessage.type === 'bust' 
                        ? 'bg-red-600 border-red-400 text-white' 
                        : 'bg-gray-200 border-white text-gray-900'
                    }
                `}>
                    <h1 className="text-5xl md:text-7xl font-black italic uppercase tracking-tighter drop-shadow-md">
                        {feedbackMessage.text}
                    </h1>
                </div>
            </div>
        )}

        {/* Player 1 Area */}
        <div className="flex-1 border-r border-gray-800/50">
            {teams[0] && renderPlayerArea(teams[0])}
        </div>

        {/* Player 2 Area */}
        <div className="flex-1">
            {teams[1] && renderPlayerArea(teams[1])}
        </div>

        {/* FLOATING MATCH SCORE PILL */}
        <div className="absolute bottom-32 md:bottom-24 left-1/2 transform -translate-x-1/2 z-20 pointer-events-none w-full flex flex-col items-center justify-end">
            <div className="bg-gray-900/90 backdrop-blur-md border border-gray-700 px-4 py-1 rounded-full shadow-2xl flex items-center space-x-3 mb-1">
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[0] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]])}
                 </span>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[1] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]])}
                 </span>
            </div>
            <div className="text-[9px] text-gray-400 font-bold bg-black/50 px-2 py-0.5 rounded-full backdrop-blur-sm">
                First to {match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin}
            </div>
        </div>

        {/* Checkout Hint Overlay */}
        {showCheckoutHints && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                 <CheckoutHint score={currentScore} />
            </div>
        )}
      </div>

      {/* 3. INPUT AREA & VOICE CONSOLE */}
      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[42dvh] flex flex-col relative z-30">

         {/* --- VOICE CONSOLE & UTILITY BAR --- */}
         <div className="h-14 shrink-0 bg-black/40 flex items-center justify-between px-2 relative border-b border-gray-800/50">
             {/* Background Tech Pattern */}
             <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiBmaWxsLW9wYWNpdHk9IjEiLz4KPGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9InJnYmEoNiwgMTgyLCAyMTIsIDAuMDUpIi8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>

             {/* LEFT: Utility Action (Swap Start) */}
             <div className="w-20 flex justify-start z-10">
                {!showStarterSelection && isLegStart && (
                    <button 
                        onClick={handleSwitchStart} 
                        className="text-[10px] font-bold text-gray-500 hover:text-cyan-400 border border-gray-700 hover:border-cyan-500 rounded px-2 py-1 uppercase transition-colors"
                    >
                        Swap Start
                    </button>
                )}
             </div>

             {/* CENTER: The Console Display */}
             <div className="flex-1 mx-2 h-10 bg-black/60 rounded border border-gray-700/50 flex items-center justify-center relative overflow-hidden shadow-inner">
                 {/* Status Light */}
                 <div className={`absolute left-2 w-1.5 h-1.5 rounded-full ${
                     isModelMissing ? 'bg-red-900' : 
                     isLoadingModel ? 'bg-yellow-500 animate-pulse' :
                     isListening ? 'bg-cyan-500 animate-pulse shadow-[0_0_8px_cyan]' : 
                     'bg-green-500'
                 }`}></div>

                 {/* Main Readout */}
                 <div className="flex flex-col items-center justify-center leading-none">
                     {/* The Input Buffer (Draft Score) */}
                     {inputBuffer ? (
                         <span className="text-2xl font-mono font-bold text-orange-500 tracking-widest drop-shadow-sm">
                             {inputBuffer}
                         </span>
                     ) : (
                         <div className="flex flex-col items-center">
                            {/* Voice Feedback Text */}
                            <span className={`font-mono text-xs font-bold uppercase tracking-wider ${
                                isModelMissing ? 'text-red-600' :
                                isLoadingModel ? 'text-yellow-500' :
                                isListening ? 'text-cyan-400' : 
                                'text-gray-600'
                            }`}>
                                {isModelMissing ? "IA NON DISPONIBLE" :
                                 isLoadingModel ? "INITIALISATION..." : 
                                 isListening ? (transcript || "LISTENING...") : 
                                 lastVoiceCommand ? `CMD: ${lastVoiceCommand}` : 
                                 "READY • LOCAL"}
                            </span>
                            {/* Subtext */}
                            {voiceError && !isModelMissing && <span className="text-[8px] text-red-500 font-bold uppercase">{voiceError}</span>}
                         </div>
                     )}
                 </div>
             </div>

             {/* RIGHT: Utility Action (Undo) */}
             <div className="w-20 flex justify-end z-10">
                <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={handleUndo} 
                    disabled={match.currentLeg.history.length === 0} 
                    className="text-xs font-bold text-gray-400 hover:text-white px-0"
                >
                    UNDO ↶
                </Button>
             </div>
         </div>

         {/* Keypad Layout */}
         <div className="flex flex-1 px-2 pb-2 gap-2 min-h-0 pt-2">
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
                 // Passing Voice Props
                 hasVoiceSupport={hasRecognitionSupport}
                 isModelMissing={isModelMissing}
                 onMicClick={handleMicClick}
                 isListening={isListening}
                 isLoadingModel={isLoadingModel}
                 // Quick Actions
                 quickShortcutsLeft={quickShortcuts.left}
                 quickShortcutsRight={quickShortcuts.right}
                 onQuickAction={handleQuickAction}
               />
            </div>
            <div className="w-[22%]">
               <Button 
                 className={`h-full w-full text-xl md:text-3xl font-black rounded-xl transition-all duration-200 ${canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'bg-gradient-to-b from-orange-500 to-red-600 shadow-lg shadow-orange-900/50' : 'bg-gray-800 text-gray-400'}`}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
         </div>
      </div>

      {/* --- MODALS --- */}
      {renderModals()}

      {/* --- WINNER SCREEN --- */}
      {showWinnerScreen && (
          <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">

             {/* Confettis Simulation (Simple Dots) */}
             <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-50">
                {[...Array(20)].map((_, i) => (
                    <div key={i} className="absolute w-2 h-2 bg-orange-500 rounded-full animate-pulse" 
                         style={{ 
                             top: `${Math.random() * 100}%`, 
                             left: `${Math.random() * 100}%`,
                             animationDelay: `${Math.random()}s`,
                             animationDuration: '2s'
                         }}></div>
                ))}
             </div>

             <h1 className="text-6xl md:text-8xl font-black italic text-transparent bg-clip-text bg-gradient-to-br from-orange-500 via-yellow-500 to-red-500 drop-shadow-[0_0_30px_rgba(234,88,12,0.8)] mb-4 text-center">
                 VAINQUEUR
             </h1>

             <div className="text-3xl md:text-5xl font-bold text-white mb-12 uppercase tracking-widest text-center border-b-4 border-orange-500 pb-4">
                 {match.matchWinnerId 
                    ? (match.players.find(p => p.teamId === match.matchWinnerId)?.name || 'Team')
                    : 'Unknown'
                 }
             </div>

             <div className="flex flex-col gap-4 w-full max-w-sm">
                 <Button onClick={handleGoToStats} size="lg" className="w-full h-20 text-2xl shadow-[0_0_20px_rgba(234,88,12,0.4)] animate-bounce">
                     SUIVANT ➔
                 </Button>
                 <div className="text-[10px] text-gray-600 text-center font-mono uppercase tracking-widest animate-pulse">
                     Auto-exit in 30s
                 </div>
             </div>
          </div>
      )}

    </div>
  );

  function renderPlayerArea(teamId: string) {
      // (Implementation same as existing)
      const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles 
        ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
        : teamPlayersLocal[0]?.name || 'Player';

      const isTeamActive = currentPlayer.teamId === teamId;
      const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

      const calculateAvg = (turns: any[]) => {
          const score = turns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
          const darts = turns.reduce((acc, t) => acc + t.dartsThrown, 0);
          return darts > 0 ? ((score / darts) * 3).toFixed(1) : "0.0";
      };

      const legTurns = match.currentLeg.history.filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const legAvg = calculateAvg(legTurns);
      const legDarts = legTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

      const allTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const matchAvg = calculateAvg(allTurns);

      const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });

      return (
        <PlayerScore 
            name={displayName}
            currentThrowerName={throwerName}
            score={match.currentLeg.scores[teamId]}
            isActive={isTeamActive}
            legsWon={match.legsWon[teamId]}
            setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
            stats={{
                matchAvg: matchAvg,
                legAvg: legAvg,
                legDarts: legDarts,
                lastScore: lastTurn?.score || null
            }}
        />
      );
  }

  function renderModals() {
      // (Implementation same as existing)
      return (
          <>
            {showStarterSelection && (
                <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-6 uppercase">Bull Up</h2>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-lg mb-8">
                        {/* Team 1 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 1 First</div>
                            {team1Players.map(p => (
                                <Button key={p.id} variant={selectedT1StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT1StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                        {/* Team 2 */}
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 2 First</div>
                            {team2Players.map(p => (
                                <Button key={p.id} variant={selectedT2StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT2StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-md">
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team1')} className="border border-orange-600 text-orange-500">T1 STARTS</Button>
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team2')} className="border border-orange-600 text-orange-500">T2 STARTS</Button>
                    </div>
                </div>
            )}

            {pendingCheckoutScore !== null && (
                <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-white mb-8 uppercase">Game Shot!</h2>
                    <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Darts Used</p>
                    <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                        {[1, 2, 3].map(d => {
                            const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                            const disabled = d < minDarts;
                            return (
                                <Button key={d} variant={disabled ? "secondary" : "primary"} onClick={() => !disabled && handleCheckoutConfirm(d)} className={`h-20 text-4xl ${disabled ? 'opacity-20' : ''}`} disabled={disabled}>{d}</Button>
                            )
                        })}
                    </div>
                    <div className="mt-8"><Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button></div>
                </div>
            )}

            {showSettings && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-md border border-gray-700 max-h-[80vh] overflow-y-auto">
                    <h2 className="text-xl font-black text-white mb-6 text-center uppercase">Settings</h2>

                    {/* General Settings */}
                    <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg mb-4">
                        <span className="text-gray-300 font-bold text-sm">Checkout Hints</span>
                        <button onClick={() => setShowCheckoutHints(!showCheckoutHints)} className={`w-12 h-6 rounded-full relative transition-colors ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                        </button>
                    </div>

                    {/* Quick Keys Configuration */}
                    <div className="bg-gray-800/50 rounded-lg p-4 border border-gray-700 mb-6">
                        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                             Quick Keys Config 
                             <span className="text-[9px] bg-gray-700 px-1 rounded text-gray-300">Tablet / Desktop</span>
                        </h3>

                        <div className="grid grid-cols-2 gap-4">
                            {/* Left Col (20s) */}
                            <div className="space-y-2">
                                <div className="text-center text-[10px] text-cyan-500 font-bold uppercase">Left (20s Focus)</div>
                                {quickShortcuts.left.map((val, idx) => (
                                    <input 
                                        key={`L-conf-${idx}`}
                                        type="number"
                                        min="0"
                                        max="180"
                                        className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-center font-mono font-bold text-cyan-500 focus:border-cyan-500 focus:outline-none"
                                        value={val}
                                        onChange={(e) => updateShortcut('left', idx, e.target.value)}
                                    />
                                ))}
                            </div>

                            {/* Right Col (19s) */}
                            <div className="space-y-2">
                                <div className="text-center text-[10px] text-orange-500 font-bold uppercase">Right (19s Focus)</div>
                                {quickShortcuts.right.map((val, idx) => (
                                    <input 
                                        key={`R-conf-${idx}`}
                                        type="number"
                                        min="0"
                                        max="180"
                                        className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-center font-mono font-bold text-orange-500 focus:border-orange-500 focus:outline-none"
                                        value={val}
                                        onChange={(e) => updateShortcut('right', idx, e.target.value)}
                                    />
                                ))}
                            </div>
                        </div>
                    </div>

                    <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
                </div>
                </div>
            )}

            {showExitConfirm && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                    <h3 className="text-2xl font-black text-white mb-2 italic">QUIT MATCH?</h3>
                    <div className="grid grid-cols-2 gap-3 mt-8">
                        <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>No</Button>
                        <Button variant="danger" onClick={onExit}>Yes</Button>
                    </div>
                </div>
                </div>
            )}

            {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Match Stats" />}
          </>
      );
  }
};

export type InOutRule = 'Open' | 'Double' | 'Master';
export type MatchMode = 'LEGS' | 'SETS';

export interface Player {
  id: string;
  name: string;
  teamId: string; // New: logical grouping for score sharing
}

export interface GameConfig {
  startingScore: number;
  checkIn: InOutRule;
  checkOut: InOutRule;
  matchMode: MatchMode;
  setsToWin: number;
  legsToWin: number;
  isDoubles: boolean; // New: True if 2v2
  enableVoice: boolean; // New: True if AI voice is active
}

export interface Turn {
  playerId: string;
  score: number;
  isBust: boolean;
  remainingAfter: number;
  dartsThrown: number;
}

export interface LegState {
  scores: Record<string, number>; // keys are teamId
  history: Turn[];
  winnerId: string | null; // winner is a teamId
  startingPlayerIndex: number;
}

export interface MatchState {
  id: string;
  config: GameConfig;
  players: Player[]; // Ordered rotation list
  setsWon: Record<string, number>; // keys are teamId
  legsWon: Record<string, number>; // keys are teamId
  completedLegs: LegState[];
  currentLeg: LegState;
  status: 'active' | 'finished';
  matchWinnerId: string | null; // teamId
  currentPlayerIndex: number;
  duration: number; // Total match duration in seconds
}

import React, { useState, useEffect } from 'react';
import { Button } from '../components/ui/Button';
import { GameConfig, Player, InOutRule, MatchMode } from '../types';

interface SetupViewProps {
  onStart: (players: Player[], config: GameConfig) => void;
  onBack: () => void;
}

export const SetupView: React.FC<SetupViewProps> = ({ onStart, onBack }) => {
  const [startingScore, setStartingScore] = useState(501);
  const [customScoreStr, setCustomScoreStr] = useState('170');

  const [matchMode, setMatchMode] = useState<MatchMode>('LEGS');
  const [legsToWin, setLegsToWin] = useState(3);
  const [setsToWin, setSetsToWin] = useState(3);

  // New: Doubles Mode
  const [isDoubles, setIsDoubles] = useState(false);
  const [enableVoice, setEnableVoice] = useState(false);

  // Player State
  const [playerNames, setPlayerNames] = useState<string[]>(['Player 1', 'Player 2']);

  // Doubles specific state
  const [team1Names, setTeam1Names] = useState(['Player 1', 'Player 2']);
  const [team2Names, setTeam2Names] = useState(['Player 3', 'Player 4']);

  // Defaults: Double Out, Open In
  const [checkOut, setCheckOut] = useState<InOutRule>('Double');
  const [checkIn, setCheckIn] = useState<InOutRule>('Open');

  // Solo Player Count
  const updatePlayerCount = (delta: number) => {
    const currentCount = playerNames.length;
    const newCount = Math.max(1, Math.min(4, currentCount + delta));

    if (newCount === currentCount) return;

    setPlayerNames(prev => {
      if (newCount > prev.length) {
        return [...prev, `Player ${newCount}`];
      } else {
        return prev.slice(0, newCount);
      }
    });
  };

  const updatePlayerName = (index: number, name: string) => {
    const newNames = [...playerNames];
    newNames[index] = name;
    setPlayerNames(newNames);
  };

  const updateTeamName = (team: 1 | 2, index: number, name: string) => {
      if (team === 1) {
          const n = [...team1Names];
          n[index] = name;
          setTeam1Names(n);
      } else {
          const n = [...team2Names];
          n[index] = name;
          setTeam2Names(n);
      }
  }

  const handleStart = () => {
    const safeStartingScore = startingScore > 0 ? startingScore : 501;
    let players: Player[] = [];

    if (isDoubles) {
        const p1 = { id: 't1p1', name: team1Names[0].trim() || 'Player 1', teamId: 'team1' };
        const p2 = { id: 't1p2', name: team1Names[1].trim() || 'Player 2', teamId: 'team1' };
        const p3 = { id: 't2p1', name: team2Names[0].trim() || 'Player 3', teamId: 'team2' };
        const p4 = { id: 't2p2', name: team2Names[1].trim() || 'Player 4', teamId: 'team2' };
        players = [p1, p2, p3, p4];
    } else {
        players = playerNames.map((name, i) => ({
            id: `p${i+1}`,
            name: name.trim() || `Player ${i+1}`,
            teamId: `p${i+1}` 
        }));
    }

    const config: GameConfig = {
      startingScore: safeStartingScore,
      checkIn,
      checkOut,
      matchMode,
      legsToWin, 
      setsToWin,
      isDoubles,
      enableVoice
    };

    onStart(players, config);
  };

  const activeOptionClass = "bg-gradient-to-r from-orange-600 to-red-600 text-white border-transparent shadow-[0_0_10px_rgba(234,88,12,0.3)]";
  const inactiveOptionClass = "bg-gray-800 border-gray-700 text-gray-400 hover:border-orange-500/50 hover:text-gray-200";

  const getRuleDescription = (type: 'in' | 'out', rule: InOutRule) => {
     if (type === 'out') {
         switch(rule) {
             case 'Open': return "Finish on any segment.";
             case 'Double': return "Standard: Finish on a Double or Bullseye.";
             case 'Master': return "Finish on a Double, Triple or Bullseye.";
         }
     } else {
         switch(rule) {
             case 'Open': return "Start scoring immediately.";
             case 'Double': return "Must hit a Double to start.";
             case 'Master': return "Must hit a Double or Triple to start.";
         }
     }
  };

  const presets = [301, 501, 701, 1001];
  const isPresetSelected = presets.includes(startingScore);
  const isCustomActive = !isPresetSelected || startingScore === parseInt(customScoreStr || '0');

  const handleCustomFocus = () => {
      const val = parseInt(customScoreStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  const handleCustomChange = (valStr: string) => {
      setCustomScoreStr(valStr);
      const val = parseInt(valStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      <div className="flex items-center mb-6">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
            MATCH SETUP
        </h2>
      </div>

      <div className="flex-1 space-y-6 max-w-md mx-auto w-full overflow-y-auto pb-4 custom-scrollbar">

        {/* Score Selection */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Starting Score</label>
          <div className="grid grid-cols-4 gap-2 mb-3">
            {presets.map(score => (
              <button
                key={score}
                onClick={() => setStartingScore(score)}
                className={`py-3 rounded font-black border transition-all duration-200 ${startingScore === score ? activeOptionClass : inactiveOptionClass}`}
              >
                {score}
              </button>
            ))}
          </div>

           <div 
             className={`flex items-center space-x-3 p-3 rounded-lg border transition-all duration-200 ${isCustomActive && !presets.includes(startingScore) ? 'bg-gray-800 border-orange-500 shadow-[0_0_10px_rgba(234,88,12,0.15)]' : 'bg-gray-800/30 border-gray-700'}`}
             onClick={handleCustomFocus}
           >
               <span className={`text-xs font-bold uppercase tracking-wider whitespace-nowrap ${isCustomActive && !presets.includes(startingScore) ? 'text-orange-500' : 'text-gray-500'}`}>Custom Score</span>
               <input 
                  type="number" 
                  min="1"
                  max="9999"
                  value={customScoreStr}
                  onChange={(e) => handleCustomChange(e.target.value)}
                  onFocus={handleCustomFocus}
                  className={`w-full bg-transparent text-right font-mono font-black text-xl focus:outline-none focus:text-orange-500 ${isCustomActive && !presets.includes(startingScore) ? 'text-white' : 'text-gray-500'}`}
                  placeholder="Enter score..."
               />
           </div>
        </section>

        {/* Voice AI Section */}
        <section className="bg-gray-800/30 p-4 rounded-xl border border-gray-800">
            <div className="flex justify-between items-center mb-2">
                <div>
                    <label className="block text-cyan-500 text-xs font-bold uppercase tracking-widest">Assistant Vocal AI</label>
                    <p className="text-[10px] text-gray-500 mt-1 leading-relaxed">
                        Annoncez vos scores à la voix (ex: "Triple 20", "Cent quarante"). Nécessite un téléchargement de ~45Mo au premier lancement.
                    </p>
                </div>
                <button 
                    onClick={() => setEnableVoice(!enableVoice)}
                    className={`w-14 h-7 rounded-full relative transition-all duration-300 shrink-0 ${enableVoice ? 'bg-cyan-600 shadow-[0_0_10px_rgba(8,145,178,0.4)]' : 'bg-gray-700'}`}
                >
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all duration-300 shadow-sm ${enableVoice ? 'left-8' : 'left-1'}`}></div>
                </button>
            </div>
        </section>

        {/* Players Configuration */}
        <section>
            <div className="flex justify-between items-center mb-2">
                <label className="block text-orange-500 text-xs font-bold uppercase tracking-widest">Players</label>
                <div className="flex bg-gray-800 rounded p-1">
                    <button onClick={() => setIsDoubles(false)} className={`px-3 py-1 text-xs font-bold rounded ${!isDoubles ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>Solo</button>
                    <button onClick={() => setIsDoubles(true)} className={`px-3 py-1 text-xs font-bold rounded ${isDoubles ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>Doubles (2v2)</button>
                </div>
            </div>

            {!isDoubles ? (
                <>
                    <div className="flex items-center space-x-4 bg-gray-800/50 p-2 rounded-lg mb-4 border border-gray-700">
                        <button onClick={() => updatePlayerCount(-1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">-</button>
                        <span className="flex-1 text-center font-black text-2xl text-white">{playerNames.length}</span>
                        <button onClick={() => updatePlayerCount(1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">+</button>
                    </div>
                    <div className="space-y-2">
                        {playerNames.map((name, index) => (
                        <div key={index} className="flex items-center group">
                            <span className="w-8 text-gray-500 text-xs font-bold group-hover:text-orange-500 transition-colors">#{index + 1}</span>
                            <input
                            type="text"
                            value={name}
                            onChange={(e) => updatePlayerName(index, e.target.value)}
                            onFocus={(e) => e.target.select()}
                            className="flex-1 bg-gray-800 border border-gray-700 text-white px-3 py-3 rounded font-bold focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all"
                            placeholder={`Player ${index + 1}`}
                            />
                        </div>
                        ))}
                    </div>
                </>
            ) : (
                <div className="space-y-4">
                    <div className="bg-gray-800/30 p-3 rounded border border-gray-700">
                        <div className="text-xs text-orange-500 font-bold uppercase mb-2">Team 1</div>
                        <div className="space-y-2">
                            <input value={team1Names[0]} onChange={(e) => updateTeamName(1, 0, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 1" />
                            <input value={team1Names[1]} onChange={(e) => updateTeamName(1, 1, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 2" />
                        </div>
                    </div>
                    <div className="bg-gray-800/30 p-3 rounded border border-gray-700">
                        <div className="text-xs text-orange-500 font-bold uppercase mb-2">Team 2</div>
                        <div className="space-y-2">
                            <input value={team2Names[0]} onChange={(e) => updateTeamName(2, 0, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 3" />
                            <input value={team2Names[1]} onChange={(e) => updateTeamName(2, 1, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 4" />
                        </div>
                    </div>
                </div>
            )}
        </section>

        {/* Format */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Match Format</label>

          <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-4">
             <button onClick={() => setMatchMode('LEGS')} className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all ${matchMode === 'LEGS' ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                Legs
             </button>
             <button onClick={() => setMatchMode('SETS')} className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all ${matchMode === 'SETS' ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                Sets
             </button>
          </div>

          <div className="bg-gray-800/30 p-4 rounded-lg border border-gray-700 space-y-4">
             {matchMode === 'LEGS' ? (
                <div>
                   <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Legs to Win Match</label>
                   <div className="grid grid-cols-5 gap-2">
                      {[1, 3, 5, 7, 9].map(num => (
                         <button key={num} onClick={() => setLegsToWin(num)} className={`py-2 rounded font-bold text-sm border ${legsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                            {num}
                         </button>
                      ))}
                   </div>
                </div>
             ) : (
                <>
                  <div>
                      <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Sets to Win Match</label>
                      <div className="grid grid-cols-4 gap-2">
                          {[1, 3, 5, 7].map(num => (
                            <button key={num} onClick={() => setSetsToWin(num)} className={`py-2 rounded font-bold text-sm border ${setsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                {num}
                            </button>
                          ))}
                      </div>
                  </div>
                  <div>
                      <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Legs to Win a Set</label>
                      <div className="grid grid-cols-4 gap-2">
                          {[3, 5].map(num => (
                            <button key={num} onClick={() => setLegsToWin(num)} className={`py-2 rounded font-bold text-sm border ${legsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                {num}
                            </button>
                          ))}
                      </div>
                  </div>
                </>
             )}
          </div>
        </section>

        {/* In / Out Rules */}
        <section className="grid grid-cols-1 gap-6">
           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Check In Rule</label>
               <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button
                      key={rule}
                      onClick={() => setCheckIn(rule)}
                      className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkIn === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                      {rule} In
                    </button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('in', checkIn)}</p>
           </div>

           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Checkout Rule</label>
               <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button
                      key={rule}
                      onClick={() => setCheckOut(rule)}
                      className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkOut === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                      {rule} Out
                    </button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('out', checkOut)}</p>
           </div>
        </section>

      </div>

      <div className="mt-4">
        <Button onClick={handleStart} className="w-full py-5 text-2xl shadow-orange-900/20">GAME ON</Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView';
import { ProfileView } from './views/ProfileView';
import { HistoryView } from './views/HistoryView'; 
import { MyStatsView } from './views/MyStatsView'; 
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { VoiceLoaderView } from './views/VoiceLoaderView'; // New Import
import { GameConfig, Player, MatchState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'PROFILE' | 'HISTORY' | 'MY_STATS' | 'GAME_SELECTION' | 'SETUP' | 'LOADING_AI' | 'MATCH' | 'STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    if (type === 'X01') {
      setSelectedGameType(type);
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  const handleStartSetup = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);

    if (config.enableVoice) {
        setScreen('LOADING_AI');
    } else {
        setScreen('MATCH');
    }
  };

  const handleAiLoaded = () => {
      setScreen('MATCH');
  };

  const handleMatchFinish = (winnerId: string) => {
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch);

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  const handleExitMatch = () => {
    exitFullScreen();
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleRematch = () => {
      if (!currentMatch) return;

      const newMatch = createMatch(currentMatch.players, currentMatch.config);
      setCurrentMatch(newMatch);
      enterFullScreen();
      setScreen('MATCH');
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => setScreen('HISTORY')}
              onStats={() => setScreen('MY_STATS')}
              onProfile={() => setScreen('PROFILE')}
              onSettings={() => alert("Settings coming soon.")}
              onLogout={handleLogout}
          />
      )}

      {screen === 'PROFILE' && user && (
          <ProfileView 
              user={user}
              onBack={() => setScreen('DASHBOARD')}
              onUpdateUser={(updatedUser) => setUser(updatedUser)}
          />
      )}

      {screen === 'HISTORY' && user && (
          <HistoryView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'MY_STATS' && user && (
          <MyStatsView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          onStart={handleStartSetup} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {screen === 'LOADING_AI' && (
         <VoiceLoaderView 
            onLoaded={handleAiLoaded}
            onSkip={handleAiLoaded}
         />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={() => { setScreen(user ? 'DASHBOARD' : 'HOME'); setCurrentMatch(null); }}
          onRematch={handleRematch}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState } from '../types';
import { submitTurn, undoTurn, switchStartPlayer, getMinDartsForScore, reorderPlayersForDoubles, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');

  const [currentTime, setCurrentTime] = useState<string>(
    new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  );
  const [elapsedSeconds, setElapsedSeconds] = useState(0);

  const matchStatusRef = useRef(match.status);
  useEffect(() => { matchStatusRef.current = match.status; }, [match.status]);

  const [quickShortcuts, setQuickShortcuts] = useState<{ left: number[], right: number[] }>({
      left: [180, 140, 100, 60, 26], 
      right: [171, 133, 95, 57, 19]  
  });

  const { 
      isListening, 
      transcript, 
      startListening, 
      hasRecognitionSupport, 
      resetTranscript, 
      error: voiceError,
      isLoadingModel,
      isModelMissing
  } = useSpeechRecognition();

  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [lastVoiceCommand, setLastVoiceCommand] = useState<string | null>(null);

  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  const [showStarterSelection, setShowStarterSelection] = useState<boolean>(initialMatch.config.isDoubles);

  const team1Players = match.players.filter(p => p.teamId === 'team1');
  const team2Players = match.players.filter(p => p.teamId === 'team2');

  const [selectedT1StarterId, setSelectedT1StarterId] = useState<string>(team1Players[0]?.id || '');
  const [selectedT2StarterId, setSelectedT2StarterId] = useState<string>(team2Players[0]?.id || '');

  const [showCheckoutHints, setShowCheckoutHints] = useState(true);

  const currentPlayer = match.players[match.currentPlayerIndex];
  const currentScore = match.currentLeg.scores[currentPlayer.teamId];

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      if (matchStatusRef.current === 'active') {
          setElapsedSeconds(prev => prev + 1);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timeout: ReturnType<typeof setTimeout>;
    if (showWinnerScreen) {
        timeout = setTimeout(() => {
            onExit();
        }, 30000); 
    }
    return () => clearTimeout(timeout);
  }, [showWinnerScreen, onExit]);

  useEffect(() => {
      if (transcript && match.config.enableVoice) {
          const result = parseDartsVoiceCommand(transcript);

          if (result.type !== 'UNKNOWN') {
             setLastVoiceCommand(transcript);
             setTimeout(() => setLastVoiceCommand(null), 3000);
             resetTranscript();
          }

          if (result.type === 'SCORE' && result.value !== undefined) {
              setInputBuffer(result.value.toString());
          } 
          else if (result.type === 'COMMAND_SUBMIT') {
              if (inputBuffer) {
                  handleSubmitScore();
              }
          }
          else if (result.type === 'COMMAND_CLEAR') {
              handleClear();
          }
          else if (result.type === 'COMMAND_UNDO') {
              handleUndo();
          }
      }
  }, [transcript, resetTranscript, inputBuffer, match.config.enableVoice]); 

  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 2000);
  };

  const handleInput = (val: number) => {
    if (inputBuffer.length >= 3) return;
    const newVal = inputBuffer + val.toString();
    if (parseInt(newVal) > 180) return;
    setInputBuffer(newVal);
  };

  const handleClear = () => {
    setInputBuffer('');
    resetTranscript(); 
  };

  const getMaxCheckout = (rule: 'Open' | 'Double' | 'Master') => {
      if (rule === 'Double') return 170;
      return 180;
  };

  const processScoreSubmission = (score: number) => {
      if (isNaN(score)) return;
      if (score > 180) return;

      const maxCheckout = getMaxCheckout(match.config.checkOut);

      if (score === currentScore && score <= maxCheckout) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      if (score === 0) {
          triggerFeedback("PAS DE SCORE", "miss");
      }

      let nextState = submitTurn(match, score, 3);

      if (nextState.status === 'finished') {
          nextState = { ...nextState, duration: elapsedSeconds };
          setMatch(nextState);
          setShowWinnerScreen(true);
          setInputBuffer('');
          resetTranscript();
          return;
      }

      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn && lastTurn.isBust) {
          triggerFeedback("TROP DE SCORE", "bust");
      }

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => {
    if (!inputBuffer) return;
    processScoreSubmission(parseInt(inputBuffer));
  };

  const handleQuickAction = (val: number) => {
      processScoreSubmission(val);
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);

     if (nextState.status === 'finished') {
         nextState = { ...nextState, duration: elapsedSeconds };
         setMatch(nextState);
         setShowWinnerScreen(true);
     } else {
         setMatch(nextState);
     }

     setInputBuffer('');
     setPendingCheckoutScore(null);
  }

  const handleUndo = () => {
    setMatch(undoTurn(match));
    setInputBuffer('');
  };

  const handleSwitchStart = () => {
     setMatch(switchStartPlayer(match));
  };

  const handleConfirmDoublesStart = (startingTeamId: string) => {
      const updatedMatch = reorderPlayersForDoubles(
          match, 
          selectedT1StarterId, 
          selectedT2StarterId, 
          startingTeamId
      );
      setMatch(updatedMatch);
      setShowStarterSelection(false);
  }

  const handleMicClick = () => {
      if (match.config.enableVoice && !isListening && !isModelMissing && !isLoadingModel) {
          startListening();
      } 
  };

  const handleGoToStats = () => {
      if (!match.matchWinnerId) return;
      if (onFinishWithState) {
          onFinishWithState(match.matchWinnerId, match);
      } else {
          onFinish(match.matchWinnerId);
      }
  };

  const updateShortcut = (side: 'left' | 'right', index: number, valStr: string) => {
      const val = parseInt(valStr);
      if (isNaN(val)) return;

      setQuickShortcuts(prev => {
          const newArr = side === 'left' ? [...prev.left] : [...prev.right];
          newArr[index] = val;
          return { ...prev, [side]: newArr };
      });
  };

  const isCheckoutPossible = () => {
      const rule = match.config.checkOut;
      if (rule === 'Double') {
          return currentScore <= 170 && currentScore > 1 && ![169, 168, 166, 165, 163, 162, 159].includes(currentScore);
      }
      return currentScore <= 180 && currentScore > 0;
  };

  const canCheckoutNow = isCheckoutPossible();
  const isLegStart = match.currentLeg.history.length === 0;
  const teams: string[] = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">
      <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20 relative select-none">
        <div className="absolute left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none flex flex-col items-center">
             <span className="font-mono text-gray-500 font-bold text-sm md:text-base opacity-80 tracking-widest bg-gray-900 px-2 rounded leading-none">
                 {currentTime}
             </span>
             <span className="font-mono text-[10px] text-gray-600 font-bold tracking-widest mt-0.5">
                 {formatDuration(elapsedSeconds)}
             </span>
        </div>
        <div className="flex flex-col items-start justify-center z-10">
           <div className="font-black italic text-sm md:text-lg tracking-tight leading-none">
                <span className="text-white">BOUGNAT</span> <span className="text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">DARTS</span>
           </div>
           <div className="flex items-center gap-2 text-[8px] md:text-[10px] font-mono text-gray-500 leading-none mt-1">
               <span className="whitespace-nowrap">IN: <span className="text-gray-300 font-bold">{match.config.checkIn}</span></span>
               <span className="text-gray-700">|</span>
               <span className="whitespace-nowrap">OUT: <span className="text-gray-300 font-bold">{match.config.checkOut}</span></span>
           </div>
        </div>
        <div className="flex gap-3 z-10">
            <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white transition-colors">⚙️</button>
            <button onClick={() => setShowStats(true)} className="text-gray-400 hover:text-white text-[10px] md:text-xs font-bold uppercase border border-gray-700 px-2 py-1 rounded bg-gray-800 hover:bg-gray-700 transition-colors">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 hover:text-red-400 text-[10px] md:text-xs font-bold uppercase border border-red-900/30 px-2 py-1 rounded bg-red-900/10 hover:bg-red-900/30 transition-colors">Exit</button>
        </div>
      </div>

      <div className="flex-1 relative flex items-stretch min-h-0 z-0">
        {feedbackMessage && (
            <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none bg-black/50 backdrop-blur-sm animate-in fade-in zoom-in duration-200">
                <div className={`transform rotate-[-5deg] border-4 px-8 py-4 rounded-xl shadow-[0_0_50px_rgba(0,0,0,0.8)]
                    ${feedbackMessage.type === 'bust' 
                        ? 'bg-red-600 border-red-400 text-white' 
                        : 'bg-gray-200 border-white text-gray-900'
                    }
                `}>
                    <h1 className="text-5xl md:text-7xl font-black italic uppercase tracking-tighter drop-shadow-md">
                        {feedbackMessage.text}
                    </h1>
                </div>
            </div>
        )}
        <div className="flex-1 border-r border-gray-800/50">
            {teams[0] && renderPlayerArea(teams[0])}
        </div>
        <div className="flex-1">
            {teams[1] && renderPlayerArea(teams[1])}
        </div>
        <div className="absolute bottom-32 md:bottom-24 left-1/2 transform -translate-x-1/2 z-20 pointer-events-none w-full flex flex-col items-center justify-end">
            <div className="bg-gray-900/90 backdrop-blur-md border border-gray-700 px-4 py-1 rounded-full shadow-2xl flex items-center space-x-3 mb-1">
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[0] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]])}
                 </span>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>
                 <span className="text-orange-500 font-black text-xl md:text-2xl font-mono">
                    {teams[1] && (match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]])}
                 </span>
            </div>
            <div className="text-[9px] text-gray-400 font-bold bg-black/50 px-2 py-0.5 rounded-full backdrop-blur-sm">
                First to {match.config.matchMode === 'SETS' ? match.config.setsToWin : match.config.legsToWin}
            </div>
        </div>
        {showCheckoutHints && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                 <CheckoutHint score={currentScore} />
            </div>
        )}
      </div>

      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[42dvh] flex flex-col relative z-30">
         <div className="h-14 shrink-0 bg-black/40 flex items-center justify-between px-2 relative border-b border-gray-800/50">
             <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiBmaWxsLW9wYWNpdHk9IjEiLz4KPGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9InJnYmEoNiwgMTgyLCAyMTIsIDAuMDUpIi8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>
             <div className="w-20 flex justify-start z-10">
                {!showStarterSelection && isLegStart && (
                    <button 
                        onClick={handleSwitchStart} 
                        className="text-[10px] font-bold text-gray-500 hover:text-cyan-400 border border-gray-700 hover:border-cyan-500 rounded px-2 py-1 uppercase transition-colors"
                    >
                        Swap Start
                    </button>
                )}
             </div>
             <div className="flex-1 mx-2 h-10 bg-black/60 rounded border border-gray-700/50 flex items-center justify-center relative overflow-hidden shadow-inner">
                 <div className={`absolute left-2 w-1.5 h-1.5 rounded-full ${
                     !match.config.enableVoice ? 'bg-gray-800' :
                     isModelMissing ? 'bg-red-900' : 
                     isLoadingModel ? 'bg-yellow-500 animate-pulse' :
                     isListening ? 'bg-cyan-500 animate-pulse shadow-[0_0_8px_cyan]' : 
                     'bg-green-500'
                 }`}></div>

                 <div className="flex flex-col items-center justify-center leading-none">
                     {inputBuffer ? (
                         <span className="text-2xl font-mono font-bold text-orange-500 tracking-widest drop-shadow-sm">
                             {inputBuffer}
                         </span>
                     ) : (
                         <div className="flex flex-col items-center">
                            <span className={`font-mono text-xs font-bold uppercase tracking-wider ${
                                !match.config.enableVoice ? 'text-gray-800' :
                                isModelMissing ? 'text-red-600' :
                                isLoadingModel ? 'text-yellow-500' :
                                isListening ? 'text-cyan-400' : 
                                'text-gray-600'
                            }`}>
                                {!match.config.enableVoice ? "VOIX DESACTIVEE" :
                                 isModelMissing ? "IA NON DISPONIBLE" :
                                 isLoadingModel ? "INITIALISATION..." : 
                                 isListening ? (transcript || "LISTENING...") : 
                                 lastVoiceCommand ? `CMD: ${lastVoiceCommand}` : 
                                 "READY • LOCAL"}
                            </span>
                            {match.config.enableVoice && voiceError && !isModelMissing && <span className="text-[8px] text-red-500 font-bold uppercase">{voiceError}</span>}
                         </div>
                     )}
                 </div>
             </div>
             <div className="w-20 flex justify-end z-10">
                <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={handleUndo} 
                    disabled={match.currentLeg.history.length === 0} 
                    className="text-xs font-bold text-gray-400 hover:text-white px-0"
                >
                    UNDO ↶
                </Button>
             </div>
         </div>
         <div className="flex flex-1 px-2 pb-2 gap-2 min-h-0 pt-2">
            <div className="flex-1">
               <Keypad 
                 currentInput={inputBuffer}
                 onInput={handleInput}
                 onClear={handleClear}
                 onEnter={handleSubmitScore}
                 isCheckoutPossible={canCheckoutNow}
                 hasVoiceSupport={hasRecognitionSupport && match.config.enableVoice}
                 isModelMissing={isModelMissing}
                 onMicClick={handleMicClick}
                 isListening={isListening}
                 isLoadingModel={isLoadingModel}
                 quickShortcutsLeft={quickShortcuts.left}
                 quickShortcutsRight={quickShortcuts.right}
                 onQuickAction={handleQuickAction}
               />
            </div>
            <div className="w-[22%]">
               <Button 
                 className={`h-full w-full text-xl md:text-3xl font-black rounded-xl transition-all duration-200 ${canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'bg-gradient-to-b from-orange-500 to-red-600 shadow-lg shadow-orange-900/50' : 'bg-gray-800 text-gray-400'}`}
                 onClick={handleSubmitScore}
               >
                 {canCheckoutNow && parseInt(inputBuffer || '0') === currentScore ? 'OUT' : 'OK'}
               </Button>
            </div>
         </div>
      </div>

      {renderModals()}

      {showWinnerScreen && (
          <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
             <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-50">
                {[...Array(20)].map((_, i) => (
                    <div key={i} className="absolute w-2 h-2 bg-orange-500 rounded-full animate-pulse" 
                         style={{ 
                             top: `${Math.random() * 100}%`, 
                             left: `${Math.random() * 100}%`,
                             animationDelay: `${Math.random()}s`,
                             animationDuration: '2s'
                         }}></div>
                ))}
             </div>
             <h1 className="text-6xl md:text-8xl font-black italic text-transparent bg-clip-text bg-gradient-to-br from-orange-500 via-yellow-500 to-red-500 drop-shadow-[0_0_30px_rgba(234,88,12,0.8)] mb-4 text-center">
                 VAINQUEUR
             </h1>
             <div className="text-3xl md:text-5xl font-bold text-white mb-12 uppercase tracking-widest text-center border-b-4 border-orange-500 pb-4">
                 {match.matchWinnerId 
                    ? (match.players.find(p => p.teamId === match.matchWinnerId)?.name || 'Team')
                    : 'Unknown'
                 }
             </div>
             <div className="flex flex-col gap-4 w-full max-w-sm">
                 <Button onClick={handleGoToStats} size="lg" className="w-full h-20 text-2xl shadow-[0_0_20px_rgba(234,88,12,0.4)] animate-bounce">
                     SUIVANT ➔
                 </Button>
                 <div className="text-[10px] text-gray-600 text-center font-mono uppercase tracking-widest animate-pulse">
                     Auto-exit in 30s
                 </div>
             </div>
          </div>
      )}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      const teamPlayersLocal = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles 
        ? (teamId === 'team1' ? 'TEAM 1' : 'TEAM 2') 
        : teamPlayersLocal[0]?.name || 'Player';

      const isTeamActive = currentPlayer.teamId === teamId;
      const throwerName = isTeamActive && match.config.isDoubles ? currentPlayer.name : undefined;

      const calculateAvg = (turns: any[]) => {
          const score = turns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
          const darts = turns.reduce((acc, t) => acc + t.dartsThrown, 0);
          return darts > 0 ? ((score / darts) * 3).toFixed(1) : "0.0";
      };

      const legTurns = match.currentLeg.history.filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const legAvg = calculateAvg(legTurns);
      const legDarts = legTurns.reduce((acc, t) => acc + t.dartsThrown, 0);

      const allTurns = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });
      const matchAvg = calculateAvg(allTurns);

      const lastTurn = match.currentLeg.history.slice().reverse().find(t => {
          const p = match.players.find(pl => pl.id === t.playerId);
          return p?.teamId === teamId;
      });

      return (
        <PlayerScore 
            name={displayName}
            currentThrowerName={throwerName}
            score={match.currentLeg.scores[teamId]}
            isActive={isTeamActive}
            legsWon={match.legsWon[teamId]}
            setsWon={match.config.matchMode === 'SETS' ? match.setsWon[teamId] : undefined}
            stats={{
                matchAvg: matchAvg,
                legAvg: legAvg,
                legDarts: legDarts,
                lastScore: lastTurn?.score || null
            }}
        />
      );
  }

  function renderModals() {
      return (
          <>
            {showStarterSelection && (
                <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-6 uppercase">Bull Up</h2>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-lg mb-8">
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 1 First</div>
                            {team1Players.map(p => (
                                <Button key={p.id} variant={selectedT1StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT1StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                        <div className="space-y-2">
                            <div className="text-center text-orange-500 font-bold uppercase text-xs">Team 2 First</div>
                            {team2Players.map(p => (
                                <Button key={p.id} variant={selectedT2StarterId === p.id ? "primary" : "secondary"} onClick={() => setSelectedT2StarterId(p.id)} className="w-full py-3 text-sm">{p.name}</Button>
                            ))}
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 w-full max-w-md">
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team1')} className="border border-orange-600 text-orange-500">T1 STARTS</Button>
                        <Button variant="ghost" onClick={() => handleConfirmDoublesStart('team2')} className="border border-orange-600 text-orange-500">T2 STARTS</Button>
                    </div>
                </div>
            )}

            {pendingCheckoutScore !== null && (
                <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
                    <h2 className="text-3xl font-black italic text-white mb-8 uppercase">Game Shot!</h2>
                    <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Darts Used</p>
                    <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                        {[1, 2, 3].map(d => {
                            const minDarts = getMinDartsForScore(pendingCheckoutScore, match.config.checkOut);
                            const disabled = d < minDarts;
                            return (
                                <Button key={d} variant={disabled ? "secondary" : "primary"} onClick={() => !disabled && handleCheckoutConfirm(d)} className={`h-20 text-4xl ${disabled ? 'opacity-20' : ''}`} disabled={disabled}>{d}</Button>
                            )
                        })}
                    </div>
                    <div className="mt-8"><Button variant="ghost" onClick={() => setPendingCheckoutScore(null)}>Cancel</Button></div>
                </div>
            )}

            {showSettings && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-md border border-gray-700 max-h-[80vh] overflow-y-auto">
                    <h2 className="text-xl font-black text-white mb-6 text-center uppercase">Settings</h2>
                    <div className="flex justify-between items-center p-4 bg-gray-800 rounded-lg mb-4">
                        <span className="text-gray-300 font-bold text-sm">Checkout Hints</span>
                        <button onClick={() => setShowCheckoutHints(!showCheckoutHints)} className={`w-12 h-6 rounded-full relative transition-colors ${showCheckoutHints ? 'bg-orange-600' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showCheckoutHints ? 'left-7' : 'left-1'}`}></div>
                        </button>
                    </div>
                    <div className="bg-gray-800/50 rounded-lg p-4 border border-gray-700 mb-6">
                        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                             Quick Keys Config 
                             <span className="text-[9px] bg-gray-700 px-1 rounded text-gray-300">Tablet / Desktop</span>
                        </h3>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <div className="text-center text-[10px] text-cyan-500 font-bold uppercase">Left (20s Focus)</div>
                                {quickShortcuts.left.map((val, idx) => (
                                    <input 
                                        key={`L-conf-${idx}`}
                                        type="number"
                                        min="0"
                                        max="180"
                                        className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-center font-mono font-bold text-cyan-500 focus:border-cyan-500 focus:outline-none"
                                        value={val}
                                        onChange={(e) => updateShortcut('left', idx, e.target.value)}
                                    />
                                ))}
                            </div>
                            <div className="space-y-2">
                                <div className="text-center text-[10px] text-orange-500 font-bold uppercase">Right (19s Focus)</div>
                                {quickShortcuts.right.map((val, idx) => (
                                    <input 
                                        key={`R-conf-${idx}`}
                                        type="number"
                                        min="0"
                                        max="180"
                                        className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-center font-mono font-bold text-orange-500 focus:border-orange-500 focus:outline-none"
                                        value={val}
                                        onChange={(e) => updateShortcut('right', idx, e.target.value)}
                                    />
                                ))}
                            </div>
                        </div>
                    </div>
                    <Button className="w-full" onClick={() => setShowSettings(false)}>Close</Button>
                </div>
                </div>
            )}

            {showExitConfirm && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                    <h3 className="text-2xl font-black text-white mb-2 italic">QUIT MATCH?</h3>
                    <div className="grid grid-cols-2 gap-3 mt-8">
                        <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>No</Button>
                        <Button variant="danger" onClick={onExit}>Yes</Button>
                    </div>
                </div>
                </div>
            )}

            {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Match Stats" />}
          </>
      );
  }
};

import React from 'react';
import { Button } from '../ui/Button';

interface KeypadProps {
  onInput: (val: number) => void;
  onClear: () => void;
  onEnter: () => void;
  currentInput: string;
  isCheckoutPossible: boolean;
  // Voice Props
  onMicClick?: () => void;
  isListening?: boolean;
  isLoadingModel?: boolean;
  hasVoiceSupport?: boolean;
  isModelMissing?: boolean;
  // Quick Actions (New)
  quickShortcutsLeft?: number[];
  quickShortcutsRight?: number[];
  onQuickAction?: (val: number) => void;
}

export const Keypad: React.FC<KeypadProps> = ({ 
  onInput, 
  onClear, 
  onEnter, 
  currentInput, 
  isCheckoutPossible,
  onMicClick,
  isListening,
  isLoadingModel,
  hasVoiceSupport,
  isModelMissing,
  quickShortcutsLeft = [],
  quickShortcutsRight = [],
  onQuickAction
}) => {
  const keys = [1, 2, 3, 4, 5, 6, 7, 8, 9];

  return (
    <div className="h-full flex gap-2">

      {/* LEFT SHORTCUTS */}
