// Fix for error on line 52: reorderPlayersForDoubles was unfinished and missing required logic.
export const reorderPlayersForDoubles = (
    match: MatchState, 
    t1StarterId: string, 
    t2StarterId: string, 
    startingTeamId: string
): MatchState => {
    const getP = (id: string) => match.players.find(pl => pl.id === id)!;

    const t1Starter = getP(t1StarterId);
