                   <button key={num} onClick={() => matchMode === 'LEGS' ? setLegsToWin(num) : setSetsToWin(num)} className={`py-2 rounded font-bold text-sm border ${(matchMode === 'LEGS' ? legsToWin : setsToWin) === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>{num}</button>
