           </div>
           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Règle de sortie</label>
               <div className="flex p-1 bg-gray-800 rounded-lg mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button key={rule} onClick={() => setCheckOut(rule)} className={`flex-1 py-2 text-[10px] font-bold rounded ${checkOut === rule ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>{rule} Out</button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic">{getRuleDescription('out', checkOut)}</p>
           </div>
        </section>
      </div>

      <div className="mt-4">
        <Button onClick={handleStart} className="w-full py-5 text-2xl shadow-orange-900/20 uppercase">C'est parti !</Button>
