// Fixed calculateDetailedStats to include all necessary fields for UI
export const calculateDetailedStats = (match: MatchState, playerId: string) => {
  const p = match.players.find(pl => pl.id === playerId);
  if (!p) return null;
  const teamId = p.teamId;

  const allLegs = [...match.completedLegs, match.currentLeg];
  const allTurns = allLegs.flatMap(l => l.history).filter(t => t.playerId === playerId);
  const totalScore = allTurns.reduce((acc, t) => acc + (t.isBust ? 0 : t.score), 0);
  const totalDarts = allTurns.reduce((acc, t) => acc + t.dartsThrown, 0);
  const threeDartAvg = totalDarts > 0 ? ((totalScore / totalDarts) * 3).toFixed(1) : "0.0";

  // Highest Score in a turn
  const highestScore = allTurns.reduce((max, t) => Math.max(max, t.score), 0);

  // First 9 Avg: First 3 turns of each leg
  let f9S = 0;
  let f9D = 0;
  allLegs.forEach(l => {
      const playerTurnsInLeg = l.history.filter(t => t.playerId === playerId).slice(0, 3);
      playerTurnsInLeg.forEach(t => {
          if (!t.isBust) f9S += t.score;
          f9D += t.dartsThrown;
      });
  });
  const first9Avg = f9D > 0 ? ((f9S / f9D) * 3).toFixed(1) : "0.0";

  const winLegs = match.completedLegs.filter(l => l.winnerId === teamId);
  const highestCheckout = winLegs.reduce((max, l) => {
      const last = l.history[l.history.length-1];
      return (last && last.playerId === playerId && last.score > max) ? last.score : max;
  }, 0);

  const dartsPerWinLeg = winLegs.map(l => l.history.filter(t => t.playerId === playerId).reduce((acc, t) => acc + t.dartsThrown, 0));
  const bestLegDarts = dartsPerWinLeg.length > 0 ? Math.min(...dartsPerWinLeg) : null;
  const worstLegDarts = dartsPerWinLeg.length > 0 ? Math.max(...dartsPerWinLeg) : null;

  const scoreCounts = {
    c180: allTurns.filter(t => t.score === 180).length,
    c160: allTurns.filter(t => t.score >= 160 && t.score < 180).length,
    c140: allTurns.filter(t => t.score >= 140 && t.score < 160).length,
    c120: allTurns.filter(t => t.score >= 120 && t.score < 140).length,
    c100: allTurns.filter(t => t.score >= 100 && t.score < 120).length,
    c80: allTurns.filter(t => t.score >= 80 && t.score < 100).length,
    c60: allTurns.filter(t => t.score >= 60 && t.score < 80).length,
    c40: allTurns.filter(t => t.score >= 40 && t.score < 60).length,
  };

  return {
    threeDartAvg,
    first9Avg,
    checkoutPercent: "-", // Placeholder for checkout percentage
    highestCheckout,
    highestScore,
    bestLegDarts,
    worstLegDarts,
    scoreCounts,
    totalDarts
  };
};

