import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');
  const [currentTime, setCurrentTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const matchStatusRef = useRef(match.status);

  const { isListening, transcript, startListening, hasRecognitionSupport, resetTranscript, error: voiceError, isLoadingModel, isModelMissing } = useSpeechRecognition();

  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  useEffect(() => {
    matchStatusRef.current = match.status;
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      if (matchStatusRef.current === 'active') setElapsedSeconds(prev => prev + 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [match.status]);

  useEffect(() => {
      if (transcript && match.config.enableVoice) {
          const result = parseDartsVoiceCommand(transcript);
          if (result.type === 'SCORE' && result.value !== undefined) setInputBuffer(result.value.toString());
          else if (result.type === 'COMMAND_SUBMIT') { if (inputBuffer) handleSubmitScore(); }
          else if (result.type === 'COMMAND_CLEAR') setInputBuffer('');
          else if (result.type === 'COMMAND_UNDO') setMatch(undoTurn(match));
      }
  }, [transcript]);

  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 1500);
  };

  const processScoreSubmission = (score: number) => {
      if (isNaN(score) || score > 180) return triggerFeedback("INVALIDE", "bust");
      const currentPlayer = match.players[match.currentPlayerIndex];
      const currentScore = match.currentLeg.scores[currentPlayer.teamId];

      if (score === currentScore) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      let nextState = submitTurn(match, score, 3);
      if (nextState.status === 'finished') {
          setMatch({ ...nextState, duration: elapsedSeconds });
          setShowWinnerScreen(true);
          return;
      }

      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn?.isBust) triggerFeedback("TROP !", "bust");
      else if (score >= 100) triggerFeedback(score.toString(), "info");

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => inputBuffer && processScoreSubmission(parseInt(inputBuffer));
  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     if (nextState.status === 'finished') {
         setMatch({ ...nextState, duration: elapsedSeconds });
         setShowWinnerScreen(true);
     } else setMatch(nextState);
     setPendingCheckoutScore(null);
  };

  const currentPlayer = match.players[match.currentPlayerIndex];
  const teams = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">
      <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20">
        <div className="flex flex-col">
           <div className="font-black italic text-sm md:text-lg"><span className="text-white">BOUGNAT</span> <span className="text-orange-500">DARTS</span></div>
           <div className="text-[8px] md:text-[10px] font-mono text-gray-500 uppercase">Sortie: {match.config.checkOut}</div>
        </div>
        <div className="text-gray-400 font-mono text-sm">{currentTime}</div>
        <div className="flex gap-2">
            <button onClick={() => setShowStats(true)} className="text-[10px] font-bold uppercase border border-gray-700 px-2 py-1 rounded bg-gray-800">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 text-[10px] font-bold uppercase border border-red-900/30 px-2 py-1 rounded">Quitter</button>
        </div>
      </div>

      <div className="flex-1 relative flex items-stretch">
        {feedbackMessage && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
                <div className={`transform rotate-[-5deg] border-4 px-8 py-4 rounded-xl shadow-2xl ${feedbackMessage.type === 'bust' ? 'bg-red-600 border-red-400' : 'bg-cyan-600 border-cyan-400'}`}>
                    <h1 className="text-5xl font-black italic uppercase">{feedbackMessage.text}</h1>
                </div>
            </div>
        )}
        <div className="flex-1 border-r border-gray-800/50">{renderPlayerArea(teams[0])}</div>
        <div className="flex-1">{renderPlayerArea(teams[1])}</div>

        {/* Pilule Centrale de Score Relevée à bottom-32 */}
        <div className="absolute bottom-32 left-1/2 transform -translate-x-1/2 flex flex-col items-center z-20">
            <div className="bg-gray-900/95 backdrop-blur-md border border-gray-700 px-5 py-2 rounded-full shadow-[0_0_30px_rgba(0,0,0,0.5)] flex items-center space-x-4 mb-1">
                 {/* Team 1 */}
                 <div className="flex items-center gap-1.5">
                    <span className="text-orange-500 font-black text-2xl font-mono leading-none">
                        {match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]]}
                    </span>
                    {match.config.matchMode === 'SETS' && (
                        <span className="text-gray-500 font-mono text-xs font-bold">({match.legsWon[teams[0]]})</span>
                    )}
                 </div>

                 {/* Label Central */}
                 <span className="text-[10px] text-gray-600 font-black uppercase tracking-widest border-x border-gray-800 px-3 h-4 flex items-center">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>

                 {/* Team 2 */}
                 <div className="flex items-center gap-1.5">
                    {match.config.matchMode === 'SETS' && (
                        <span className="text-gray-500 font-mono text-xs font-bold">({match.legsWon[teams[1]]})</span>
                    )}
                    <span className="text-orange-500 font-black text-2xl font-mono leading-none">
                        {match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]]}
                    </span>
                 </div>
            </div>
            {/* Sous-badge d'objectif */}
            <div className="text-[9px] text-gray-500 font-bold bg-black/40 px-3 py-1 rounded-full border border-white/5 uppercase tracking-wider">
                {match.config.matchMode === 'SETS' 
                    ? `Premier à ${match.config.setsToWin} Sets (${match.config.legsToWin} Legs/Set)` 
                    : `Premier à ${match.config.legsToWin} Legs`}
            </div>
        </div>
      </div>

      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[40dvh] flex flex-col">
         <div className="h-12 bg-black/40 flex items-center justify-between px-4 border-b border-gray-800">
             <div className="text-[10px] font-bold text-gray-500 uppercase">
                {isListening ? "À l'écoute..." : (isLoadingModel ? "Initialisation IA..." : "Prêt")}
             </div>
             <div className="text-2xl font-mono font-bold text-orange-500 tracking-widest">{inputBuffer || "---"}</div>
             <button onClick={() => setMatch(undoTurn(match))} className="text-[10px] font-bold text-gray-500 uppercase">Annuler ↶</button>
         </div>
         <div className="flex-1 p-2 flex gap-2">
            <div className="flex-1">
               <Keypad currentInput={inputBuffer} onInput={v => setInputBuffer(prev => (prev+v).slice(0,3))} onClear={() => setInputBuffer('')} onEnter={handleSubmitScore} isCheckoutPossible={false} hasVoiceSupport={hasRecognitionSupport} isListening={isListening} onMicClick={startListening} />
            </div>
            <div className="w-24 flex flex-col gap-2">
                <Button className="flex-1 text-3xl font-black" onClick={handleSubmitScore}>OK</Button>
            </div>
         </div>
      </div>

      {showWinnerScreen && (
          <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
             <h1 className="text-6xl font-black italic text-orange-500 mb-4 text-center">VAINQUEUR</h1>
             <div className="text-3xl font-bold text-white mb-12 uppercase border-b-4 border-orange-500 pb-4 text-center">
                 {match.matchWinnerId ? (match.players.find(p => p.teamId === match.matchWinnerId)?.name) : ''}
             </div>
             <Button onClick={() => onFinishWithState ? onFinishWithState(match.matchWinnerId!, match) : onFinish(match.matchWinnerId!)} size="lg" className="w-full max-w-xs h-20 text-2xl uppercase">Voir les Stats ➔</Button>
          </div>
      )}

      {showExitConfirm && (
          <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                <h3 className="text-2xl font-black text-white mb-2 italic uppercase">Quitter le match ?</h3>
                <div className="grid grid-cols-2 gap-3 mt-8">
                    <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>NON</Button>
                    <Button variant="danger" onClick={onExit}>OUI</Button>
                </div>
            </div>
          </div>
      )}

      {pendingCheckoutScore !== null && (
          <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
              <h2 className="text-3xl font-black italic text-white mb-8 uppercase tracking-tighter">Game Shot !</h2>
              <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Fléchettes utilisées</p>
              <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                  {[1, 2, 3].map(d => (
                      <Button key={d} onClick={() => handleCheckoutConfirm(d)} className="h-20 text-4xl">{d}</Button>
                  ))}
              </div>
          </div>
      )}

      {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Statistiques" />}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      const isTeamActive = currentPlayer.teamId === teamId;
      const teamPlayers = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles ? (teamId === 'team1' ? 'ÉQUIPE 1' : 'ÉQUIPE 2') : teamPlayers[0]?.name;

      const calcAvg = (history: Turn[]) => {
          const s = history.reduce((a, t) => a + (t.isBust ? 0 : t.score), 0);
          const d = history.reduce((a, t) => a + t.dartsThrown, 0);
          return d > 0 ? ((s / d) * 3).toFixed(1) : "0.0";
      };

      const allHistory = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => match.players.find(pl => pl.id === t.playerId)?.teamId === teamId);

      return (
        <PlayerScore 
            name={displayName} 
            isActive={isTeamActive} 
            score={match.currentLeg.scores[teamId]} 
            legsWon={match.legsWon[teamId]}
            stats={{
                matchAvg: calcAvg(allHistory),
                legAvg: calcAvg(match.currentLeg.history.filter(t => match.players.find(pl => pl.id === t.playerId)?.teamId === teamId)),
                legDarts: match.currentLeg.history.filter(t => match.players.find(pl => pl.id === t.playerId)?.teamId === teamId).reduce((a, t) => a + t.dartsThrown, 0),
                lastScore: allHistory[allHistory.length-1]?.score || null
            }}
        />
      );
  }
};

import React from 'react';
import { Button } from '../ui/Button';

interface KeypadProps {
  onInput: (val: number) => void;
  onClear: () => void;
  onEnter: () => void;
  currentInput: string;
  isCheckoutPossible: boolean;
  // Voice Props
  onMicClick?: () => void;
  isListening?: boolean;
  isLoadingModel?: boolean;
  hasVoiceSupport?: boolean;
  isModelMissing?: boolean;
  isVoiceEnabled?: boolean; // Nouvelle prop
  // Quick Actions
  quickShortcutsLeft?: number[];
  quickShortcutsRight?: number[];
  onQuickAction?: (val: number) => void;
}

export const Keypad: React.FC<KeypadProps> = ({ 
  onInput, 
  onClear, 
  onEnter, 
  currentInput, 
  isCheckoutPossible,
  onMicClick,
  isListening,
  isLoadingModel,
  hasVoiceSupport,
  isModelMissing,
  isVoiceEnabled = true, // Par défaut activé pour compatibilité
  quickShortcutsLeft = [],
  quickShortcutsRight = [],
  onQuickAction
}) => {
  const keys = [1, 2, 3, 4, 5, 6, 7, 8, 9];

  // Le micro est désactivé si : pas de support navigateur, option décochée, chargement en cours, déjà à l'écoute, ou modèle manquant
  const isMicDisabled = !isVoiceEnabled || !hasVoiceSupport || isLoadingModel || isListening || isModelMissing;

  return (
    <div className="h-full flex gap-2">

      {/* LEFT SHORTCUTS */}
      {quickShortcutsLeft.length > 0 && (
        <div className="hidden md:flex flex-col gap-2 w-24 shrink-0">
           {quickShortcutsLeft.map((val, idx) => (
               <Button 
                  key={`L-${idx}`} 
                  variant="secondary" 
                  onClick={() => onQuickAction && onQuickAction(val)}
                  className="flex-1 text-xl font-black bg-gray-900/80 border-gray-800 text-cyan-500 hover:text-white hover:bg-cyan-900 hover:border-cyan-500/50 shadow-lg transition-all"
               >
                  {val}
               </Button>
           ))}
        </div>
      )}

      {/* CENTER NUMPAD */}
      <div className="flex-1 flex flex-col gap-2">
          <div className="flex-1 grid grid-cols-3 gap-2">
              {keys.map((k) => (
                <Button 
                  key={k} 
                  variant="secondary" 
                  onClick={() => onInput(k)}
                  className="text-2xl font-bold bg-gray-800 hover:bg-gray-700 border-gray-700 h-full shadow-inner active:scale-95 transition-transform"
                >
                  {k}
                </Button>
              ))}
          </div>
          <div className="h-1/4 grid grid-cols-3 gap-2">
              <Button variant="danger" onClick={onClear} className="h-full text-lg font-bold shadow-sm">C</Button>
              <Button variant="secondary" onClick={() => onInput(0)} className="h-full text-2xl font-bold bg-gray-800 border-gray-700 shadow-inner">0</Button>

              {/* Mic Button */}
              <button 
                  onClick={onMicClick}
                  disabled={isMicDisabled}
                  className={`
                    relative h-full w-full rounded flex items-center justify-center transition-all duration-300 overflow-hidden border
                    ${!isVoiceEnabled || !hasVoiceSupport
                        ? 'bg-gray-900 border-gray-800 opacity-20 cursor-not-allowed' 
                        : isModelMissing 
                            ? 'bg-gray-900 border-gray-800 opacity-50 cursor-not-allowed'
                            : isLoadingModel 
                                ? 'bg-gray-800 border-cyan-500/30 cursor-wait' 
                                : isListening
                                    ? 'bg-cyan-500 border-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.6)] scale-[0.98]'
                                    : 'bg-gradient-to-br from-cyan-600 to-blue-700 hover:from-cyan-500 hover:to-blue-600 border-transparent shadow-lg shadow-cyan-900/50'
                    }
                  `}
              >
                  {isListening && hasVoiceSupport && !isModelMissing && isVoiceEnabled && (
                      <div className="absolute inset-0 bg-cyan-400 animate-pulse opacity-50"></div>
                  )}

                  <div className={`relative z-10 ${!isVoiceEnabled || !hasVoiceSupport ? 'text-gray-700' : 'text-white'}`}>
                      {!isVoiceEnabled || !hasVoiceSupport ? (
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 opacity-50">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                          </svg>
                      ) : isModelMissing ? (
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 text-gray-600">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636" />
                          </svg>
                      ) : isLoadingModel ? (
                          <div className="w-6 h-6 border-2 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
                      ) : isListening ? (
                          <div className="flex items-center gap-1 h-4">
                              <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite] h-2"></div>
                              <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite_0.1s] h-4"></div>
                              <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite_0.2s] h-2"></div>
                          </div>
                      ) : (
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 drop-shadow-md">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                          </svg>
                      )}
                  </div>
              </button>
          </div>
      </div>

      {/* RIGHT SHORTCUTS */}
      {quickShortcutsRight.length > 0 && (
        <div className="hidden md:flex flex-col gap-2 w-24 shrink-0">
           {quickShortcutsRight.map((val, idx) => (
               <Button 
                  key={`R-${idx}`} 
                  variant="secondary" 
                  onClick={() => onQuickAction && onQuickAction(val)}
                  className="flex-1 text-xl font-black bg-gray-900/80 border-gray-800 text-orange-500 hover:text-white hover:bg-orange-900 hover:border-orange-500/50 shadow-lg transition-all"
               >
                  {val}
               </Button>
           ))}
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState, Turn } from '../types';
import { submitTurn, undoTurn, getMinDartsForScore, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');
  const [currentTime, setCurrentTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const matchStatusRef = useRef(match.status);

  const { isListening, transcript, startListening, hasRecognitionSupport, resetTranscript, error: voiceError, isLoadingModel, isModelMissing } = useSpeechRecognition();

  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  useEffect(() => {
    matchStatusRef.current = match.status;
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      if (matchStatusRef.current === 'active') setElapsedSeconds(prev => prev + 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [match.status]);

  useEffect(() => {
      if (transcript && match.config.enableVoice) {
          const result = parseDartsVoiceCommand(transcript);
          if (result.type === 'SCORE' && result.value !== undefined) setInputBuffer(result.value.toString());
          else if (result.type === 'COMMAND_SUBMIT') { if (inputBuffer) handleSubmitScore(); }
          else if (result.type === 'COMMAND_CLEAR') setInputBuffer('');
          else if (result.type === 'COMMAND_UNDO') setMatch(undoTurn(match));
      }
  }, [transcript]);

  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 1500);
  };

  const processScoreSubmission = (score: number) => {
      if (isNaN(score) || score > 180) return triggerFeedback("INVALIDE", "bust");
      const currentPlayer = match.players[match.currentPlayerIndex];
      const currentScore = match.currentLeg.scores[currentPlayer.teamId];

      if (score === currentScore) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      let nextState = submitTurn(match, score, 3);
      if (nextState.status === 'finished') {
          setMatch({ ...nextState, duration: elapsedSeconds });
          setShowWinnerScreen(true);
          return;
      }

      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn?.isBust) triggerFeedback("TROP !", "bust");
      else if (score >= 100) triggerFeedback(score.toString(), "info");

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => inputBuffer && processScoreSubmission(parseInt(inputBuffer));
  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     if (nextState.status === 'finished') {
         setMatch({ ...nextState, duration: elapsedSeconds });
         setShowWinnerScreen(true);
     } else setMatch(nextState);
     setPendingCheckoutScore(null);
  };

  const currentPlayer = match.players[match.currentPlayerIndex];
  const teams = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">
      <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20">
        <div className="flex flex-col">
           <div className="font-black italic text-sm md:text-lg"><span className="text-white">BOUGNAT</span> <span className="text-orange-500">DARTS</span></div>
           <div className="text-[8px] md:text-[10px] font-mono text-gray-500 uppercase">Sortie: {match.config.checkOut}</div>
        </div>
        <div className="text-gray-400 font-mono text-sm">{currentTime}</div>
        <div className="flex gap-2">
