                    ERREUR: {error}
                </div>
            )}

            <div className="flex gap-4">
                <Button 
                    onClick={startListening} 
                    disabled={isListening || isLoadingModel}
                    className={`flex-1 ${isListening ? 'opacity-50' : ''}`}
                >
                    {isModelLoaded ? (isListening ? 'Écoute en cours...' : 'Démarrer le Micro') : 'Charger Modèle & Micro'}
