import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView';
import { ProfileView } from './views/ProfileView';
import { HistoryView } from './views/HistoryView'; 
import { MyStatsView } from './views/MyStatsView'; 
import { SettingsView } from './views/SettingsView'; // New Import
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { VoiceLoaderView } from './views/VoiceLoaderView'; 
import { GameConfig, Player, MatchState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'PROFILE' | 'HISTORY' | 'MY_STATS' | 'SETTINGS' | 'GAME_SELECTION' | 'SETUP' | 'LOADING_AI' | 'MATCH' | 'STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    if (type === 'X01') {
      setSelectedGameType(type);
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  const handleStartSetup = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);

    if (config.enableVoice) {
        setScreen('LOADING_AI');
    } else {
        setScreen('MATCH');
    }
  };

  const handleAiLoaded = () => {
      setScreen('MATCH');
  };

  const handleMatchFinish = (winnerId: string) => {
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch);

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  const handleExitMatch = () => {
    exitFullScreen();
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleRematch = () => {
      if (!currentMatch) return;

      const newMatch = createMatch(currentMatch.players, currentMatch.config);
      setCurrentMatch(newMatch);
      enterFullScreen();
      setScreen('MATCH');
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => setScreen('HISTORY')}
              onStats={() => setScreen('MY_STATS')}
              onProfile={() => setScreen('PROFILE')}
              onSettings={() => setScreen('SETTINGS')}
              onLogout={handleLogout}
          />
      )}

      {screen === 'PROFILE' && user && (
          <ProfileView 
              user={user}
              onBack={() => setScreen('DASHBOARD')}
              onUpdateUser={(updatedUser) => setUser(updatedUser)}
          />
      )}

      {screen === 'HISTORY' && user && (
          <HistoryView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'MY_STATS' && user && (
          <MyStatsView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'SETTINGS' && (
          <SettingsView 
             onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          onStart={handleStartSetup} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {screen === 'LOADING_AI' && (
         <VoiceLoaderView 
            onLoaded={handleAiLoaded}
            onSkip={handleAiLoaded}
         />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={() => { setScreen(user ? 'DASHBOARD' : 'HOME'); setCurrentMatch(null); }}
          onRematch={handleRematch}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '../components/ui/Button';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface SettingsViewProps {
  onBack: () => void;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ onBack }) => {
  const { 
    isListening, 
    transcript, 
    startListening, 
    stopListening, 
    resetTranscript, 
    error, 
    isLoadingModel, 
    isModelLoaded, 
    isModelMissing,
    logs 
  } = useSpeechRecognition();

  const [parsedResult, setParsedResult] = useState<string>('');
  const [manualInput, setManualInput] = useState('');
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Real-time parsing test
  useEffect(() => {
    if (transcript) {
        const result = parseDartsVoiceCommand(transcript);
        if (result.type === 'SCORE') {
            setParsedResult(`🎯 SCORE DETECTÉ: ${result.value} pts (${JSON.stringify(result.darts || [])})`);
        } else if (result.type === 'UNKNOWN') {
             setParsedResult(`❓ INCONNU (Raison: ${result.reason || 'No match'})`);
        } else {
             setParsedResult(`⚡ COMMANDE: ${result.type}`);
        }
    } else {
        setParsedResult('En attente de parole...');
    }
  }, [transcript]);

  const handleManualTest = () => {
      const result = parseDartsVoiceCommand(manualInput);
      alert(JSON.stringify(result, null, 2));
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      {/* HEADER */}
      <div className="flex items-center mb-6 shrink-0">
        <Button variant="ghost" onClick={() => { stopListening(); onBack(); }} size="sm">← Retour</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400 uppercase">
            PARAMÈTRES & DEBUG
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto space-y-8 max-w-4xl mx-auto w-full pb-10">

        {/* SECTION 1: VOICE ENGINE STATUS */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-orange-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                1. État du Moteur Vocal (Vosk)
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                <StatusBadge label="Modèle Chargé" active={isModelLoaded} error={isModelMissing} />
                <StatusBadge label="Microphone Actif" active={isListening} error={!!error} />
                <StatusBadge label="Chargement en cours" active={isLoadingModel} warning />
            </div>

            {error && (
                <div className="bg-red-900/50 border border-red-500/50 text-red-200 p-3 rounded mb-4 font-mono text-xs">
                    ERREUR: {error}
                </div>
            )}

            <div className="flex gap-4">
                <Button 
                    onClick={startListening} 
                    disabled={isListening || isLoadingModel}
                    className={`flex-1 ${isListening ? 'opacity-50' : ''}`}
                >
                    {isModelLoaded ? (isListening ? 'Écoute en cours...' : 'Démarrer le Micro') : 'Charger Modèle & Micro'}
                </Button>

                <Button 
                    variant="secondary"
                    onClick={stopListening}
                    disabled={!isListening}
                >
                    Stop
                </Button>
                 <Button 
                    variant="ghost"
                    onClick={resetTranscript}
                >
                    Reset Texte
                </Button>
            </div>
        </section>

        {/* SECTION 2: LIVE TRANSCRIPT */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6 relative overflow-hidden">
             <h3 className="text-cyan-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                2. Test de Reconnaissance
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="text-xs text-gray-500 uppercase font-bold">Transcription Brute (Ce que l'IA entend)</label>
                    <div className="min-h-[60px] bg-black/50 border border-gray-600 rounded p-4 font-mono text-lg text-white mt-1">
                        {transcript || <span className="text-gray-600 italic">...silence...</span>}
                    </div>
                </div>

                <div>
                    <label className="text-xs text-gray-500 uppercase font-bold">Interprétation Jeu (Parsing)</label>
                    <div className={`min-h-[40px] border rounded p-3 font-mono font-bold mt-1 ${parsedResult.includes('SCORE') ? 'bg-green-900/20 border-green-600 text-green-400' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>
                        {parsedResult}
                    </div>
                </div>
            </div>
        </section>

        {/* SECTION 3: PARSER TESTER */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-purple-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                3. Testeur de Syntaxe (Texte)
            </h3>
            <p className="text-xs text-gray-400 mb-4">Testez si vos phrases sont correctement comprises par le moteur de jeu, indépendamment du micro.</p>
            <div className="flex gap-2">
                <input 
                    type="text" 
                    value={manualInput}
                    onChange={(e) => setManualInput(e.target.value)}
                    placeholder="Ex: triple vingt double dix"
                    className="flex-1 bg-gray-900 border border-gray-600 rounded px-4 py-2 text-white font-mono"
                />
                <Button variant="secondary" onClick={handleManualTest}>Tester</Button>
            </div>
        </section>

        {/* SECTION 4: SYSTEM LOGS */}
        <section className="bg-black border border-gray-800 rounded-xl p-4 font-mono text-[10px] md:text-xs">
            <h3 className="text-gray-500 font-bold uppercase tracking-widest mb-2">Logs Système</h3>
            <div className="h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                {logs.length === 0 && <div className="text-gray-600">Aucun log pour le moment.</div>}
                {logs.map((log, i) => (
                    <div key={i} className={`${log.includes('Err') || log.includes('FATAL') ? 'text-red-500' : log.includes('WARN') ? 'text-yellow-500' : 'text-green-500/80'}`}>
                        {log}
                    </div>
                ))}
                <div ref={logsEndRef} />
            </div>
        </section>

      </div>
    </div>
  );
};

const StatusBadge = ({ label, active, error, warning }: any) => (
    <div className={`flex items-center justify-between p-3 rounded border ${
        error ? 'bg-red-900/20 border-red-800' : 
        warning && active ? 'bg-yellow-900/20 border-yellow-800' :
        active ? 'bg-green-900/20 border-green-800' : 
        'bg-gray-800 border-gray-700'
    }`}>
        <span className="text-xs font-bold uppercase text-gray-400">{label}</span>
        <div className={`w-3 h-3 rounded-full ${
             error ? 'bg-red-500' : 
             warning && active ? 'bg-yellow-500 animate-pulse' :
             active ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 
             'bg-gray-600'
        }`}></div>
    </div>
);

