          {showQr && (
            <div className="bg-white p-2 rounded-xl shadow-[0_0_30px_rgba(255,255,255,0.15)] animate-in fade-in zoom-in duration-300">
                <img 
                    src={qrUrl} 
                    alt="Scan to open App" 
                    className="w-32 h-32 md:w-40 md:h-40"
                    loading="lazy"
                />
            </div>
          )}
      </div>

      {/* Footer Info & Connection Status */}
      <div className="text-gray-600 text-[10px] text-center font-mono shrink-0 flex flex-col items-center gap-2">
        <p>Powered by DartMaster Engine • v1.1.0</p>

        {/* DB Status Indicator */}
        <div className="flex items-center gap-2 bg-gray-900/50 px-3 py-1 rounded-full border border-gray-800">
            <div className={`w-2 h-2 rounded-full ${
                dbStatus === 'checking' ? 'bg-yellow-500 animate-pulse' :
                dbStatus === 'ok' ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.6)]' :
                'bg-red-500'
            }`}></div>
            <span className="uppercase tracking-widest font-bold text-[9px] text-gray-500">
                {dbStatus === 'checking' ? 'CONNECTING...' :
                 dbStatus === 'ok' ? 'SYSTEM ONLINE' : 
                 'OFFLINE MODE'}
            </span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView';
import { ProfileView } from './views/ProfileView';
import { HistoryView } from './views/HistoryView'; 
import { MyStatsView } from './views/MyStatsView'; 
import { SettingsView } from './views/SettingsView'; // New Import
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { VoiceLoaderView } from './views/VoiceLoaderView'; 
import { GameConfig, Player, MatchState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'PROFILE' | 'HISTORY' | 'MY_STATS' | 'SETTINGS' | 'GAME_SELECTION' | 'SETUP' | 'LOADING_AI' | 'MATCH' | 'STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    if (type === 'X01') {
      setSelectedGameType(type);
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  const handleStartSetup = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);

    if (config.enableVoice) {
        setScreen('LOADING_AI');
    } else {
        setScreen('MATCH');
    }
  };

  const handleAiLoaded = () => {
      setScreen('MATCH');
  };

  const handleMatchFinish = (winnerId: string) => {
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch);

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  const handleExitMatch = () => {
    exitFullScreen();
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleRematch = () => {
      if (!currentMatch) return;

      const newMatch = createMatch(currentMatch.players, currentMatch.config);
      setCurrentMatch(newMatch);
      enterFullScreen();
      setScreen('MATCH');
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
          onSettings={() => setScreen('SETTINGS')}
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => setScreen('HISTORY')}
              onStats={() => setScreen('MY_STATS')}
              onProfile={() => setScreen('PROFILE')}
              onSettings={() => setScreen('SETTINGS')}
              onLogout={handleLogout}
          />
      )}

      {screen === 'PROFILE' && user && (
          <ProfileView 
              user={user}
              onBack={() => setScreen('DASHBOARD')}
              onUpdateUser={(updatedUser) => setUser(updatedUser)}
          />
      )}

      {screen === 'HISTORY' && user && (
          <HistoryView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'MY_STATS' && user && (
          <MyStatsView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'SETTINGS' && (
          <SettingsView 
             onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          onStart={handleStartSetup} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {screen === 'LOADING_AI' && (
         <VoiceLoaderView 
            onLoaded={handleAiLoaded}
            onSkip={handleAiLoaded}
         />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={() => { setScreen(user ? 'DASHBOARD' : 'HOME'); setCurrentMatch(null); }}
          onRematch={handleRematch}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  activeMicrophone: string | null; // New field
  logs: string[];
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);
  const [activeMicLabel, setActiveMicLabel] = useState<string | null>(null);

  const [logs, setLogs] = useState<string[]>([]);

  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      setLogs(prev => [...prev, `[${time}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
      const initVoiceEngine = async () => {
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          setIsLoadingModel(true);
          setError(null);

          globalModelLoadingPromise = (async () => {
            try {
                // Utilisation du lien Raw GitHub correct
                const modelUrl = "https://raw.githubusercontent.com/floriangiral/Bougnat_darts_counter/main/public/models/vosk-model-small-fr-0.22.zip";

                addLog(`Step 1: Loading Model from ${modelUrl}...`);

                const response = await fetch(modelUrl);
                if (!response.ok) {
                    throw new Error(`HTTP Error: ${response.status} (File not found?)`);
                }

                const blob = await response.blob();
                const contentType = blob.type;
                // Vérification basique pour s'assurer qu'on n'a pas reçu une page 404 HTML
                if (contentType && (contentType.includes("text/html") || contentType.includes("application/json"))) {
                     throw new Error("Invalid file received. Check if file exists in public/models/.");
                }

                addLog(`Step 2: Loading Engine...`);
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Engine Import Timeout")), 15000))
                ]);

                if (!VoskModule) throw new Error("Module failed to load");
                globalVoskModule = VoskModule;

                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Step 3: Extracting...`);

                const modelPromise = createModel(URL.createObjectURL(blob));
                const model = await Promise.race([
                    modelPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Model Extraction Timeout")), 60000))
                ]);

                globalModel = model;

                addLog("SUCCESS: Voice Engine Ready.");
                return model;

            } catch (e: any) {
                addLog(`FATAL: ${e.message}`);
                console.error(e);
                throw e; 
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
          } catch (e: any) {
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
          } finally {
              setIsLoadingModel(false); 
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog]);


  // --- RUNTIME LOGIC ---
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (recognizerRef.current) {
        try {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setActiveMicLabel(null);
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    if (!globalModel) {
        addLog("Err: Model missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        // FIXED: Ensure AudioContext is properly resumed
        if (audioContext.state === 'suspended') {
            await audioContext.resume();
        }

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1
            }
        });
        mediaStreamRef.current = stream;

        // Extract Microphone Label
        const track = stream.getAudioTracks()[0];
        if (track) {
            setActiveMicLabel(track.label);
            addLog(`Mic: ${track.label}`);
        } else {
            setActiveMicLabel("Default Device");
        }

        // FIXED: Use context sample rate
        const actualSampleRate = audioContext.sampleRate;
        addLog(`Rate: ${actualSampleRate}Hz`);

        let recognizer;
        try {
            // Tentative avec grammaire stricte
            const grammar = JSON.stringify(getDartsGrammar());
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate, grammar);
        } catch (grammarErr) {
            console.warn("Grammar failed (likely unknown words), falling back to default dict.", grammarErr);
            addLog("Warn: Grammar fallback");
            // Repli sur le dictionnaire complet si la grammaire échoue
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
        }

        recognizer.on("result", (message: any) => {
            const result = message.result;
            if (result && result.text) {
                console.log("Result:", result.text);
                setTranscript(result.text);
                // On garde l'écoute active pour enchaîner ou on stop ?
                // Ici on stop après une phrase complète pour éviter le bruit
                stopListeningInternal(); 
            }
        });

        recognizer.on("partialresult", (message: any) => {
             const partial = message.result?.partial;
             if (partial) {
                 setTranscript(partial);
             }
        });

        recognizerRef.current = recognizer;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processor.onaudioprocess = (event) => {
            if (recognizerRef.current && isListening) { 
                try {
                    if (recognizerRef.current.acceptWaveform) {
                        recognizerRef.current.acceptWaveform(event.inputBuffer);
                    }
                } catch (err) {
                   // ignore
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);
        processorRef.current = processor;

        setIsListening(true);
        addLog("Listening...");

        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            addLog("Timeout (Silence)");
            stopListening();
        }, 8000);

    } catch (err: any) {
        setError("Mic Blocked");
        addLog(`Mic Error: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening, isListening]); // Added isListening dep to be safe, though usually handled via ref

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    activeMicrophone: activeMicLabel,
    logs
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '../components/ui/Button';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface SettingsViewProps {
  onBack: () => void;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ onBack }) => {
  const { 
    isListening, 
    transcript, 
    startListening, 
    stopListening, 
    resetTranscript, 
    error, 
    isLoadingModel, 
    isModelLoaded, 
    isModelMissing,
    activeMicrophone,
    logs 
  } = useSpeechRecognition();

  const [parsedResult, setParsedResult] = useState<string>('');
  const [manualInput, setManualInput] = useState('');
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Real-time parsing test
  useEffect(() => {
    if (transcript) {
        const result = parseDartsVoiceCommand(transcript);
        if (result.type === 'SCORE') {
            setParsedResult(`🎯 SCORE DETECTÉ: ${result.value} pts (${JSON.stringify(result.darts || [])})`);
        } else if (result.type === 'UNKNOWN') {
             setParsedResult(`❓ INCONNU (Raison: ${result.reason || 'No match'})`);
        } else {
             setParsedResult(`⚡ COMMANDE: ${result.type}`);
        }
    } else {
        setParsedResult('En attente de parole...');
    }
  }, [transcript]);

  const handleManualTest = () => {
      const result = parseDartsVoiceCommand(manualInput);
      alert(JSON.stringify(result, null, 2));
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      {/* HEADER */}
      <div className="flex items-center mb-6 shrink-0">
        <Button variant="ghost" onClick={() => { stopListening(); onBack(); }} size="sm">← Retour</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400 uppercase">
            PARAMÈTRES & DEBUG
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto space-y-8 max-w-4xl mx-auto w-full pb-10">

        {/* SECTION 1: VOICE ENGINE STATUS */}
