                <div className="mb-4 p-3 bg-black/40 border border-gray-700 rounded flex items-center justify-between">
                    <span className="text-gray-500 text-xs font-bold uppercase tracking-wider">Source Audio</span>
                    <span className="text-cyan-400 font-mono text-xs md:text-sm font-bold truncate max-w-[200px] md:max-w-none">
                        {activeMicrophone}
