import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  activeMicrophone: string | null;
  audioLevel: number; // 0 to 100
  logs: string[];
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);
  const [activeMicLabel, setActiveMicLabel] = useState<string | null>(null);
  const [audioLevel, setAudioLevel] = useState(0); // RMS Level

  const [logs, setLogs] = useState<string[]>([]);

  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const audioLevelRequestRef = useRef<number | null>(null); // For RAF throttling

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      setLogs(prev => [...prev, `[${time}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
      const initVoiceEngine = async () => {
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          setIsLoadingModel(true);
          setError(null);

          globalModelLoadingPromise = (async () => {
            try {
                const modelUrl = "https://raw.githubusercontent.com/floriangiral/Bougnat_darts_counter/main/public/models/vosk-model-small-fr-0.22.zip";

                addLog(`Step 1: Loading Model...`);

                const response = await fetch(modelUrl);
                if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

                const blob = await response.blob();

                addLog(`Step 2: Loading Engine...`);
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Engine Import Timeout")), 15000))
                ]);

                if (!VoskModule) throw new Error("Module failed to load");
                globalVoskModule = VoskModule;

                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Step 3: Extracting...`);

                const modelPromise = createModel(URL.createObjectURL(blob));
                const model = await Promise.race([
                    modelPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Model Extraction Timeout")), 60000))
                ]);

                globalModel = model;
                addLog("SUCCESS: Voice Engine Ready.");
                return model;

            } catch (e: any) {
                addLog(`FATAL: ${e.message}`);
                console.error(e);
                throw e; 
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
          } catch (e: any) {
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
          } finally {
              setIsLoadingModel(false); 
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog]);


  // --- RUNTIME LOGIC ---
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (recognizerRef.current) {
        try {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    if (audioLevelRequestRef.current) {
        cancelAnimationFrame(audioLevelRequestRef.current);
        audioLevelRequestRef.current = null;
    }
    setActiveMicLabel(null);
    setAudioLevel(0);
    setIsListening(false);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    if (!globalModel) {
        addLog("Err: Model missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass();
        audioContextRef.current = audioContext;

        await audioContext.resume(); // Ensure context is running

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                autoGainControl: true, 
                channelCount: 1
            }
        });
        mediaStreamRef.current = stream;

        // Extract Microphone Label
        const track = stream.getAudioTracks()[0];
        setActiveMicLabel(track ? track.label : "Default Device");
        addLog(`Mic: ${track ? track.label : "Unknown"}`);

        const actualSampleRate = audioContext.sampleRate;
        addLog(`Rate: ${actualSampleRate}Hz`);

        // Initialize Recognizer
        let recognizer;
        try {
            const grammar = JSON.stringify(getDartsGrammar());
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate, grammar);
        } catch (grammarErr) {
            addLog("Warn: Grammar fallback");
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
        }

        recognizer.on("result", (message: any) => {
            if (message.result && message.result.text) {
                console.log("Result:", message.result.text);
                setTranscript(message.result.text);
                // Optional: Stop after command? 
                // stopListeningInternal(); 
            }
        });

        recognizer.on("partialresult", (message: any) => {
             if (message.result?.partial) setTranscript(message.result.partial);
        });

        recognizerRef.current = recognizer;

        // Audio Graph
        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;
        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processorRef.current = processor;

        let skipFrame = 0;

        processor.onaudioprocess = (event) => {
            const inputData = event.inputBuffer.getChannelData(0);

            // 1. RMS Calculation (Audio Level)
            // Throttle calculation to save CPU (every 4th chunk roughly)
            if (skipFrame++ % 3 === 0) {
                 let sum = 0;
                 // Sub-sample buffer for speed
                 for (let i = 0; i < inputData.length; i += 10) {
                     sum += inputData[i] * inputData[i];
                 }
                 const rms = Math.sqrt(sum / (inputData.length / 10));
                 const level = Math.min(100, Math.round(rms * 1000)); // Amplify for visibility

                 // Update state safely via ref throttling logic if needed, 
                 // here we just rely on React batching but could use RAF.
                 setAudioLevel(level);
            }

            // 2. Feed Recognizer
            if (recognizerRef.current && isListening) { 
                try {
                    recognizerRef.current.acceptWaveform(event.inputBuffer);
                } catch (err) {
                   // ignore buffer errors
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination); // Required for Chrome to fire events

        setIsListening(true);
        addLog("Listening (Audio Graph Built)...");

        // Timeout
        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            addLog("Timeout (Max Duration)");
            stopListening();
        }, 10000);

    } catch (err: any) {
        setError("Mic Blocked/Fail");
        addLog(`Start Err: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening, isListening]);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    activeMicrophone: activeMicLabel,
    audioLevel, // New
    logs
  };
};

