import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  activeMicrophone: string | null;
  audioLevel: number;
  logs: string[];
  isStrictGrammar: boolean;
  toggleGrammar: () => void;
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasSupport, setHasSupport] = useState(true);

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);
  const [activeMicLabel, setActiveMicLabel] = useState<string | null>(null);
  const [audioLevel, setAudioLevel] = useState(0); 
  const [isStrictGrammar, setIsStrictGrammar] = useState(true); // Default to True for better accuracy

  const [logs, setLogs] = useState<string[]>([]);

  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isListeningRef = useRef(false);

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      setLogs(prev => [...prev, `[${time}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  const toggleGrammar = useCallback(() => {
      setIsStrictGrammar(prev => !prev);
      if (isListening) {
          addLog("Configuration changed: Restarting listener...");
          stopListeningInternal();
      }
  }, [isListening, addLog]);

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
      const initVoiceEngine = async () => {
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          setIsLoadingModel(true);
          setError(null);

          globalModelLoadingPromise = (async () => {
            try {
                const modelUrl = "https://raw.githubusercontent.com/floriangiral/Bougnat_darts_counter/main/public/models/vosk-model-small-fr-0.22.zip";

                addLog(`Step 1: Loading Model...`);
                const response = await fetch(modelUrl);
                if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);
                const blob = await response.blob();

                addLog(`Step 2: Loading Engine...`);
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Engine Import Timeout")), 15000))
                ]);

                if (!VoskModule) throw new Error("Module failed to load");
                globalVoskModule = VoskModule;

                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Step 3: Extracting...`);

                const modelPromise = createModel(URL.createObjectURL(blob));
                const model = await Promise.race([
                    modelPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Model Extraction Timeout")), 60000))
                ]);

                globalModel = model;
                addLog("SUCCESS: Voice Engine Ready.");
                return model;

            } catch (e: any) {
                addLog(`FATAL: ${e.message}`);
                console.error(e);
                throw e; 
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
          } catch (e: any) {
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
          } finally {
              setIsLoadingModel(false); 
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog]);


  // --- RUNTIME LOGIC ---
  const stopListeningInternal = () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (recognizerRef.current) {
        try {
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setActiveMicLabel(null);
    setAudioLevel(0);
    setIsListening(false);
    isListeningRef.current = false;
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  const startListening = useCallback(async () => {
    if (!globalModel) {
        addLog("Err: Model missing");
        return;
    }

    setTranscript(''); 
    setError(null);

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;

        // CRITICAL FIX: Force 16kHz context to match hardware and Vosk model
        // This prevents browser upsampling artifacts
        let audioContext;
        try {
            audioContext = new AudioContextClass({ sampleRate: 16000 });
        } catch (e) {
            console.warn("Could not force 16kHz context, fallback to default", e);
            audioContext = new AudioContextClass();
        }
        audioContextRef.current = audioContext;

        await audioContext.resume();

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                // Disable software processing (Echo/Noise) to trust the Jabra hardware
                echoCancellation: false,
                noiseSuppression: false,
                autoGainControl: false, 
                channelCount: 1,
                sampleRate: 16000 // Hint for the browser
            }
        });
        mediaStreamRef.current = stream;

        const track = stream.getAudioTracks()[0];
        setActiveMicLabel(track ? track.label : "Default Device");
        addLog(`Mic: ${track ? track.label : "Unknown"}`);

        const actualSampleRate = audioContext.sampleRate;
        addLog(`Rate: ${actualSampleRate}Hz (Req: 16k) | Mode: ${isStrictGrammar ? 'STRICT' : 'FREE'}`);

        // Initialize Recognizer
        let recognizer;
        try {
            if (isStrictGrammar) {
                const grammar = JSON.stringify(getDartsGrammar());
                recognizer = new globalModel.KaldiRecognizer(actualSampleRate, grammar);
            } else {
                recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
            }
        } catch (grammarErr) {
            addLog("Warn: Grammar Config failed, fallback to default");
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
        }

        recognizer.on("result", (message: any) => {
            if (message.result && message.result.text) {
                const txt = message.result.text;
                if (txt) {
                    addLog(`RAW: "${txt}"`);
                    setTranscript(txt);
                }
            }
        });

        // Optional: Partial results for faster visual feedback
        recognizer.on("partialresult", (message: any) => {
             // if (message.result?.partial) setTranscript(message.result.partial);
        });

        recognizerRef.current = recognizer;

        // Audio Graph
        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;

        // Buffer size optimized for 16kHz (4096 samples = ~250ms)
        // Can try 2048 if latency is too high, but 4096 is safer for web workers
        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processorRef.current = processor;

        let skipFrame = 0;

        processor.onaudioprocess = (event) => {
            const inputData = event.inputBuffer.getChannelData(0);

            // 1. RMS Level Calculation
            if (skipFrame++ % 2 === 0) { // Faster update check
                 let sum = 0;
                 for (let i = 0; i < inputData.length; i += 5) { // Check more samples
                     sum += inputData[i] * inputData[i];
                 }
                 const rms = Math.sqrt(sum / (inputData.length / 5));
                 setAudioLevel(Math.min(100, Math.round(rms * 1500))); // Higher gain on visual
            }

            // 2. Feed Recognizer
            if (recognizerRef.current && isListeningRef.current) { 
                try {
                    recognizerRef.current.acceptWaveform(event.inputBuffer);
                } catch (err) {
                   // ignore buffer errors
                }
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);

        setIsListening(true);
        isListeningRef.current = true;
        addLog("Listening (16kHz Pure Audio)...");

        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            addLog("Timeout (Max Duration)");
            stopListening();
        }, 15000); // Extended timeout

    } catch (err: any) {
        setError("Mic Blocked/Fail");
        addLog(`Start Err: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening, isStrictGrammar]);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: hasSupport,
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    activeMicrophone: activeMicLabel,
    audioLevel,
    logs,
    isStrictGrammar,
    toggleGrammar
  };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { getDartsGrammar } from '../utils/voiceParser';

// --- SINGLETONS (Module Level) ---
let globalModel: any = null;
let globalModelLoadingPromise: Promise<any> | null = null;
let globalVoskModule: any = null;

export type EngineType = 'NATIVE' | 'VOSK';

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  isLoadingModel: boolean;
  isModelLoaded: boolean;
  isModelMissing: boolean;
  activeMicrophone: string | null;
  audioLevel: number;
  logs: string[];
  isStrictGrammar: boolean;
  toggleGrammar: () => void;
  engine: EngineType;
  setEngine: (e: EngineType) => void;
  isNativeSupported: boolean;
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Engine State
  const isNativeSupported = typeof window !== 'undefined' && (!!(window as any).SpeechRecognition || !!(window as any).webkitSpeechRecognition);
  const [engine, setEngine] = useState<EngineType>(isNativeSupported ? 'NATIVE' : 'VOSK');

  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [isModelLoaded, setIsModelLoaded] = useState(!!globalModel);
  const [isModelMissing, setIsModelMissing] = useState(false);
  const [activeMicLabel, setActiveMicLabel] = useState<string | null>(null);
  const [audioLevel, setAudioLevel] = useState(0); 
  const [isStrictGrammar, setIsStrictGrammar] = useState(true);

  const [logs, setLogs] = useState<string[]>([]);

  // Refs for VOSK
  const recognizerRef = useRef<any>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  // Refs for NATIVE
  const nativeRecognitionRef = useRef<any>(null);

  const silenceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isListeningRef = useRef(false);

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      setLogs(prev => [...prev, `[${time}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  const toggleGrammar = useCallback(() => {
      setIsStrictGrammar(prev => !prev);
      if (isListening) {
          addLog("Config changed: Restarting...");
          stopListening();
          // Timeout to allow cleanup before restart, tricky in React effect loop, user manual restart is safer
      }
  }, [isListening, addLog]);

  // --- VOSK INIT LOGIC (Only runs if needed) ---
  useEffect(() => {
      if (engine === 'NATIVE') return; // Don't load Vosk if using Native

      const initVoiceEngine = async () => {
          if (globalModel) {
              setIsModelLoaded(true);
              setIsLoadingModel(false);
              return;
          }

          if (globalModelLoadingPromise) {
              setIsLoadingModel(true);
              try {
                  await globalModelLoadingPromise;
                  setIsModelLoaded(true);
              } catch (e) {
                  setIsModelMissing(true);
                  setError("Load Failed");
              } finally {
                  setIsLoadingModel(false);
              }
              return;
          }

          setIsLoadingModel(true);
          setError(null);

          globalModelLoadingPromise = (async () => {
            try {
                const modelUrl = "https://raw.githubusercontent.com/floriangiral/Bougnat_darts_counter/main/public/models/vosk-model-small-fr-0.22.zip";

                addLog(`Step 1: Loading Model...`);
                const response = await fetch(modelUrl);
                if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);
                const blob = await response.blob();

                addLog(`Step 2: Loading Engine...`);
                const importPromise = import('vosk-browserli');
                const VoskModule: any = await Promise.race([
                    importPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Engine Import Timeout")), 15000))
                ]);

                if (!VoskModule) throw new Error("Module failed to load");
                globalVoskModule = VoskModule;

                const createModel = VoskModule.createModel || VoskModule.default?.createModel;
                addLog(`Step 3: Extracting...`);

                const modelPromise = createModel(URL.createObjectURL(blob));
                const model = await Promise.race([
                    modelPromise,
                    new Promise((_, reject) => setTimeout(() => reject(new Error("Model Extraction Timeout")), 60000))
                ]);

                globalModel = model;
                addLog("SUCCESS: Vosk Engine Ready.");
                return model;

            } catch (e: any) {
                addLog(`FATAL: ${e.message}`);
                console.error(e);
                throw e; 
            }
          })();

          try {
              await globalModelLoadingPromise;
              setIsModelLoaded(true);
              setIsModelMissing(false);
          } catch (e: any) {
              setIsModelMissing(true); 
              setError(e.message || "Init Failed");
          } finally {
              setIsLoadingModel(false); 
              globalModelLoadingPromise = null;
          }
      };

      initVoiceEngine();

      return () => {
        stopListeningInternal();
      };
  }, [addLog, engine]);


  // --- STOP LOGIC ---
  const stopListeningInternal = () => {
    isListeningRef.current = false;
    setIsListening(false);

    // Cleanup Native
    if (nativeRecognitionRef.current) {
        try {
            nativeRecognitionRef.current.stop();
        } catch(e) {}
        nativeRecognitionRef.current = null;
    }

    // Cleanup Vosk
    if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    if (recognizerRef.current) {
        try {
            // Don't fully remove globalModel, just the instance
            recognizerRef.current.remove();
            recognizerRef.current = null;
        } catch(e) { console.warn(e); }
    }
    if (silenceTimeoutRef.current) {
        clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = null;
    }
    setActiveMicLabel(null);
    setAudioLevel(0);
  };

  const stopListening = useCallback(() => {
    stopListeningInternal();
  }, []);

  // --- START LOGIC ---
  const startListening = useCallback(async () => {
    setTranscript(''); 
    setError(null);
    stopListeningInternal(); // Ensure clean state

    // --- STRATEGY: NATIVE ---
    if (engine === 'NATIVE') {
        if (!isNativeSupported) {
            setError("Browser not supported");
            return;
        }
        try {
            addLog("Starting Native Recognition...");
            const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
            const recognition = new SpeechRecognition();
            recognition.continuous = true;
            recognition.interimResults = true;
            recognition.lang = 'fr-FR';
            recognition.maxAlternatives = 1;

            recognition.onstart = () => {
                setIsListening(true);
                isListeningRef.current = true;
                addLog("Native Listening Active");
                setActiveMicLabel("System Default (Native)");
            };

            recognition.onerror = (event: any) => {
                addLog(`Native Error: ${event.error}`);
                if (event.error === 'not-allowed') setError("Mic Permission Denied");
                if (event.error === 'no-speech') return; // Ignore
                // Don't stop immediately on minor errors
            };

            recognition.onend = () => {
                if (isListeningRef.current) {
                    addLog("Native restart (keep-alive)");
                    try { recognition.start(); } catch(e){}
                } else {
                    addLog("Native Stopped");
                    setIsListening(false);
                }
            };

            recognition.onresult = (event: any) => {
                if (!isListeningRef.current) return;
                let finalTranscript = '';
                let interimTranscript = '';

                for (let i = event.resultIndex; i < event.results.length; ++i) {
                    const transcriptPart = event.results[i][0].transcript;
                    if (event.results[i].isFinal) {
                        finalTranscript += transcriptPart;
                    } else {
                        interimTranscript += transcriptPart;
                    }
                }

                // Use interim for speed, parsing logic handles partials
                const text = finalTranscript || interimTranscript;
                if (text) {
                    setTranscript(text);
                    addLog(`Native: "${text}"`);
                    // Mock audio level for UI feedback since Native API doesn't give volume
                    setAudioLevel(Math.random() * 50 + 30); 
                }
            };

            recognition.start();
            nativeRecognitionRef.current = recognition;

        } catch (e: any) {
            setError("Native Init Failed");
            addLog(e.message);
        }
        return;
    }

    // --- STRATEGY: VOSK (Fallback) ---
    if (!globalModel) {
        addLog("Err: Model missing for Vosk");
        return;
    }

    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;

        // Force 16kHz for Vosk
        let audioContext;
        try {
            audioContext = new AudioContextClass({ sampleRate: 16000 });
        } catch (e) {
            audioContext = new AudioContextClass();
        }
        audioContextRef.current = audioContext;

        await audioContext.resume();

        const stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                echoCancellation: false,
                noiseSuppression: false,
                autoGainControl: false, 
                channelCount: 1,
                sampleRate: 16000
            }
        });
        mediaStreamRef.current = stream;

        const track = stream.getAudioTracks()[0];
        setActiveMicLabel(track ? track.label : "Default Device");
        addLog(`Mic: ${track ? track.label : "Unknown"} (VOSK)`);

        const actualSampleRate = audioContext.sampleRate;

        let recognizer;
        try {
            if (isStrictGrammar) {
                const grammar = JSON.stringify(getDartsGrammar());
                recognizer = new globalModel.KaldiRecognizer(actualSampleRate, grammar);
            } else {
                recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
            }
        } catch (grammarErr) {
            recognizer = new globalModel.KaldiRecognizer(actualSampleRate);
        }

        recognizer.on("result", (message: any) => {
            if (message.result && message.result.text) {
                const txt = message.result.text;
                if (txt) {
                    addLog(`Vosk: "${txt}"`);
                    setTranscript(txt);
                }
            }
        });

        recognizerRef.current = recognizer;

        const source = audioContext.createMediaStreamSource(stream);
        sourceRef.current = source;
        const processor = audioContext.createScriptProcessor(4096, 1, 1);
        processorRef.current = processor;

        let skipFrame = 0;
        processor.onaudioprocess = (event) => {
            const inputData = event.inputBuffer.getChannelData(0);

            // RMS Level
            if (skipFrame++ % 2 === 0) {
                 let sum = 0;
                 for (let i = 0; i < inputData.length; i += 5) {
                     sum += inputData[i] * inputData[i];
                 }
                 const rms = Math.sqrt(sum / (inputData.length / 5));
                 setAudioLevel(Math.min(100, Math.round(rms * 1500)));
            }

            if (recognizerRef.current && isListeningRef.current) { 
                try {
                    recognizerRef.current.acceptWaveform(event.inputBuffer);
                } catch (err) {}
            }
        };

        source.connect(processor);
        processor.connect(audioContext.destination);

        setIsListening(true);
        isListeningRef.current = true;
        addLog("Vosk Listening...");

        if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
        silenceTimeoutRef.current = setTimeout(() => {
            addLog("Timeout (Max Duration)");
            stopListening();
        }, 15000);

    } catch (err: any) {
        setError("Mic Blocked/Fail");
        addLog(`Start Err: ${err.message}`);
        stopListening();
    }
  }, [addLog, stopListening, isStrictGrammar, engine, isNativeSupported]);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport: true, // We support at least one engine
    error,
    isLoadingModel,
    isModelLoaded,
    isModelMissing,
    activeMicrophone: activeMicLabel,
    audioLevel,
    logs,
    isStrictGrammar,
    toggleGrammar,
    engine,
    setEngine,
    isNativeSupported
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '../components/ui/Button';
import { useSpeechRecognition, EngineType } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface SettingsViewProps {
  onBack: () => void;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ onBack }) => {
  const { 
    isListening, 
    transcript, 
    startListening, 
    stopListening, 
    resetTranscript, 
    error, 
    isLoadingModel, 
    isModelLoaded, 
    isModelMissing,
    activeMicrophone,
    audioLevel,
    logs,
    isStrictGrammar,
    toggleGrammar,
    engine,
    setEngine,
    isNativeSupported
  } = useSpeechRecognition();

  const [parsedResult, setParsedResult] = useState<string>('');
  const [manualInput, setManualInput] = useState('');
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Real-time parsing test
  useEffect(() => {
    if (transcript) {
        const result = parseDartsVoiceCommand(transcript);
        if (result.type === 'SCORE') {
            setParsedResult(`🎯 SCORE DETECTÉ: ${result.value} pts (${JSON.stringify(result.darts || [])})`);
        } else if (result.type === 'UNKNOWN') {
             setParsedResult(`❓ INCONNU (Raison: ${result.reason || 'No match'})`);
        } else {
             setParsedResult(`⚡ COMMANDE: ${result.type}`);
        }
    } else {
        if (!manualInput) {
            setParsedResult('En attente de parole ou de test manuel...');
        }
    }
  }, [transcript]);

  const handleManualTest = () => {
      if (!manualInput.trim()) return;
      const result = parseDartsVoiceCommand(manualInput);
      if (result.type === 'SCORE') {
          setParsedResult(`📝 [MANUEL] SCORE: ${result.value} pts\n🎯 Fléchettes: ${JSON.stringify(result.darts || [], null, 2)}`);
      } else if (result.type === 'UNKNOWN') {
           setParsedResult(`❓ [MANUEL] INCONNU\nRaison: ${result.reason || 'No match'}\nNormalisé: "${result.normalized}"`);
      } else {
           setParsedResult(`⚡ [MANUEL] COMMANDE: ${result.type}`);
      }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') handleManualTest();
  };

  const switchEngine = (e: EngineType) => {
      if (isListening) stopListening();
      setEngine(e);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      {/* HEADER */}
      <div className="flex items-center mb-6 shrink-0">
        <Button variant="ghost" onClick={() => { stopListening(); onBack(); }} size="sm">← Retour</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400 uppercase">
            PARAMÈTRES & DEBUG
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto space-y-8 max-w-4xl mx-auto w-full pb-10">

        {/* SECTION 1: VOICE ENGINE CONFIG */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-orange-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                1. Configuration Moteur Vocal
            </h3>

            {/* ENGINE SELECTOR */}
            <div className="mb-6">
                 <label className="text-xs text-gray-500 font-bold uppercase mb-2 block">Moteur de Reconnaissance</label>
                 <div className="flex bg-gray-900 rounded p-1 border border-gray-700">
                     <button 
                        onClick={() => switchEngine('NATIVE')}
                        disabled={!isNativeSupported}
                        className={`flex-1 py-2 rounded text-xs font-bold uppercase tracking-wider transition-all ${engine === 'NATIVE' ? 'bg-cyan-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'} ${!isNativeSupported ? 'opacity-30 cursor-not-allowed' : ''}`}
                     >
                         Natif (Recommandé)
                     </button>
                     <button 
                        onClick={() => switchEngine('VOSK')}
                        className={`flex-1 py-2 rounded text-xs font-bold uppercase tracking-wider transition-all ${engine === 'VOSK' ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}
                     >
                         Vosk (Hors Ligne)
                     </button>
                 </div>
                 {!isNativeSupported && (
                     <p className="text-[10px] text-red-400 mt-1 italic">Le moteur natif n'est pas supporté par ce navigateur (Essayez Chrome/Safari).</p>
                 )}
            </div>

            {/* ENGINE SPECIFIC STATUS */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                {engine === 'VOSK' && <StatusBadge label="Modèle Chargé" active={isModelLoaded} error={isModelMissing} />}
                <StatusBadge label="Microphone Actif" active={isListening} error={!!error} />
                <StatusBadge label="Type" active={true} text={engine} />
            </div>

            {/* Microphone Label & Volume Meter */}
            {isListening && activeMicrophone && (
                <div className="mb-4 p-3 bg-black/40 border border-gray-700 rounded flex flex-col gap-2">
                    <div className="flex items-center justify-between">
                        <span className="text-gray-500 text-xs font-bold uppercase tracking-wider">Source Audio</span>
                        <span className="text-cyan-400 font-mono text-xs md:text-sm font-bold truncate">
                            {activeMicrophone}
                        </span>
                    </div>

                    {/* AUDIO LEVEL BAR */}
                    <div className="w-full h-2 bg-gray-800 rounded-full overflow-hidden relative">
                         <div 
                            className="h-full bg-gradient-to-r from-green-500 to-red-500 transition-all duration-75 ease-out"
                            style={{ width: `${Math.min(100, audioLevel)}%` }}
                         ></div>
                    </div>
                </div>
            )}

            {/* VOSK SPECIFIC OPTIONS */}
            {engine === 'VOSK' && (
                <div className="mb-4 flex flex-col gap-2">
                     <div className="flex items-center justify-between bg-gray-900/50 p-3 rounded border border-gray-700">
                        <div className="flex flex-col">
                            <span className="text-sm font-bold text-gray-300">Mode Grammaire Stricte</span>
                            <span className="text-[10px] text-gray-500">Limite le vocabulaire aux termes de fléchettes (Vosk uniquement).</span>
                        </div>
                        <button 
                            onClick={toggleGrammar}
                            className={`w-12 h-6 rounded-full relative transition-colors duration-300 ${isStrictGrammar ? 'bg-orange-600' : 'bg-gray-600'}`}
                        >
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform duration-300 ${isStrictGrammar ? 'left-7' : 'left-1'}`}></div>
                        </button>
                     </div>
                </div>
            )}

            {error && (
                <div className="bg-red-900/50 border border-red-500/50 text-red-200 p-3 rounded mb-4 font-mono text-xs">
                    ERREUR: {error}
                </div>
            )}

            <div className="flex gap-4">
                <Button 
                    onClick={startListening} 
                    disabled={isListening || (engine === 'VOSK' && isLoadingModel)}
                    className={`flex-1 ${isListening ? 'opacity-50' : ''}`}
                >
                    {(engine === 'VOSK' && !isModelLoaded) ? 'Charger & Démarrer' : (isListening ? 'Écoute en cours...' : 'Démarrer le Micro')}
                </Button>

                <Button 
                    variant="secondary"
                    onClick={stopListening}
                    disabled={!isListening}
                >
                    Stop
                </Button>
                 <Button 
                    variant="ghost"
                    onClick={resetTranscript}
                >
                    Reset Texte
                </Button>
            </div>
        </section>

        {/* SECTION 2: PARSER TESTER */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-purple-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                2. Testeur de Syntaxe (Texte)
            </h3>
            <p className="text-xs text-gray-400 mb-4">Tapez une commande (ex: "triple 20", "double 16") pour tester la logique sans micro.</p>
            <div className="flex gap-2">
                <input 
                    type="text" 
                    value={manualInput}
                    onChange={(e) => setManualInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ex: triple vingt double dix"
                    className="flex-1 bg-gray-900 border border-gray-600 rounded px-4 py-2 text-white font-mono focus:border-purple-500 outline-none transition-colors"
                />
                <Button variant="secondary" onClick={handleManualTest}>Tester</Button>
            </div>
        </section>

        {/* SECTION 3: LIVE & RESULT DISPLAY */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6 relative overflow-hidden">
             <h3 className="text-cyan-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                3. Résultat de Reconnaissance / Parsing
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="text-xs text-gray-500 uppercase font-bold">Transcription Audio (Live)</label>
                    <div className="min-h-[60px] bg-black/50 border border-gray-600 rounded p-4 font-mono text-lg text-white mt-1">
                        {transcript || <span className="text-gray-600 italic">...silence...</span>}
                    </div>
                </div>

                <div>
                    <label className="text-xs text-gray-500 uppercase font-bold">Interprétation (Moteur de Jeu)</label>
                    <div className={`min-h-[80px] border rounded p-3 font-mono font-bold mt-1 whitespace-pre-wrap ${parsedResult.includes('SCORE') ? 'bg-green-900/20 border-green-600 text-green-400' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>
                        {parsedResult}
                    </div>
                </div>
            </div>
        </section>

        {/* SECTION 4: SYSTEM LOGS */}
        <section className="bg-black border border-gray-800 rounded-xl p-4 font-mono text-[10px] md:text-xs">
            <h3 className="text-gray-500 font-bold uppercase tracking-widest mb-2">Logs Système</h3>
            <div className="h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                {logs.length === 0 && <div className="text-gray-600">Aucun log pour le moment.</div>}
                {logs.map((log, i) => (
                    <div key={i} className={`${log.includes('Err') || log.includes('FATAL') ? 'text-red-500' : log.includes('WARN') ? 'text-yellow-500' : 'text-green-500/80'}`}>
                        {log}
                    </div>
                ))}
                <div ref={logsEndRef} />
            </div>
        </section>

      </div>
    </div>
  );
};

const StatusBadge = ({ label, active, error, warning, text }: any) => (
    <div className={`flex items-center justify-between p-3 rounded border ${
        error ? 'bg-red-900/20 border-red-800' : 
        warning && active ? 'bg-yellow-900/20 border-yellow-800' :
        active ? 'bg-green-900/20 border-green-800' : 
        'bg-gray-800 border-gray-700'
    }`}>
        <span className="text-xs font-bold uppercase text-gray-400">{label}</span>
        {text ? (
            <span className="text-xs font-black text-white">{text}</span>
        ) : (
            <div className={`w-3 h-3 rounded-full ${
                error ? 'bg-red-500' : 
                warning && active ? 'bg-yellow-500 animate-pulse' :
                active ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 
                'bg-gray-600'
            }`}></div>
        )}
    </div>
);

import { useState, useCallback, useRef, useEffect } from 'react';

export interface UseSpeechRecognitionReturn {
  isListening: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  hasRecognitionSupport: boolean;
  error: string | null;
  activeMicrophone: string | null;
  logs: string[];
}

export const useSpeechRecognition = (): UseSpeechRecognitionReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [activeMicLabel, setActiveMicLabel] = useState<string | null>(null);
  const [logs, setLogs] = useState<string[]>([]);

  const recognitionRef = useRef<any>(null);
  const isListeningRef = useRef(false);

  // Check browser support
  const hasRecognitionSupport = typeof window !== 'undefined' && 
    (!!(window as any).SpeechRecognition || !!(window as any).webkitSpeechRecognition);

  const addLog = useCallback((msg: string) => {
      const now = new Date();
      const time = `${now.getHours()}:${now.getMinutes()}:${now.getSeconds()}`;
      setLogs(prev => [...prev, `[${time}] ${msg}`]);
      console.log(`[VoiceEngine] ${msg}`);
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  const stopListening = useCallback(() => {
    isListeningRef.current = false;
    setIsListening(false);
    setActiveMicLabel(null);

    if (recognitionRef.current) {
        try {
            recognitionRef.current.stop();
        } catch(e) {
            // ignore errors on stop
        }
        recognitionRef.current = null;
    }
  }, []);

  const startListening = useCallback(() => {
    setTranscript(''); 
    setError(null);

    // Safety cleanup
    if (recognitionRef.current) {
        try { recognitionRef.current.stop(); } catch(e){}
        recognitionRef.current = null;
    }

    if (!hasRecognitionSupport) {
        setError("Navigateur non supporté (Utilisez Chrome/Safari/Edge)");
        return;
    }

    try {
        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        const recognition = new SpeechRecognition();

        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'fr-FR';
        recognition.maxAlternatives = 1;

        recognition.onstart = () => {
            setIsListening(true);
            isListeningRef.current = true;
            addLog("Moteur Natif Démarré");
            setActiveMicLabel("Microphone Système");
        };

        recognition.onerror = (event: any) => {
            addLog(`Erreur Native: ${event.error}`);
            if (event.error === 'not-allowed') {
                setError("Accès Micro Refusé");
                stopListening();
            }
            if (event.error === 'aborted') {
                setIsListening(false);
            }
        };

        recognition.onend = () => {
            // Auto-restart mechanism for continuous listening
            if (isListeningRef.current) {
                addLog("Redémarrage auto...");
                try { 
                    recognition.start(); 
                } catch(e) {
                    setIsListening(false);
                }
            } else {
                addLog("Arrêt du moteur");
                setIsListening(false);
            }
        };

        recognition.onresult = (event: any) => {
            if (!isListeningRef.current) return;

            let finalTranscript = '';
            let interimTranscript = '';

            for (let i = event.resultIndex; i < event.results.length; ++i) {
                const transcriptPart = event.results[i][0].transcript;
                if (event.results[i].isFinal) {
                    finalTranscript += transcriptPart;
                } else {
                    interimTranscript += transcriptPart;
                }
            }

            const text = finalTranscript || interimTranscript;
            if (text) {
                setTranscript(text);
                addLog(`Entendu: "${text}"`);
            }
        };

        recognition.start();
        recognitionRef.current = recognition;

    } catch (e: any) {
        setError("Erreur d'initialisation");
        addLog(e.message);
        setIsListening(false);
    }
  }, [addLog, hasRecognitionSupport, stopListening]);

  // Cleanup on unmount
  useEffect(() => {
      return () => {
          if (recognitionRef.current) {
              try { recognitionRef.current.stop(); } catch(e){}
          }
      };
  }, []);

  return {
    isListening,
    transcript,
    startListening,
    stopListening,
    resetTranscript,
    hasRecognitionSupport,
    error,
    activeMicrophone: activeMicLabel,
    logs
  };
};

/**
 * Vosk DARTS voice parser (FR) – version améliorée
 * Objectifs :
 * - Reconnaître des annonces "dart-centric" : T20 / D16 / S5, "triple 20", "double bull", "bulle", "miss"
 * - Support 1 à 3 flèches dans une même phrase : "t 20 d 10 s 5" => 85
 * - Garder compatibilité avec scores globaux 0..180 ("cent vingt", "85")
 */

export type VoiceCommandResult =
  | { type: "SCORE"; value: number; darts?: DartThrow[]; normalized?: string }
  | { type: "COMMAND_SUBMIT" | "COMMAND_CLEAR" | "COMMAND_UNDO"; normalized?: string }
  | { type: "UNKNOWN"; normalized?: string; reason?: string };

type DartThrow = {
  mult: 1 | 2 | 3;
  value: number; // 0..20, 25, 50
  label: string; // "S20", "T19", "DBULL", "MISS"
};

// -------------------- DICTIONNAIRES --------------------

const COMMANDS: Record<string, "COMMAND_SUBMIT" | "COMMAND_CLEAR" | "COMMAND_UNDO"> = {
  valider: "COMMAND_SUBMIT",
  ok: "COMMAND_SUBMIT",
  suivant: "COMMAND_SUBMIT",
  entrer: "COMMAND_SUBMIT",

  annuler: "COMMAND_CLEAR",
  effacer: "COMMAND_CLEAR",
  corriger: "COMMAND_CLEAR",
  non: "COMMAND_CLEAR",

  "répète": "COMMAND_UNDO",
  repete: "COMMAND_UNDO",
  retour: "COMMAND_UNDO",
  undo: "COMMAND_UNDO",
};

const FILLER_WORDS = new Set([
  "j", "ai", "fait", "mis", "je", "fais", "c", "est", "un", "une", "il", "y", "a",
  "et", "sur", "le", "la", "de", "pour", "alors", "bon", "bah", "mets", "note", "ajoute", "score",
]);

const MULTIPLIERS: Record<string, 1 | 2 | 3> = {
  simple: 1, s: 1,
  double: 2, d: 2,
  triple: 3, t: 3,
  simples: 1,
  doubles: 2,
  triples: 3,
};

const SPECIALS: Record<string, DartThrow> = {
  // Bull
  bull: { mult: 2, value: 25, label: "DBULL" },     // 50 au total (2*25)
  bulle: { mult: 2, value: 25, label: "DBULL" },
  boule: { mult: 2, value: 25, label: "DBULL" },    // Phonétique FR
  centre: { mult: 2, value: 25, label: "DBULL" },
  "plein centre": { mult: 2, value: 25, label: "DBULL" },
  "double bull": { mult: 2, value: 25, label: "DBULL" },
  "simple bull": { mult: 1, value: 25, label: "SBULL" },
  "petit centre": { mult: 1, value: 25, label: "SBULL" },
  "simple boule": { mult: 1, value: 25, label: "SBULL" }, // Phonétique FR

  // Miss
  miss: { mult: 1, value: 0, label: "MISS" },
  mise: { mult: 1, value: 0, label: "MISS" },     // Phonétique FR
  rien: { mult: 1, value: 0, label: "MISS" },
  "zéro": { mult: 1, value: 0, label: "MISS" },
  zero: { mult: 1, value: 0, label: "MISS" },
  "à côté": { mult: 1, value: 0, label: "MISS" },
  dehors: { mult: 1, value: 0, label: "MISS" },
};

const ATOMS: Record<string, number> = {
  "zéro": 0, zero: 0,
  un: 1, une: 1, deux: 2, trois: 3, quatre: 4,
  cinq: 5, six: 6, sept: 7, huit: 8, neuf: 9,
  dix: 10, onze: 11, douze: 12, treize: 13,
  quatorze: 14, quinze: 15, seize: 16,
  "dix-sept": 17, "dix sept": 17,
  "dix-huit": 18, "dix huit": 18,
  "dix-neuf": 19, "dix neuf": 19,
  vingt: 20, vingts: 20,
  trente: 30, quarante: 40, cinquante: 50, soixante: 60,
  "soixante-dix": 70, septante: 70,
  "quatre-vingt": 80, "quatre-vingts": 80, huitante: 80,
  "quatre-vingt-dix": 90, nonante: 90,
  cent: 100, cents: 100,
};

// -------------------- OUTILS --------------------

const stripDiacritics = (s: string) =>
  s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const normalize = (text: string): string => {
  let t = stripDiacritics(text.toLowerCase())
    .replace(/[.,;:!?]/g, " ")
    .replace(/-/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // normalisations courantes
  t = t
    .replace(/\btriple(s)?\b/g, "triple")
    .replace(/\bdouble(s)?\b/g, "double")
    .replace(/\bsimple(s)?\b/g, "simple");

  return t;
};

const frenchTextToNumber = (text: string): number | null => {
  const cleanText = text.replace(/\bet\b/g, " ").replace(/-/g, " ").replace(/\s+/g, " ").trim();
  if (!cleanText) return null;
  const parts = cleanText.split(" ");

  let total = 0;
  let current = 0;

  for (const part of parts) {
    const rawInt = parseInt(part, 10);
    if (!Number.isNaN(rawInt)) {
      current += rawInt;
      continue;
    }

    const val = ATOMS[part];
    if (val === undefined) continue;

    if (val === 100) {
      if (current === 0) current = 100;
      else current *= 100;
    } else {
      // quatre vingt => 80
      if (part.startsWith("vingt") && current === 4) current = 80;
      else current += val;
    }
  }

  total += current;
  // ici on accepte 0 explicitement
  return Number.isFinite(total) ? total : null;
};

// Tokenisation en gardant quelques bigrams utiles ("double bull", "plein centre", etc.)
const tokenize = (clean: string): string[] => {
  if (!clean) return [];
  const parts = clean.split(" ").filter(Boolean);

  const out: string[] = [];
  for (let i = 0; i < parts.length; i++) {
    const a = parts[i];
    const b = parts[i + 1];

    // bigrams / trigrams
    if (a === "double" && b === "bull") { out.push("double bull"); i += 1; continue; }
    if (a === "simple" && b === "bull") { out.push("simple bull"); i += 1; continue; }
    if (a === "plein" && b === "centre") { out.push("plein centre"); i += 1; continue; }
    if (a === "petit" && b === "centre") { out.push("petit centre"); i += 1; continue; }
    if (a === "a" && b === "cote") { out.push("à côté"); i += 1; continue; } // "a cote" sans accent

    // Phonétiques
    if (a === "double" && b === "boule") { out.push("double boule"); i += 1; continue; }
    if (a === "simple" && b === "boule") { out.push("simple boule"); i += 1; continue; }

    // ignorer fillers isolés
    if (FILLER_WORDS.has(a)) continue;

    out.push(a);
  }
  return out;
};

// -------------------- PARSING DARTS --------------------

// Parse une annonce de type :
// - "t 20", "triple 20", "d 16", "double seize", "bull", "double bull", "miss"
// Retour : DartThrow + nombre de tokens consommés
const parseSingleThrow = (tokens: string[], start: number): { thr: DartThrow; consumed: number } | null => {
  const t0 = tokens[start];
  if (!t0) return null;

  // specials multi-mots déjà tokenisés
  if (SPECIALS[t0]) return { thr: SPECIALS[t0], consumed: 1 };

  // digits directs "25" / "50" (on interprète : 25=SBULL, 50=DBULL)
  if (/^\d+$/.test(t0)) {
    const v = parseInt(t0, 10);
    if (v === 25) return { thr: { mult: 1, value: 25, label: "SBULL" }, consumed: 1 };
    if (v === 50) return { thr: { mult: 2, value: 25, label: "DBULL" }, consumed: 1 };
    // si on annonce "20" tout court => S20
    if (v >= 0 && v <= 20) return { thr: { mult: 1, value: v, label: `S${v}` }, consumed: 1 };
  }

  // multiplicateur + nombre (1..20 ou 25)
  const mult = MULTIPLIERS[t0];
  if (mult) {
    const t1 = tokens[start + 1];
    if (!t1) return null;

    // cas "double bull" déjà géré, mais au cas où
    if (t1 === "bull" || t1 === "boule") {
      const thr = mult === 1
        ? { mult: 1 as const, value: 25, label: "SBULL" }
        : { mult: 2 as const, value: 25, label: "DBULL" };
      return { thr, consumed: 2 };
    }

    // nombre digits
    let val = /^\d+$/.test(t1) ? parseInt(t1, 10) : (frenchTextToNumber(t1) ?? NaN);

    // nombre en 2 mots (ex: "dix sept") si Vosk le split : on tente de regarder 2 tokens
    if (!Number.isFinite(val)) {
      const t2 = tokens[start + 2];
      if (t2) {
        const joined = `${t1} ${t2}`;
        const v2 = frenchTextToNumber(joined);
        if (v2 !== null) {
          val = v2;
          // consumed 3
          if ((val >= 0 && val <= 20) || val === 25) {
            const thr: DartThrow = val === 25
              ? (mult === 1 ? { mult: 1, value: 25, label: "SBULL" } : { mult: 2, value: 25, label: "DBULL" })
              : { mult, value: val, label: `${mult === 1 ? "S" : mult === 2 ? "D" : "T"}${val}` };
            return { thr, consumed: 3 };
          }
        }
      }
      return null;
    }

    if (!((val >= 0 && val <= 20) || val === 25)) return null;

    const thr: DartThrow =
      val === 25
        ? (mult === 1 ? { mult: 1, value: 25, label: "SBULL" } : { mult: 2, value: 25, label: "DBULL" })
        : { mult, value: val, label: `${mult === 1 ? "S" : mult === 2 ? "D" : "T"}${val}` };

    return { thr, consumed: 2 };
  }

  // mots spéciaux simples (bull/miss/etc.) déjà gérés
  // rien reconnu
  return null;
};

// Essaie de parser 1..3 flèches ; renvoie SCORE si cohérent
const parseDartsThrows = (tokens: string[]): { darts: DartThrow[]; score: number } | null => {
  const darts: DartThrow[] = [];
  let i = 0;

  while (i < tokens.length && darts.length < 3) {
    const parsed = parseSingleThrow(tokens, i);
    if (!parsed) {
      i += 1;
      continue;
    }
    darts.push(parsed.thr);
    i += parsed.consumed;
  }

  if (darts.length === 0) return null;

  // score : pour bull DBULL = 2*25=50, SBULL = 25, MISS = 0
  const score = darts.reduce((sum, d) => sum + d.mult * d.value, 0);
  if (score < 0 || score > 180) return null;

  return { darts, score };
};

// -------------------- API PRINCIPALE --------------------

export const parseDartsVoiceCommand = (transcript: string): VoiceCommandResult => {
  if (!transcript) return { type: "UNKNOWN", normalized: "" };

  const normalized = normalize(transcript);

  // commande exacte (après normalisation)
  if (COMMANDS[normalized]) return { type: COMMANDS[normalized], normalized };

  // tokenisation + parsing darts (1..3 flèches)
  const tokens = tokenize(normalized);
  const dartsParsed = parseDartsThrows(tokens);
  if (dartsParsed) {
    return { type: "SCORE", value: dartsParsed.score, darts: dartsParsed.darts, normalized };
  }

  // fallback : score global 0..180 (ex: "cent quarante", "85")
  let score = /^\d+$/.test(normalized) ? parseInt(normalized, 10) : NaN;
  if (Number.isNaN(score)) {
    const v = frenchTextToNumber(normalized);
    if (v !== null) score = v;
  }

  if (!Number.isNaN(score) && score >= 0 && score <= 180) {
    return { type: "SCORE", value: score, normalized };
  }

  return { type: "UNKNOWN", normalized, reason: "no_match" };
};

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '../components/ui/Button';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface SettingsViewProps {
  onBack: () => void;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ onBack }) => {
  const { 
    isListening, 
    transcript, 
    startListening, 
    stopListening, 
    resetTranscript, 
    error, 
    activeMicrophone,
    logs,
  } = useSpeechRecognition();

  const [parsedResult, setParsedResult] = useState<string>('');
  const [manualInput, setManualInput] = useState('');
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Real-time parsing test
  useEffect(() => {
    if (transcript) {
        const result = parseDartsVoiceCommand(transcript);
        if (result.type === 'SCORE') {
            setParsedResult(`🎯 SCORE DETECTÉ: ${result.value} pts (${JSON.stringify(result.darts || [])})`);
        } else if (result.type === 'UNKNOWN') {
             setParsedResult(`❓ INCONNU (Raison: ${result.reason || 'No match'})`);
        } else {
             setParsedResult(`⚡ COMMANDE: ${result.type}`);
        }
    } else {
        if (!manualInput) {
            setParsedResult('En attente de parole ou de test manuel...');
        }
    }
  }, [transcript]);

  const handleManualTest = () => {
      if (!manualInput.trim()) return;
      const result = parseDartsVoiceCommand(manualInput);
      if (result.type === 'SCORE') {
          setParsedResult(`📝 [MANUEL] SCORE: ${result.value} pts\n🎯 Fléchettes: ${JSON.stringify(result.darts || [], null, 2)}`);
      } else if (result.type === 'UNKNOWN') {
           setParsedResult(`❓ [MANUEL] INCONNU\nRaison: ${result.reason || 'No match'}\nNormalisé: "${result.normalized}"`);
      } else {
           setParsedResult(`⚡ [MANUEL] COMMANDE: ${result.type}`);
      }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') handleManualTest();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      {/* HEADER */}
      <div className="flex items-center mb-6 shrink-0">
        <Button variant="ghost" onClick={() => { stopListening(); onBack(); }} size="sm">← Retour</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400 uppercase">
            PARAMÈTRES & DEBUG
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto space-y-8 max-w-4xl mx-auto w-full pb-10">

        {/* SECTION 1: VOICE ENGINE STATUS */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-orange-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                1. Moteur Vocal (Web Speech API)
            </h3>

            {/* Microphone Label */}
            {isListening && activeMicrophone && (
                <div className="mb-4 p-3 bg-black/40 border border-gray-700 rounded flex flex-col gap-2">
                    <div className="flex items-center justify-between">
                        <span className="text-gray-500 text-xs font-bold uppercase tracking-wider">Source Audio</span>
                        <span className="text-cyan-400 font-mono text-xs md:text-sm font-bold truncate">
                            {activeMicrophone}
                        </span>
                    </div>
                </div>
            )}

            {error && (
                <div className="bg-red-900/50 border border-red-500/50 text-red-200 p-3 rounded mb-4 font-mono text-xs">
                    ERREUR: {error}
                </div>
            )}

            <div className="flex gap-4">
                <Button 
                    onClick={startListening} 
                    disabled={isListening}
                    className={`flex-1 ${isListening ? 'opacity-50' : ''}`}
                >
                    {isListening ? 'Écoute en cours...' : 'Démarrer le Micro'}
                </Button>

                <Button 
                    variant="secondary"
                    onClick={stopListening}
                    disabled={!isListening}
                >
                    Stop
                </Button>
                 <Button 
                    variant="ghost"
                    onClick={resetTranscript}
                >
                    Reset Texte
                </Button>
            </div>

            <p className="text-[10px] text-gray-500 mt-3 italic">
                Note: Le moteur natif utilise les serveurs de reconnaissance de votre navigateur (Google/Apple). Une connexion internet est généralement requise.
            </p>
        </section>

        {/* SECTION 2: PARSER TESTER */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-purple-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                2. Testeur de Syntaxe (Texte)
            </h3>
            <p className="text-xs text-gray-400 mb-4">Tapez une commande (ex: "triple 20", "double 16") pour tester la logique sans micro.</p>
            <div className="flex gap-2">
                <input 
                    type="text" 
                    value={manualInput}
                    onChange={(e) => setManualInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ex: triple vingt double dix"
                    className="flex-1 bg-gray-900 border border-gray-600 rounded px-4 py-2 text-white font-mono focus:border-purple-500 outline-none transition-colors"
                />
                <Button variant="secondary" onClick={handleManualTest}>Tester</Button>
            </div>
        </section>

        {/* SECTION 3: LIVE & RESULT DISPLAY */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6 relative overflow-hidden">
             <h3 className="text-cyan-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                3. Résultat de Reconnaissance / Parsing
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="text-xs text-gray-500 uppercase font-bold">Transcription Audio (Live)</label>
                    <div className="min-h-[60px] bg-black/50 border border-gray-600 rounded p-4 font-mono text-lg text-white mt-1">
                        {transcript || <span className="text-gray-600 italic">...silence...</span>}
                    </div>
                </div>

                <div>
                    <label className="text-xs text-gray-500 uppercase font-bold">Interprétation (Moteur de Jeu)</label>
                    <div className={`min-h-[80px] border rounded p-3 font-mono font-bold mt-1 whitespace-pre-wrap ${parsedResult.includes('SCORE') ? 'bg-green-900/20 border-green-600 text-green-400' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>
                        {parsedResult}
                    </div>
                </div>
            </div>
        </section>

        {/* SECTION 4: SYSTEM LOGS */}
        <section className="bg-black border border-gray-800 rounded-xl p-4 font-mono text-[10px] md:text-xs">
            <h3 className="text-gray-500 font-bold uppercase tracking-widest mb-2">Logs Système</h3>
            <div className="h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                {logs.length === 0 && <div className="text-gray-600">Aucun log pour le moment.</div>}
                {logs.map((log, i) => (
                    <div key={i} className={`${log.includes('Err') || log.includes('FATAL') ? 'text-red-500' : log.includes('WARN') ? 'text-yellow-500' : 'text-green-500/80'}`}>
                        {log}
                    </div>
                ))}
                <div ref={logsEndRef} />
            </div>
        </section>

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Button } from '../components/ui/Button';
import { GameConfig, Player, InOutRule, MatchMode } from '../types';

interface SetupViewProps {
  onStart: (players: Player[], config: GameConfig) => void;
  onBack: () => void;
}

export const SetupView: React.FC<SetupViewProps> = ({ onStart, onBack }) => {
  const [startingScore, setStartingScore] = useState(501);
  const [customScoreStr, setCustomScoreStr] = useState('170');

  const [matchMode, setMatchMode] = useState<MatchMode>('LEGS');
  const [legsToWin, setLegsToWin] = useState(3);
  const [setsToWin, setSetsToWin] = useState(3);

  // New: Doubles Mode
  const [isDoubles, setIsDoubles] = useState(false);
  const [enableVoice, setEnableVoice] = useState(false);

  // Player State
  const [playerNames, setPlayerNames] = useState<string[]>(['Player 1', 'Player 2']);

  // Doubles specific state
  const [team1Names, setTeam1Names] = useState(['Player 1', 'Player 2']);
  const [team2Names, setTeam2Names] = useState(['Player 3', 'Player 4']);

  // Defaults: Double Out, Open In
  const [checkOut, setCheckOut] = useState<InOutRule>('Double');
  const [checkIn, setCheckIn] = useState<InOutRule>('Open');

  // Solo Player Count
  const updatePlayerCount = (delta: number) => {
    const currentCount = playerNames.length;
    const newCount = Math.max(1, Math.min(4, currentCount + delta));

    if (newCount === currentCount) return;

    setPlayerNames(prev => {
      if (newCount > prev.length) {
        return [...prev, `Player ${newCount}`];
      } else {
        return prev.slice(0, newCount);
      }
    });
  };

  const updatePlayerName = (index: number, name: string) => {
    const newNames = [...playerNames];
    newNames[index] = name;
    setPlayerNames(newNames);
  };

  const updateTeamName = (team: 1 | 2, index: number, name: string) => {
      if (team === 1) {
          const n = [...team1Names];
          n[index] = name;
          setTeam1Names(n);
      } else {
          const n = [...team2Names];
          n[index] = name;
          setTeam2Names(n);
      }
  }

  const handleStart = () => {
    const safeStartingScore = startingScore > 0 ? startingScore : 501;
    let players: Player[] = [];

    if (isDoubles) {
        const p1 = { id: 't1p1', name: team1Names[0].trim() || 'Player 1', teamId: 'team1' };
        const p2 = { id: 't1p2', name: team1Names[1].trim() || 'Player 2', teamId: 'team1' };
        const p3 = { id: 't2p1', name: team2Names[0].trim() || 'Player 3', teamId: 'team2' };
        const p4 = { id: 't2p2', name: team2Names[1].trim() || 'Player 4', teamId: 'team2' };
        players = [p1, p2, p3, p4];
    } else {
        players = playerNames.map((name, i) => ({
            id: `p${i+1}`,
            name: name.trim() || `Player ${i+1}`,
            teamId: `p${i+1}` 
        }));
    }

    const config: GameConfig = {
      startingScore: safeStartingScore,
      checkIn,
      checkOut,
      matchMode,
      legsToWin, 
      setsToWin,
      isDoubles,
      enableVoice
    };

    onStart(players, config);
  };

  const activeOptionClass = "bg-gradient-to-r from-orange-600 to-red-600 text-white border-transparent shadow-[0_0_10px_rgba(234,88,12,0.3)]";
  const inactiveOptionClass = "bg-gray-800 border-gray-700 text-gray-400 hover:border-orange-500/50 hover:text-gray-200";

  const getRuleDescription = (type: 'in' | 'out', rule: InOutRule) => {
     if (type === 'out') {
         switch(rule) {
             case 'Open': return "Finish on any segment.";
             case 'Double': return "Standard: Finish on a Double or Bullseye.";
             case 'Master': return "Finish on a Double, Triple or Bullseye.";
         }
     } else {
         switch(rule) {
             case 'Open': return "Start scoring immediately.";
             case 'Double': return "Must hit a Double to start.";
             case 'Master': return "Must hit a Double or Triple to start.";
         }
     }
  };

  const presets = [301, 501, 701, 1001];
  const isPresetSelected = presets.includes(startingScore);
  const isCustomActive = !isPresetSelected || startingScore === parseInt(customScoreStr || '0');

  const handleCustomFocus = () => {
      const val = parseInt(customScoreStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  const handleCustomChange = (valStr: string) => {
      setCustomScoreStr(valStr);
      const val = parseInt(valStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      <div className="flex items-center mb-6">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
            MATCH SETUP
        </h2>
      </div>

      <div className="flex-1 space-y-6 max-w-md mx-auto w-full overflow-y-auto pb-4 custom-scrollbar">

        {/* Score Selection */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Starting Score</label>
          <div className="grid grid-cols-4 gap-2 mb-3">
            {presets.map(score => (
              <button
                key={score}
                onClick={() => setStartingScore(score)}
                className={`py-3 rounded font-black border transition-all duration-200 ${startingScore === score ? activeOptionClass : inactiveOptionClass}`}
              >
                {score}
              </button>
            ))}
          </div>

           <div 
             className={`flex items-center space-x-3 p-3 rounded-lg border transition-all duration-200 ${isCustomActive && !presets.includes(startingScore) ? 'bg-gray-800 border-orange-500 shadow-[0_0_10px_rgba(234,88,12,0.15)]' : 'bg-gray-800/30 border-gray-700'}`}
             onClick={handleCustomFocus}
           >
               <span className={`text-xs font-bold uppercase tracking-wider whitespace-nowrap ${isCustomActive && !presets.includes(startingScore) ? 'text-orange-500' : 'text-gray-500'}`}>Custom Score</span>
               <input 
                  type="number" 
                  min="1"
                  max="9999"
                  value={customScoreStr}
                  onChange={(e) => handleCustomChange(e.target.value)}
                  onFocus={handleCustomFocus}
                  className={`w-full bg-transparent text-right font-mono font-black text-xl focus:outline-none focus:text-orange-500 ${isCustomActive && !presets.includes(startingScore) ? 'text-white' : 'text-gray-500'}`}
                  placeholder="Enter score..."
               />
           </div>
        </section>

        {/* Voice AI Section */}
        <section className="bg-gray-800/30 p-4 rounded-xl border border-gray-800">
            <div className="flex justify-between items-center mb-2">
                <div>
                    <label className="block text-cyan-500 text-xs font-bold uppercase tracking-widest">Assistant Vocal</label>
                    <p className="text-[10px] text-gray-500 mt-1 leading-relaxed">
                        Annoncez vos scores à la voix (ex: "Triple 20", "Cent quarante"). Utilise le moteur natif de votre appareil.
                    </p>
                </div>
                <button 
                    onClick={() => setEnableVoice(!enableVoice)}
                    className={`w-14 h-7 rounded-full relative transition-all duration-300 shrink-0 ${enableVoice ? 'bg-cyan-600 shadow-[0_0_10px_rgba(8,145,178,0.4)]' : 'bg-gray-700'}`}
                >
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all duration-300 shadow-sm ${enableVoice ? 'left-8' : 'left-1'}`}></div>
                </button>
            </div>
        </section>

        {/* Players Configuration */}
        <section>
            <div className="flex justify-between items-center mb-2">
                <label className="block text-orange-500 text-xs font-bold uppercase tracking-widest">Players</label>
                <div className="flex bg-gray-800 rounded p-1">
                    <button onClick={() => setIsDoubles(false)} className={`px-3 py-1 text-xs font-bold rounded ${!isDoubles ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>Solo</button>
                    <button onClick={() => setIsDoubles(true)} className={`px-3 py-1 text-xs font-bold rounded ${isDoubles ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>Doubles (2v2)</button>
                </div>
            </div>

            {!isDoubles ? (
                <>
                    <div className="flex items-center space-x-4 bg-gray-800/50 p-2 rounded-lg mb-4 border border-gray-700">
                        <button onClick={() => updatePlayerCount(-1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">-</button>
                        <span className="flex-1 text-center font-black text-2xl text-white">{playerNames.length}</span>
                        <button onClick={() => updatePlayerCount(1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">+</button>
                    </div>
                    <div className="space-y-2">
                        {playerNames.map((name, index) => (
                        <div key={index} className="flex items-center group">
                            <span className="w-8 text-gray-500 text-xs font-bold group-hover:text-orange-500 transition-colors">#{index + 1}</span>
                            <input
                            type="text"
                            value={name}
                            onChange={(e) => updatePlayerName(index, e.target.value)}
                            onFocus={(e) => e.target.select()}
                            className="flex-1 bg-gray-800 border border-gray-700 text-white px-3 py-3 rounded font-bold focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all"
                            placeholder={`Player ${index + 1}`}
                            />
                        </div>
                        ))}
                    </div>
                </>
            ) : (
                <div className="space-y-4">
                    <div className="bg-gray-800/30 p-3 rounded border border-gray-700">
                        <div className="text-xs text-orange-500 font-bold uppercase mb-2">Team 1</div>
                        <div className="space-y-2">
                            <input value={team1Names[0]} onChange={(e) => updateTeamName(1, 0, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 1" />
                            <input value={team1Names[1]} onChange={(e) => updateTeamName(1, 1, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 2" />
                        </div>
                    </div>
                    <div className="bg-gray-800/30 p-3 rounded border border-gray-700">
                        <div className="text-xs text-orange-500 font-bold uppercase mb-2">Team 2</div>
                        <div className="space-y-2">
                            <input value={team2Names[0]} onChange={(e) => updateTeamName(2, 0, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 3" />
                            <input value={team2Names[1]} onChange={(e) => updateTeamName(2, 1, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 4" />
                        </div>
                    </div>
                </div>
            )}
        </section>

        {/* Format */}
        <section>
          <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Match Format</label>

          <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-4">
             <button onClick={() => setMatchMode('LEGS')} className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all ${matchMode === 'LEGS' ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                Legs
             </button>
             <button onClick={() => setMatchMode('SETS')} className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all ${matchMode === 'SETS' ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                Sets
             </button>
          </div>

          <div className="bg-gray-800/30 p-4 rounded-lg border border-gray-700 space-y-4">
             {matchMode === 'LEGS' ? (
                <div>
                   <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Legs to Win Match</label>
                   <div className="grid grid-cols-5 gap-2">
                      {[1, 3, 5, 7, 9].map(num => (
                         <button key={num} onClick={() => setLegsToWin(num)} className={`py-2 rounded font-bold text-sm border ${legsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                            {num}
                         </button>
                      ))}
                   </div>
                </div>
             ) : (
                <>
                  <div>
                      <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Sets to Win Match</label>
                      <div className="grid grid-cols-4 gap-2">
                          {[1, 3, 5, 7].map(num => (
                            <button key={num} onClick={() => setSetsToWin(num)} className={`py-2 rounded font-bold text-sm border ${setsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                {num}
                            </button>
                          ))}
                      </div>
                  </div>
                  <div>
                      <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Legs to Win a Set</label>
                      <div className="grid grid-cols-4 gap-2">
                          {[3, 5].map(num => (
                            <button key={num} onClick={() => setLegsToWin(num)} className={`py-2 rounded font-bold text-sm border ${legsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                {num}
                            </button>
                          ))}
                      </div>
                  </div>
                </>
             )}
          </div>
        </section>

        {/* In / Out Rules */}
        <section className="grid grid-cols-1 gap-6">
           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Check In Rule</label>
               <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button
                      key={rule}
                      onClick={() => setCheckIn(rule)}
                      className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkIn === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                      {rule} In
                    </button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('in', checkIn)}</p>
           </div>

           <div>
               <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Checkout Rule</label>
               <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                 {(['Open', 'Double', 'Master'] as const).map(rule => (
                    <button
                      key={rule}
                      onClick={() => setCheckOut(rule)}
                      className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkOut === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                      {rule} Out
                    </button>
                 ))}
               </div>
               <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('out', checkOut)}</p>
           </div>
        </section>

      </div>

      <div className="mt-4">
        <Button onClick={handleStart} className="w-full py-5 text-2xl shadow-orange-900/20">GAME ON</Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView';
import { ProfileView } from './views/ProfileView';
import { HistoryView } from './views/HistoryView'; 
import { MyStatsView } from './views/MyStatsView'; 
import { SettingsView } from './views/SettingsView';
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { GameConfig, Player, MatchState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'PROFILE' | 'HISTORY' | 'MY_STATS' | 'SETTINGS' | 'GAME_SELECTION' | 'SETUP' | 'MATCH' | 'STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    if (type === 'X01') {
      setSelectedGameType(type);
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  const handleStartSetup = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);
    setScreen('MATCH');
  };

  const handleMatchFinish = (winnerId: string) => {
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch);

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  const handleExitMatch = () => {
    exitFullScreen();
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleRematch = () => {
      if (!currentMatch) return;

      const newMatch = createMatch(currentMatch.players, currentMatch.config);
      setCurrentMatch(newMatch);
      enterFullScreen();
      setScreen('MATCH');
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
          onSettings={() => setScreen('SETTINGS')}
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => setScreen('HISTORY')}
              onStats={() => setScreen('MY_STATS')}
              onProfile={() => setScreen('PROFILE')}
              onSettings={() => setScreen('SETTINGS')}
              onLogout={handleLogout}
          />
      )}

      {screen === 'PROFILE' && user && (
          <ProfileView 
              user={user}
              onBack={() => setScreen('DASHBOARD')}
              onUpdateUser={(updatedUser) => setUser(updatedUser)}
          />
      )}

      {screen === 'HISTORY' && user && (
          <HistoryView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'MY_STATS' && user && (
          <MyStatsView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'SETTINGS' && (
          <SettingsView 
             onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          onStart={handleStartSetup} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={() => { setScreen(user ? 'DASHBOARD' : 'HOME'); setCurrentMatch(null); }}
          onRematch={handleRematch}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import React from 'react';
import { Button } from '../ui/Button';

interface KeypadProps {
  onInput: (val: number) => void;
  onClear: () => void;
  onEnter: () => void;
  currentInput: string;
  isCheckoutPossible: boolean;
  // Voice Props
  onMicClick?: () => void;
  isListening?: boolean;
  hasVoiceSupport?: boolean;
  isVoiceEnabled?: boolean; 
  // Quick Actions
  quickShortcutsLeft?: number[];
  quickShortcutsRight?: number[];
  onQuickAction?: (val: number) => void;
}

export const Keypad: React.FC<KeypadProps> = ({ 
  onInput, 
  onClear, 
  onEnter, 
  currentInput, 
  isCheckoutPossible,
  onMicClick,
  isListening,
  hasVoiceSupport,
  isVoiceEnabled = true,
  quickShortcutsLeft = [],
  quickShortcutsRight = [],
  onQuickAction
}) => {
  const keys = [1, 2, 3, 4, 5, 6, 7, 8, 9];

  // Le micro est désactivé si : pas de support navigateur, option décochée ou déjà à l'écoute
  const isMicDisabled = !isVoiceEnabled || !hasVoiceSupport || isListening;

  return (
    <div className="h-full flex gap-2">

      {/* LEFT SHORTCUTS */}
      {quickShortcutsLeft.length > 0 && (
        <div className="hidden md:flex flex-col gap-2 w-24 shrink-0">
           {quickShortcutsLeft.map((val, idx) => (
               <Button 
                  key={`L-${idx}`} 
                  variant="secondary" 
                  onClick={() => onQuickAction && onQuickAction(val)}
                  className="flex-1 text-xl font-black bg-gray-900/80 border-gray-800 text-cyan-500 hover:text-white hover:bg-cyan-900 hover:border-cyan-500/50 shadow-lg transition-all"
               >
                  {val}
               </Button>
           ))}
        </div>
      )}

      {/* CENTER NUMPAD */}
      <div className="flex-1 flex flex-col gap-2">
          <div className="flex-1 grid grid-cols-3 gap-2">
              {keys.map((k) => (
                <Button 
                  key={k} 
                  variant="secondary" 
                  onClick={() => onInput(k)}
                  className="text-2xl font-bold bg-gray-800 hover:bg-gray-700 border-gray-700 h-full shadow-inner active:scale-95 transition-transform"
                >
                  {k}
                </Button>
              ))}
          </div>
          <div className="h-1/4 grid grid-cols-3 gap-2">
              <Button variant="danger" onClick={onClear} className="h-full text-lg font-bold shadow-sm">C</Button>
              <Button variant="secondary" onClick={() => onInput(0)} className="h-full text-2xl font-bold bg-gray-800 border-gray-700 shadow-inner">0</Button>

              {/* Mic Button */}
              <button 
                  onClick={onMicClick}
                  disabled={isMicDisabled}
                  className={`
                    relative h-full w-full rounded flex items-center justify-center transition-all duration-300 overflow-hidden border
                    ${!isVoiceEnabled || !hasVoiceSupport
                        ? 'bg-gray-900 border-gray-800 opacity-20 cursor-not-allowed' 
                        : isListening
                            ? 'bg-cyan-500 border-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.6)] scale-[0.98]'
                            : 'bg-gradient-to-br from-cyan-600 to-blue-700 hover:from-cyan-500 hover:to-blue-600 border-transparent shadow-lg shadow-cyan-900/50'
                    }
                  `}
              >
                  {isListening && hasVoiceSupport && isVoiceEnabled && (
                      <div className="absolute inset-0 bg-cyan-400 animate-pulse opacity-50"></div>
                  )}

                  <div className={`relative z-10 ${!isVoiceEnabled || !hasVoiceSupport ? 'text-gray-700' : 'text-white'}`}>
                      {!isVoiceEnabled || !hasVoiceSupport ? (
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 opacity-50">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                          </svg>
                      ) : isListening ? (
                          <div className="flex items-center gap-1 h-4">
                              <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite] h-2"></div>
                              <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite_0.1s] h-4"></div>
                              <div className="w-1 bg-white rounded-full animate-[music_1s_ease-in-out_infinite_0.2s] h-2"></div>
                          </div>
                      ) : (
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7 drop-shadow-md">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                          </svg>
                      )}
                  </div>
              </button>
          </div>
      </div>

      {/* RIGHT SHORTCUTS */}
      {quickShortcutsRight.length > 0 && (
        <div className="hidden md:flex flex-col gap-2 w-24 shrink-0">
           {quickShortcutsRight.map((val, idx) => (
               <Button 
                  key={`R-${idx}`} 
                  variant="secondary" 
                  onClick={() => onQuickAction && onQuickAction(val)}
                  className="flex-1 text-xl font-black bg-gray-900/80 border-gray-800 text-orange-500 hover:text-white hover:bg-orange-900 hover:border-orange-500/50 shadow-lg transition-all"
               >
                  {val}
               </Button>
           ))}
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState, Turn } from '../types';
import { submitTurn, undoTurn, getMinDartsForScore, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');
  const [currentTime, setCurrentTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const matchStatusRef = useRef(match.status);

  const { isListening, transcript, startListening, hasRecognitionSupport, resetTranscript } = useSpeechRecognition();

  const [showStats, setShowStats] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  useEffect(() => {
    matchStatusRef.current = match.status;
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      if (matchStatusRef.current === 'active') setElapsedSeconds(prev => prev + 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [match.status]);

  useEffect(() => {
      if (transcript && match.config.enableVoice) {
          const result = parseDartsVoiceCommand(transcript);
          if (result.type === 'SCORE' && result.value !== undefined) setInputBuffer(result.value.toString());
          else if (result.type === 'COMMAND_SUBMIT') { if (inputBuffer) handleSubmitScore(); }
          else if (result.type === 'COMMAND_CLEAR') setInputBuffer('');
          else if (result.type === 'COMMAND_UNDO') setMatch(undoTurn(match));
      }
  }, [transcript]);

  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 1500);
  };

  const processScoreSubmission = (score: number) => {
      if (isNaN(score) || score > 180) return triggerFeedback("INVALIDE", "bust");
      const currentPlayer = match.players[match.currentPlayerIndex];
      const currentScore = match.currentLeg.scores[currentPlayer.teamId];

      if (score === currentScore) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      let nextState = submitTurn(match, score, 3);
      if (nextState.status === 'finished') {
          setMatch({ ...nextState, duration: elapsedSeconds });
          setShowWinnerScreen(true);
          return;
      }

      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn?.isBust) triggerFeedback("TROP !", "bust");
      else if (score >= 100) triggerFeedback(score.toString(), "info");

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => inputBuffer && processScoreSubmission(parseInt(inputBuffer));
  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
     if (nextState.status === 'finished') {
         setMatch({ ...nextState, duration: elapsedSeconds });
         setShowWinnerScreen(true);
     } else setMatch(nextState);
     setPendingCheckoutScore(null);
  };

  const currentPlayer = match.players[match.currentPlayerIndex];
  const teams = Array.from(new Set(match.players.map(p => p.teamId)));

  return (
    <div className="h-[100dvh] w-full bg-black text-white flex flex-col overflow-hidden relative">
      <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20">
        <div className="flex flex-col">
           <div className="font-black italic text-sm md:text-lg"><span className="text-white">BOUGNAT</span> <span className="text-orange-500">DARTS</span></div>
           <div className="text-[8px] md:text-[10px] font-mono text-gray-500 uppercase">Sortie: {match.config.checkOut}</div>
        </div>

        {/* CENTER TIME & TIMER */}
        <div className="flex flex-col items-center justify-center">
            <div className="text-gray-500 font-mono text-[10px] leading-none mb-1">{currentTime}</div>
            <div className="text-orange-500 font-mono font-bold text-sm md:text-base leading-none tracking-widest">{formatDuration(elapsedSeconds)}</div>
        </div>

        <div className="flex gap-2">
            <button onClick={() => setShowStats(true)} className="text-[10px] font-bold uppercase border border-gray-700 px-2 py-1 rounded bg-gray-800">Stats</button>
            <button onClick={() => setShowExitConfirm(true)} className="text-red-500 text-[10px] font-bold uppercase border border-red-900/30 px-2 py-1 rounded">Quitter</button>
        </div>
      </div>

      <div className="flex-1 relative flex items-stretch">
        {feedbackMessage && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
                <div className={`transform rotate-[-5deg] border-4 px-8 py-4 rounded-xl shadow-2xl ${feedbackMessage.type === 'bust' ? 'bg-red-600 border-red-400' : 'bg-cyan-600 border-cyan-400'}`}>
                    <h1 className="text-5xl font-black italic uppercase">{feedbackMessage.text}</h1>
                </div>
            </div>
        )}
        <div className="flex-1 border-r border-gray-800/50">{renderPlayerArea(teams[0])}</div>
        <div className="flex-1">{renderPlayerArea(teams[1])}</div>

        {/* Pilule Centrale de Score Relevée à bottom-32 */}
        <div className="absolute bottom-32 left-1/2 transform -translate-x-1/2 flex flex-col items-center z-20">
            <div className="bg-gray-900/95 backdrop-blur-md border border-gray-700 px-5 py-2 rounded-full shadow-[0_0_30px_rgba(0,0,0,0.5)] flex items-center space-x-4 mb-1">
                 {/* Team 1 */}
                 <div className="flex items-center gap-1.5">
                    <span className="text-orange-500 font-black text-2xl font-mono leading-none">
                        {match.config.matchMode === 'SETS' ? match.setsWon[teams[0]] : match.legsWon[teams[0]]}
                    </span>
                    {match.config.matchMode === 'SETS' && (
                        <span className="text-gray-500 font-mono text-xs font-bold">({match.legsWon[teams[0]]})</span>
                    )}
                 </div>

                 {/* Label Central */}
                 <span className="text-[10px] text-gray-600 font-black uppercase tracking-widest border-x border-gray-800 px-3 h-4 flex items-center">
                    {match.config.matchMode === 'SETS' ? 'SETS' : 'LEGS'}
                 </span>

                 {/* Team 2 */}
                 <div className="flex items-center gap-1.5">
                    {match.config.matchMode === 'SETS' && (
                        <span className="text-gray-500 font-mono text-xs font-bold">({match.legsWon[teams[1]]})</span>
                    )}
                    <span className="text-orange-500 font-black text-2xl font-mono leading-none">
                        {match.config.matchMode === 'SETS' ? match.setsWon[teams[1]] : match.legsWon[teams[1]]}
                    </span>
                 </div>
            </div>
            {/* Sous-badge d'objectif */}
            <div className="text-[9px] text-gray-500 font-bold bg-black/40 px-3 py-1 rounded-full border border-white/5 uppercase tracking-wider">
                {match.config.matchMode === 'SETS' 
                    ? `Premier à ${match.config.setsToWin} Sets (${match.config.legsToWin} Legs/Set)` 
                    : `Premier à ${match.config.legsToWin} Legs`}
            </div>
        </div>
      </div>

      <div className="shrink-0 bg-gray-900 border-t border-gray-800 pb-safe h-[40dvh] flex flex-col">
         <div className="h-12 bg-black/40 flex items-center justify-between px-4 border-b border-gray-800">
             <div className="text-[10px] font-bold text-gray-500 uppercase">
                {!match.config.enableVoice 
                    ? "IA non activée" 
                    : (isListening ? "À l'écoute..." : "Prêt")
                }
             </div>
             <div className="text-2xl font-mono font-bold text-orange-500 tracking-widest">{inputBuffer || "---"}</div>
             <button onClick={() => setMatch(undoTurn(match))} className="text-[10px] font-bold text-gray-500 uppercase">Annuler ↶</button>
         </div>
         <div className="flex-1 p-2 flex gap-2">
            <div className="flex-1">
               <Keypad 
                  currentInput={inputBuffer} 
                  onInput={v => setInputBuffer(prev => (prev+v).slice(0,3))} 
                  onClear={() => setInputBuffer('')} 
                  onEnter={handleSubmitScore} 
                  isCheckoutPossible={false} 
                  hasVoiceSupport={hasRecognitionSupport} 
                  isListening={isListening} 
                  onMicClick={startListening} 
                  isVoiceEnabled={match.config.enableVoice}
               />
            </div>
            <div className="w-24 flex flex-col gap-2">
                <Button className="flex-1 text-3xl font-black" onClick={handleSubmitScore}>OK</Button>
            </div>
         </div>
      </div>

      {showWinnerScreen && (
          <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
             <h1 className="text-6xl font-black italic text-orange-500 mb-4 text-center">VAINQUEUR</h1>
             <div className="text-3xl font-bold text-white mb-12 uppercase border-b-4 border-orange-500 pb-4 text-center">
                 {match.matchWinnerId ? (match.players.find(p => p.teamId === match.matchWinnerId)?.name) : ''}
             </div>
             <Button onClick={() => onFinishWithState ? onFinishWithState(match.matchWinnerId!, match) : onFinish(match.matchWinnerId!)} size="lg" className="w-full max-w-xs h-20 text-2xl uppercase">Voir les Stats ➔</Button>
          </div>
      )}

      {showExitConfirm && (
          <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700">
                <h3 className="text-2xl font-black text-white mb-2 italic uppercase">Quitter le match ?</h3>
                <div className="grid grid-cols-2 gap-3 mt-8">
                    <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>NON</Button>
                    <Button variant="danger" onClick={onExit}>OUI</Button>
                </div>
            </div>
          </div>
      )}

      {pendingCheckoutScore !== null && (
          <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-center p-6">
              <h2 className="text-3xl font-black italic text-white mb-8 uppercase tracking-tighter">Game Shot !</h2>
              <p className="text-gray-500 mb-4 text-xs font-bold uppercase tracking-widest">Fléchettes utilisées</p>
              <div className="grid grid-cols-3 gap-4 w-full max-w-sm">
                  {[1, 2, 3].map(d => (
                      <Button key={d} onClick={() => handleCheckoutConfirm(d)} className="h-20 text-4xl">{d}</Button>
                  ))}
              </div>
          </div>
      )}

      {showStats && <StatsModal match={match} onClose={() => setShowStats(false)} title="Statistiques" />}
    </div>
  );

  function renderPlayerArea(teamId: string) {
      const isTeamActive = currentPlayer.teamId === teamId;
      const teamPlayers = match.players.filter(p => p.teamId === teamId);
      const displayName = match.config.isDoubles ? (teamId === 'team1' ? 'ÉQUIPE 1' : 'ÉQUIPE 2') : teamPlayers[0]?.name;

      const calcAvg = (history: Turn[]) => {
          const s = history.reduce((a, t) => a + (t.isBust ? 0 : t.score), 0);
          const d = history.reduce((a, t) => a + t.dartsThrown, 0);
          return d > 0 ? ((s / d) * 3).toFixed(1) : "0.0";
      };

      const allHistory = [...match.completedLegs, match.currentLeg].flatMap(l => l.history).filter(t => match.players.find(pl => pl.id === t.playerId)?.teamId === teamId);

      return (
        <PlayerScore 
            name={displayName} 
            isActive={isTeamActive} 
            score={match.currentLeg.scores[teamId]} 
            legsWon={match.legsWon[teamId]}
            stats={{
                matchAvg: calcAvg(allHistory),
                legAvg: calcAvg(match.currentLeg.history.filter(t => match.players.find(pl => pl.id === t.playerId)?.teamId === teamId)),
                legDarts: match.currentLeg.history.filter(t => match.players.find(pl => pl.id === t.playerId)?.teamId === teamId).reduce((a, t) => a + t.dartsThrown, 0),
                lastScore: allHistory[allHistory.length-1]?.score || null
            }}
        />
      );
  }
};

import React, { useEffect, useState } from 'react';
import { Button } from '../components/ui/Button';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';

interface VoiceLoaderViewProps {
  onLoaded: () => void;
  onSkip: () => void;
}

export const VoiceLoaderView: React.FC<VoiceLoaderViewProps> = ({ onLoaded, onSkip }) => {
  const { hasRecognitionSupport, logs, error } = useSpeechRecognition();
  const [progress, setProgress] = useState(0);

  // Native speech recognition is available immediately if supported by the browser.
  const isModelLoaded = hasRecognitionSupport;
  const isModelMissing = !hasRecognitionSupport;

  // Auto-redirect on success after a short delay for visual confirmation
  useEffect(() => {
    if (isModelLoaded) {
      setProgress(100);
      const timer = setTimeout(() => {
        onLoaded();
      }, 800);
      return () => clearTimeout(timer);
    }
  }, [isModelLoaded, onLoaded]);

  // Simulate progress based on logs for better UX
  useEffect(() => {
    const lastLog = logs[logs.length - 1] || "";
    if (lastLog.includes("Step 1")) setProgress(30);
    else if (lastLog.includes("Download Complete")) setProgress(60);
    else if (lastLog.includes("Step 2")) setProgress(75);
    else if (lastLog.includes("Step 3")) setProgress(90);
  }, [logs]);

  // Extract a user-friendly message from the logs
  const getFriendlyStatus = () => {
      if (isModelMissing) return "Browser Not Supported";
      if (isModelLoaded) return "Voice System Ready";

      const lastLog = logs[logs.length - 1] || "";
      if (lastLog.includes("Step 1")) return "Downloading AI Model...";
      if (lastLog.includes("Step 2")) return "Initializing Engine...";
      if (lastLog.includes("Step 3")) return "Configuring Neural Net...";
      return "Initializing...";
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col items-center justify-center relative overflow-hidden">

        {/* Background Decor */}
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20 pointer-events-none"></div>
        <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-orange-600/10 rounded-full blur-[120px] pointer-events-none animate-pulse"></div>

        {/* MAIN CARD */}
        <div className="z-10 w-full max-w-md bg-gray-900/80 backdrop-blur-xl border border-gray-800 rounded-2xl p-8 shadow-2xl flex flex-col items-center text-center">

            {/* ICON AREA */}
            <div className="mb-8 relative">
                <div className={`w-24 h-24 rounded-full flex items-center justify-center border-4 shadow-[0_0_30px_rgba(0,0,0,0.5)] transition-all duration-500
                    ${isModelMissing ? 'border-red-600 bg-red-900/20' : 
                      isModelLoaded ? 'border-green-500 bg-green-900/20 shadow-green-500/20' : 
                      'border-orange-500 bg-orange-900/20 shadow-orange-500/20 animate-pulse'}
                `}>
                    {isModelMissing ? (
                         <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-10 h-10 text-red-500">
                             <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" />
                         </svg>
                    ) : isModelLoaded ? (
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-10 h-10 text-green-500">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
                        </svg>
                    ) : (
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-10 h-10 text-orange-500">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                        </svg>
                    )}
                </div>
            </div>

            {/* TEXT STATUS */}
            <h2 className="text-2xl font-black italic uppercase tracking-wider mb-2 text-white">
                {isModelLoaded ? "READY TO PLAY" : "VOICE ASSISTANT"}
            </h2>

            <p className={`text-sm font-bold uppercase tracking-widest mb-6 ${isModelMissing ? 'text-red-500' : 'text-gray-400'}`}>
                {getFriendlyStatus()}
            </p>

            {/* PROGRESS BAR (Only if loading) */}
            {!isModelLoaded && !isModelMissing && (
                <div className="w-full bg-gray-800 rounded-full h-2 mb-8 overflow-hidden relative">
                    <div 
                        className="bg-gradient-to-r from-orange-600 to-red-600 h-full transition-all duration-500 ease-out shadow-[0_0_10px_rgba(234,88,12,0.6)]"
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>
            )}

            {/* ERROR HANDLING UI */}
            {isModelMissing && (
                <div className="mb-6 bg-red-900/10 border border-red-800/50 rounded-lg p-4 text-left w-full">
                     <p className="text-xs text-red-300 font-mono mb-2">
                        {error || "This browser does not support Speech Recognition. Try Chrome, Safari or Edge."}
                     </p>
                     <p className="text-[10px] text-gray-500 uppercase font-bold">
                        Error Code: BROWSER_NOT_SUPPORTED
                     </p>
                </div>
            )}

            {/* ACTION BUTTONS */}
            <div className="w-full space-y-3">
                {isModelLoaded ? (
                     <Button onClick={onLoaded} className="w-full h-14 text-lg bg-green-600 hover:bg-green-500 shadow-lg shadow-green-900/40">
                        ENTER MATCH
                     </Button>
                ) : (
                    <Button 
                        variant="ghost" 
                        onClick={onSkip} 
                        className="w-full text-gray-500 hover:text-white border border-gray-800 hover:bg-gray-800"
                    >
                        {isModelMissing ? 'CONTINUE WITHOUT VOICE' : 'SKIP & PLAY MANUALLY'}
                    </Button>
                )}
            </div>

            {/* Footer Tech Text */}
            <div className="mt-6 text-[9px] text-gray-600 font-mono uppercase">
                Powered by Web Speech API
            </div>
        </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Button } from '../ui/Button';

interface MatchSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  shortcutsLeft: number[];
  shortcutsRight: number[];
  onUpdateShortcuts: (side: 'left' | 'right', newValues: number[]) => void;
  showHints: boolean;
  onToggleHints: () => void;
}

export const MatchSettingsModal: React.FC<MatchSettingsModalProps> = ({
  isOpen,
  onClose,
  shortcutsLeft,
  shortcutsRight,
  onUpdateShortcuts,
  showHints,
  onToggleHints
}) => {
  if (!isOpen) return null;

  // Helper to update a specific index in the array
  const handleInputChange = (side: 'left' | 'right', index: number, valStr: string) => {
    const val = parseInt(valStr);
    if (isNaN(val)) return;

    const newArr = side === 'left' ? [...shortcutsLeft] : [...shortcutsRight];
    newArr[index] = Math.min(180, Math.max(0, val)); // Clamp 0-180
    onUpdateShortcuts(side, newArr);
  };

  return (
    <div className="fixed inset-0 z-[60] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="bg-gray-950 p-4 border-b border-gray-800 flex justify-between items-center">
            <h3 className="text-lg font-black italic text-white uppercase tracking-wider">Options du Match</h3>
            <button onClick={onClose} className="text-gray-500 hover:text-white transition-colors text-2xl leading-none">×</button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6 overflow-y-auto">

            {/* Toggles */}
            <section>
                <h4 className="text-orange-500 text-xs font-bold uppercase tracking-widest mb-3">Affichage & Aides</h4>
                <div className="bg-gray-800/50 p-3 rounded-lg flex items-center justify-between border border-gray-700">
                    <span className="text-sm font-bold text-gray-300">Aides à la sortie (Checkout Hints)</span>
                    <button 
                        onClick={onToggleHints}
                        className={`w-12 h-6 rounded-full relative transition-colors duration-300 ${showHints ? 'bg-cyan-600' : 'bg-gray-600'}`}
                    >
                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform duration-300 ${showHints ? 'left-7' : 'left-1'}`}></div>
                    </button>
                </div>
            </section>

            {/* Shortcuts Config */}
            <section>
                <div className="flex justify-between items-center mb-3">
                    <h4 className="text-cyan-500 text-xs font-bold uppercase tracking-widest">Raccourcis Clavier (Desktop)</h4>
                    <span className="text-[9px] bg-gray-800 text-gray-500 px-2 py-0.5 rounded border border-gray-700">Masqué sur mobile</span>
                </div>

                <div className="grid grid-cols-2 gap-6">
                    {/* Left Column */}
                    <div>
                        <div className="text-[10px] text-gray-500 font-mono text-center mb-2 uppercase">Gauche</div>
                        <div className="space-y-2">
                            {shortcutsLeft.map((val, idx) => (
                                <div key={`L-${idx}`} className="flex items-center bg-gray-800 rounded border border-gray-700 px-2">
                                    <span className="text-gray-500 text-xs font-mono mr-2">#{idx+1}</span>
                                    <input 
                                        type="number" 
                                        value={val}
                                        onChange={(e) => handleInputChange('left', idx, e.target.value)}
                                        className="w-full bg-transparent text-white font-bold py-2 focus:outline-none text-center"
                                    />
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Right Column */}
                    <div>
                        <div className="text-[10px] text-gray-500 font-mono text-center mb-2 uppercase">Droite</div>
                        <div className="space-y-2">
                            {shortcutsRight.map((val, idx) => (
                                <div key={`R-${idx}`} className="flex items-center bg-gray-800 rounded border border-gray-700 px-2">
                                    <span className="text-gray-500 text-xs font-mono mr-2">#{idx+1}</span>
                                    <input 
                                        type="number" 
                                        value={val}
                                        onChange={(e) => handleInputChange('right', idx, e.target.value)}
                                        className="w-full bg-transparent text-white font-bold py-2 focus:outline-none text-center"
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
                <p className="text-[10px] text-gray-600 mt-3 italic text-center">
                    Ces boutons s'affichent uniquement sur les écrans larges.
                </p>
            </section>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-800 bg-gray-950">
            <Button onClick={onClose} className="w-full">Valider</Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState, Turn } from '../types';
import { submitTurn, undoTurn, getMinDartsForScore, formatDuration } from '../utils/gameLogic';
import { PlayerScore } from '../components/game/PlayerScore';
import { Keypad } from '../components/game/Keypad';
import { Button } from '../components/ui/Button';
import { CheckoutHint } from '../components/game/CheckoutHint';
import { StatsModal } from '../components/stats/StatsModal';
import { MatchSettingsModal } from '../components/game/MatchSettingsModal';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';

interface MatchViewProps {
  initialMatch: MatchState;
  onFinish: (winnerId: string) => void;
  onFinishWithState?: (winnerId: string, match: MatchState) => void;
  onExit: () => void;
}

export const MatchView: React.FC<MatchViewProps> = ({ initialMatch, onFinish, onFinishWithState, onExit }) => {
  const [match, setMatch] = useState<MatchState>(initialMatch);
  const [inputBuffer, setInputBuffer] = useState<string>('');
  const [currentTime, setCurrentTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const matchStatusRef = useRef(match.status);

  // Voice Hook
  const { isListening, transcript, startListening, hasRecognitionSupport, resetTranscript } = useSpeechRecognition();

  // Modals & UI States
  const [showStats, setShowStats] = useState(false);
  const [showMatchSettings, setShowMatchSettings] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showWinnerScreen, setShowWinnerScreen] = useState(false);

  // Game Interaction States
  const [pendingCheckoutScore, setPendingCheckoutScore] = useState<number | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<{ text: string, type: 'bust' | 'miss' | 'info' } | null>(null);

  // --- SETTINGS STATE (Local to Match) ---
  const [showHints, setShowHints] = useState(true);
  const [shortcutsLeft, setShortcutsLeft] = useState<number[]>([41, 45, 60, 100]);
  const [shortcutsRight, setShortcutsRight] = useState<number[]>([26, 81, 85, 140]);

  useEffect(() => {
    matchStatusRef.current = match.status;
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      if (matchStatusRef.current === 'active') setElapsedSeconds(prev => prev + 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [match.status]);

  useEffect(() => {
      if (transcript && match.config.enableVoice) {
          const result = parseDartsVoiceCommand(transcript);
          if (result.type === 'SCORE' && result.value !== undefined) setInputBuffer(result.value.toString());
          else if (result.type === 'COMMAND_SUBMIT') { if (inputBuffer) handleSubmitScore(); }
          else if (result.type === 'COMMAND_CLEAR') setInputBuffer('');
          else if (result.type === 'COMMAND_UNDO') setMatch(undoTurn(match));
      }
  }, [transcript]);

  const triggerFeedback = (text: string, type: 'bust' | 'miss' | 'info') => {
      setFeedbackMessage({ text, type });
      setTimeout(() => setFeedbackMessage(null), 1500);
  };

  const processScoreSubmission = (score: number) => {
      if (isNaN(score) || score > 180) return triggerFeedback("INVALIDE", "bust");
      const currentPlayer = match.players[match.currentPlayerIndex];
      const currentScore = match.currentLeg.scores[currentPlayer.teamId];

      if (score === currentScore) {
           setPendingCheckoutScore(score);
           setInputBuffer(''); 
           return;
      }

      let nextState = submitTurn(match, score, 3);
      if (nextState.status === 'finished') {
          setMatch({ ...nextState, duration: elapsedSeconds });
          setShowWinnerScreen(true);
          return;
      }

      const lastTurn = nextState.currentLeg.history[nextState.currentLeg.history.length - 1];
      if (lastTurn?.isBust) triggerFeedback("TROP !", "bust");
      else if (score >= 100) triggerFeedback(score.toString(), "info");

      setMatch(nextState);
      setInputBuffer('');
      resetTranscript();
  };

  const handleSubmitScore = () => inputBuffer && processScoreSubmission(parseInt(inputBuffer));

  const handleQuickScore = (val: number) => {
      processScoreSubmission(val);
  };

  const handleCheckoutConfirm = (dartsUsed: number) => {
     if (pendingCheckoutScore === null) return;
     let nextState = submitTurn(match, pendingCheckoutScore, dartsUsed);
