          triggerFeedback("IMPOSSIBLE", "bust");
          return;
      }

      const impliedScore = currentScore - targetRemaining;

      // Validation du score implicite (ex: score de 200 impossible)
      if (impliedScore > 180) {
           triggerFeedback("MAX 180", "bust");
           return;
      }

      processScoreSubmission(impliedScore);
  };

