Here is a clean architecture proposal and implementation strategy to add Server-side ASR capabilities alongside your existing stack without regression.

### 1. Architecture Proposal & File Tree

We will introduce a **Strategy Pattern** for voice recognition. The Application normally consumes a hook that defaults to the Browser strategy. The Settings page will instantiate the Server strategy directly for testing.

**File Structure:**
```text
src/
├── utils/
│   └── voiceParser.ts            # (Existing) Your logic to convert "Triple 20" -> 60
├── voice/
│   ├── types.ts                  # Shared interfaces and Enums
│   ├── audio/
│   │   └── AudioRecorder.ts      # Handles Mic stream & conversion to 16k mono PCM
│   ├── providers/
│   │   ├── BrowserRecognitionProvider.ts # Wrapper around existing Web Speech API
│   │   └── ServerAsrRecognitionProvider.ts # NEW: WebSocket + AudioRecorder implementation
│   └── useVoiceProvider.ts       # Hook to consume a provider in React
└── views/
    └── Settings/
        └── VoiceDebugPanel.tsx   # NEW: The isolated test UI
```

---

### 2. Shared Types Definition

Create `src/voice/types.ts`. This decouples the UI from the specific technology.

```typescript
// src/voice/types.ts

export type VoiceStatus = 'idle' | 'connecting' | 'listening' | 'processing' | 'error';

export interface TranscriptionResult {
    text: string;
    isFinal: boolean;
    timestamp: number;
    latency?: number; // Processing time in ms
}

export interface VoiceError {
    code: string;
    message: string;
    originalError?: any;
}

export interface IVoiceRecognitionProvider {
    readonly id: string;
    readonly label: string;

    // Lifecycle
    connect(): Promise<void>;
    disconnect(): void;
    start(): Promise<void>;
    stop(): void;

    // Event Subscriptions
    onStatusChange(callback: (status: VoiceStatus) => void): void;
    onTranscript(callback: (result: TranscriptionResult) => void): void;
    onError(callback: (error: VoiceError) => void): void;
}

export interface ServerAsrConfig {
    enabled: boolean;
    wsUrl: string;
    modelLabel: string;
    vadMode: 'none' | 'simpleEnergy';
}
```

---

### 3. Server ASR Provider Implementation

Create `src/voice/providers/ServerAsrRecognitionProvider.ts`. This handles the WebSocket connection and binary audio streaming.

**Prerequisites:** Assumes the server accepts raw PCM (16-bit, 16kHz, Mono) or similar binary stream over WebSocket and returns JSON `{ text: string, is_final: boolean }`.

```typescript
// src/voice/providers/ServerAsrRecognitionProvider.ts
import { IVoiceRecognitionProvider, VoiceStatus, TranscriptionResult, VoiceError, ServerAsrConfig } from '../types';

export class ServerAsrRecognitionProvider implements IVoiceRecognitionProvider {
    readonly id = 'server-asr';
    readonly label = 'Server ASR (Experimental)';

    private socket: WebSocket | null = null;
    private audioContext: AudioContext | null = null;
    private processor: ScriptProcessorNode | null = null;
    private stream: MediaStream | null = null;
    private config: ServerAsrConfig;

    // Event Listeners
    private statusListeners: ((s: VoiceStatus) => void)[] = [];
    private transcriptListeners: ((r: TranscriptionResult) => void)[] = [];
    private errorListeners: ((e: VoiceError) => void)[] = [];

    constructor(config: ServerAsrConfig) {
        this.config = config;
    }

    onStatusChange(cb: (s: VoiceStatus) => void) { this.statusListeners.push(cb); }
    onTranscript(cb: (r: TranscriptionResult) => void) { this.transcriptListeners.push(cb); }
    onError(cb: (e: VoiceError) => void) { this.errorListeners.push(cb); }

    private setStatus(status: VoiceStatus) {
        this.statusListeners.forEach(cb => cb(status));
    }

    async connect(): Promise<void> {
        if (!this.config.wsUrl) {
            this.emitError('CONFIG', 'WebSocket URL is missing');
            return;
        }

        this.setStatus('connecting');

        try {
            this.socket = new WebSocket(this.config.wsUrl);

            this.socket.onopen = () => {
                this.setStatus('idle');
            };

            this.socket.onmessage = (event) => {
                try {
                    const data = JSON.parse(event.data);
                    // Adapt this to match your actual server response schema
                    const result: TranscriptionResult = {
                        text: data.text || '',
                        isFinal: data.is_final || false,
                        timestamp: Date.now(),
                        latency: data.processing_time // if available from server
                    };

                    if (result.text.trim()) {
                        this.transcriptListeners.forEach(cb => cb(result));
                    }
                } catch (e) {
                    console.warn('Failed to parse ASR message', e);
                }
            };

            this.socket.onerror = (e) => {
                this.emitError('WS_ERROR', 'WebSocket error occurred', e);
                this.setStatus('error');
            };

            this.socket.onclose = () => {
                this.setStatus('idle');
            };
        } catch (e) {
            this.emitError('CONNECTION_FAILED', 'Could not create WebSocket', e);
        }
    }

    async start(): Promise<void> {
        if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
            await this.connect();
        }

        try {
            this.setStatus('listening');

            // 1. Setup Audio Context
            this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

            // 2. Get Mic Stream
            this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = this.audioContext.createMediaStreamSource(this.stream);

            // 3. Setup Processing (Simple approach: ScriptProcessor)
            // Note: In production AudioWorklet is preferred, but ScriptProcessor is easier for a quick skeleton
            this.processor = this.audioContext.createScriptProcessor(4096, 1, 1);

            source.connect(this.processor);
            this.processor.connect(this.audioContext.destination);

            this.processor.onaudioprocess = (e) => {
                if (this.socket && this.socket.readyState === WebSocket.OPEN) {
                    const inputData = e.inputBuffer.getChannelData(0);
                    // Downsample logic or conversion to PCM 16bit happens here
                    const pcmData = this.floatTo16BitPCM(inputData);
                    this.socket.send(pcmData);
                }
            };
        } catch (e) {
            this.emitError('MIC_ACCESS', 'Microphone access denied', e);
        }
    }

    stop(): void {
        this.setStatus('processing'); // Often there is a tail of processing

        // Cleanup Audio
        if (this.stream) this.stream.getTracks().forEach(t => t.stop());
        if (this.processor) this.processor.disconnect();
        if (this.audioContext) this.audioContext.close();

        this.stream = null;
        this.processor = null;
        this.audioContext = null;

        // Optional: Send EOF message to server
        if (this.socket?.readyState === WebSocket.OPEN) {
            this.socket.send(JSON.stringify({ type: 'stop' }));
        }

        this.setStatus('idle');
    }

    disconnect(): void {
        this.stop();
        if (this.socket) {
            this.socket.close();
            this.socket = null;
        }
    }

    private emitError(code: string, msg: string, original?: any) {
        const error = { code, message: msg, originalError: original };
        this.errorListeners.forEach(cb => cb(error));
    }

    // Utility: Convert Float32 (Web Audio) to Int16 (Server standard)
    private floatTo16BitPCM(input: Float32Array): ArrayBuffer {
        const output = new DataView(new ArrayBuffer(input.length * 2));
        for (let i = 0; i < input.length; i++) {
            const s = Math.max(-1, Math.min(1, input[i]));
            output.setInt16(i * 2, s < 0 ? s * 0x8000 : s * 0x7FFF, true); // little-endian
        }
        return output.buffer;
    }
}
```

---

### 4. Settings / Debug Panel

Create `src/views/Settings/VoiceDebugPanel.tsx`. This component is completely isolated from gameplay. It manages its own instance of the provider based on local state configuration.

```tsx
// src/views/Settings/VoiceDebugPanel.tsx
import React, { useState, useEffect, useRef } from 'react';
import { ServerAsrRecognitionProvider } from '../../voice/providers/ServerAsrRecognitionProvider';
import { VoiceStatus, TranscriptionResult, VoiceError } from '../../voice/types';
import { parseDartsVoiceCommand } from '../../utils/voiceParser'; // Your existing parser

const STORAGE_KEY = 'darts_app_experimental_asr_config';

export const VoiceDebugPanel: React.FC = () => {
    // 1. Config State
    const [config, setConfig] = useState(() => {
        const saved = localStorage.getItem(STORAGE_KEY);
        return saved ? JSON.parse(saved) : {
            enabled: false,
            wsUrl: import.meta.env.VITE_SERVER_ASR_WS_URL || 'ws://localhost:9000/transcribe',
            modelLabel: 'faster-whisper-medium',
            vadMode: 'simpleEnergy'
        };
    });

    // 2. Runtime State
    const [status, setStatus] = useState<VoiceStatus>('idle');
    const [logs, setLogs] = useState<Array<{time: string, type: string, msg: string, parsed?: any}>>([]);
    const [currentPartial, setCurrentPartial] = useState<string>('');
    const providerRef = useRef<ServerAsrRecognitionProvider | null>(null);

    // 3. Persist Config
    useEffect(() => {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
    }, [config]);

    // 4. Initialize Provider (Only when in this panel)
    useEffect(() => {
        if (!config.enabled) return;

        const provider = new ServerAsrRecognitionProvider(config);

        provider.onStatusChange(setStatus);
        provider.onError((e) => addLog('ERROR', `${e.code}: ${e.message}`));

        provider.onTranscript((res) => {
            if (res.isFinal) {
                // RUN EXISTING PARSER HERE
                const parsedResult = parseDartsVoiceCommand(res.text);

                addLog('FINAL', res.text, parsedResult);
                setCurrentPartial('');
            } else {
                setCurrentPartial(res.text);
            }
        });

        providerRef.current = provider;

        // Cleanup
        return () => {
            provider.disconnect();
        };
    }, [config.enabled, config.wsUrl]); // Re-init on critical config change

    const addLog = (type: string, msg: string, parsed?: any) => {
        setLogs(prev => [{
            time: new Date().toISOString().split('T')[1].slice(0, -1),
            type,
            msg,
            parsed
        }, ...prev].slice(0, 50)); // Keep last 50
    };

    const toggleListening = async () => {
        if (!providerRef.current) return;
        if (status === 'listening') {
            providerRef.current.stop();
        } else {
            await providerRef.current.start();
        }
    };

    const updateConfig = ( key: keyof typeof config, value: any) => {
        setConfig(prev => ({ ...prev, [key]: value }));
    };

    return (
        <div className="p-4 border rounded bg-gray-900 text-white">
