import { IVoiceRecognitionProvider, VoiceStatus, TranscriptionResult, VoiceError, ServerAsrConfig } from '../types';

export class ServerAsrRecognitionProvider implements IVoiceRecognitionProvider {
    readonly id = 'server-asr';
    readonly label = 'Server ASR (Experimental)';

    private socket: WebSocket | null = null;
    private audioContext: AudioContext | null = null;
    private processor: ScriptProcessorNode | null = null;
    private stream: MediaStream | null = null;
    private source: MediaStreamAudioSourceNode | null = null;

    private config: ServerAsrConfig;
    private status: VoiceStatus = 'idle';

    // Event Listeners
    private statusListeners: Set<(s: VoiceStatus) => void> = new Set();
    private transcriptListeners: Set<(r: TranscriptionResult) => void> = new Set();
    private errorListeners: Set<(e: VoiceError) => void> = new Set();

    constructor(config: ServerAsrConfig) {
        this.config = config;
    }

    onStatusChange(cb: (s: VoiceStatus) => void) { this.statusListeners.add(cb); }
    onTranscript(cb: (r: TranscriptionResult) => void) { this.transcriptListeners.add(cb); }
    onError(cb: (e: VoiceError) => void) { this.errorListeners.add(cb); }

    private setStatus(newStatus: VoiceStatus) {
        this.status = newStatus;
        this.statusListeners.forEach(cb => cb(newStatus));
    }

    async connect(): Promise<void> {
        if (this.socket?.readyState === WebSocket.OPEN) return;
        if (!this.config.wsUrl) {
            this.emitError('CONFIG', 'WebSocket URL is missing');
            return;
        }

        this.setStatus('connecting');

        return new Promise((resolve, reject) => {
            try {
                this.socket = new WebSocket(this.config.wsUrl);

                this.socket.onopen = () => {
                    this.setStatus('idle');
                    resolve();
                };

                this.socket.onmessage = (event) => {
                    this.handleMessage(event.data);
                };

                this.socket.onerror = (e) => {
                    console.error('ASR WS Error:', e);
                    this.emitError('WS_ERROR', 'WebSocket connection failed');
                    this.setStatus('error');
                    reject(e);
                };

                this.socket.onclose = () => {
                    if (this.status !== 'error') this.setStatus('idle');
                    this.cleanupAudio();
                };
            } catch (e) {
                this.emitError('CONNECTION_FAILED', 'Could not create WebSocket', e);
                reject(e);
            }
        });
    }

    private handleMessage(data: any) {
        try {
            const msg = JSON.parse(data);

            // Expected protocol: { type: "partial"|"final", text: "..." }
            if (msg.text) {
                const result: TranscriptionResult = {
                    text: msg.text,
                    isFinal: msg.type === 'final',
                    timestamp: Date.now(),
                    latency: msg.processing_time
                };
                this.transcriptListeners.forEach(cb => cb(result));
            }
        } catch (e) {
            // Ignore non-JSON messages or malformed data
        }
    }

    async start(): Promise<void> {
        if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
            try {
                await this.connect();
            } catch (e) {
                return;
            }
        }

        try {
            // 1. Setup Audio Context (16kHz requirement usually)
            const sampleRate = 16000;
            this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ 
                sampleRate 
            });

            // 2. Get Mic Stream
            this.stream = await navigator.mediaDevices.getUserMedia({ 
                audio: { 
                    channelCount: 1, 
                    echoCancellation: true, 
                    noiseSuppression: true,
                    autoGainControl: true 
                } 
            });

            this.source = this.audioContext.createMediaStreamSource(this.stream);

            // 3. Setup Processing
            // Using ScriptProcessor for compatibility and simplicity in this context
            this.processor = this.audioContext.createScriptProcessor(4096, 1, 1);

            this.source.connect(this.processor);
            this.processor.connect(this.audioContext.destination);

            this.processor.onaudioprocess = (e) => {
                this.processAudioFrame(e.inputBuffer.getChannelData(0));
            };

            this.setStatus('listening');
        } catch (e) {
            this.emitError('MIC_ACCESS', 'Microphone access denied or audio error', e);
            this.cleanupAudio();
        }
    }

    private processAudioFrame(inputData: Float32Array) {
        if (!this.socket || this.socket.readyState !== WebSocket.OPEN) return;

        // VAD Check
        if (this.config.vadMode === 'simpleEnergy') {
            const rms = Math.sqrt(inputData.reduce((acc, val) => acc + val * val, 0) / inputData.length);
            if (rms < (this.config.vadThreshold || 0.01)) {
                return; // Silence
            }
        }

        // Convert Float32 to Int16 PCM
        const pcmData = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) {
            const s = Math.max(-1, Math.min(1, inputData[i]));
            pcmData[i] = s < 0 ? s * 0x8000 : s * 0x7FFF;
        }

        this.socket.send(pcmData.buffer);
    }

    stop(): void {
        if (this.status === 'listening') {
            this.setStatus('processing'); // Wait for final result potentially
            // Optional: send EOS message to server if protocol supports it
            // if (this.socket) this.socket.send(JSON.stringify({ type: 'stop' }));
        }

        this.cleanupAudio();

        // Slight delay to allow final messages to arrive before setting idle
        setTimeout(() => {
            if (this.status === 'processing') this.setStatus('idle');
        }, 500);
    }

    disconnect(): void {
        this.stop();
        if (this.socket) {
            this.socket.close();
            this.socket = null;
        }
    }

    private cleanupAudio() {
        if (this.stream) {
            this.stream.getTracks().forEach(t => t.stop());
            this.stream = null;
        }
        if (this.source) {
            this.source.disconnect();
            this.source = null;
        }
        if (this.processor) {
            this.processor.disconnect();
            this.processor = null;
        }
        if (this.audioContext) {
            this.audioContext.close();
            this.audioContext = null;
        }
    }

    private emitError(code: string, msg: string, original?: any) {
        const error = { code, message: msg, originalError: original };
        this.errorListeners.forEach(cb => cb(error));
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { ServerAsrRecognitionProvider } from '../../voice/providers/ServerAsrRecognitionProvider';
import { VoiceStatus, TranscriptionResult } from '../../voice/types';
import { parseDartsVoiceCommand } from '../../utils/voiceParser';
import { Button } from '../ui/Button';

const STORAGE_KEY = 'darts_experimental_asr_v1';

export const VoiceDebugPanel: React.FC = () => {
    // Configuration
    const [config, setConfig] = useState(() => {
        const saved = localStorage.getItem(STORAGE_KEY);
        return saved ? JSON.parse(saved) : {
            enabled: false,
            wsUrl: import.meta.env.VITE_SERVER_ASR_WS_URL || 'ws://localhost:9000/transcribe',
            vadMode: 'simpleEnergy',
            vadThreshold: 0.01
        };
    });

    // Runtime State
    const [status, setStatus] = useState<VoiceStatus>('idle');
    const [logs, setLogs] = useState<Array<{t: string, type: string, msg: string, parsed?: any}>>([]);
    const [currentPartial, setCurrentPartial] = useState('');
    const providerRef = useRef<ServerAsrRecognitionProvider | null>(null);

    // Save config on change
    useEffect(() => {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
    }, [config]);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (providerRef.current) {
                providerRef.current.disconnect();
            }
        };
    }, []);

    const initProvider = () => {
        if (providerRef.current) return;

        const p = new ServerAsrRecognitionProvider(config);

        p.onStatusChange((s) => {
            setStatus(s);
            addLog('STATUS', s);
        });

        p.onError((e) => {
            addLog('ERROR', `${e.code}: ${e.message}`);
        });

        p.onTranscript((res: TranscriptionResult) => {
            if (res.isFinal) {
                const parsed = parseDartsVoiceCommand(res.text);
                addLog('FINAL', res.text, parsed);
                setCurrentPartial('');
            } else {
                setCurrentPartial(res.text);
            }
        });

        providerRef.current = p;
    };

    const addLog = (type: string, msg: string, parsed?: any) => {
        setLogs(prev => [{
            t: new Date().toLocaleTimeString(),
            type,
            msg,
            parsed
        }, ...prev].slice(0, 50));
    };

    const toggleListening = async () => {
        if (!config.enabled) return;

        initProvider();
        const p = providerRef.current!;

        if (status === 'listening' || status === 'connecting') {
            p.stop();
        } else {
            await p.start();
        }
    };

    const updateConfig = (key: string, val: any) => {
        setConfig((prev: any) => ({ ...prev, [key]: val }));
        // Force provider re-creation if config changes
        if (providerRef.current) {
            providerRef.current.disconnect();
            providerRef.current = null;
        }
    };

    if (!config.enabled && !localStorage.getItem(STORAGE_KEY)) {
        // Simple way to check if user has ever enabled it. If not, hide fully or show teaser.
        // For now, we show the toggle.
    }

    return (
        <div className="bg-gray-900 border border-gray-700 rounded-xl p-6 space-y-6 mt-8">
            <div className="flex items-center justify-between border-b border-gray-800 pb-4">
                <h2 className="text-xl font-black italic text-cyan-500">EXPERIMENTAL ASR</h2>
                <label className="flex items-center space-x-3 cursor-pointer">
                    <span className="text-xs font-bold text-gray-500 uppercase">Enable</span>
                    <input 
                        type="checkbox" 
                        checked={config.enabled}
                        onChange={(e) => updateConfig('enabled', e.target.checked)}
                        className="w-5 h-5 rounded border-gray-600 bg-gray-700 text-cyan-500 focus:ring-cyan-500"
                    />
                </label>
            </div>

            {config.enabled && (
                <>
                    {/* Settings Form */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">WebSocket URL</label>
                            <input 
                                value={config.wsUrl}
                                onChange={(e) => updateConfig('wsUrl', e.target.value)}
                                className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white text-sm font-mono"
                                placeholder="ws://localhost:9000"
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">VAD Threshold (RMS)</label>
                            <input 
                                type="number" step="0.001" min="0" max="0.1"
                                value={config.vadThreshold}
                                onChange={(e) => updateConfig('vadThreshold', parseFloat(e.target.value))}
                                className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white text-sm font-mono"
                            />
                        </div>
                    </div>

                    {/* Test Area */}
                    <div className="bg-black/50 rounded-lg border border-gray-800 p-4">
                        <div className="flex items-center justify-between mb-4">
                            <div className="flex items-center gap-3">
                                <Button 
                                    onClick={toggleListening}
                                    variant={status === 'listening' ? 'danger' : 'primary'}
                                    size="sm"
                                >
                                    {status === 'listening' ? 'STOP MIC' : 'START MIC'}
                                </Button>
                                <span className={`text-xs font-bold uppercase ${
                                    status === 'listening' ? 'text-green-500 animate-pulse' : 'text-gray-600'
                                }`}>
                                    {status}
                                </span>
                            </div>
                            <button onClick={() => setLogs([])} className="text-xs text-gray-500 hover:text-white underline">
                                Clear Logs
                            </button>
                        </div>

                        {/* Live Output */}
                        <div className="mb-4 min-h-[60px] p-3 rounded bg-gray-900 border border-gray-800">
                            <div className="text-gray-500 text-xs uppercase mb-1">Live Partial</div>
                            <div className="text-lg text-white font-mono">{currentPartial || '...'}</div>
                        </div>

                        {/* Logs */}
                        <div className="h-60 overflow-y-auto font-mono text-xs space-y-2 custom-scrollbar">
                            {logs.map((log, i) => (
                                <div key={i} className="flex gap-2 text-gray-400 border-b border-gray-800/50 pb-1">
                                    <span className="text-gray-600 shrink-0">{log.t}</span>
                                    <span className={`font-bold shrink-0 w-16 ${
                                        log.type === 'FINAL' ? 'text-green-400' :
                                        log.type === 'ERROR' ? 'text-red-400' : 'text-blue-400'
                                    }`}>{log.type}</span>
                                    <div className="flex-1 break-all">
                                        <span className="text-gray-300">{log.msg}</span>
                                        {log.parsed && (
                                            <div className="mt-1 ml-2 p-1 bg-gray-800 rounded text-cyan-300">
                                                ➔ PARSED: {JSON.stringify(log.parsed)}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '../components/ui/Button';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { parseDartsVoiceCommand } from '../utils/voiceParser';
import { VoiceDebugPanel } from '../components/settings/VoiceDebugPanel';

interface SettingsViewProps {
  onBack: () => void;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ onBack }) => {
  const { 
    isListening, 
    transcript, 
    startListening, 
    stopListening, 
    resetTranscript, 
    error, 
    activeMicrophone,
    logs,
  } = useSpeechRecognition();

  const [parsedResult, setParsedResult] = useState<string>('');
  const [manualInput, setManualInput] = useState('');
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Real-time parsing test
  useEffect(() => {
    if (transcript) {
        const result = parseDartsVoiceCommand(transcript);
        if (result.type === 'SCORE') {
            setParsedResult(`🎯 SCORE DETECTÉ: ${result.value} pts (${JSON.stringify(result.darts || [])})`);
        } else if (result.type === 'UNKNOWN') {
             setParsedResult(`❓ INCONNU (Raison: ${result.reason || 'No match'})`);
        } else {
             setParsedResult(`⚡ COMMANDE: ${result.type}`);
        }
    } else {
        if (!manualInput) {
            setParsedResult('En attente de parole ou de test manuel...');
        }
    }
  }, [transcript]);

  const handleManualTest = () => {
      if (!manualInput.trim()) return;
      const result = parseDartsVoiceCommand(manualInput);
      if (result.type === 'SCORE') {
          setParsedResult(`📝 [MANUEL] SCORE: ${result.value} pts\n🎯 Fléchettes: ${JSON.stringify(result.darts || [], null, 2)}`);
      } else if (result.type === 'UNKNOWN') {
           setParsedResult(`❓ [MANUEL] INCONNU\nRaison: ${result.reason || 'No match'}\nNormalisé: "${result.normalized}"`);
      } else {
           setParsedResult(`⚡ [MANUEL] COMMANDE: ${result.type}`);
      }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') handleManualTest();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      {/* HEADER */}
      <div className="flex items-center mb-6 shrink-0">
        <Button variant="ghost" onClick={() => { stopListening(); onBack(); }} size="sm">← Retour</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400 uppercase">
            PARAMÈTRES & DEBUG
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto space-y-8 max-w-4xl mx-auto w-full pb-10">

        {/* SECTION 1: VOICE ENGINE STATUS */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-orange-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                1. Moteur Vocal (Web Speech API)
            </h3>

            {/* Microphone Label */}
            {isListening && activeMicrophone && (
                <div className="mb-4 p-3 bg-black/40 border border-gray-700 rounded flex flex-col gap-2">
                    <div className="flex items-center justify-between">
                        <span className="text-gray-500 text-xs font-bold uppercase tracking-wider">Source Audio</span>
                        <span className="text-cyan-400 font-mono text-xs md:text-sm font-bold truncate">
                            {activeMicrophone}
                        </span>
                    </div>
                </div>
            )}

            {error && (
                <div className="bg-red-900/50 border border-red-500/50 text-red-200 p-3 rounded mb-4 font-mono text-xs">
                    ERREUR: {error}
                </div>
            )}

            <div className="flex gap-4">
                <Button 
                    onClick={startListening} 
                    disabled={isListening}
                    className={`flex-1 ${isListening ? 'opacity-50' : ''}`}
                >
                    {isListening ? 'Écoute en cours...' : 'Démarrer le Micro'}
                </Button>

                <Button 
                    variant="secondary"
                    onClick={stopListening}
                    disabled={!isListening}
                >
                    Stop
                </Button>
                 <Button 
                    variant="ghost"
                    onClick={resetTranscript}
                >
                    Reset Texte
                </Button>
            </div>

            <p className="text-[10px] text-gray-500 mt-3 italic">
                Note: Le moteur natif utilise les serveurs de reconnaissance de votre navigateur (Google/Apple). Une connexion internet est généralement requise.
            </p>
        </section>

        {/* SECTION 2: PARSER TESTER */}
        <section className="bg-gray-800/40 border border-gray-700 rounded-xl p-6">
            <h3 className="text-purple-500 font-bold uppercase tracking-widest text-sm mb-4 border-b border-gray-700 pb-2">
                2. Testeur de Syntaxe (Texte)
            </h3>
            <p className="text-xs text-gray-400 mb-4">Tapez une commande (ex: "triple 20", "double 16") pour tester la logique sans micro.</p>
            <div className="flex gap-2">
                <input 
                    type="text" 
                    value={manualInput}
                    onChange={(e) => setManualInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ex: triple vingt double dix"
                    className="flex-1 bg-gray-900 border border-gray-600 rounded px-4 py-2 text-white font-mono focus:border-purple-500 outline-none transition-colors"
                />
                <Button variant="secondary" onClick={handleManualTest}>Tester</Button>
