            <div className="flex gap-4">
                <Button 
                    onClick={startListening} 
                    disabled={isListening}
                    className={`flex-1 ${isListening ? 'opacity-50' : ''}`}
                >
                    {isListening ? 'Écoute en cours...' : 'Démarrer le Micro'}
                </Button>

                <Button 
                    variant="secondary"
                    onClick={stopListening}
                    disabled={!isListening}
