                    </div>
                ))}
                <div ref={logsEndRef} />
            </div>
        </section>

        {/* SECTION 5: EXPERIMENTAL SERVER ASR */}
        <VoiceDebugPanel />

      </div>
    </div>
  );
};

export type VoiceStatus = 'idle' | 'connecting' | 'listening' | 'processing' | 'error';

export interface TranscriptionResult {
    text: string;
    isFinal: boolean;
    timestamp: number;
    latency?: number;
}

export interface VoiceError {
    code: string;
    message: string;
    originalError?: any;
}

export interface IVoiceRecognitionProvider {
    readonly id: string;
    readonly label: string;

    connect(): Promise<void>;
    disconnect(): void;
    start(): Promise<void>;
    stop(): void;

    onStatusChange(callback: (status: VoiceStatus) => void): void;
    onTranscript(callback: (result: TranscriptionResult) => void): void;
    onError(callback: (error: VoiceError) => void): void;
    onVolumeChange?(callback: (volume: number) => void): void; // 0.0 to 1.0
}

export interface ServerAsrConfig {
    enabled: boolean;
    wsUrl: string;
    modelLabel: string;
    chunkMs: number;
    vadMode: 'none' | 'simpleEnergy';
    vadThreshold: number; // 0.0 à 1.0 (RMS)
}

import { IVoiceRecognitionProvider, VoiceStatus, TranscriptionResult, VoiceError, ServerAsrConfig } from '../types';

export class ServerAsrRecognitionProvider implements IVoiceRecognitionProvider {
    readonly id = 'server-asr';
    readonly label = 'Server ASR (Experimental)';

    private socket: WebSocket | null = null;
    private audioContext: AudioContext | null = null;
    private processor: ScriptProcessorNode | null = null;
    private stream: MediaStream | null = null;
    private source: MediaStreamAudioSourceNode | null = null;

    private config: ServerAsrConfig;
    private status: VoiceStatus = 'idle';
    private bufferAccumulator: Float32Array = new Float32Array(0);

    // Event Listeners
    private statusListeners: Set<(s: VoiceStatus) => void> = new Set();
    private transcriptListeners: Set<(r: TranscriptionResult) => void> = new Set();
    private errorListeners: Set<(e: VoiceError) => void> = new Set();
    private volumeListeners: Set<(v: number) => void> = new Set();

    constructor(config: ServerAsrConfig) {
        this.config = config;
    }

    onStatusChange(cb: (s: VoiceStatus) => void) { this.statusListeners.add(cb); }
    onTranscript(cb: (r: TranscriptionResult) => void) { this.transcriptListeners.add(cb); }
    onError(cb: (e: VoiceError) => void) { this.errorListeners.add(cb); }
    onVolumeChange(cb: (v: number) => void) { this.volumeListeners.add(cb); }

    private setStatus(newStatus: VoiceStatus) {
        this.status = newStatus;
        this.statusListeners.forEach(cb => cb(newStatus));
    }

    async connect(): Promise<void> {
        if (this.socket?.readyState === WebSocket.OPEN) return;
        if (!this.config.wsUrl) {
            this.emitError('CONFIG', 'WebSocket URL is missing');
            return;
        }

        this.setStatus('connecting');

        return new Promise((resolve, reject) => {
            try {
                this.socket = new WebSocket(this.config.wsUrl);

                this.socket.onopen = () => {
                    this.setStatus('idle');
                    resolve();
                };

                this.socket.onmessage = (event) => {
                    this.handleMessage(event.data);
                };

                this.socket.onerror = (e) => {
                    console.error('ASR WS Error:', e);
                    this.emitError('WS_ERROR', 'WebSocket connection failed');
                    this.setStatus('error');
                    reject(e);
                };

                this.socket.onclose = () => {
                    if (this.status !== 'error') this.setStatus('idle');
                    this.cleanupAudio();
                };
            } catch (e) {
                this.emitError('CONNECTION_FAILED', 'Could not create WebSocket', e);
                reject(e);
            }
        });
    }

    private handleMessage(data: any) {
        try {
            const msg = JSON.parse(data);

            // Log pour le debug si rien ne se passe
            if (process.env.NODE_ENV === 'development') {
                console.debug('ASR Message:', msg);
            }

            // Adaptez ici selon le format exact de votre serveur
            if (msg.text) {
                const result: TranscriptionResult = {
                    text: msg.text,
                    isFinal: msg.type === 'final' || msg.is_final === true,
                    timestamp: Date.now(),
                    latency: msg.processing_time
                };
                this.transcriptListeners.forEach(cb => cb(result));
            }
        } catch (e) {
            // Ignore non-JSON or malformed
        }
    }

    async start(): Promise<void> {
        if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
            try {
                await this.connect();
            } catch (e) {
                return;
            }
        }

        try {
            // 1. Setup Audio Context
            const sampleRate = 16000;
            this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ 
                sampleRate 
            });

            // CRITIQUE : Toujours forcer le resume() car les navigateurs bloquent l'audio
            if (this.audioContext.state === 'suspended') {
                await this.audioContext.resume();
            }

            // 2. Get Mic Stream
            this.stream = await navigator.mediaDevices.getUserMedia({ 
                audio: { 
                    channelCount: 1, 
                    echoCancellation: true, 
                    noiseSuppression: true,
                    autoGainControl: true,
                    sampleRate: 16000
                } 
            });

            this.source = this.audioContext.createMediaStreamSource(this.stream);

            // 3. Setup Processing
            // 4096 samples @ 16kHz ~= 256ms
            this.processor = this.audioContext.createScriptProcessor(4096, 1, 1);

            this.source.connect(this.processor);
            this.processor.connect(this.audioContext.destination);

            this.processor.onaudioprocess = (e) => {
                const input = e.inputBuffer.getChannelData(0);
                this.processAudioFrame(input);
            };

            this.setStatus('listening');
        } catch (e) {
            this.emitError('MIC_ACCESS', 'Microphone access denied or audio error', e);
            this.cleanupAudio();
        }
    }

    private processAudioFrame(inputData: Float32Array) {
        if (!this.socket || this.socket.readyState !== WebSocket.OPEN) return;

        // Calcul du volume (RMS) pour l'UI et le VAD
        let sum = 0;
        for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
        const rms = Math.sqrt(sum / inputData.length);

        // Notification du volume à l'UI (normalisé grosso modo pour l'affichage)
        const displayVol = Math.min(1, rms * 5); 
        this.volumeListeners.forEach(cb => cb(displayVol));

        // VAD Check
        if (this.config.vadMode === 'simpleEnergy') {
            if (rms < (this.config.vadThreshold || 0.002)) {
                return; // Silence trop bas, on n'envoie pas
            }
        }

        // Convert Float32 to Int16 PCM
        const pcmData = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) {
            // Clamp entre -1 et 1
            const s = Math.max(-1, Math.min(1, inputData[i]));
            // Convertir vers 16-bit PCM
            pcmData[i] = s < 0 ? s * 0x8000 : s * 0x7FFF;
        }

        this.socket.send(pcmData.buffer);
    }

    stop(): void {
        if (this.status === 'listening') {
            this.setStatus('processing');
        }

        this.cleanupAudio();

        setTimeout(() => {
            if (this.status === 'processing') this.setStatus('idle');
        }, 500);
    }

    disconnect(): void {
        this.stop();
        if (this.socket) {
            this.socket.close();
            this.socket = null;
        }
    }

    private cleanupAudio() {
        if (this.stream) {
            this.stream.getTracks().forEach(t => t.stop());
            this.stream = null;
        }
        if (this.source) {
            this.source.disconnect();
            this.source = null;
        }
        if (this.processor) {
            this.processor.disconnect();
            this.processor = null;
        }
        if (this.audioContext) {
            this.audioContext.close();
            this.audioContext = null;
        }
    }

    private emitError(code: string, msg: string, original?: any) {
        const error = { code, message: msg, originalError: original };
        this.errorListeners.forEach(cb => cb(error));
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { ServerAsrRecognitionProvider } from '../../voice/providers/ServerAsrRecognitionProvider';
import { VoiceStatus, TranscriptionResult, ServerAsrConfig } from '../../voice/types';
import { parseDartsVoiceCommand } from '../../utils/voiceParser';
import { Button } from '../ui/Button';

// Clés de configuration pour localStorage
const STORE_KEYS = {
    ENABLED: 'serverAsrEnabledForTesting',
    WS_URL: 'serverAsrWsUrl',
    MODEL_LABEL: 'serverAsrModelLabel',
    CHUNK_MS: 'serverAsrChunkMs',
    VAD_MODE: 'serverAsrVadMode',
    VAD_THRESHOLD: 'serverAsrVadThreshold' // Extra interne
};

export const VoiceDebugPanel: React.FC = () => {
    // 1. Initialisation de la config depuis localStorage
    const [config, setConfig] = useState<ServerAsrConfig>(() => {
        return {
            enabled: localStorage.getItem(STORE_KEYS.ENABLED) === 'true',
            wsUrl: localStorage.getItem(STORE_KEYS.WS_URL) || 'ws://localhost:9000/transcribe',
            modelLabel: localStorage.getItem(STORE_KEYS.MODEL_LABEL) || 'whisper-small',
            chunkMs: parseInt(localStorage.getItem(STORE_KEYS.CHUNK_MS) || '250', 10),
            vadMode: (localStorage.getItem(STORE_KEYS.VAD_MODE) as any) || 'simpleEnergy',
            vadThreshold: parseFloat(localStorage.getItem(STORE_KEYS.VAD_THRESHOLD) || '0.002')
        };
    });

    // 2. Persistance automatique lors des changements
    useEffect(() => {
        localStorage.setItem(STORE_KEYS.ENABLED, String(config.enabled));
        localStorage.setItem(STORE_KEYS.WS_URL, config.wsUrl);
        localStorage.setItem(STORE_KEYS.MODEL_LABEL, config.modelLabel);
        localStorage.setItem(STORE_KEYS.CHUNK_MS, String(config.chunkMs));
        localStorage.setItem(STORE_KEYS.VAD_MODE, config.vadMode);
        localStorage.setItem(STORE_KEYS.VAD_THRESHOLD, String(config.vadThreshold));
    }, [config]);

    // Runtime State
    const [status, setStatus] = useState<VoiceStatus>('idle');
    const [logs, setLogs] = useState<Array<{t: string, type: string, msg: string, parsed?: any}>>([]);
    const [currentPartial, setCurrentPartial] = useState('');
    const [micVolume, setMicVolume] = useState(0); // 0 à 100
    const providerRef = useRef<ServerAsrRecognitionProvider | null>(null);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (providerRef.current) {
                providerRef.current.disconnect();
            }
        };
    }, []);

    const initProvider = () => {
        if (providerRef.current) return;

        const p = new ServerAsrRecognitionProvider(config);

        p.onStatusChange((s) => {
            setStatus(s);
            addLog('STATUS', s);
        });

        p.onError((e) => {
            addLog('ERROR', `${e.code}: ${e.message}`);
        });

        // Feedback visuel du volume
        p.onVolumeChange((vol) => {
            setMicVolume(Math.round(vol * 100));
        });

        p.onTranscript((res: TranscriptionResult) => {
            if (res.isFinal) {
                // TEST: On passe le texte au parseur du jeu pour voir si c'est valide
                const parsed = parseDartsVoiceCommand(res.text);
                addLog('FINAL', res.text, parsed);
                setCurrentPartial('');
            } else {
                setCurrentPartial(res.text);
            }
        });

        providerRef.current = p;
    };

    const addLog = (type: string, msg: string, parsed?: any) => {
        setLogs(prev => [{
            t: new Date().toLocaleTimeString(),
            type,
            msg,
            parsed
        }, ...prev].slice(0, 50)); 
    };

    const toggleListening = async () => {
        if (!config.enabled) return;

        initProvider();
        const p = providerRef.current!;

        if (status === 'listening' || status === 'connecting') {
            p.stop();
            setMicVolume(0);
        } else {
            await p.start();
        }
    };

    const updateConfig = (key: keyof ServerAsrConfig, val: any) => {
        setConfig(prev => ({ ...prev, [key]: val }));
        // Si on change la config, on tue le provider pour forcer la reconnexion au prochain start
        if (providerRef.current) {
            providerRef.current.disconnect();
            providerRef.current = null;
            setStatus('idle');
            setMicVolume(0);
        }
    };

    return (
        <div className="bg-gray-900 border border-gray-700 rounded-xl p-6 space-y-6 mt-8">
            <div className="flex items-center justify-between border-b border-gray-800 pb-4">
                <div>
                    <h2 className="text-xl font-black italic text-cyan-500">EXPERIMENTAL ASR</h2>
                    <p className="text-xs text-gray-500 mt-1">Reconnaissance vocale serveur (Whisper/Kaldi) via WebSocket</p>
                </div>
                <label className="flex items-center space-x-3 cursor-pointer bg-gray-800 px-3 py-2 rounded-lg hover:bg-gray-700 transition">
                    <span className={`text-xs font-bold uppercase ${config.enabled ? 'text-white' : 'text-gray-500'}`}>
                        {config.enabled ? 'ACTIF' : 'DÉSACTIVÉ'}
                    </span>
                    <input 
                        type="checkbox" 
                        checked={config.enabled}
                        onChange={(e) => updateConfig('enabled', e.target.checked)}
                        className="w-5 h-5 rounded border-gray-600 bg-gray-700 text-cyan-500 focus:ring-cyan-500"
                    />
                </label>
            </div>

            {config.enabled && (
                <>
                    {/* Settings Form */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">WebSocket URL</label>
                            <input 
                                value={config.wsUrl}
                                onChange={(e) => updateConfig('wsUrl', e.target.value)}
                                className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white text-sm font-mono focus:border-cyan-500 outline-none"
                                placeholder="ws://localhost:9000"
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">VAD Threshold</label>
                            <div className="flex gap-2 items-center">
                                <input 
                                    type="range" min="0" max="0.05" step="0.001"
                                    value={config.vadThreshold}
                                    onChange={(e) => updateConfig('vadThreshold', parseFloat(e.target.value))}
                                    className="flex-1"
                                />
                                <span className="font-mono text-xs text-gray-400 w-12 text-right">{config.vadThreshold.toFixed(3)}</span>
                            </div>
                        </div>
                    </div>

                    {/* Test Area */}
                    <div className="bg-black/50 rounded-lg border border-gray-800 p-4">
                        <div className="flex items-center justify-between mb-4">
                            <div className="flex items-center gap-3">
                                <Button 
                                    onClick={toggleListening}
                                    variant={status === 'listening' ? 'danger' : 'primary'}
                                    size="sm"
                                    className="font-mono"
                                >
                                    {status === 'listening' ? 'STOP MIC' : 'START MIC'}
                                </Button>
                                <span className={`text-xs font-bold uppercase tracking-wider ${
                                    status === 'listening' ? 'text-green-500 animate-pulse' : 
                                    status === 'error' ? 'text-red-500' : 'text-gray-600'
                                }`}>
                                    [{status}]
                                </span>
                            </div>
                            <button onClick={() => setLogs([])} className="text-xs text-gray-500 hover:text-white underline">
                                Clear Logs
                            </button>
                        </div>

                         {/* Volume Bar (VU Meter) */}
                         <div className="mb-4">
                            <div className="flex justify-between text-[10px] uppercase text-gray-500 font-bold mb-1">
                                <span>Volume Micro</span>
                                <span>{micVolume}%</span>
                            </div>
                            <div className="h-2 bg-gray-800 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-75 ease-out ${micVolume > 50 ? 'bg-red-500' : micVolume > 10 ? 'bg-green-500' : 'bg-green-800'}`}
                                    style={{ width: `${micVolume}%` }}
                                />
                            </div>
                            {status === 'listening' && micVolume === 0 && (
                                <p className="text-[10px] text-red-400 mt-1">
                                    ⚠️ Aucun son détecté. Vérifiez vos permissions micro ou si un autre onglet l'utilise.
                                </p>
                            )}
                        </div>

                        {/* Live Output */}
                        <div className="mb-4 min-h-[60px] p-3 rounded bg-gray-900 border border-gray-800 flex flex-col justify-center">
                            <div className="text-gray-500 text-[10px] uppercase mb-1 font-bold">Flux Partiel (Live)</div>
                            <div className="text-lg text-white font-mono leading-tight">
                                {currentPartial || <span className="text-gray-700 italic">...</span>}
                            </div>
                        </div>

                        {/* Logs Console */}
                        <div className="h-60 overflow-y-auto font-mono text-xs space-y-1 custom-scrollbar bg-black/20 p-2 rounded border border-gray-800/50">
                            {logs.length === 0 && <div className="text-gray-700 text-center py-4">Aucune activité</div>}
                            {logs.map((log, i) => (
                                <div key={i} className="flex gap-2 text-gray-400 border-b border-gray-800/30 pb-1 mb-1">
                                    <span className="text-gray-600 shrink-0 select-none">{log.t}</span>
                                    <span className={`font-bold shrink-0 w-16 ${
                                        log.type === 'FINAL' ? 'text-green-400' :
                                        log.type === 'ERROR' ? 'text-red-400' : 'text-blue-400'
                                    }`}>{log.type}</span>
                                    <div className="flex-1 break-words">
                                        <span className="text-gray-300">{log.msg}</span>
                                        {log.parsed && (
                                            <div className="mt-1 ml-2 p-1.5 bg-gray-800/80 rounded border-l-2 border-cyan-500 text-cyan-300 text-[10px]">
                                                <span className="opacity-50 mr-2">GAME ENGINE:</span>
                                                {log.parsed.type === 'SCORE' ? `🎯 SCORE ${log.parsed.value}` : 
                                                 log.parsed.type === 'UNKNOWN' ? `❓ INCONNU` : 
                                                 `⚡ COMMANDE ${log.parsed.type}`}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </>
            )}
        </div>
    );
};

